window.ATLAS_I18N_LOR={"01IO012":["雙重戒律","本回合給予1個友軍單位+3|+0或+0|+3。","","「不必害怕改變。改變會讓你自省，並考驗你的極限，是我們最棒的導師。」——卡瑪","法術",[],["愛歐尼亞"],"普通"],"01IO015":["犽宿","我方擊暈或召回1個敵軍單位時，此牌對該單位造成2點傷害。","我方擊暈或召回5個以上單位。","「死亡就像風……」","單位",[],["愛歐尼亞"],"英雄"],"01IO020":["面具看守者","召喚此牌時，本回合給予其他友軍單位+1|+0。","","「從今而後，你代表戒律、訓練、謙遜與平衡。就在今日，你成為『均衡』的一員了。」","單位",[],["愛歐尼亞"],"普通"],"01IO045":["春臨信使","支援：本回合給予受此牌支援的友軍單位吸血。","","「冬季支配大地之際，\n陣陣腳步踏上雪地。\n悠悠甦醒之時，枝頭冒出藤蔓嫩葉\n遍覆森林，預示季節的更迭。」\n——尚禪詩歌","單位",[],["愛歐尼亞"],"普通"],"01IO008":["四尾旋刃者","我方擊暈或召回單位時，賦予此牌+2|+0。","","「喔，你覺得我很『可愛』？『毛茸茸』？？那你看看這招是不是讓你『愛死了』！」","單位",["約德爾人"],["愛歐尼亞"],"稀有"],"01IO040":["均衡奪命劍客","","","「此處曾經是我們的學校、寺廟、家園。如今我們只能潛伏於暗影滿佈的廢墟。劫的軍團玷汙這片莊嚴之地；我保證會讓他們後悔莫及。」","單位",[],["愛歐尼亞"],"普通"],"01IO041":["卡瑪","回合結束：在手牌生成1張我方區域的隨機法術牌。","我方進入開悟狀態。","「在自省之中，我們能專注於心，找到繞過阻礙的新路。」","單位",[],["愛歐尼亞"],"英雄"],"01IO011":["召回","召回1個友軍單位。","","聰明的戰士不僅僅要知道自己有多少韌性，更要克己。畢竟留得青山在，不怕沒柴燒。","法術",[],["愛歐尼亞"],"普通"],"01IO009":["劫","攻擊：召喚1個攻擊中的疾風殘影，其能力值與此牌相同。","此牌或我方疾風殘影打擊敵方主堡2次。","「只有愚者才追求平衡。暗影向我展現了真實的力量。」","單位",[],["愛歐尼亞"],"英雄"],"01IO014":["林地長老","召喚此牌時，賦予手牌中的友軍單位+1|+1。","","愛歐尼亞的知識早已付諸文字，但真正賦予文字新生命的功臣，是愛歐尼亞受人尊崇、負責傳授傳奇與教誨的長老們。","單位",[],["愛歐尼亞"],"普通"],"01IO005":["靈巧普羅","","","「我知道聽起來很不可思議，但我記得的最後一件事就是……毛茸茸的觸感……？」——那歐竊匪","單位",["普羅"],["愛歐尼亞"],"普通"],"01IO044":["那歐土匪","召回1個友軍單位即可出此牌。","","「快，我們得趕緊離開這裡！我叫什麼名字？我會在路上解釋清楚，我保證……」","單位",[],["愛歐尼亞"],"普通"],"01IO023":["寶石迅獅","出牌：賦予手牌中1個友軍單位+3|+3。","","「每次有衝突發生，村民們總會向秋谷的遠古守護者祈求。凡能打動她心之人，皆能受到祝福，扭轉戰鬥局勢。」——《最初淨土傳說》","單位",[],["愛歐尼亞"],"稀有"],"01IO029":["播撒的種子","賦予手牌中的友軍單位+1|+0。","","「這些不僅僅是種子、幼苗，也是大地本身的傳承，賜予我們豐盛未來的承諾。」——卡瑪","法術",[],["愛歐尼亞"],"稀有"],"01IO003":["死亡印記","將1個友軍單位的閃靈轉移至1個敵軍單位身上。","","「我是隱身黑暗的利刃。」——劫\n\n","法術",[],["愛歐尼亞"],"稀有"],"01IO047":["暗影火光","賦予所有戰鬥中的侍從單位閃靈。","","當魔法的流動失去平衡，便會從精神世界湧入物質領域，後果往往不堪設想。","法術",[],["愛歐尼亞"],"史詩"],"01IO026":["精神導師","出牌：賦予手牌中1個友軍單位+1|+0。","","「我花費數年才養成這般足以致命的體格！那些賞鳥、觀雲，以及抬起一盤又一盤甜麵包的辛苦日子！誰能有這般毅力呢？」","單位",[],["愛歐尼亞"],"普通"],"01IO024":["黎明與黃昏","挑選1個友軍單位，召喚2個與之相同的閃靈複製單位。","","「慎在兩個世界之間進退兩難，他最終只會把兩邊都搞砸。我只把自己全心奉獻給愛歐尼亞。」——劫","法術",[],["愛歐尼亞"],"稀有"],"01IO028":["鱗甲四不像","出牌：賦予此牌+3|+0或+0|+3。","","林地最古老的生物之一，牠的適應力歷久不衰，證明自己經得起時間的考驗。","單位",["爬蟲族"],["愛歐尼亞"],"普通"],"01IO057":["暗影刺客","召喚此牌時，抽1張牌。","","她優雅踩著\n無聲的步伐踏入暗影；\n爪痕是唯一留下的行跡。","單位",[],["愛歐尼亞"],"普通"],"01IO032":["慎","支援：本回合給予受此牌支援的友軍單位光盾。","此牌在場上時，友軍單位獲得光盾5次。","「物質與精神領域相互纏繞，猶如緊扣的雙手……」 ","單位",[],["愛歐尼亞"],"英雄"],"01IO013":["暗影之魔","","","「為了獲得力量，你願意犧牲什麼？這趟旅程從烙下誓言開始，直到你所能給的全被取走，才會抵達終點。」\n——劫","單位",[],["愛歐尼亞"],"普通"],"01IO018":["急速猛攻","本回合給予1個友軍單位+1|+0與快速攻擊。","","戰鬥只不過是一場比賽，看誰能更快奪走對方性命。","法術",[],["愛歐尼亞"],"普通"],"01IO056":["追風者．犽凝","出牌：擊暈2個敵軍單位。","","「小時候我曾問弟弟：『起風是代表風在逃逸，還是追隨？』那時他追隨在我身後是為了尋求指引。現在我追隨在他身後則是為了伸張正義。」\n","單位",[],["愛歐尼亞"],"稀有"],"01IO016":["西風聖鳥","出牌：挑選1張西風聖鳥以外的手牌，並在手牌生成1張該牌的複製牌。","","「長老安慰戰敗的悲泣戰士：『去尋找諸天之上的聖者吧。唯有他能尋回仍留在記憶中的失物』。」\n——《最初淨土傳說》","單位",["鳥族"],["愛歐尼亞"],"稀有"],"01IO036":["林地瞭望兵","打擊：使手牌中魔耗值最高的單位魔耗值-1。","","「巡邏兵，有一……不對……兩隻巨型毛茸生物朝著我們過來了！呼叫支——喔，等等，望遠鏡又拿反了……」","單位",["約德爾人"],["愛歐尼亞"],"普通"],"01IO033":["迅腿米娜","出牌：召回3個敵軍單位。","","「我們當時正在草地上疾行，這個小鬼忽然不知道從哪裡跳出來，砰、砰、砰地踢到我們呼吸困難！」——那歐竊匪","單位",[],["愛歐尼亞"],"史詩"],"01IO001":["重生儀式","治療1個友軍單位或我方主堡4點生命值。抽1張牌。","","「唯有提高心靈層次，肉身才能變得完整。」\n——卡瑪","法術",[],["愛歐尼亞"],"稀有"],"01IO010":["並肩作戰","調換2個友軍單位位置，並在本回合給予其光盾。","","「我會跟隨均衡的步伐前行。」——慎\n","法術",[],["愛歐尼亞"],"稀有"],"01IO022":["鬼步","本回合給予1個友軍單位隱密。","","「即刻出發，保持隱匿……任務完成之前不許回來。」\n——劫","法術",[],["愛歐尼亞"],"普通"],"01IO021":["幼年風行貓獸","召喚此牌時，本回合給予其他友軍單位+2|+2。","","「春天的花朵首先在愛歐尼亞的峭壁綻開，新生的飛禽拍打著翅膀，沐浴在春季的輕柔微風中。」\n——《最初淨土傳說》","單位",[],["愛歐尼亞"],"史詩"],"01IO054":["亙古洞悉","在手牌生成1張我方區域的其他隨機法術牌。\n開悟：改為生成2張。","","「希望渺茫時，記得你不是孤身一人。過往一直與我們同在，無數個明天將帶來希望。」——卡瑪","法術",[],["愛歐尼亞"],"稀有"],"01IO027":["默言影見者","打擊主堡：在手牌生成1張此牌的複製牌。","","「肉體弱不禁風，不可信賴，猶如光與影的界線那樣脆弱。」","單位",[],["愛歐尼亞"],"史詩"],"01IO031":["飲雲飛鯨","我方的疾速和專注法術魔耗值-1。","","牠的歌響徹全村；每道從天上傳至山腰的聲波又長又低沉，宛如午後奇異的雲彩飄忽不定。","單位",[],["愛歐尼亞"],"稀有"],"01IO002":["愛歐尼亞的意志","召回1個單位。","","入侵者踏入愛歐尼亞的領土，才發現就算征服了居民，也征服不了這片大地。","法術",[],["愛歐尼亞"],"普通"],"01IO017":["那歐利刃斥侯","召喚此牌時，本回合給予此牌隱密。","","「沒問題，我可以先發制人。只要幫我逃出這個鬼地方，我就跟你對分贓物，保證值回票價！」","單位",["約德爾人"],["愛歐尼亞"],"普通"],"01IO042":["武術學徒","我方召喚其他單位時，本回合給予此牌+1|+1。","","「要是沒人看見你的英勇招式，那戰鬥還有什麼意義呢？」","單位",[],["愛歐尼亞"],"普通"],"01IO006":["林地雙煞","我方召喚其他單位時，本回合給予此牌+1|+0。","","「嘿，注意那些樹枝！左邊，小心左邊！」\n「毛球，哪一天換我坐在你肩上，去哪裡都聽你的。但在那之前，就交給我吧！」","單位",[],["愛歐尼亞"],"稀有"],"01IO050":["均衡引路人","效忠：從我方牌組召喚1個魔耗值為1的友軍單位。","","無論她去到何處，總會確保其他人也能跟上。","單位",[],["愛歐尼亞"],"稀有"],"01IO048":["遊剎裏","","","「劫大師，您的軍團將我們驅離家園，證明了您的力量。現在就讓我證明自己也有足以貫徹您教誨的實力。」","單位",[],["愛歐尼亞"],"稀有"],"01IO007":["暗影之刃．忍","打擊：在手牌生成1張暗影之魔。","","「儘量逃跑、奮戰、畏縮吧。那都不重要，暗影已來到你身旁。」","單位",[],["愛歐尼亞"],"史詩"],"01IO053":["翡翠覺醒者","開悟：此牌獲得+4|+4。","","「征戰是人類的本能，但是本能無法凌駕我們的高尚美德，比如：信任、耐心與沉思。」","單位",[],["愛歐尼亞"],"普通"],"01IO004":["生命藥水","治療1個友軍單位或我方主堡3點生命值。","","雖然每個世代、區域和家族都有各自的獨家祕方，但有些配方的確效果更為出眾。","法術",[],["愛歐尼亞"],"普通"],"01IO049":["抵制","抵銷1個快速法術、慢速法術或技能。","","休想。","法術",[],["愛歐尼亞"],"稀有"],"01IO052":["那歐劫匪","召喚此牌時，召喚1位與此牌能力值相同的那歐竊匪。","","「諾克薩斯入侵之前，我曾是名四處旅行的音樂家，名聲從每個村莊遠播至平典城。如今我只能靠搶來的金幣苟延殘喘。母親說得對，我應該當一名治療師的……」","單位",[],["愛歐尼亞"],"普通"],"01IO030":["蒼天龍","","","「天上雲層纏繞，強風吹倒我們的軍旅。我們試著尾隨其後，但誰能真的追到風呢？」——軍團大將軍","單位",["龍族"],["愛歐尼亞"],"史詩"],"01IO019":["林地守護者","當友軍單位獲得光盾時，賦予此牌+2|+0。","","「林地會保護自己人。而你……你是個外人……」","單位",[],["愛歐尼亞"],"普通"],"01IO046":["鋼鐵暴雪","擊暈1個攻擊中敵軍單位。","","「尖銳一擊！」——犽宿","法術",["元素"],["愛歐尼亞"],"稀有"],"01IO037":["靈氣庇護","本回合給予1個友軍單位光盾與吸血。","","「這把刀曾屬於我父親。希望它能為你帶來我曾一度缺乏的力量。」——慎","法術",[],["愛歐尼亞"],"普通"],"01IO043":["人魚術士","打擊：抽1張法術。","","「我們是最初淨土引以為傲的兒女。淨土魔法在我們的梵斯塔雅血脈中流動，甚至遍布整座王國。」","單位",[],["愛歐尼亞"],"稀有"],"01IO038":["獨身修女","出牌：召回其他友軍。","","「反射動作與本能是我唯一渴望的陪伴。」","單位",[],["愛歐尼亞"],"稀有"],"01IO039":["移形換影","召回1個友軍單位，並在原處召喚1個疾風殘影。","","你眼前的敵人確實存在嗎？還是說，它只是暗影的\n障眼法？","法術",[],["愛歐尼亞"],"普通"],"01IO055":["靈氣守護者","賦予手牌中1個友軍單位光盾。\n抽1張牌。","","「維持平衡之人，應當知曉保護均衡的力量。」——慎\n","法術",[],["愛歐尼亞"],"普通"],"01NX020":["達瑞文","召喚此牌時及打擊：在手牌生成1張迴旋飛斧。","此牌使用迴旋飛斧打擊2次以上。","「想要親筆簽名？去排隊吧，老兄。」","單位",[],["諾克薩斯"],"英雄"],"01NX006":["弗拉迪米爾","出牌：對任意數量的友軍單位造成1點傷害，以對1個敵軍單位造成等值的傷害。","5個以上友軍單位承受傷害且未陣亡。","邪惡，冷漠，殘酷，迷人，敏銳，魅力十足。\n令人難以抗拒……","單位",[],["諾克薩斯"],"英雄"],"01NX004":["天擇刎頸殺","擊殺1個力量值為3以下的單位。","","人難免一死，只不過弱者比較早死。","法術",[],["諾克薩斯"],"稀有"],"01NX048":["血色督察","此牌承受傷害且未陣亡時，在手牌\n隨機生成1張血色單位。","","「最親愛的夥伴們！」「當然，這一天我期盼好久了。」「沒關係，只要能參加，要怎麼整我都行。」「雨天就不能舉辦露天舞會了！那就太掃興了。」「嗚，我莫名其妙被罵了。那你呢？凱？你會參加嗎？」","單位",[],["諾克薩斯"],"普通"],"01NX038":["達瑞斯","","此牌在場上時，敵方主堡生命值剩一半以下。","「鋼鐵般的意志，媲美泰坦巨人的力量。特菲利安軍團沒有更優秀的將軍人選了。」——斯溫\n","單位",[],["諾克薩斯"],"英雄"],"01NX023":["群蛛之主","召喚此牌時，賦予我方其他蜘蛛單位+2|+0。","","只消瞟一眼，你便成了她的囊中物。只消咬一口，你便成了牠們的牙下亡魂。","單位",["蜘蛛"],["諾克薩斯"],"稀有"],"01NX013":["致命出擊","擊暈1個敵軍單位。本回合給予所有友軍單位+2|+0。","","「隨便一名蠢蛋都能以壓倒性兵力戰勝敵軍。惟有遠見的人才懂得隱藏實力，留待關鍵時刻出擊。」——斯溫","法術",[],["諾克薩斯"],"稀有"],"01NX046":["蜘蛛哨兵","出牌：擊暈1個敵軍單位。","","「噢，我完全被她迷住了！她那雙誘人長腿、令人酥軟的甜美嗓音，還有玫瑰色的雙瞳。她今晚竟然願意與我共進佳餚，實在太幸運了！」——倒楣的貴族","單位",["蜘蛛"],["諾克薩斯"],"普通"],"01NX047":["鮮血轉換","對1個友軍單位造成1點傷害後，本回合給予另1個友軍單位+2|+2。","","「親愛的，有得就有失。我得，你失。」——弗拉迪米爾","法術",[],["諾克薩斯"],"普通"],"01NX040":["軍團破壞者","攻擊：對敵方主堡造成1點傷害。","","「破盾兵可以把敵人砍成兩半。但倘若需要更加細膩的手段，軍團也不乏其他人才。」——斯溫","單位",[],["諾克薩斯"],"普通"],"01NX025":["同袍兄弟","賦予2個友軍單位+2|+0。","","「戰場上結拜的兄弟姊妹與親人沒兩樣。畢竟，血濃於水。」——軍團退將","法術",[],["諾克薩斯"],"普通"],"01NX055":["普通蜘蛛","召喚此牌時，召喚1隻小蜘蛛。","","「我的蜘蛛渴望有人陪伴，可惜牠們只是一廂情願。」\n——伊莉絲","單位",["蜘蛛"],["諾克薩斯"],"普通"],"01NX030":["血色門徒","此牌承受傷害且未陣亡時，對敵方主堡造成1點傷害。","","「好想你啊，愛德文！你收到邀請了嗎？」「規定上是沒有特別區分新人和老鳥啦。我只希望那天別下雨。」「老父老母要是知道實情，肯定會把我趕出家門。」「血氣方剛的小毛頭才會幹這種事。」","單位",[],["諾克薩斯"],"稀有"],"01NX007":["競技場主持人","攻擊：本回合給予其他攻擊中友軍單位+1|+0。","","他歡欣高吼。在那瞬間，整座競技場的心跳與他的脈搏合為一體，觀眾的激動興奮之情全緊握在他勝利的手中。","單位",[],["諾克薩斯"],"稀有"],"01NX021":["軍團流寇","攻擊：賦予我方各處軍團流寇+1|+1。","","特菲利安軍團身後總是跟著一群投機的賊寇，隨時伺機上前掠奪戰後倖存的老弱傷殘。","單位",[],["諾克薩斯"],"普通"],"01NX009":["人氣角鬥士","召喚此牌時，我方場上每有1個友軍單位，便賦予此牌+1|+1。","","有些角鬥士散發服人的魅力，有些角鬥士則是身手矯捷。維錫德既不迷人，也不敏捷，但沒人能比他更快把對手打成肉醬。","單位",[],["諾克薩斯"],"稀有"],"01NX011":["迴轉死神","使1個戰鬥中友軍單位打擊1個戰鬥中敵軍單位。","","「我最愛這份工作了！」——達瑞文","法術",[],["諾克薩斯"],"普通"],"01NX053":["決鬥","若我方場上有力量值為5以上的友軍單位，則擊殺所有力量值為4以下的單位。","","「誰準備好上場廝殺啦？！！！」——競技場主持人","法術",[],["諾克薩斯"],"史詩"],"01NX054":["威嚇怒吼","擊暈所有力量值為4以下的敵軍單位。","","「他深深地吸一口氣，我們即將看到——沒錯，觀眾們！那就是雷電最有名的戰嚎！我們當場都嚇到腿軟了，閃～～電！」——競技場主持人","法術",[],["諾克薩斯"],"稀有"],"01NX029":["軍團退將","其他友軍單位承受傷害且未陣亡時，賦予該單位+1|+0。","","他拖著瀕死的身軀離開戰場，在丈夫和藥師的悉心照料下逐漸復原。即使早已褪下戰袍多年，諾克薩斯仍不計成本留住這位見多識廣的沙場老將。","單位",[],["諾克薩斯"],"史詩"],"01NX014":["雙刃手席菈扎","此牌對主堡造成雙倍傷害。","","「他說什麼？！那人真是腦袋裝水泥。那雙厚實的肩膀倒是無可挑剔……」","單位",[],["諾克薩斯"],"史詩"],"01NX042":["卡特蓮娜","召喚此牌時，在手牌生成1張飛逝利刃刀鋒。","此牌打擊1次。此牌升級時會被召回。","「要練手感，沒有什麼比蒂瑪西亞活標靶\n還來得適合......」","單位",[],["諾克薩斯"],"英雄"],"01NX051":["法隆上尉","召喚此牌時，在手牌生成2張毀滅風暴。","","出身佐恩汙水坑的班恩．法隆從小被佐恩人視為殘暴、性情無常之人，並遭到排擠。加入諾克薩斯軍團後，法隆受到接納、賞識，成為無人能敵的武將。","單位",[],["諾克薩斯"],"史詩"],"01NX012":["軍團後衛","","","諾克薩斯的士兵在戰場上以驍勇善戰聞名，因此擔任後衛簡直是一種懲罰。","單位",[],["諾克薩斯"],"普通"],"01NX043":["利刃刀鋒","對任1目標造成1點傷害。","","「刀刃在對的人手中，就能切斷一切……我是說真的。」——卡特蓮娜","法術",[],["諾克薩斯"],"普通"],"01NX037":["軍團擲彈兵","遺願：對敵方主堡造成1點傷害。","","諾克薩斯人從小就受到教誨，加入軍團效忠帝國就能光榮一生。不過只有少數人能獲得擔任軍團擲彈兵的殊榮。","單位",[],["諾克薩斯"],"普通"],"01NX010":["軍團大將軍","召喚此牌時，本牌局我方每擊暈或召回1個單位，便賦予此牌+1|+1。","","所有諾克薩斯人都知曉帝國強盛的三大法則，但是假如士兵想尋求晉升機會，他們必須學會活用三大\n法則。","單位",[],["諾克薩斯"],"普通"],"01NX017":["軍團擂鼓兵","支援：本回合給予受此牌支援的友軍單位快速攻擊。","","隨著她的鏗鏘鼓聲，軍團步步侵略，擴張帝國版圖。他們無人可擋。事實上也從來沒人擋得住。","單位",[],["諾克薩斯"],"普通"],"01NX003":["競技場組頭","回合開始：棄置我方魔耗值最低的手牌，並抽1張牌。","","「……你賭席菈扎會是場上唯一的生還者。但那個愛歐尼亞小子只是斷了一隻手臂，他還沒死。所以他也是生還者，懂嗎？當然，你也可以選擇加倍下注……」","單位",["約德爾人"],["諾克薩斯"],"稀有"],"01NX039":["洞察力","打出或棄置時，賦予所有友軍單位+1|+0。","","「無法預知未來之人，未來將無立足之地。」——傑利科．斯溫","法術",[],["諾克薩斯"],"稀有"],"01NX041":["特菲利安破盾兵","","","「我沒耐心慢慢圍城，派破盾兵上場。」——達瑞斯","單位",[],["諾克薩斯"],"普通"],"01NX036":["牛頭怪角鬥士","回合開始：擊暈最弱敵軍單位。","","「我不在乎你的仇家是誰，也不在乎對方幹了什麼。想要我替你在場上報仇，就得先拿出銀子。就算情節慘絕人寰，價碼一樣不變。」","單位",[],["諾克薩斯"],"稀有"],"01NX044":["攻城槌","攻擊：賦予此牌+4|+0。","","「長官，敵方拒絕打開城門。他們要求跟達瑞斯談話，但他還有兩天的路程。該派騎士去找他嗎？」\n「沒有這個必要。」","單位",[],["諾克薩斯"],"史詩"],"01NX005":["血色貴族","出牌：對1個友軍單位造成1點傷害，並賦予+1|+0與蠻力","","「新人該不會一進去就要被惡整吧？」「古老而美好的舞會儀式，真令人嚮往啊。你們會帶家人出席嗎？」「先把他們趕出家門就好啦，哈哈哈！」","單位",[],["諾克薩斯"],"普通"],"01NX016":["特菲利安新兵","召喚此牌時，若場上有其他諾克薩斯友軍單位，則賦予此牌+2|+0。","","「直到斧頭砍到變鈍，靴子被血水浸爛，這頭銜就歸你了。」——軍團退將","單位",[],["諾克薩斯"],"普通"],"01NX019":["實力至上","本回合給予1個友軍單位+3|+0與蠻力。","","「我說過縝密戰略沒那麼重要，不代表不好，只是真的沒那麼重要。」——達瑞斯","法術",[],["諾克薩斯"],"普通"],"01NX015":["寶貝毒蛛","","","所有蜘蛛她都愛，只不過這隻更得寵一點。","單位",["蜘蛛"],["諾克薩斯"],"普通"],"01NX050":["死亡蓮花","對所有戰鬥中單位造成1點傷害。","","「跟我一起跳舞吧。」——卡特蓮娜","法術",[],["諾克薩斯"],"稀有"],"01NX056":["瞬步","對1個敵軍單位造成2點傷害，然後進行備戰。","","等到瞧見刀刃，一切為時已晚。","法術",[],["諾克薩斯"],"普通"],"01NX033":["特菲利安鑑定員","召喚此牌時，我方場上每有1個力量值為5以上的友軍單位，便抽1張牌。","","「唯有堅決敏銳的眼力才能挑選出夠格加入特菲利安軍團的人才。她呢，她從一哩外就能從羊群中看見一隻狼。」——軍團大將軍","單位",[],["諾克薩斯"],"稀有"],"01NX052":["血債血還","對1個友軍侍從單位造成1點傷害。若其未陣亡，則在手牌生成1張該單位的複製牌。","","血術士的第一堂課總是搞得四處血瀝瀝。","法術",[],["諾克薩斯"],"普通"],"01NX045":["野蠻角鬥士","","","「下一位，巨爪！上次他把瘋魔五人組痛扁一頓……現在變三人組了。好啦！押注打賭誰是今天的輸家！賠率四比一！」——競技場組頭卡爾","單位",[],["諾克薩斯"],"稀有"],"01NX031":["特菲利安求譽者","","","大多數人在特菲利安軍團掙得一席便已滿足，\n但也有些人不會。","單位",[],["諾克薩斯"],"稀有"],"01NX002":["毀滅風暴","對敵方主堡造成4點傷害。","","「攻城這檔事，有時候必須仰賴天才軍師，有時候只要更猛烈攻擊就行了。」——達瑞斯","法術",[],["諾克薩斯"],"稀有"],"01NX008":["巨異蜥騎兵","效忠：賦予此牌+1|+1與蠻力。","","這個特殊的兵種確實需要馬，不過不是拿來騎；他們的座下怪獸覺得馬吃起來是人間美味。","單位",[],["諾克薩斯"],"稀有"],"01NX034":["黏人普羅","","","「諾克薩斯容不下……容不下弱——誰來把這隻煩人的傢伙帶走？！」——達瑞斯","單位",["普羅"],["諾克薩斯"],"普通"],"01NX035":["達瑞文的頭號粉絲","召喚此牌時，若達瑞文不在我方場上或手牌中，則將他移至牌組最上方。","","「想要親筆簽名？去……去排隊啦，老兄！」","單位",[],["諾克薩斯"],"普通"],"01NX026":["特菲利安莽夫","","","「魯莽是個缺陷，但是經歷過軍團的鍛鍊，魯莽也可以是傷人的利器。」——斯溫","單位",[],["諾克薩斯"],"普通"],"01NX027":["憤怒魔藥","本回合給予1個友軍單位+3|+0。","","「張手遭拒，握拳迎擊。」——諾克薩斯格言","法術",[],["諾克薩斯"],"普通"],"01NX022":["諾克薩斯斷頭台","擊殺1個負傷單位，然後在手牌生成1張飛逝諾克薩斯斷頭台。","","迅速了結對手，即是達瑞斯的仁慈。","法術",[],["諾克薩斯"],"稀有"],"01NX032":["血色覺醒者","召喚此牌時，對其他友軍單位造成1點傷害。","","「恕我直言，就算我拒絕，你們還是會硬拉我去。所以……當然會囉。」","單位",[],["諾克薩斯"],"稀有"],"01NX024":["神臂加登","支援：本回合給予受此牌支援的友軍單位+3|+0與蠻力。","","「席菈扎是個很棒的女友——我是說朋友，我們絕對沒有在交往。但假設我們正在交往，我想對她說，週年紀念日快樂。提問到此結束，謝謝。」","單位",[],["諾克薩斯"],"史詩"],"01NX049":["狡詐","擊暈1個敵軍單位。","","「最好留點繩子給敵人，好讓他們自縊，省得還要一路拖到絞刑台。」——勒布朗","法術",[],["諾克薩斯"],"普通"],"01DE031":["拂曉申言者","回合結束：若本回合有友軍單位陣亡，則賦予其他友軍單位+1|+1。","","「邪惡勢力贏得了一時，卻贏不了一世。緬懷為我們捐軀的人，將他們的回憶當作盔甲披在身上！」","單位",[],["蒂瑪西亞"],"史詩"],"01DE022":["路西恩","","此牌在場上時，有4個以上友軍單位陣亡，或我方姍娜陣亡。","「姍娜，只要有你在，我就會好好的。」","單位",[],["蒂瑪西亞"],"英雄"],"01DE019":["組織動員","手牌中友軍單位魔耗值-1。","","「只要訓練兩週，農民也能上前線作戰。這是我們對每位體格健壯的蒂瑪西亞子民的期望。」——蓋倫","法術",[],["蒂瑪西亞"],"稀有"],"01DE042":["拉克絲","","此牌在場上時，我方消耗6點以上魔力打出法術。此牌升級時，在手牌生成1張終極閃光。","「我一直都知道自己很特別……體內蘊藏著光芒。我還不了解那究竟是什麼，但我必須搞清楚！」 ","單位",[],["蒂瑪西亞"],"英雄"],"01DE010":["銀翼鷲槍騎兵","遺願：在手牌隨機生成1張菁英牌。","","「唯有勇猛無畏的戰士，才敢將性命交付給銀翼鷲，在高空與敵人纏鬥。這群戰士不僅勇猛，耐力也極高。」\n——蓋倫","單位",["菁英","鳥族"],["蒂瑪西亞"],"稀有"],"01DE020":["先鋒守軍","","","「我們雖不知道所面對的敵人或生物究竟是何物，但能認清身旁同袍的臉龐已足矣。」","單位",["菁英"],["蒂瑪西亞"],"普通"],"01DE034":["武器鐵匠","召喚菁英單位時，賦予該單位+1|+1。","","戰爭勝負早在鑄造武器的那一刻就注定了。","單位",[],["蒂瑪西亞"],"稀有"],"01DE002":["塔蒂雅娜．皇冠守衛","召喚此牌時，進行備戰。","","「我們的家族為這王國灑下熱血。你不該為了那些不正經的光魔法而捨棄家族榮耀。」","單位",[],["蒂瑪西亞"],"史詩"],"01DE012":["蓋倫","召喚此牌時，本回合給予其他友軍單位+1|+1。","此牌打擊兩次。","千錘百鍊的堅毅才能造就精兵，即便面對死亡的巨大威脅，我們也不會動搖半分。","單位",["菁英"],["蒂瑪西亞"],"英雄"],"01DE017":["一夫當關","若場上僅有1個友軍單位，則賦予其+3|+3。","","當其他人倒下，真正的英雄必須擔負起開闢勝利之路的重責大任。","法術",[],["蒂瑪西亞"],"稀有"],"01DE045":["菲歐拉","","此牌擊殺2個敵軍單位。","「不論是單場競技或比武大會，私下過招或上陣對敵，我都衷心期盼遇上一位夠格的對手。直到成為最強之前，我絕不停歇。」","單位",[],["蒂瑪西亞"],"英雄"],"01DE052":["閃鋼陣型","召喚此牌及攻擊時：本回合給予所有友軍單位光盾。","","「這陣型是我們諸多戰術的基礎，所有士兵都必須對自己以及戰友手中的盾牌堅信不移。只要他們屹立不搖，王國便可長盛不衰。」——蓋倫\n","單位",[],["蒂瑪西亞"],"史詩"],"01DE021":["冷酷進擊","進行備戰。",""," 「每個人終要面對內心最深層的恐懼。算你幸運，因為我來了。」——路西恩\n","法術",[],["蒂瑪西亞"],"普通"],"01DE025":["束縛","使1個友軍單位俘虜另1個單位。","","「服從我們吧。我們代表法律，而你必須遵守。不得有異議。」\n——狙魔宣教士","法術",[],["蒂瑪西亞"],"普通"],"01DE007":["審判","使1個戰鬥中友軍單位打擊所有戰鬥中敵軍單位。","","正義總會繞一圈回到原點。","法術",[],["蒂瑪西亞"],"史詩"],"01DE055":["羅倫特家族決鬥家","出牌：賦予手牌中1個友軍單位挑戰者。","","「他看上去就是位打扮花俏，手持昂貴寶劍的紈絝子弟。萬萬沒想到，他真的知道怎麼揮劍！我想再跟他比劃一場，不過他操著誇張的口音，我沒聽清楚他的名字。」\n——蒂瑪西亞少尉","單位",[],["蒂瑪西亞"],"普通"],"01DE048":["狙魔煽動者","在本牌局中，我方打出魔耗值為6以上的法術牌後，賦予此牌+2|+2。","","「很久以前，因符文聖戰引發的狂暴魔法，將整片符文大地摧殘得狼狽不堪。本組織之所以建立，正是為了驅逐王國內外的所有魔法，保護所有人民。」——狙魔者手冊","單位",[],["蒂瑪西亞"],"稀有"],"01DE001":["先鋒掌旗手","效忠：賦予其他友軍單位+1|+1。","","「你們必須了解我國旗幟所承載的重負。旗幟為了我們的國王、家園，還有人民而飛揚。這是我們對蒂瑪西亞堅定不移的信念。將旗幟高舉，向他們展現我們的驕傲。」——塔蒂雅娜．皇冠守衛 ","單位",["菁英"],["蒂瑪西亞"],"稀有"],"01DE043":["戰地廚師","支援：本回合給予受此牌支援的友軍單位+1|+1。","","別輕視蒂瑪西亞軍隊裡的任何一名成員。","單位",[],["蒂瑪西亞"],"普通"],"01DE049":["英勇普羅","","","「這名新兵的身上似乎散發出優良士兵特有的耐力與勇氣。有朝一日，他能加入無畏先鋒嗎？不過……他個子比一般人矮小，再看看他表現如何吧。」\n——先鋒中士","單位",["普羅"],["蒂瑪西亞"],"普通"],"01DE053":["羅倫特家族騎士","打擊：在手牌隨機生成1張我方區域的挑戰者侍從牌。","","「……我的天啊。」——菲歐拉","單位",[],["蒂瑪西亞"],"史詩"],"01DE033":["緬懷先烈","本回合每有1個友軍單位陣亡，此牌魔耗值便-1。隨機召喚1個魔耗值為5的蒂瑪西亞侍從單位。","","「為了替前人撥亂反正，今日我們挺身而出。我們同袍的犧牲絕非枉然。」——光輝守護者","法術",[],["蒂瑪西亞"],"稀有"],"01DE044":["加倍勇猛","治癒1個友軍單位，並使其力量值與生命值加倍。","","在蒂瑪西亞，以一擋二可不是吹牛自誇。","法術",[],["蒂瑪西亞"],"稀有"],"01DE024":["狙魔監管員","遺願：在手牌隨機生成1張魔耗值為6以上，不屬於蒂瑪西亞區域的法術牌。","","「雖然奧術物品擁有不可言喻的迷人風采，但這些充滿力量的物品必須交到可靠的專家手上，遠離我們善良無知的市民為上策。」——狙魔者手冊","單位",[],["蒂瑪西亞"],"普通"],"01DE004":["銀翼鷲先鋒","出牌：召喚1個此牌的複製單位。","","牠們穿破雲層，宛如一道道銀色閃電敏捷且精準地向目標俯衝。來無影，去無蹤。 ","單位",["菁英","鳥族"],["蒂瑪西亞"],"普通"],"01DE011":["羅倫特家族門徒","","","「他做了什麼好事？我把貴重的古拉德．皮耶平衡雙刀託付給他！他明明說只會拿去進行訓練！」\n——羅倫特家族刀劍收藏家","單位",[],["蒂瑪西亞"],"普通"],"01DE047":["天降大任","召喚1名無畏先鋒。","","無畏先鋒的聖衣在一位又一位的兵士手中傳遞。如此一來，剛入伍的新兵才會感受到身負大任的\n重量與驕傲。","法術",[],["蒂瑪西亞"],"普通"],"01DE046":["先鋒瞭望兵","","","安靜無聲不代表安全無虞。","單位",["菁英"],["蒂瑪西亞"],"普通"],"01DE050":["淨化","沉默1個侍從單位。","","「反魔法英石灰色印徽是對抗魔法的基本防護，象徵我們的責任，也提醒旁人我們的權威性。從現在起，這個印徽就是你的最高榮譽。」\n——狙魔者手冊","法術",[],["蒂瑪西亞"],"普通"],"01DE040":["狙魔宣教士","在本牌局中，我方打出魔耗值為6以上的法術牌後，賦予此牌+1|+1與挑戰者。","","「蒂瑪西亞的人民，保護你們的安全是我的榮幸。不過，我們需要各位堅定不移的支持。因為即使在高聳的城牆內，仍有魔法師混在我們當中！」\n","單位",[],["蒂瑪西亞"],"稀有"],"01DE036":["先鋒護衛","召喚菁英單位時，使此牌魔耗值-1。","","「我所經歷的每趟旅程、遇見的每個人，都教會我新事物。但是看得越多，變得越強，我才發現要走的路還漫長得很……」——先鋒護衛希莉亞\n","單位",["菁英"],["蒂瑪西亞"],"普通"],"01DE037":["斗轉之力","本回合給予1個友軍單位+3|+0與光盾。","","「『你打起架就像一隻普羅』，這形容真是再貼切不過了！」——菲歐拉","法術",[],["蒂瑪西亞"],"稀有"],"01DE014":["增援部隊","召喚2名無畏先鋒，並賦予我方菁英單位+1|+1。","","「我們的對手深明，凡攻擊我們任何一人，就等於攻擊我們全體。」\n——無畏先鋒守則\n","法術",[],["蒂瑪西亞"],"稀有"],"01DE015":["光輝守護者","召喚此牌時，若本回合有友軍單位陣亡，則賦予此牌吸血與堅忍。","","「冰冷的亡靈前仆後繼，伸出雙手將她的戰友拉下來。她隻身一人，隨著一道正義之光灑下。每次她揮舞兵刃，就彷彿在歌頌著那些捐軀將士的名字。」——蒂瑪西亞少尉","單位",[],["蒂瑪西亞"],"稀有"],"01DE003":["羅倫特家族刀劍收藏家","出牌：賦予1個友軍單位+2|+2。","","「沒錯，它們確實很美麗。但就像任何精良工器一樣，唯有在大師手中，才能展現真正的美。」 ","單位",[],["蒂瑪西亞"],"稀有"],"01DE026":["單挑","使1個友軍單位與1個敵軍單位互相打擊。","","「多說無益；我們用劍刃溝通。」——菲歐拉","法術",[],["蒂瑪西亞"],"普通"],"01DE032":["稜光障壁","本回合給予1個友軍單位光盾。","","「當你與眾不同，全世界都會跟你作對。有人說，你的不同之處會成為弱點，其實你只會更加堅強且富有同情心。再黑暗的時刻，都有我保護你！」——拉克絲","法術",[],["蒂瑪西亞"],"普通"],"01DE027":["預備擊劍","本回合給予所有友軍單位挑戰者。","","「沒有一名蒂瑪西亞人會拒絕羅倫特的劍術課程，但是也沒有人能撐完整堂課。」——菲歐拉","法術",[],["蒂瑪西亞"],"稀有"],"01DE006":["先鋒中士","召喚此牌時，在手牌生成1張蒂瑪西亞萬歲！","","「他日夜帶領我們訓練，激戰時身先士卒。宛如鋼鐵般堅硬、也像磐石般穩重。領袖人選非他莫屬。」——蒂瑪西亞少尉","單位",["菁英"],["蒂瑪西亞"],"稀有"],"01DE038":["光之哨兵姍娜","我方路西恩首次陣亡時，賦予此牌+1|+1與雙重攻擊。","","「我們的哨兵是抵禦永無安寧的亡靈、守護人類王國的第一道防線。我們先發制人、猛力進攻，同伴命懸一線時更是絕不退縮。」","單位",[],["蒂瑪西亞"],"稀有"],"01DE041":["互相照應","本回合給予2個友軍單位+3|+3。","","「掩護我，我要闖進去了！」\n「哈，我剛剛正想對你說一樣的話。」\n——東營區的隆和達克斯","法術",[],["蒂瑪西亞"],"稀有"],"01DE035":["蒂瑪西亞萬歲！","本回合給予所有友軍單位+3|+3。","","「它代表了我們的家園、家人，還有披甲上陣的同袍。它也是我們的驕傲、榮譽與力量。就在今日，在我們挺身奮戰的存亡之際，讓我們大力呼喊其名：蒂瑪西亞！」\n——先鋒中士","法術",[],["蒂瑪西亞"],"稀有"],"01DE018":["光輝打擊","本回合給予1個友軍單位+1|+1。","","「亡靈打起仗總是不顧一切，彷彿沒有明天。我們就讓它們如願死在今天。」——路西恩\n\n","法術",[],["蒂瑪西亞"],"普通"],"01DE009":["閃鋼捍衛者","出牌：本回合給予1個友軍單位光盾。","","「我國之所以強盛繁榮，是因為每位戰士的性命就如同一枚錢幣，我們絕不浪擲。」——嘉文三世國王","單位",[],["蒂瑪西亞"],"普通"],"01DE039":["克勞菲爾德的希莉亞","","","「每晚上床睡覺前，母親會一邊述說蒂瑪西亞偉大英雄的故事，一邊磨利手中的劍。我的夢裡總是充滿著冒險。\n就在今天，我將開始撰寫屬於我自己的故事。」","單位",["菁英"],["蒂瑪西亞"],"普通"],"01DE056":["先鋒首刃軍","攻擊：賦予此牌+2|+2。","","才聽見戰場上的吶喊聲，我的雙腳已經蠢蠢欲動，準備衝鋒陷陣。只要她一聲令下，我將無條件獻上性命，貫徹她的意志。","單位",["菁英"],["蒂瑪西亞"],"普通"],"01DE029":["疾羽獵鷹","我方召喚其他單位時，賦予此牌挑戰者。","","這種猛禽是銀翼鷲的近親，同樣具有獵食本能，但牠們還不太能適應自己小一號的體型。","單位",["鳥族"],["蒂瑪西亞"],"普通"],"01DE028":["先鋒騎兵","","","無畏先鋒不靠鼓聲或樂曲，而是僅靠馬蹄踩踏地面發出的規律節奏來記錄行軍時間。","單位",["菁英"],["蒂瑪西亞"],"普通"],"01DE013":["鎖子甲","賦予1個友軍單位堅忍。","","蒂瑪西亞之鋼因超凡強度而家喻戶曉。鐵匠需要擁有與其相當的力量和聲望方能鍛造。","法術",[],["蒂瑪西亞"],"普通"],"01DE023":["狙魔調查員","在本牌局中，我方打出魔耗值為6以上的法術牌後，在手牌生成1張束縛。","","「抱歉，打擾了。麻煩您全力配合調查。我們注意到一些……『不尋常的事』……」","單位",[],["蒂瑪西亞"],"普通"],"01DE051":["驍勇戰士希莉亞","攻擊：本回合給予其他攻擊中友軍單位+1|+1與威嚇。","","「對我而言，傳說和軼事不只是虛構情節，這些偉大的冒險好像在呼喚著我。我離開克勞菲爾德，探尋屬於自己的旅程，才發現這不過是起點，未來還有更多冒險等著我去體驗。」\n","單位",["菁英"],["蒂瑪西亞"],"史詩"],"01DE054":["先鋒贖士","召喚此牌時，若本回合有友軍單位陣亡，則抽1張單位牌。","","「作戰吶喊的每一聲、揮出的每一劍，盾牌的每一次撞擊，都是對捐軀將士的緬懷！今天，我們勝券在握！」","單位",["菁英"],["蒂瑪西亞"],"普通"],"01DE030":["銀翼鷲俯擊兵","","","大批箭雨從城牆直瀉而下，但怎麼也傷不了那劃破長空的銀色斑點。 ","單位",["鳥族"],["蒂瑪西亞"],"普通"],"01PZ040":["吉茵珂絲","","此牌在場上時我方用盡手牌。","「怎麼啦，惡鯊？」\n「我好擔心你喔，吉茵珂絲！每次你無聊就會想要……」\n「想要來個大轟炸！惡鯊，這真是好主意！」","單位",[],["皮爾托福&佐恩"],"英雄"],"01PZ008":["提摩","打擊主堡：將5張劇毒膨菇隨機植入敵方牌組。","把15張以上劇毒膨菇植入敵方牌組。","「班德爾偵察隊第154條守則：未知不足以為懼！\n第276條守則：森林居民是我們的朋友！\n第354條守則：毛茸茸的東西或許可以摸，\n但絕對不能吃！第417條守則……」","單位",["約德爾人"],["班德爾城","皮爾托福&佐恩"],"英雄"],"01PZ056":["漢默丁格","我方打出法術時，在手牌生成1張相同魔耗值的飛逝砲臺，其魔耗值為0。","此牌在場上時，我方召喚力量值總和為12以上的機械友軍單位。","「瘋狂科學家？哼！我明明是『超級正常只不過偶爾缺乏條理又不拘一格』的科學家好嗎？謝謝再見！」","單位",["約德爾人"],["班德爾城","皮爾托福&佐恩"],"英雄"],"01PZ013":["自我強化科學家","出牌：棄置我方手牌。抽3張牌。對1個敵軍單位造成3點傷害。","","為了完成夢想，他斷送了雙手，卻仍努力不懈。任何事都無法阻止他的野心。","單位",[],["皮爾托福&佐恩"],"史詩"],"01PZ007":["電光遊行花車","支援：在我方牌組生成4張受此牌支援的友軍單位的複製牌。","","人群被大砲轟炸聲引來廣場，熱切想觀賞表演。他們八成要花好幾週才能把纏在髮間的彩紙洗掉。","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ018":["菁英學院奇才","","","她是怎麼瞄準的？這是個好問題。","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ019":["勤奮的學徒","召喚此牌時，恢復2點法術魔力。","","不是每個人都能立刻為皮爾托福帶來進步。有些人需要一些提點，好比說，那些用錯透鏡還仔細拉近焦距猛看的傢伙。","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ025":["膨菇小販","我方打出法術時，將3張劇毒膨菇植入敵方牌組。","","「這批貨純嗎？」\n「當然！全是頂級貨！我親自跟它們談過了！」\n「好，給我——你說什麼？」\n「嗯哼！這傢伙就要結婚了！」\n「你嗑了多少……？」\n「——它要跟藤壺結婚！」","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ048":["可瑞娜．瓦拉撒","出牌：泯滅我方牌組最上方5張牌，其中每張法術可對所有敵軍單位及敵方主堡造成1點傷害。","","「目光如豆的皮爾托福人只搞齒輪、金屬那套，不懂我培育的那些根莖、花瓣和細胞是多麼細緻的藝術。我會為他們打造優雅無比的死亡體驗，優雅到他們根本配不上。」","單位",[],["皮爾托福&佐恩"],"史詩"],"01PZ028":["應急裝置","打出或棄置時，召喚1隻廢料河蟹。","","當時，年輕發明家手邊只剩一些廢料，時間所剩無幾，忽然她想起一個非比尋常的靈感來源：她曾在偏遠的叢林看過一隻生物沿著河岸小步快跑。","法術",[],["皮爾托福&佐恩"],"普通"],"01PZ050":["咒能高漲","本回合給予1個友軍單位+4|+0與快速攻擊。","","「開始發光之後，我就有點發癢。這很正常……對吧？」\n——伊澤瑞爾","法術",[],["皮爾托福&佐恩"],"普通"],"01PZ054":["爆破幫菜鳥","攻擊：對敵方主堡造成2點傷害。","","「你這樣做對嗎？」\n「不確定。」\n「你應該要確定的啊。」\n「你應該一開始就別問。」","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ030":["可疑人物","出牌：挑選1個侍從單位，將此牌幻化為與之相同的複製單位。","","「各位化學伯爵，大家好！」","單位",["約德爾人"],["皮爾托福&佐恩"],"稀有"],"01PZ017":["藥劑桶供應商","召喚此牌時，召喚2個腐蝕藥劑桶。","","「齊爾派你來的？我跟他說過了，這跟我沒關係。我自己沒見過的商品要怎麼退費呢？不過既然事情都發生了，我手上倒是有一批新貨可以割愛……」","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ038":["汙水坑疏濬機器人","出牌：棄置1張牌以抽1張牌。","","汙水坑是物盡其用的極致典範。","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ036":["伊澤瑞爾","打擊主堡：在手牌生成1張飛逝祕術射擊。","我方指定8個以上敵軍單位為法術/技能目標。","「護目鏡？有了。圍巾？有了。我完全搞得懂運作原理的魔法臂鎧？有了，有了，都有了！」","單位",[],["皮爾托福&佐恩"],"英雄"],"01PZ035":["杰．梅德拉達","此牌成為法術/技能目標時，抽1張牌。","","梅德拉達氏族在皮爾托福聲名顯赫，身為法定繼承人的杰卻對家族事業興趣缺缺，成天只想追尋古文物……父親為此苦惱不已。","單位",[],["皮爾托福&佐恩"],"史詩"],"01PZ010":["蘑菇雲","將5張劇毒膨菇植入敵方牌組。","","首先，你聽到膨菇爆開的輕輕一聲「砰」。接著，一股劇烈疼痛逐漸削弱你的力量。最後，只剩下遠處傳來的咯咯笑聲……","法術",[],["皮爾托福&佐恩"],"普通"],"01PZ045":["佐恩小乞丐","出牌：棄置1張牌以抽1張牌。","","「還以為汙水坑的貧民們多少會互相照顧呢。」\n「兄弟，他們光自怨自艾就沒時間了吧。」\n「真可憐。呃……你有看到我的錢包嗎？」","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ002":["陋巷酒吧老闆","召喚此牌時，本牌局我方每召喚1位陋巷酒吧老闆，則在手牌生成1張隨機卡牌。","","「沒錯，夥計。它稍微有股後勁，就像汙水坑稍微有點臭味一樣。要吐的話桶子就在點唱機旁邊。」","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ004":["精準彈幕","從敵軍單位與敵方主堡中挑選3個目標，依序造成3點、2點與1點傷害。","","「天才不需要運氣，照樣百發百中。」——伊澤瑞爾","法術",[],["皮爾托福&佐恩"],"史詩"],"01PZ020":["大膽普羅","","","第一次發射純粹是個意外，她在理毛的時候不小心滑入進步日禮炮。現在，她成了皮爾托福的大明星，成天劃過高空，飛越底下發出讚嘆聲的人群。","單位",["普羅"],["皮爾托福&佐恩"],"普通"],"01PZ046":["盜版贗品","挑選1張手牌，在我方牌組生成4張複製牌。","","最真摯的盜竊叫作模仿。","法術",[],["皮爾托福&佐恩"],"稀有"],"01PZ052":["祕術射擊","對任1目標造成2點傷害。","","「我從不失手。但大家都知道我會先射兩發，以示警戒……」——伊澤瑞爾","法術",[],["皮爾托福&佐恩"],"普通"],"01PZ033":["追尋完喵","在本牌局中，若我方已打出20張新卡牌，則召喚貓劫降臨。","","「到頭來，為了馮奕卜的願景付出努力的所有人都被蒙在鼓裡。我們對後果一無所知，不曉得自己即將釋放多麼恐怖的力量。」——皮爾托福專案工程師","法術",[],["皮爾托福&佐恩"],"史詩"],"01PZ005":["海克斯變形儀","將1個侍從單位幻化為與另1個侍從完全相同的複製單位。","","「是你一直嚷嚷著想變瘦啊。」\n「所以你就把我變成約德爾人？！」\n「你變瘦了啊！」\n「……我也變成約德爾人了！」","法術",[],["皮爾托福&佐恩"],"稀有"],"01PZ021":["密登史多的黨羽","打擊主堡：召喚1個此牌的複製單位。","","「伯茲先生，我們發現你睡在金庫裡面，全身覆蓋著金色齒輪，一手還緊緊抓住金庫被砸壞的門。」\n「那不是我。只是某個長得跟我很像的傢伙。」\n「你到現在還抓著門不放呢。」\n「對啊，肯定不是我。」","單位",[],["皮爾托福&佐恩"],"稀有"],"01PZ031":["史提克衝擊","從敵軍單位與敵方主堡中挑選2個目標，各造成1點傷害。\n抽1張牌。","","「這就是我們發現弧放電的方式！沒錯，這個假設是我的前輩提出的，但他卻低估了電弧的廣泛應用。真是愚鈍的傢伙……」——漢默丁格","法術",[],["皮爾托福&佐恩"],"稀有"],"01PZ059":["金嚇破壞機器人","","","擊殺、踩扁、摧毀，再來一次。","單位",["機械"],["皮爾托福&佐恩"],"普通"],"01PZ001":["雜物堆","棄置最多2張牌即可出此牌。\n我方每棄置1張牌，則抽1張牌。","","「噢～老天，五名特警還有一個石像？等等！我有個法寶！放去哪裡啦……」——吉茵珂絲","法術",[],["皮爾托福&佐恩"],"普通"],"01PZ057":["巧遇","召喚2隻廢料河蟹。","","兩隻溫和的生物曾隔著陸地遙遙相對，如今終於藉著汙水坑的微溫水域聚首。","法術",[],["皮爾托福&佐恩"],"普通"],"01PZ027":["生熱光束","此牌魔耗值等於我方所剩魔力。\n對1個單位造成等同消耗魔力的傷害。","","「我們耗盡了時間和資金，儘管現在光束能正常運作，我們仍無法調節光束消耗的能量。」\n——佐恩實驗家","法術",[],["皮爾托福&佐恩"],"稀有"],"01PZ055":["聰慧學者","我方抽牌時，本回合給予此牌+1|+0。","","想像力是偉大發明的火花，不過潛心研究才能讓火花點燃為大火。","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ014":["無照新發明","召喚1件非法怪裝置。","","「他們搞出來的禍端還可以分成多種風味：遠方爆炸的震動、裂隙飄出的腐臭濃煙。這些蠢蛋遲早會把這座城市毀了。」——皮爾托福慈善家","法術",[],["皮爾托福&佐恩"],"普通"],"01PZ034":["汙水坑拾荒者","效忠：在手牌生成1張汙水坑地圖。本回合該牌的魔耗值為0。","","佐恩的孩子們很快就開始探索老礦坑隧道，深入街巷阡陌。他們發現了另一番天地，還結交到許多摯友。\n","單位",[],["皮爾托福&佐恩"],"稀有"],"01PZ003":["組合機器人","我方打出法術時，賦予此牌+1|+1。","","「任何笨蛋都能組裝機器，但要將真正的尖端科技灌輸到機械大腦裡，只有百年難得一見的奇才做得到！過不久那些該死的官僚就會乖乖爬回來\n找我了……」——科拉斯．漢維克","單位",[],["皮爾托福&佐恩"],"稀有"],"01PZ044":["化學龐克撕裂樂手","出牌：對所有敵軍單位造成1點傷害。","","「……他的獨奏忽地轉成和聲小調，接著又彈奏起琶音——琶音是一種演奏技巧——一路滑進橋段的移調。你八成不懂得欣賞他的傑作吧。」\n——看門人麥克斯．布里夫","單位",[],["皮爾托福&佐恩"],"稀有"],"01PZ029":["大善人","出牌：顯化1張我方區域的史詩牌。","","「以前我滿腔怒火，只懂得摧毀競爭對手，盡攬財富名聲。現在，我只把財產分送給有需要之人，希望懺悔之舉能洗清我的罪過。」","單位",[],["皮爾托福&佐恩"],"稀有"],"01PZ051":["武趣工匠","我方所有法術與技能造成1點額外傷害。","","「想提高轟炸威力是吧？交給我就對了！」","單位",[],["皮爾托福&佐恩"],"稀有"],"01PZ023":["馮奕卜教授","我方召喚魔耗值為1的單位時，賦予其+2|+2。","","「今天我要為各位委員帶來我的最新發明，在此邀請我令人敬重的夥伴進行示範……」","單位",["貓族"],["皮爾托福&佐恩"],"稀有"],"01PZ024":["暴走配線員","在本牌局中，我方打出魔耗值為6以上的法術牌後，賦予此牌+4|+0與快速攻擊。","","姓名：科拉斯．漢維克；年齡：51歲；執照類別：第2級（附條件）；狀態：吊銷；備註：無視多次警告，實驗室爆炸（第13X764NM號案件）後仍持續輸出。切勿予以放行許可。","單位",[],["皮爾托福&佐恩"],"稀有"],"01PZ049":["進步日！","抽3張牌，使其魔耗值各-1。","","進步日！\n一起來太陽門廣場！\n見證海克斯科技奇蹟！\n令人大開眼界的大膽普羅！\n聆聽洞悉明日之人暢談今日局面\n免費入場！\n歡迎皮爾托福的孩子共襄盛舉！","法術",[],["皮爾托福&佐恩"],"史詩"],"01PZ006":["廣場守護者","本牌局我方每打出1張法術，此牌魔耗值便-1。","","給你二十秒乖乖就範。","單位",[],["皮爾托福&佐恩"],"稀有"],"01PZ053":["呼碰引伴","召喚此牌時，在手牌生成1張蘑菇雲。","","「嗯，沒錯！有一大團，鬼鬼祟祟！他們看起來好像瘋了，但你不懂。我才懂！他們要幹一票大的！一票大的。膨菇、起司、雪酪……我說到哪了？」——膨菇小販","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ012":["咬咬手榴彈！","若此牌遭到棄置，則反而會被召喚。","","「上吧，咬咬！」——吉茵珂絲","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ039":["狂躁！","棄置1張牌即可出此牌。\n對任1目標造成3點傷害。","","「大火力登場！」——吉茵珂絲","法術",[],["皮爾托福&佐恩"],"稀有"],"01PZ016":["靈光電火球","在手牌隨機生成1張魔耗值為6以上、我方區域的法術牌。\n恢復我方所有法術魔力。","","只消一次頓悟，便可造就一生傳奇。","法術",[],["皮爾托福&佐恩"],"普通"],"01PZ058":["重量級呼碰","召喚此牌時，在手牌生成2張蘑菇雲。","","「我看過一個大傢伙，真的！她跟一匹馬一樣重，跟石怪一樣詭計多端。我告訴你，你一定要仔細注意這傢伙。她可不是平白無故坐上呼碰女王的寶座！」——膨菇小販","單位",["約德爾人"],["皮爾托福&佐恩"],"稀有"],"01PZ009":["懸浮飛板初學者","","","「個人飛行機械？簡直在作白日夢！我才吩咐徒弟把最新的原型扔掉而已。話說，他人跑去哪了？」——皮爾托福工程師","單位",[],["皮爾托福&佐恩"],"普通"],"01PZ042":["英勇水手","支援：本回合給予受此牌支援的友軍單位隱密。","","許多皮爾托福人透過科學和創新，在進步之城內安全地探索未知的領域。但仍有少數人航向地平線，發掘更廣闊的未知領域：全世界。","單位",[],["皮爾托福&佐恩"],"稀有"],"01PZ026":["汙水坑地圖","賦予1個友軍單位隱密。","","「皮爾托福人老是以為自己無所不知，但是少了我們的指點，他們根本看不懂這裡的地圖！當地人才懂的資訊最珍貴了。當然我也可以分享……只要你願意掏腰包就行。」——汙水坑拾荒者，阿朱納．雷姆","法術",[],["皮爾托福&佐恩"],"普通"],"01PZ043":["化學龐克扒手","打擊主堡：在手牌生成1張來自敵方牌組的隨機法術牌。","","進步之城底層的那群傢伙本來應該相互廝殺，沒想到他們團結起來，互助合作，打造了一個新家——佐恩，雖然不怎麼理想，但至少是屬於他們的領地。","單位",[],["皮爾托福&佐恩"],"稀有"],"01PZ047":["腐蝕藥劑桶","遺願：對雙方主堡各造成1點傷害。","","「你大可以穿防護服，但是一穿起來就跟呼碰的胳肢窩一樣，悶熱得要人命。手套或許還行？如果那黏答答的東西不小心沾到身上，你最好祈禱別沾到什麼重要部位。」——佐恩工頭，齊爾．艾可思","單位",[],["皮爾托福&佐恩"],"普通"],"01FR024":["艾妮維亞","攻擊：對所有敵軍單位與敵方主堡造成1點傷害。\n遺願：復甦此牌並幻化為蛋妮維亞。","我方進入開悟狀態。","「我在這片貧瘠大地誕生，我有責任守護這塊疆土。時間、戰爭，甚至是死亡都無法逼我放下戒備。」","單位",["鳥族"],["弗雷爾卓德"],"英雄"],"01FR039":["泰達米爾","","此牌將要陣亡時，反而會升級。","「別為理想殉身，把它活出來。」","單位",[],["弗雷爾卓德"],"英雄"],"01FR006":["寒霜之裔的傳承","挑選1個友軍單位，賦予我方各處相同卡牌+2|+2。","","「我們是少數的寒霜之裔，吾族血脈流淌著弗雷爾卓德的魔法。祖先們將古老的邪惡封印起來，現在碩果僅存的我們必須保持警戒，提防邪惡勢力捲土重來。」——守護者葛瑞戈","法術",[],["弗雷爾卓德"],"普通"],"01FR022":["警示鷹","召喚此牌時，賦予牌組最上方2個友軍單位+1|+1。","","「掠奪者曾三次進逼至艾伐洛森的大門，每次總會遇到箭在弦上對準我們的窘境。他們到底耍了什麼花招，能屢次察覺進攻？」——戰痕族長史特芬","單位",["鳥族"],["弗雷爾卓德"],"普通"],"01FR042":["嚴寒狂風","凍傷2個敵軍單位。","","「你竟敢在我的地盤挑戰我？小子，你根本是來送死。」\n——艾妮維亞","法術",["元素"],["弗雷爾卓德"],"稀有"],"01FR009":["布郎姆","此牌首次承受傷害且未陣亡時，召喚1隻大力普羅。","此牌共承受10點以上傷害並存活。","「把拔，跟我說布郎姆和他的巨石門的故事嘛！」\n「或是他在下墜時，把山峰一分為二的那段！」\n「喔！不然說說他保護小酒館免受暴怒雪怪破壞的故事吧？！」","單位",[],["弗雷爾卓德"],"英雄"],"01FR018":["冰霜尖牙狼","打擊：若此牌打擊力量值為0的單位，則視同擊殺之。","","北方的掠食性動物發現，那些遭受寒冬蹂躪的獵物是最容易得手的目標。","單位",["犬族"],["弗雷爾卓德"],"稀有"],"01FR036":["艾伐洛森神射手","出牌：對1個敵軍單位造成1點傷害。","","在弗雷爾卓德不打獵，你就準備挨餓。","單位",[],["弗雷爾卓德"],"普通"],"01FR045":["戰痕族長史特芬","此牌承受傷害且未陣亡時，賦予此牌+3|+0。","","「史瓦妮賜給我第一道戰痕時，我就對冬之爪立下誓言。從此之後，每道戰痕都是為她效勞所得的賞賜。」","單位",[],["弗雷爾卓德"],"普通"],"01FR008":["孤單普羅","召喚此牌時，在手牌隨機生成1張魔耗值為1的其他普羅牌。","","「我在弗雷爾卓德待了一輩子，從沒見過比這難過的小傢伙更令人痛心不捨的了。」——普羅牧人","單位",["普羅"],["弗雷爾卓德"],"普通"],"01FR055":["碎裂","挑選1個敵軍單位，若其力量值為0，則對該單位造成4點傷害。若否，則凍傷該單位。","","「凜冬橫越大地之時，她能讓強者變得卑微，弱者變得墮落。」——戰痕族長史特芬","法術",["元素"],["弗雷爾卓德"],"普通"],"01FR038":["艾希","攻擊：凍傷最強敵軍單位。","我方使5個以上敵軍單位的力量值降至0。此牌升級時，在牌組頂端生成1張水晶箭。","「當我瞭望家園，看到的不僅是現在，也看到可能的未來：一片昌盛的榮景，不只是我的族人得享富足，也包括所有企求和平的人。弗雷爾卓德，萬眾而一心！」","單位",[],["弗雷爾卓德"],"英雄"],"01FR029":["吹號求援","抽1張英雄牌。","","「掠奪者來襲！吹響軍號、點燃狼煙，我們必須盡可能召集援軍全力抵禦！」——艾伐洛森哨兵","法術",[],["弗雷爾卓德"],"稀有"],"01FR035":["無戰痕掠奪者","此牌承受傷害且未陣亡時，賦予此牌+3|+0。","","「艾伐洛森人只會把孩子教成軟弱畏戰的個性。我們的孩子則在戰火中誕生。」——戰痕之母芙蕊娜\n","單位",[],["弗雷爾卓德"],"普通"],"01FR020":["雪崩","對所有單位造成2點傷害。","","每次雪崩皆肇因自一顆不安分的礫石。","法術",["元素"],["弗雷爾卓德"],"稀有"],"01FR014":["幼年雪怪","遺願：在我方牌組生成2張暴怒雪怪。","","「它小小一隻又那麼與世無爭！真難相信長大後就變成……呃……一隻大雪怪。」——艾伐洛森捕獸人","單位",["雪怪"],["弗雷爾卓德"],"普通"],"01FR049":["潛行狼","召喚此牌時，使敵方召喚1隻雪兔。","","「兔子就是兔子，永遠無法變成狼。」\n——冬之爪俗語","單位",["犬族"],["弗雷爾卓德"],"普通"],"01FR037":["艾伐洛森騎衛隊","效忠：賦予牌組最上方的友軍單位+3|+3與蠻力。","","增援部隊在山脊上列陣，騎衛隊低頭向戰爭之母行禮。因為他們的艾希女王，艾伐洛森的化身，將為子民帶來和平。","單位",[],["弗雷爾卓德"],"稀有"],"01FR026":["狂爪虎王","","","集戰馬的力量及貓科動物的野蠻於一身。","單位",["貓族"],["弗雷爾卓德"],"普通"],"01FR030":["鋼鐵脆化","凍傷1個生命值為3以下的敵軍單位。","","「很冷嗎？哈！希望你的精神要比盛夏打造的鋼鐵更加堅韌！」——布郎姆","法術",["元素"],["弗雷爾卓德"],"普通"],"01FR013":["戰痕之母芙蕊娜","此牌承受傷害且未陣亡時，賦予此牌+3|+0。","","「我寧可在冰天雪地發抖凍死，也不屑與艾希那群弱者共享一座爐火。但若是他們想要讓身子熱一熱，我就如他們所願。」","單位",[],["弗雷爾卓德"],"史詩"],"01FR019":["凜冬吐息","擊殺所有力量值為0的敵軍單位，接著凍傷所有敵軍單位。","","戰爭之母凜冬是任何意圖侵略弗雷爾卓德之人必須面對的最初和最後的敵人。她的血誓盟侶為無情狂風和刺骨冰霜。","法術",["元素"],["弗雷爾卓德"],"史詩"],"01FR041":["艾伐洛森爐衛 ","召喚此牌時，賦予牌組中友軍單位+1|+1。","","「眾多部族為了同一面旗幟而戰！或許終有一天，弗雷爾卓德全體能齊心禦敵。」","單位",[],["弗雷爾卓德"],"史詩"],"01FR025":["普羅牧人","召喚此牌時，若我方掌控\n普羅牌，則抽1張普羅牌。","","照顧牧群只有兩個重點：愛與陪伴。其他的都只是吹毛求疵罷了。\n","單位",[],["弗雷爾卓德"],"稀有"],"01FR054":["戰痕少女掠奪者","","","「弱者坐等收成，強者逕行奪取。弱小的艾伐洛森人將會認清自己屬於哪一種！」","單位",[],["弗雷爾卓德"],"稀有"],"01FR021":["獨行狂戰塔卡茲","攻擊：對所有戰鬥中的單位造成1點傷害。","","「塔卡茲打起仗比多數人更奮力勇猛，遇到挫敗也能很有風度地接受。至少多數時候是這樣……」——泰達米爾","單位",[],["弗雷爾卓德"],"史詩"],"01FR043":["毛茸茸之心","出牌：將我方場上的普羅侍從單位結合成為1個普羅成群，並賦予該單位他們所有的能力值與增益特性。","","「我再說一個故事，但要保持安靜，不然戰爭之母就來了！\n很久以前，盜匪攻擊艾伐洛森的村莊。她的部隊只有幾人，通通看起來很迷茫。不過這時一隻普羅出現並對艾伐洛森伸出援手……」","單位",["普羅"],["弗雷爾卓德"],"稀有"],"01FR033":["玄妙石陣","回合開始：本回合額外獲得1顆魔力寶石。","","「遠古石堆時時提醒著我們，自己不過是部族長久歷史中，勇敢拓荒不馴之地的其中一群人。」——艾希","單位",[],["弗雷爾卓德"],"普通"],"01FR011":["冰谷弓箭手","出牌：凍傷1個敵軍單位。","","能夠適應嚴峻天候和冰封凍土，讓艾伐洛森人引以為傲。目光銳利的守軍更是進一步把自然地勢轉成防禦優勢。 ","單位",[],["弗雷爾卓德"],"普通"],"01FR050":["親切的小酒館老闆","出牌：治療1個友軍單位或我方主堡3點生命值。","","「這棟老建築就是『微醺貓頭鷹』，我們有各式燉菜和佳釀幫你驅走寒意，快進來吧！」","單位",[],["弗雷爾卓德"],"普通"],"01FR052":["虛厄遊獸","出牌：泯滅手牌及場上所有\n力量值為4以下的單位。","","「我從碎石堆中站起身，發現周圍地上燒出一圈烙印。夥伴曾經站立的地方成了一堆悶燒的灰燼，而不遠處有個若隱若現的形體邁步向前……」\n——漫遊者比亞","單位",[],["弗雷爾卓德"],"史詩"],"01FR016":["普羅點心","賦予各處普羅友軍單位+1|+1。","","「牠們先是狼吞虎嚥，然後伸出舌頭開心地看著你，彷彿融雪時節剃完毛的厄努克，跟你討更多好料！誰忍心拒絕啊。」——艾伐洛森糕點師","法術",[],["弗雷爾卓德"],"普通"],"01FR005":["戰鬥狂怒","賦予1個友軍單位+8|+4。","","「他們說，我這個人……性情剛烈。」——泰達米爾","法術",[],["弗雷爾卓德"],"稀有"],"01FR023":["戰爭之母的呼喚","現在及每回合開始時，召喚牌組最上方的友軍單位。","","總有一天，一聲無庸置疑的呼喚將響徹弗雷爾卓德，宣告遠古仇敵再次現身。屆時所有人都會挺身回應呼召。","法術",[],["弗雷爾卓德"],"史詩"],"01FR047":["野魂祕術師","開悟：此牌獲得+4|+4。","","「學會野獸嘶吼的人，很快就會忘卻原來的語言。」\n——艾妮維亞","單位",[],["弗雷爾卓德"],"普通"],"01FR056":["寒地雪怪","召喚此牌時，凍傷所有生命值為3以下的敵軍單位。","","「啊啊啊啊啊啊啊！」——漫遊者比亞","單位",["雪怪"],["弗雷爾卓德"],"稀有"],"01FR027":["厄努克公牛","","","艾伐洛森有幾篇「老伯伯厄努克」的民間故事，主角是一頭固執又愛發牢騷的厄努克。他一心只想找一片溫暖的草地，配上一個可以碎碎念的話題。 ","單位",["厄努克"],["弗雷爾卓德"],"普通"],"01FR057":["獸群心性","本回合給予所有友軍單位+2|+2與蠻力。","","一聲孤獨的狼嚎在黑夜裡迴盪，嚎叫聲隨後此起彼落。過了一陣子，狼嚎聲合而為一，宛如一首由嗜血的激動叫聲所組成的主旋律。","法術",[],["弗雷爾卓德"],"稀有"],"01FR004":["抗擊藥劑","本回合給予1個友軍單位+0|+2。","","「外面天氣糟透了，對吧？別擔心，『微醺貓頭鷹』的特殊佳釀口感強烈，能夠驅走你骨子裡的寒意，還能讓新生兒長出胸毛喔！」——親切的小酒館老闆","法術",[],["弗雷爾卓德"],"普通"],"01FR048":["艾伐洛森捕獸人","召喚此牌時，在我方牌組最上方3張牌中生成1張暴怒雪怪。","","「整整一個禮拜都沒抓到半隻！不是牠們看穿我的陷阱，就是有東西把牠們嚇跑了……」","單位",[],["弗雷爾卓德"],"普通"],"01FR017":["厄努克牛群","出牌：從我方牌組前6張牌召喚所有厄努克，將其餘卡牌洗回我方牌組。","","「艾伐洛森人就像雙眼無神的草食厄努克牛群，連無痕者都能輕易撂倒。他們靠著人多勢眾才得以存活。」——戰痕之母芙蕊娜","單位",["厄努克"],["弗雷爾卓德"],"普通"],"01FR046":["精神抖擻","賦予1個負傷友軍單位+3|+3。","","「……布郎姆的傷勢頗為嚴重，他卻仰天大笑。因為他知道最艱困危急的時刻，正是英雄誕生之際！」\n——《布郎姆傳說》","法術",[],["弗雷爾卓德"],"稀有"],"01FR012":["催化魔方","獲得1格魔力寶石槽位，並治療主堡3點生命值。","","魔方之石是一塊具有神奇恢復能力的超凡寶石，無論紅水晶或藍水晶都無法比擬其散發出的光澤。 ","法術",[],["弗雷爾卓德"],"普通"],"01FR040":["冰霜獠牙薩滿","回合開始：凍傷最強敵軍單位。","","「要與野外共存就不該逃避冰天雪地，應當在荒涼中陶醉狂歡。」","單位",[],["弗雷爾卓德"],"稀有"],"01FR031":["遠古雪怪","回合結束：此牌魔耗值-1。","","「那是怎麼回事？聽起來像是打噴嚏。冰川會……打噴嚏嗎？」——漫遊者比亞\n","單位",["雪怪"],["弗雷爾卓德"],"稀有"],"01FR053":["大力普羅","","","「這位長角力士為了保護普羅王，不顧一切擊退一隻發瘋的狂爪虎，結果失去了一隻眼睛！這告訴我們，戰槌再無堅不摧，也需要強大的心靈才能奮力揮舞。」\n——普羅牧人\n","單位",["普羅"],["弗雷爾卓德"],"普通"],"01FR010":["血誓之盟","賦予2個友軍單位+0|+3。","","「我會成為你內心的火把、隨侍你身旁的盾牌。我將竭力保護部族，以血誓之盟為證，願我倆的命運從此合一。」\n——泰達米爾","法術",[],["弗雷爾卓德"],"稀有"],"01FR001":["急速冰凍","凍傷1個敵軍單位。","","寒冷無預警襲擊，即使再強的戰士都感到無助。","法術",["元素"],["弗雷爾卓德"],"稀有"],"01FR032":["星光先知","我方打出法術時，賦予牌組最上方的友軍單位+1|+1。","","「賦予他們敏銳的雙耳聆聽吹來的風、輕盈的腳步跨越即將來臨的風雪、清晰的雙眼看穿冬日的陰霾。」","單位",[],["弗雷爾卓德"],"稀有"],"01FR051":["荒誕傳說","若我方場上有雪怪單位，則召喚1隻暴怒雪怪。若無，則改為生成該牌置於我方牌組頂端。","","「……這傢伙的嘴巴滿係尖尖的牙齒、雙拳充滿破壞力、眼神超～級森氣，吼聲還能撼動大樹！比亞叔叔係這麼跟我說的！」——少女英格娃","法術",[],["弗雷爾卓德"],"普通"],"01FR034":["虛厄韌獸","召喚此牌時，每有1個友軍單位陣亡，則賦予此牌+1|+1。","","「唉，老比亞經歷了一些事情，在北方失去了手下。他幾個月後歸來，整個人臉色蒼白，語無倫次。現在只會喃喃重複『巨大野獸』、『超大利爪』。真是可憐……」\n——親切的小酒館老闆","單位",[],["弗雷爾卓德"],"稀有"],"01FR007":["碎碎念的比亞","召喚此牌時，抽1張力量值為5以上的單位牌。","","「你……你必須相信我！那是隻巨獸。我真心不騙，超巨大！」","單位",[],["弗雷爾卓德"],"普通"],"01FR003":["艾伐洛森哨兵","遺願：抽1張牌。","","「我曾經遠征戰場尋找自己的立足之地。現在，我在農場和家人的陪伴下找到安身之處。我是他們的雙眼，他們的安全就是我的責任。」","單位",[],["弗雷爾卓德"],"普通"],"01SI038":["魅影搗蛋鬼","每有1個其他友軍單位陣亡，便對敵方主堡造成1點傷害。","","最殘酷的不是她裝成哭泣的小女孩誘殺士兵，而是她在生還的士兵心中深植恐懼，讓他們回到家後對他們自己女兒的哭鬧置之不理。","單位",[],["闇影島"],"稀有"],"01SI049":["窺視異域","擊殺1個友軍單位以抽2張牌。","","「我犯了大錯，我們根本不該妄想窺視那片灰霧背後的世界。無論那裡藏著什麼樣的知識，要付出的代價實在太大了。」——無畏守備官，阿里．倫斯","法術",[],["闇影島"],"普通"],"01SI053":["伊莉絲","攻擊：召喚1隻攻擊中的小蜘蛛。","回合開始：我方場上有3隻以上其他蜘蛛單位。","伊莉絲曾是諾克薩斯有權有勢家族的女主人，她與闇影島結下密不可分的關係，從中獲得永生的年輕美貌，代價是獻上幾個無辜靈魂作為祭品。她不假思索就答應了。","單位",["蜘蛛"],["闇影島"],"英雄"],"01SI057":["古代鱷龍","擊殺2個友軍單位即可出此牌。","","「全部關進籠子，答啦答……\n奪走所有魂魄，啦答啦……\n別放他們走，萬萬不能！\n否則這些魂魄會激動翻騰……」","單位",["爬蟲族"],["闇影島"],"稀有"],"01SI023":["牧靈者","召喚閃靈友軍單位時，賦予其+1|+1。","","唯有亡者知道她並非獨行。只有他們看得見她引領著無數同路人前往彼岸的國度。","單位",[],["闇影島"],"普通"],"01SI010":["暗影的逆襲","召喚2名幽魂騎士。","","彼時殂落此時生，他們始終忠心如一。","法術",[],["闇影島"],"普通"],"01SI042":["赫克林","攻擊：召喚2名攻擊中的幽魂騎士。","我方以7個以上閃靈友軍單位攻擊。","那不是雷電，是戰爭之影要現身了。","單位",[],["闇影島"],"英雄"],"01SI027":["新鮮獻祭","若本回合有3個以上友軍單位陣亡，則召喚威洛魔。","","「在毒牙之神面前跪下吧。最好連性命也一併奉獻。」\n——伊莉絲","法術",[],["闇影島"],"稀有"],"01SI048":["受詛咒的看守人","遺願：召喚1個出柙邪靈。","","狂癲加上時間，史上極惡的組合。","單位",[],["闇影島"],"普通"],"01SI018":["憂傷抄寫員","召喚此牌時，在手牌生成1張本牌局陣亡友軍單位的複製牌。","","「作者毫不知情，殞落王者的詛咒很快就要——就要——不、不、不，墨水怎麼又灑出來了！作者毫不知情——不、不、不！」","單位",[],["闇影島"],"普通"],"01SI030":["克黎思妲","","此牌在場上時，有3個以上友軍單位陣亡。","她生前是一名將軍，守護王國的英雌。但隨著肉身消逝，她心中僅剩報復的熊熊怒火。她成了滿心只想報仇雪恨的不死怨靈。","單位",[],["闇影島"],"英雄"],"01SI035":["割魂手喇煞","出牌：若本回合有友軍單位陣亡，\n則擊殺2個最弱敵軍單位。","","「他們說……他們稱之為傳奇旅程。我們的任務是保衛……蒂瑪西亞的未來。我們懷抱著希望航行，但是……犧牲這麼多人……究竟為了什麼？」\n——蒂瑪西亞士兵，阿里．倫斯","單位",[],["闇影島"],"史詩"],"01SI005":["鑿魂怪","本牌局每有1個友軍單位陣亡，此牌魔耗值便-1。","","某個早已被忘卻的王國曾把這隻怪獸當作駝獸，現在牠穿梭在各個廢棄戰地拾荒，沿路將廢料放入殼內，將死者亡魂吞入腹中。","單位",[],["闇影島"],"稀有"],"01SI037":["凶厄普羅","","","說真的，死在普羅手下其實不算太差。","單位",["普羅"],["闇影島"],"普通"],"01SI052":["瑟雷西","","此牌在場上時，有6個以上單位陣亡。","「鎖鏈鏗鏘作響，有人要來把你抓走……\n鎖鏈鏗鏘作響，獄長就在你身後……」","單位",[],["闇影島"],"英雄"],"01SI033":["萊卓斯指揮官","出牌：對敵方主堡造成等同其當前一半生命值的傷害，無條件進位。遺願：將此牌收回手牌。","","大多靈魂的記憶在年歲中逐漸消失殆盡，遺失了自我。但是萬分痛苦的萊卓斯仍緊緊抓住過往不放。有些事情，連時間也無法沖淡。","單位",[],["闇影島"],"史詩"],"01SI003":["哈洛威","復甦在本牌局陣亡的6個最強友軍單位，並賦予其閃靈。","","有幾天夜裡，一群飢餓的怨靈會乘著黯霧，穿越汪洋狩獵生者的靈魂，以新的邪惡不死生物餵養逐漸壯大的黑暗面。","法術",[],["闇影島"],"史詩"],"01SI041":["不死戰魂","遺願：於下次回合開始復甦此牌，且此牌每次陣亡，賦予其+1|+1。","","老烈士只記得自己召集了同袍，把他們全派去戰場上送死。但他早已不記得原因了……","單位",[],["闇影島"],"史詩"],"01SI045":["魂靈吸噬","從1個友軍單位汲取4點生命值。","","「你的衰亡，造就我的強大。」——瑟雷西","法術",[],["闇影島"],"普通"],"01SI036":["寒毛直豎","若本回合有友軍單位陣亡，則召喚2隻小蜘蛛。","","嚇到起雞皮疙瘩很可怕？你還沒嘗過打從心底感到毛骨悚然的滋味。","法術",[],["闇影島"],"普通"],"01SI051":["飽受折磨的奇才","每有1個其他友軍單位陣亡或遺願：恢復我方所有法術魔力。","","他焚膏繼晷，想將作品修到完美境界。不料，瞬間一陣黑煙靜靜穿過他的身體。周遭的人尖叫著逃命，他卻絲毫沒發現不對勁。","單位",[],["闇影島"],"稀有"],"01SI012":["不知情的島民","出牌：賦予手牌中1個友軍單位閃靈，且魔耗值-1。","","噢，可憐的傢伙……","單位",[],["闇影島"],"普通"],"01SI031":["幽鐵宣令官","攻擊：場上每有1個閃靈友軍單位，則賦予此牌+1|+0。","","不論生前死後，他都站在前線吼出扭曲黑暗的命令。\n而不論生前死後，赫克林的忠心騎士定會齊聲回應，\n衝鋒殺敵。","單位",[],["闇影島"],"稀有"],"01SI034":["靈魂黑矛","若本回合有友軍單位陣亡，則對1個單位造成4點傷害。","","「黑矛為逝者吟唱。」——克黎思妲","法術",[],["闇影島"],"普通"],"01SI043":["倒楣的貴族","遺願：召喚1隻小蜘蛛。","","「伊、伊莉絲夫人？你……你上哪去了？」","單位",[],["闇影島"],"普通"],"01SI009":["騷靈酒鬼","支援：賦予受此牌支援的友軍單位+2|+0與閃靈。","","有些人只在殞落王者的詛咒中看見毀滅與痛苦，有些人卻能抱著「今朝有酒今朝醉」的心態，及時行樂去囉。","單位",[],["闇影島"],"普通"],"01SI007":["鬼靈聖物","召喚3個獲釋的靈魂。","","生者和亡者都將這些古老聖物視為珍寶，生者一心想佔為己有，亡者則執意留在身邊。","法術",[],["闇影島"],"普通"],"01SI056":["發狂疾行蛛","召喚此牌時，本回合給予我方其他蜘蛛單位+1|+0，並使所有敵軍單位-1|-0。","","「牠們不用一分鐘就能吐絲纏捆一個人……需要示範一下嗎？」——伊莉絲","單位",["蜘蛛"],["闇影島"],"稀有"],"01SI001":["復仇","擊殺1個單位。","","遭到背叛的人們在垂死之際，乞求克黎思妲持黑矛為他們復仇。","法術",[],["闇影島"],"普通"],"01SI019":["惡靈領域","對本回合召喚的所有敵軍單位造成3點傷害。","","「沒人逃得了。」——瑟雷西","法術",[],["闇影島"],"稀有"],"01SI011":["無饜屠夫","擊殺1個友軍單位即可出此牌。","","人如其食。","單位",[],["闇影島"],"普通"],"01SI014":["霧魅","召喚此牌時，賦予我方各處霧魅+1|+0。","","這群島上幽魂很久以前就脫離原本的身分，化成一團純粹、永不滿足的飢餓混合體。","單位",[],["闇影島"],"普通"],"01SI022":["闇影島印記","賦予1個友軍單位+2|+2與閃靈。","","欲獲力量，願付出多少代價？","法術",[],["闇影島"],"普通"],"01SI006":["據為己有","本回合控制1個敵軍侍從單位。若我方場上已有6個友軍單位或地標，則無法打出此牌。","","他睡醒發現自己雙手發紅，整個營地太過安靜，事情不對勁。 ","法術",[],["闇影島"],"稀有"],"01SI028":["裂靈術","挑選1個友軍單位，召喚1個能力值為1|1的閃靈複製單位。","","「我從水裡撈起屍體，想查清這個可憐人的身分。我的手才碰到他的肩膀，他忽然轉過頭來面向我。這個人……是我？」——蒂瑪西亞士兵，阿里．倫斯","法術",[],["闇影島"],"稀有"],"01SI025":["殘酷暴行","擊殺1個友軍單位，並對任1目標造成等同該單位力量值的傷害。","","對不知死亡為何物之人，殺戮簡直不痛不癢。","法術",[],["闇影島"],"稀有"],"01SI046":["黯霧呼喚","隨機復甦1個本回合陣亡的友軍單位。","","「那陣黯霧會活生生割除人類的靈魂，留下一具半死不活的軀體。我曾親眼目睹家鄉遭到蹂躪，所以我要前往那些受到詛咒的島嶼，了結這一切。」\n——無畏守備官，阿里．倫斯","法術",[],["闇影島"],"普通"],"01SI050":["傾巢而出","召喚3隻小蜘蛛，並賦予我方蜘蛛單位+1|+0。","","剛孵化的時候胃口最好。","法術",[],["闇影島"],"稀有"],"01SI016":["使魅師","效忠：召喚1個霧魅。","","她總是無聲無息地現身，但她身後那群駭人的傢伙就沒這麼安靜了。","單位",[],["闇影島"],"稀有"],"01SI021":["鯊魚戰車","遺願：下次有閃靈友軍單位攻擊時，此牌將復甦並攻擊。","","「你說她看見了什麼？這樣我瞭解了。我說藥師啊，心智發狂既殘酷又容易令人深陷其中。至少其他人的說法不像她這麼荒謬。」——蒂瑪西亞醫生","單位",[],["闇影島"],"稀有"],"01SI032":["殞落王國編年史家","出牌：擊殺1個友軍單位，再將其復甦。","","很久以前，她曾坐在父親身邊，看他翻閱布滿灰塵的書卷。父親希望她將來能繼承藏品專家的衣缽，但萬萬沒想到會是這種形式。","單位",[],["闇影島"],"普通"],"01SI058":["幻影赦魔","出牌：擊殺1個友軍單位，並召喚1個魔耗值+2的隨機侍從單位。","","怨靈們，把聲音借給我！我們將協力召出\n無盡的黑暗！","單位",[],["闇影島"],"稀有"],"01SI054":["不死之握","從1個單位汲取3點生命值。","","亡者別無所求，只想讓生者不間斷的心跳聲\n停歇下來。","法術",[],["闇影島"],"普通"],"01SI044":["幽魂女戒護官","出牌：挑選1個手牌中的友軍單位，召喚1個與之相同的閃靈複製單位。","","殞落王者的詛咒所到之處，無一倖免。仁慈之人變得殘忍；勇敢之人變得野蠻；怨恨蒙蔽了理智。","單位",[],["闇影島"],"史詩"],"01SI039":["八爪夢魘","","","有些心懷惡意的怨靈從當地動物獲得靈感，常見的生物幻化為惡夢般的存在。","單位",["蜘蛛"],["闇影島"],"普通"],"01SI020":["燃魂人","召喚此牌時，復甦最強的已陣亡我方英雄。","","一根即將熄滅的蠟燭，除了點燃下一根新蠟燭，還能有什麼作用？","單位",[],["闇影島"],"稀有"],"01SI029":["吸星鬼哭","對所有敵軍單位造成1點傷害，並治療我方主堡3點生命值。","","我們每每被擊殺都將使他們更加強大。","法術",[],["闇影島"],"普通"],"01SI004":["黑潮災厄","","","有些人曾試著潛入潮水，避開殞落王者的詛咒，他們以為詛咒透不進海水深處。他們錯了。","單位",[],["闇影島"],"普通"],"01SI026":["獄長的獵物","遺願：在手牌隨機生成1張魔耗值為3以下的其他遺願侍從牌。","","他用盡全力屏住呼吸，祈禱獄長別發現自己。當時的他還不曉得，這場躲貓貓只不過是瑟雷西一連串恐怖折磨的開頭罷了……","單位",[],["闇影島"],"普通"],"01SI040":["惡趣胃","從1個單位汲取1點生命值，召喚1隻小蜘蛛。","","「夫……夫人！我不曉得你……這麼喜歡蜘蛛！能否請你命令牠們別爬上來？伊、伊莉絲夫人？求求你？」\n——倒楣的貴族，薩森領主","法術",[],["闇影島"],"普通"],"01SI015":["殞落王者的詛咒","擊殺場上所有單位。","","誰能料到如愛這般純粹的情感，也會招來全面毀滅的殘酷結局。 ","法術",[],["闇影島"],"史詩"],"01SI055":["食魂巨魔","","","「隨著船隻駛近陰森的海岸，我心想：『那些夢靨般的造物就是來自這些詭譎的沿海地區嗎？它們擁有過生命嗎？』」——蒂瑪西亞士兵，阿里．倫斯","單位",[],["闇影島"],"稀有"],"01SI047":["褪色回憶","挑選1個侍從單位。在手牌生成1張與之相同的閃靈複製牌。","","片刻之間，回憶映在眼簾。斑斑日光在她的肌膚上跳躍，飽滿多汁的黑刺莓在齒間迸裂，林地微風傳來悠悠樂聲，拂過她的耳邊。然後……畫面消失了。","法術",[],["闇影島"],"稀有"],"02PZ001":["潛水喵","召喚此牌時，抽1張牌。\n若本牌局我方已打出至少10張其他新卡牌，則賦予此牌+4|+0。","","沒有任何事能阻止他逃離只懂癡笑的人群，只不過是水而已，沒什麼好怕的。","單位",["貓族"],["皮爾托福&佐恩"],"史詩"],"02PZ010":["資深調查組員","召喚此牌時，雙方各抽1張牌。","","有些探長靠直覺破案，有些則靠線報，不過J．S．哈克諾探長的強項則純粹是靠努力：日夜不停地翻查檔案。","單位",["約德爾人"],["皮爾托福&佐恩"],"普通"],"02PZ006":["逮到你囉！","抽到此牌時，此牌本回合魔耗值-2。對1個單位造成3點傷害。","","「伯茲先生，可以麻煩你試試戴上這些手銬嗎？」\n「這對我有什麼好處？」\n「我會把它送給你當禮物。」\n「……那好吧。」\n「你被逮捕了！來人，把他帶走！」","法術",[],["皮爾托福&佐恩"],"普通"],"02PZ004":["蓄能衝擊","本回合給予1個友軍單位+2|+0。\n在手牌生成1張飛逝蓄能衝擊。","","「我的雙臂替我說話。」——菲艾","法術",[],["皮爾托福&佐恩"],"稀有"],"02PZ007":["新銳調查組員","我方打出魔耗值為2的卡牌時，抽1張牌並賦予其飛逝。","","「三流的偵探不知不覺，二流的偵探後知後覺，一流的偵探先知先覺。」——警備隊手冊","單位",[],["皮爾托福&佐恩"],"稀有"],"02PZ002":["首席機械師澤維","我方抽牌時，賦予其飛逝，\n並在手牌生成1張該牌的複製牌。","","年僅五歲，她便製作了世上第一把的多周波震動刀。這把刀雖然不是很實用（通常她只是用來切三明治），但還是幫她得到了警備隊菁英裝備部門的職位。","單位",[],["皮爾托福&佐恩"],"史詩"],"02PZ008":["菲艾","無論此牌在場上或在手牌中，我方每打出其他牌，便賦予此牌+1|+0（最多+8|+0）。","此牌單次打擊造成10點以上傷害。","「菲艾特警，拜託你稍微為他人著想一下可以嗎？出任務造成那麼多破壞，你知道傷害索賠的文書處理有多麻煩嗎！？」——新銳調查組員","單位",[],["皮爾托福&佐恩"],"英雄"],"02PZ009":["蛛絲馬跡","在手牌隨機生成1張魔耗值為2、我方區域的卡牌。本回合該牌魔耗值-2。","","「就這樣，」哈克諾探長宣布，「這條線索帶我們發現了……」","法術",[],["皮爾托福&佐恩"],"普通"],"02PZ003":["整裝待發","抽到此牌時，此牌本回合魔耗值-2。使1個友軍單位成長到4|4。","","「碼頭那邊有麻煩！帶上這些，代我問候他們。」\n——首席機械師澤維","法術",[],["皮爾托福&佐恩"],"稀有"],"02PZ005":["巡邏員警","抽到此牌時，本回合此牌魔耗值-1。","","米爾警官奔跑的模樣是隊上常出現的笑梗，不過凱普警官總是聽不懂。","單位",[],["皮爾托福&佐恩"],"普通"],"02BW040":["貝殼電擊者 ","","","「我最擅長命今平民白性，環有從不寫錯字」\n——寫在沙上的留言","單位",[],["比爾吉沃特"],"普通"],"02BW057":["狡猾踏浪者","","","「船長，我發誓我在珊瑚礁那邊看到了史上最奇怪的景象！那個笨蛋往橘子裡塞了什麼鬼啊，\n我一直在想……」——肖狗水手","單位",[],["比爾吉沃特"],"普通"],"02BW041":["深海巨怪","","","「無需害怕可厭野獸，\n因尚有人獲得救助，\n畏懼那些撞裂船頭，\n拉人入深淵的怪物。」\n——潦草刻在某間比爾吉沃特酒館屋樑上的歌謠","單位",["海怪"],["比爾吉沃特"],"普通"],"02BW013":["潛行割喉者","","","「然後那傻子就誇我有個『適合翻雲覆雨的臀』，我便跟他說再不停下花言巧語我就割下他的舌頭。」","單位",[],["比爾吉沃特"],"普通"],"02BW034":["聖猴神像","回合開始：對此牌造成2點傷害並召喚1隻火藥猴。","","「這是一個……紀念品，是從一個瘋瘋癲癲的老對頭手中奪過來的。那個白癡之前念念叨叨說著這東西蘊含『古代神祕力量』，看來還有點根據……」——好運姐","單位",[],["比爾吉沃特"],"稀有"],"02BW056":["深淵吞噬者","出牌：泯滅1個生命值低於此牌的敵軍單位。","","「有一天我踏上小船，\n遠離比爾吉沃特灣。\n突然刮起狂風大浪，\n深海女王從海浮上……」 \n——〈翼耳深海女王民謠〉","單位",["海怪"],["比爾吉沃特"],"史詩"],"02BW060":["神射海盜","我方攻擊時，對敵方主堡造成1點傷害。","","「人矮有其好處，打架時沒有人會留意下方。」","單位",["約德爾人"],["比爾吉沃特"],"普通"],"02BW011":["約德爾騙子","效忠：奪取1張牌，並在手牌生成1張警告射擊。","","「你懂得，朋友就是要互相幫忙。至於你嘛？我喜歡你雙眼炯炯有神，還有那把閃亮亮的水手刀，那可真是一柄好刀！」","單位",["約德爾人"],["比爾吉沃特"],"稀有"],"02BW030":["沉船囤積者","召喚此牌時，亂擲2張牌，並在我方牌組生成2張寶藏牌。","","「我跟你擔保，這些日子來水面下的寶藏比水面上還來得多。應該可以手到擒來的，但有她在就困難了。」\n——鋸斧屠夫","單位",["海怪"],["比爾吉沃特"],"史詩"],"02BW019":["泡泡熊","","","充盈魔法能量的洋流經過毒蛇群島的珊瑚礁，滋養著海域中奇異的生物。","單位",[],["比爾吉沃特"],"普通"],"02BW007":["惡賭徒","棄置2張牌即可出此牌。\n攻擊：抽2張牌並賦予其飛逝。","","「一般來說是很容易得手啦，桌邊的笨蛋們只顧啞著嗓子唱歌，根本不看賭桌。我才不甩他們呢，錢來了就對了，滾進我口袋總比留給他們好。」","單位",[],["比爾吉沃特"],"稀有"],"02BW014":["珊瑚小頑童","召喚此牌時，在手牌隨機生成1張魔耗值為1、我方區域的法術牌。","","大多數淺水域充滿了豐富的海洋生物，但與蔚藍航道的珊瑚礁比起來，盡皆相形遜色。蔚藍航道直如魔幻的異世界，處處都是驚奇。","單位",[],["比爾吉沃特"],"稀有"],"02BW055":["殘鉤團監工","洗劫：賦予各處魔耗值為1的友軍單位+1|+0。","","一旦她發射後，殘鉤團就必須趕快行動。水中的鮮血會招引各種來客……而且全都是不速之客。","單位",[],["比爾吉沃特"],"史詩"],"02BW017":["柑橘快遞猩","洗劫：治療所有友軍單位與我方主堡3點生命值，然後進行備戰。","","「水手們都覺得自己最強壯了，時常東邊吼來西邊吼去。對啦對啦，表現棒極了。但你們還是得吃橘子！養顏美容，鞏固牙齒，還能讓我笑咍咍。你要不吃，要不就下水，簡單吧。」","單位",[],["比爾吉沃特"],"稀有"],"02BW038":["電擊噴鰭魚","召喚此牌時，從我方牌組抽出1張魔耗值為3以下的法術牌。","","捷普曾經在三分鐘內游了蔚藍航道整整一圈，在尾段左閃右躲一一避開了熱鴉號四散的船骸！那天的海流實在是順啦！","單位",[],["比爾吉沃特"],"史詩"],"02BW021":["銳鱗獵人","出牌：賦予1個敵軍單位弱勢。","","「聽說他會游上幾公里只為尋找獵物，一旦發現目標就絕不失手。很難說他是人還是魚，但可以肯定的是，他對這片水域瞭若指掌，熟悉程度超過了我們所有人。」\n——鋸斧屠夫","單位",[],["比爾吉沃特"],"稀有"],"02BW035":["薔薇警長","召喚此牌時，賦予所有敵軍單位弱勢。","","比爾吉沃特也許是個法外之地，但在喧囂熱鬧的城市裡，有少數英勇無懼的人，正依著自己的理念，貫徹他們的正義。","單位",[],["比爾吉沃特"],"史詩"],"02BW058":["殘鉤團屠夫","洗劫：賦予此牌+1|+1。","","要加入殘鉤團絕非易事，水手必須證明自己有一手出色的航海、戰鬥及烹飪技術，差勁的應徵者一轉眼就會被三振出局。","單位",[],["比爾吉沃特"],"普通"],"02BW028":["怒濤狂鯊砲","洗劫：對敵軍單位隨機打出7次加農炮幕。","","「駛過水手，駛過殘骸，\n打鬥告終。\n霧氣消散後，船長遇見了雷克斯，\n船身於是支離破碎，成為斷裂的浮木。」\n——〈水手家之心〉","單位",[],["比爾吉沃特"],"史詩"],"02BW037":["深淵之眼","打擊主堡：抽1張牌。","","「船長一聲號令，他們升起船帆，\n前往娜敘亞麥，幫忙解決麻煩。\n但大海鬧翻臉，眾多兄弟入殮，\n只有倖存船員，能見全知之眼！」\n——〈全知之眼〉","單位",["海怪"],["比爾吉沃特"],"稀有"],"02BW008":["肖狗水手","出牌：召喚1個火藥桶，或隨機召喚1個魔耗值為1的侍從單位。","","他後來總算懂了，除了點燃的引線外，很少有東西能逼得打混水手認真幹活。","單位",["約德爾人"],["比爾吉沃特"],"稀有"],"02BW047":["殘渣打撈者","召喚此牌時，亂擲3張牌。","","能夠把好好的出海裝備全部弄壞，可以說是一種天分，不過這也是他們唯一的天分。","單位",[],["比爾吉沃特"],"普通"],"02BW004":["恐懼號水手","召喚此牌時，召喚1個火藥桶。","","「喂，我們可以天亮了再攻擊，不過那時他們的船員已經清醒，大砲也已填滿火藥；倒不如今晚偷偷送上一份大禮，大功告成、不動聲色……」","單位",[],["比爾吉沃特"],"普通"],"02BW002":["恐懼號","召喚此牌時，抽出剛普朗克。\n使我方法術、技能與友軍單位造成的所有傷害加倍。","","「呦齁齁，揮揮手帕，揚帆啟航，\n恐懼號將遨遊四方。\n我們要前進深淵，看那滿坑谷墓碑，恐懼號從不退卻！」\n——〈恐懼號出航曲〉","單位",[],["比爾吉沃特"],"史詩"],"02BW016":["拉霸機器人","召喚此牌時及回合開始：上回合我方每抽1張牌，則賦予此牌+0|+1，然後隨機分配其能力值。","","有一個原型轉到了三個炸彈然後整台爆炸，後來的型號就把這項功能移除了。","單位",[],["比爾吉沃特"],"稀有"],"02BW027":["狩獵艦隊","召喚此牌時，使敵方召喚1隻黃金獨角鯨。","","在海浪之下閃爍著光芒的不是金幣，也不是金條，而是一支光澤耀眼的號角，屬於殘惡艦隊總指揮那精明的死對頭。","單位",[],["比爾吉沃特"],"普通"],"02BW050":["圓滑獨奏家","洗劫：使手牌與牌組中所有友軍單位的魔耗值-2。","","「快跟我們踏上一場音樂之旅！欣賞符文大地各地的美妙旋律！謹記付費入場，還有給些小費……」\n——表演宣傳人員","單位",[],["比爾吉沃特"],"稀有"],"02BW015":["賽蓮號","召喚此牌時，抽出好運姐。\n此牌攻擊時，我方所有法術與技能造成1點額外傷害。","","你不會認錯賽蓮號的，那巨幅的珍珠色船帆，那精雕細琢的木工，散發華貴而俐落的形象，如同為其掌舵的船長。","單位",[],["比爾吉沃特"],"史詩"],"02BW010":["大盜普羅","洗劫：隨機賦予此牌2種特性。","","「那個貪心又殘忍的魔頭已經在懸賞告示板好長一段時間了，礙事的人都被他不眨眼地處理掉囉。你問我最糟糕的是啥？就是他……長得還怪可愛的，可惡！」\n——剛普朗克","單位",["普羅"],["比爾吉沃特"],"普通"],"02BW009":["鼬詐老千","召喚此牌後，於下次回合開始\n抽1張牌，並賦予其飛逝。","","「真是狗屁倒灶的鳥事，前面敲詐得正順手，怎麼就在最後栽了跟頭。唉，幸運女神又不想甩我了……」\n——惡賭徒","單位",[],["比爾吉沃特"],"普通"],"02BW005":["受僱槍手","召喚此牌時，賦予最強敵軍單位弱勢。","","「你就長這張猴臉？夭壽喔，簡直比懸賞令上的還不堪入目，希望你的人頭值得我浪費時間。」","單位",[],["比爾吉沃特"],"普通"],"02BW039":["青囊魚獵人","召喚此牌時，在手牌隨機生成1張海怪牌。","","財寶引誘無數水手出海，這些可憐的傢伙不久之後便會知曉大海有多可怕，以及為何倖存的人如此少。","單位",[],["比爾吉沃特"],"稀有"],"02BW006":["騙術士","出牌：幻化1個友軍單位，隨機變成魔耗值為5的侍從單位。","","「瑪威利歐？我的……我的手上哪了？」\n「看好啦，我要再把它們變出來！\n搭啦！咳咳……搭啦！」\n「……我天殺的手去哪啦？！」\n「好吧，感謝觀看，你們該滾了！」","單位",[],["比爾吉沃特"],"稀有"],"02BW036":["黃金獨角鯨","","","傳說有一隻白色的帶角鯨魚偷取了倒刺女神的東西。倒刺女神於是懲罰這隻貪婪的生物，以一層閃閃發亮的黃金覆蓋牠，讓牠終日受到他人貪念的荼毒。","單位",[],["比爾吉沃特"],"普通"],"02BW033":["黑市商人","抽出的敵方卡牌魔耗值-1。\n洗劫：奪取1張牌。","","「這裡應有盡有！還有一些『特別』貨色……記住，\n不要說是我賣給你的！」","單位",[],["比爾吉沃特"],"稀有"],"02BW032":["剛普朗克","召喚此牌時，召喚1個火藥桶。","我方對敵方主堡造成傷害累計5回合以上。","「不要瞪太久，不然會被他發現；不要說他壞話，比爾吉沃特任何風聲都逃不過他的耳朵。他來了，快低下頭，盯著地上。」——恐懼號水手","單位",[],["比爾吉沃特"],"英雄"],"02BW022":["好運姐","我方攻擊時，對所有戰鬥中敵軍單位與敵方主堡造成1點傷害。","此牌在場上時，我方進行4次攻擊。","「好運姐？在公開場合你得叫我『船長』。」","單位",[],["比爾吉沃特"],"英雄"],"02BW046":["飛斯","我方打出法術時，抵銷所有以此牌為目標的敵方法術/技能，並於本回合給予此牌隱密。","我方打出法術6次以上。","比爾吉沃特的傳奇人物當中，飛斯的性格乖戾又難搞。\n一些水手將附近發生的無數船禍都怪罪於他……","單位",["約德爾人"],["班德爾城","比爾吉沃特"],"英雄"],"02BW026":["逆命","出牌：打出1張「命運」卡牌。","此牌在場上時，我方抽出9張卡牌。","「專心看雙手的動作，計算卡牌數量，眼睛盡量跟上，\n然後別忘了……」","單位",[],["比爾吉沃特"],"英雄"],"02BW053":["納帝魯斯","","我方進入探底狀態。此牌升級時，複製被亂擲且魔耗值為4以上的友軍單位至我方牌組。","「錨被拔起帆被扯下，蘭科號轉眼變得七零八落。活下來的只剩我們幾個，而夜晚將至，寒冷也將隨之而來。抱歉了媽媽，你說的對，泰坦巨獸是真實存在的。」\n——殘破筆記拼湊出的內容","單位",[],["比爾吉沃特"],"英雄"],"02BW061":["祕密王牌","抽到此牌時，此牌本回合魔耗值-1。賦予一名友軍+2|+1。","","「手氣夠好，籌碼滾滾來。」——逆命","法術",[],["比爾吉沃特"],"普通"],"02BW024":["雙倍麻煩","隨機召喚2個魔耗值為1的侍從單位。","","「哎呀蓋夫，那不是我們在追的傢伙嗎？\n看來他多了一個同伴。」\n「巴茲，那……那是鯊魚人嗎？」\n「不管怎樣都是一大筆錢啦，對吧。」\n——未成氣候的賞金獵人巴茲和蓋夫","法術",[],["比爾吉沃特"],"稀有"],"02BW003":["強腕者","洗劫：將任一侍從單位召回至我方手牌。","","「你得替爾們工作啦！」——肖狗水手","法術",[],["比爾吉沃特"],"稀有"],"02BW025":["海之霸主","賦予1個敵軍單位弱勢，然後召喚巨齒鯊。","","「鯊魚出沒！」——飛斯","法術",[],["比爾吉沃特"],"普通"],"02BW012":["更多的火藥！","召喚2個火藥桶。","","「火藥桶！」——剛普朗克","法術",[],["比爾吉沃特"],"普通"],"02BW018":["槍火談判","對任1目標造成1點傷害。若擊殺該單位，則另外對敵方主堡造成1點傷害。","","剛普朗克的談判過程通常都很短，不過必定見血。","法術",[],["比爾吉沃特"],"普通"],"02BW048":["越獄","隨機召喚1個魔耗值為1的侍從單位。","","「巴茲，你怎麼看？這傢伙看起來不是很強。」\n「你確定嗎，蓋夫？他可是從監牢裡逃出來的耶……」\n「這只能說明他夠狡猾，而不是夠強。我們上吧！」\n——未成氣候的賞金獵人巴茲和蓋夫","法術",[],["比爾吉沃特"],"普通"],"02BW043":["選牌","將1張手牌洗入我方牌組即可出此牌。\n於下次回合開始抽2張牌，並賦予其飛逝。","","「運氣是自己創造出來的。」——逆命","法術",[],["比爾吉沃特"],"稀有"],"02BW051":["調皮小飛","從戰鬥中移除1個攻擊中的友軍單位，然後進行備戰。","","「快你一步！」——飛斯","法術",[],["比爾吉沃特"],"稀有"],"02BW054":["鋼鐵怒濤","擊暈1個敵軍單位。若我方場上有納帝魯斯，則將該單位洗入敵方牌組。","","「把他們拖入深淵……」——納帝魯斯","法術",[],["比爾吉沃特"],"稀有"],"02BW042":["心靈相通","本回合使所有友軍單位的力量值與生命值，成長到本牌局我方所打出的法術牌數量（不含此牌）。","","比爾吉沃特周邊海流湍急、波翻變幻，水手會害怕是理所當然；但他們並不全然了解，大海中所潛藏真正令人恐懼的力量。","法術",[],["比爾吉沃特"],"史詩"],"02BW059":["遜槍手","亂擲3張牌。對1個單位造成7點傷害。","","「能夠打沉敵人的，就是值得擁有的。」\n——比爾吉沃特俗語","法術",[],["比爾吉沃特"],"稀有"],"02BW023":["深淵之引誘","使我方各處海怪魔耗值-1。\n抽1張海怪牌。","","水手們低聲討論著即將降臨的黑暗日子——海面將翻騰湧動，無法言喻的怪物將從浪潮中破水而出。","法術",[],["比爾吉沃特"],"稀有"],"02BW031":["彈射","對1個敵軍單位造成2點傷害。若擊殺該單位，則另外對敵方主堡造成4點傷害。","","「我總是先發制人。」——好運姐","法術",[],["比爾吉沃特"],"稀有"],"02BW029":["打撈","亂擲2張牌，然後抽2張牌。","","船骸漂流物不會留在海面上太久的。稱職的船員得快速分辨哪些是高價貨物，哪些又是不重要的垃圾……","法術",[],["比爾吉沃特"],"普通"],"02BW049":["盜品","奪取1張牌。\n洗劫：再奪取1張。","","我的東西是我的，你的東西……也是我的。","法術",[],["比爾吉沃特"],"普通"],"02BW001":["警告過你囉","本回合給予1個敵軍單位弱勢，若該單位於本回合陣亡，則我方抽1張牌。","","「孩子們，抬頭挺胸打起精神！被船長發現你在打混就等著被大卸八塊餵海鷗吧，還不快給我動起來！」\n——恐懼號水手","法術",[],["比爾吉沃特"],"普通"],"02BW063":["障眼法","洗劫：從敵方手牌隨機抽1張非英雄牌。","","「打牌不看運氣，而是看人。成功讓對手懷疑自己，他們的一切就屬於你了。」——逆命","法術",[],["比爾吉沃特"],"稀有"],"02BW045":["槍林彈雨","在敵軍單位與敵方主堡中\n隨機對3個不同目標\n造成1點傷害。","","「火力全開！」——好運姐","法術",[],["比爾吉沃特"],"普通"],"02BW020":["警告射擊","對敵方主堡造成1點傷害。","","「老兄，你應該要跟我們一起開火的！懂不懂什麼叫做全體開炮啊！」——肖狗水手","法術",[],["比爾吉沃特"],"普通"],"02BW044":["海難投棄","亂擲4張牌。","","「沒有價值的東西，就會被拋進大海，包括你們在內。快點去幹活吧！」——肖狗水手","法術",[],["比爾吉沃特"],"稀有"],"02BW062":["島嶼領航員","召喚此牌時，隨機召喚1個魔耗值為1的侍從單位，並賦予其先遣。","","「海蛇之母恩光普照，\n從海底直到雲霄。\n灰色天空凝視地上，\n平靜海面仿佛反射她的目光。\n她輕輕微笑，心靈安詳。」\n——獻給娜葛卡布爾的禱告","單位",[],["比爾吉沃特"],"稀有"],"02FR009":["狂狼騎士","洗劫：獲得1格魔力寶石槽位。","","冬之爪部落中，在年輕的劫盜者能夠拿起武器的那一刻，他們便會被分派到一隻幼狼，從此他們會接受訓練，成為戰鬥機器：幼狼學習如何咬斷敵人的喉嚨，而騎手則學習如何劫掠和偷竊。","單位",[],["弗雷爾卓德"],"普通"],"02FR004":["寒風刺骨","本回合給予1個敵軍單位凍傷與弱勢。","","「這些溫血人在弗雷爾卓德活不過一天！」\n——史瓦妮","法術",["元素"],["弗雷爾卓德"],"稀有"],"02FR002":["史瓦妮","出牌：本回合給予1個敵軍單位凍傷與弱勢。","我方對敵方主堡造成傷害累計5回合以上。","史瓦妮的冰星錘的確強大，不過她自己才是真正的武器：一把經歷過弗雷爾卓德艱苦寒冷磨練和試煉的\n武器。","單位",[],["弗雷爾卓德"],"英雄"],"02FR001":["縱火女強盜","回合開始：對所有目標造成1點傷害。","","「他們努力耕田，\n默默撒種。\n我們隨心所欲，\n燒光一切！」\n——冬之爪童謠","單位",[],["弗雷爾卓德"],"稀有"],"02FR005":["巨熊族靈魂行者","洗劫：此牌幻化為風暴之爪巨熊。","","巨熊族原是人類，不過他們放棄了本來備受禁錮的凡體，換來偉大神靈弗力貝爾所賜予的野性力量。","單位",[],["弗雷爾卓德"],"普通"],"02FR010":["集體分贓","賦予我方牌組最上方\n3個單位+1|+1。\n洗劫：隨後抽出其中1張。","","「有好東西要跟好朋友『分享』嘛。」\n—— 無情劫掠者","法術",[],["弗雷爾卓德"],"稀有"],"02FR008":["角獸劫掠者","召喚此牌時，抽張史瓦妮。\n洗劫：使我方牌組中單位的力量值和生命值加倍。","","「春天不只帶來適合種植的溫暖天氣，也會帶來劫盜船……本來數量繁多的糧食也會變得稀少。」\n——艾伐洛森爐衛","單位",[],["弗雷爾卓德"],"史詩"],"02FR007":["北境之怒","本回合給予1個友軍單位+3|+4。","","「擁抱心中的野性吧！」 ——史瓦妮","法術",[],["弗雷爾卓德"],"普通"],"02FR006":["無情劫掠者","","","冬之爪在弗雷爾卓德無人能比，而且這些無情劫掠者的兇猛性格眾所皆知，一旦他們被嗜血狂怒沖昏頭腦，他們的對手只能祈求自己死得痛快。","單位",[],["弗雷爾卓德"],"普通"],"02FR003":["普羅極光","在手牌生成2張隨機普羅牌及2張普羅點心。","","「當你仰望夜空，\n向普羅許願時，\n便會看到點心\n在群星之中閃閃發亮。」\n——少女英格娃","法術",[],["弗雷爾卓德"],"史詩"],"02NX001":["海王號","召喚此牌時，抽張斯溫。\n回合開始：對敵方主堡造成1點傷害2次。","","當愛歐尼亞居民看見那東西從地平線出現時，他們以為自己看到了一隻怪物。其實也八九不離十了，因為那艘鋼鐵戰艦異常駭人，是諾克薩斯海軍工程史上最驚人的成就。","單位",[],["諾克薩斯"],"史詩"],"02NX007":["斯溫","打擊主堡：對敵方主堡造成3點傷害。","我方造成14點以上非戰鬥傷害。","「一股凡人無法理解的力量，讓我能夠看見常人無法看見的事物，洞察常人恐懼的黑暗。」","單位",[],["諾克薩斯"],"英雄"],"02NX006":["攻城投石機","回合開始：對敵方主堡造成1點傷害。","","長老的聲音出乎意料地冷靜。「諾克薩斯人每次都成功地推翻我們建造的城牆，」他問道：「請你告訴我，現在採集石材來建更高的城牆又有何意義呢？」","單位",[],["諾克薩斯"],"稀有"],"02NX002":["奧洛．爍角 ","攻擊：擊暈所有負傷敵軍單位。","","「多年來，我們屈服於他人，直到諾克薩斯征服了這片土地，我們才明白到何謂真正的自由，這也是我為帝國而戰的理由。」","單位",[],["諾克薩斯"],"史詩"],"02NX009":["群鴉盛宴","對1個負傷或遭到擊暈的單位造成4點傷害。","","快聽，你聽見了嗎？那如雷貫耳的是上千雙羽翼\n的拍擊聲。","法術",[],["諾克薩斯"],"稀有"],"02NX004":["帝國炸彈工兵","出牌：對1個友軍單位造成1點傷害，然後對敵方主堡造成2點傷害。","","「悄無聲息，直到轟地一聲！」","單位",[],["諾克薩斯"],"普通"],"02NX003":["諾克薩斯狂熱","對1個友軍單位造成3點傷害，以對任1目標造成3點傷害。","","「犧牲是必須的。」——傑利科．斯溫","法術",[],["諾克薩斯"],"普通"],"02NX010":["披甲角獸騎兵","力量值為5以上的敵軍單位才能對此牌造成傷害。","","「戰爭怪獸一旦啟動，便無人能擋。不想死就滾開吧。」——巨異蜥騎兵","單位",[],["諾克薩斯"],"稀有"],"02NX008":["靈魂拷問","對1個敵軍單位造成2點傷害，並對敵方主堡造成1點傷害。","","「起碼也死得有尊嚴一點吧。」——斯溫","法術",[],["諾克薩斯"],"普通"],"02NX005":["幽鐵弩砲","","","「只要有好的武器，攻城易如反掌。投石機能夠引誘他們出城；弩砲車則能夠將他們擊倒。」\n——圍城技師","單位",[],["諾克薩斯"],"普通"],"02DE003":["忠心獾熊","","","俗語說得好：「主人寵物一個樣」。","單位",[],["蒂瑪西亞"],"普通"],"02DE008":["巨角獸拍檔","","","新加入的遊俠會和夥伴在森林一同生活幾個月，學著了解巨角鹿的一舉一動。這項訓練需要耐心才能完成，不過一旦培養出默契與感情，就沒人能離間他們。","單位",[],["蒂瑪西亞"],"普通"],"02DE004":["綠牙守衛","","","「我發誓守護這片森林，以及在該處尋求庇護的一切。」","單位",["菁英"],["蒂瑪西亞"],"普通"],"02DE006":["葵恩","召喚此牌時，召喚威洛。","此牌在場上時，我方進行4次攻擊。","「葵恩是一名勇敢無懼的遊騎兵，加上威洛在她身邊和天空中陪伴，這對拍檔無人能擋。」\n——游騎兵珍妮薇·艾姆哈特","單位",[],["蒂瑪西亞"],"英雄"],"02DE009":["老練遊俠","遺願：召喚1隻忠心獾熊。","","伯特蘭出自班德爾斥侯團，並榮獲無數勛章，就只差\n「笑臉迎人」獎。","單位",["約德爾人"],["蒂瑪西亞"],"稀有"],"02DE005":["不屈靈魂","賦予1個友軍單位「傷害及死亡免疫」。","","這名遊俠忍著腿上的劇痛，再度站起身來，高舉佩劍。她能夠再站起來，不只單靠自己的決心，還有整個蒂瑪西亞的意志在支撐著她。","法術",[],["蒂瑪西亞"],"史詩"],"02DE002":["飛鷹突擊","召喚威洛。","","「飛到我頭髮裡了，我的頭髮！」——軍團流寇","法術",[],["蒂瑪西亞"],"稀有"],"02DE010":["珍妮薇．艾姆哈特","召喚此牌時，本回合給予其他友軍單位+1|+1。","","蒂瑪西亞遊俠戰鬥時的模樣鼓舞人心——他們人獸合一並肩作戰，形影不離，而且意志堅定。","單位",[],["蒂瑪西亞"],"史詩"],"02DE007":["遊俠決心","本回合給予所有友軍單位堅忍。","","「敵人逼近時，無需膽怯，樹林會保護我們。」\n——綠牙守衛","法術",[],["蒂瑪西亞"],"稀有"],"02DE001":["協力打擊","挑選1個敵軍單位，使2個友軍單位輪流打擊該單位。","","「快過來，與我並肩作戰！」——綠牙守衛","法術",[],["蒂瑪西亞"],"普通"],"02SI005":["魔法樹液","亂擲3張牌。\n治療所有友軍單位3點生命。","","「島嶼將被淨化。」——茂凱","法術",[],["闇影島"],"稀有"],"02SI010":["死花漫遊者","召喚此牌時，亂擲3張牌。","","「偉大的樹人不斷展示……生物。這隻生物……她所到之處必有生命……十分驚人……這個地方。天堂島名非虛傳！」——拼湊起來的無名日記","單位",[],["闇影島"],"普通"],"02SI008":["茂凱","每回合我方首次召喚友軍單位時，\n亂擲2張牌並召喚1個小樹精。","我方單位陣亡或卡牌遭亂擲共計25次以上。","這片詛咒大地也拿茂凱沒轍，這名樹人的意志太過堅定、憤怒太過熾熱，無人能敵、無物能擋。","單位",[],["闇影島"],"英雄"],"02SI007":["尖刺蛤蟆","遺願：亂擲2張牌並治療我方主堡2點生命值。","","「……非常出色的品種……這就是我小時候遇到過的那隻生物……一點都沒有變老！真想知道……下一個城鎮。說不定這些傢伙長生不老！」——拼湊起來的無名日記","單位",[],["闇影島"],"普通"],"02SI003":["鬼船怪物","使我方海怪單位擁有威嚇。\n攻擊：本回合給予場上所有敵軍單位-2|-0。","","他們察覺到危機時，為時已晚。巨大的怪物張開血盆大口，朝他們猛然攻擊；想要捕獲怪物的獵人，只能看著無盡的利齒逐漸粉碎他們的船隻，\n等待死亡臨頭。","單位",["海怪"],["闇影島"],"史詩"],"02SI001":["冥河集魄人","每有1個其他友軍單位陣亡，\n便從敵方主堡汲取1點生命值。","","「碰上了那個叫……尼凡的新任擺渡人！他……載我們去……他很會唱歌！……在那之前……得邀請他來吃晚餐。」——拼湊起來的無名日記","單位",[],["闇影島"],"稀有"],"02SI002":["巨型食人蔓藤","打出侍從單位時，擊殺該單位以召喚1株巨型食人蔓藤。","","「今天……又有驚人的……四處冒出來……孩子們都非常害怕。不過……並不威脅。整天靠過來……真是不怕人的傢伙。得為牠們收集多一點莓果！」\n——拼湊起來的無名日記","單位",[],["闇影島"],"史詩"],"02SI004":["樹精保姆","出牌：擊殺1個友軍單位以召喚2個小樹精。","","「每顆心都像一座花園，等著大樹生根！」","單位",[],["闇影島"],"稀有"],"02SI006":["低吼樹怪","友軍單位首次陣亡時，賦予此牌+2|+2。","","闇影島的生物早就捨棄情感；他們都得\n吃點什麼才行。","單位",[],["闇影島"],"普通"],"02SI009":["扭曲樹精","於下次回合開始召喚1個小樹精。","","「耶～」——小樹精","法術",[],["闇影島"],"普通"],"02IO008":["虎嘯龍吟","本回合給予1個友軍單位挑戰者。在手牌生成1張飛逝震驚百里。","","「克己復禮……」——李星","法術",[],["愛歐尼亞"],"普通"],"02IO002":["龍麟拳師","召喚此牌時，在手牌生成1張龍之庇護。","","「學徒必須慈悲為懷，因為巨龍養育了最初淨土，並賜予溫暖和生命。」——龍道所傳教義","單位",[],["愛歐尼亞"],"普通"],"02IO006":["李星","我方打出法術時，本回合給予此牌挑戰者；\n再次打出法術時，本回合給予此牌光盾。","我方打出法術8次以上。","「配得的人，巨龍賜予協助；疲乏的人，巨龍賜予活力；患病的人，巨龍賜予舒緩；迷失的人，巨龍賜予光芒；動搖的人，巨龍賜予平衡……」","單位",[],["愛歐尼亞"],"英雄"],"02IO004":["龍角力士","","","「學徒必須全力以赴，因為巨龍使旱地從海中隆起，賜予我們名為家鄉的土地。」——龍道所傳教義","單位",[],["愛歐尼亞"],"普通"],"02IO003":["龍瞳修行者","回合開始：川流：召喚1隻幼龍。","","「學徒必須思想清晰，因為巨龍的牽引讓太陽劃過天際，照亮我們的世界。」\n——龍道所傳教義","單位",[],["愛歐尼亞"],"史詩"],"02IO001":["龍爪女俠","此牌在手中時，在同一回合中打出2張法術牌後召喚此牌。","","「學徒必須專心聆聽，因為巨龍發出了原初之咆哮，將魔力賜給我們未臻成熟的心靈。」——龍道所傳教義","單位",[],["愛歐尼亞"],"普通"],"02IO005":["震盪掌","擊暈1個敵軍單位來召喚1位龍尾武術家。","","「我離開時無影無蹤，歸來時亦杳無聲息。」\n——龍尾武術家","法術",[],["愛歐尼亞"],"稀有"],"02IO010":["走為上策","召回1個友軍單位以在手牌生成1張飛逝打道回府。","","第一批在愛歐尼亞登陸的諾克薩斯人，遇到一群且毫無準備的弱軍。諾克薩斯人屠殺無數，但有其中一群從虎口逃生……","法術",[],["愛歐尼亞"],"稀有"],"02IO007":["神龍擺尾","使1個友軍單位將1個敵軍單位踢向\n敵方主堡，打擊該敵軍單位後再打擊敵方主堡。若敵軍單位存活，則將其召回。","","「必須釋放巨龍，不然牠會從內心吞噬我。」\n——李星","法術",[],["愛歐尼亞"],"史詩"],"02IO009":["深度冥想","川流：此牌魔耗值-2。\n抽2張其他法術牌。","","靜心冥想無法預設目的，必須在過程中迷失，\n才能尋得其道。","法術",[],["愛歐尼亞"],"稀有"],"03NX019":["弱肉強食","使對手棄置手牌中最弱的侍從牌。","","「弱者根本不該存在這世界上。對他們來說，每天都是新的折磨，彷彿被掐住喉嚨，日漸窒息。我殺人不是為了取樂，而是出於憐憫。」——獵捕手艾瑞兒","法術",[],["諾克薩斯"],"稀有"],"03NX022":["狂野利爪","使1個友軍單位打擊1個敵軍單位。若其有蠻力，則將超額傷害加諸敵方主堡。","","「喔，野蠻人今天看起來格外狂野！鄉親們，離這些爪子遠點喔！」——競技場主持人","法術",[],["諾克薩斯"],"史詩"],"03NX007":["雷玟","召喚此牌時，若我方擁有攻擊主動權，以及我方獲得攻擊主動權時，進行重鑄。","我方生成了放逐之刃。","「我不會逃避過去的自己，因為我已承諾要修復當初所破壞的事物……」","單位",[],["諾克薩斯"],"英雄"],"03NX006":["破刃殘柄","本回合給予1個友軍單位+2|+0。進行重鑄。","","「要了解你的敵人，首先要了解他的武器。它會告訴你對方如何移動、思考以及攻擊時機。武器就是主人最純粹的表達方式。」——獵捕手艾瑞兒","法術",[],["諾克薩斯"],"普通"],"03NX002":["獵捕手艾瑞兒","回合結束：若本回合我方曾對\n此牌打出法術，則使此牌\n打擊最弱敵軍單位。","","「儘管躲啊，我們會找到你。\n就連呼吸，我們都聽得到。\n盡量跑吧，我們會殺了你。」","單位",[],["諾克薩斯"],"史詩"],"03NX018":["壓制","擊暈1個敵軍單位。\n若我方場上有達瑞斯，則進行備戰。","","「我自己來就行了。」——達瑞斯","法術",[],["諾克薩斯"],"稀有"],"03NX009":["狂怒騎士","","","「沒有什麼比獵殺其他士兵更棒的了。要追蹤他們，就要同理他們的思考與感受。要抓住他們，就必須畏懼他們，就像他們畏懼你一樣。大部分的人可能不明白，但我最珍惜的就是這樣的羈絆。」","單位",[],["諾克薩斯"],"普通"],"03NX017":["巨異蜥血魔","出牌：對1個友軍單位與1個敵軍單位造成1點傷害4次。","","戰鬥前幾天，巨異蜥馴獸師不會讓牠們吃活的獵物。\n等到那些猛獸被釋放時，牠們會變得不分敵友，\n並且所向無敵。","單位",["爬蟲族"],["諾克薩斯"],"史詩"],"03NX015":["生存技巧","本回合友軍單位的生命值不會降到0以下。\n棄置此牌時，本回合最強友軍單位的生命值不會降到0以下。","","「龍犬聞到味道了，牠們會找到她，然後做個了結，除此之外別無他法。」——獵捕手艾瑞兒","法術",[],["諾克薩斯"],"稀有"],"03NX014":["打磨心志","本回合給予1個友軍單位+3|+2。","","「當然，我會修理你們的武器、照顧坐騎，再煮飯給你們吃。不然我還有什麼用處呢？」\n——護刃隨從埃拉特","法術",[],["諾克薩斯"],"普通"],"03NX003":["護刃隨從","遺願：進行重鑄。","","「正如女獵手所說，一百個日與夜，永不停歇；腳上長了一百個水泡，早餐裡有一百隻蟲子，聽過一百次『手刃』、『復仇』云云，耳朵都快長繭了。至於被那三人言語霸凌，就遠遠不止一百次了……」 ","單位",[],["諾克薩斯"],"普通"],"03NX001":["符文編鑄者","召喚此牌時，進行重鑄。","","「大部分的武器都是粗糙的工具，不會比徒手戰鬥好到哪去。但注入符文魔法的武器就不僅僅是一塊廢鐵了。」","單位",[],["諾克薩斯"],"普通"],"03NX005":["殘酷獵手","召喚此牌時，本回合給予此牌快速攻擊。","","「原來你在這啊。我們就知道不來硬的，你絕對不會俯首稱臣！至少我們是這麼希望的。」","單位",[],["諾克薩斯"],"稀有"],"03BW006":["優勝者傑克","回合開始：在手牌生成1張鯊幫制裁。","","在擂台上闖蕩多年，讓傑克學到了許多寶貴的經驗。他學到只要對手會流血，就會懂得害怕；他學到冷眼凝視的威力；他也學到了毫無所忌的暴力有多強大。","單位",[],["比爾吉沃特"],"史詩"],"03BW010":["河流饗宴","使1個友軍單位俘虜另1個友軍單位，並獲得被俘單位的能力值。","","「進來吧，朋友，那麼你想要的東西將永遠屬於你。」\n——貪啃奇","法術",[],["比爾吉沃特"],"普通"],"03BW005":["沉沒代價","將1個單位或地標洗入其牌組。","","「聽著，朋友，我給了你想要的東西，但我從沒說過那是永久的。」——貪啃奇","法術",[],["比爾吉沃特"],"稀有"],"03BW004":["貪啃奇","召喚此牌時及回合開始：在手牌生成1張品味獨到。","此牌俘虜3個以上單位。此牌升級時，泯滅被此牌俘虜的敵軍單位，若為友軍單位則將其釋放。","「朋友，我知道那個表情。我看得出來，你覺得自己滿手爛牌。你想要更棒的對吧？我或許能滿足你的渴望，讓你品嚐最想要的東西。只需在這紙上簽名……而你，我的朋友，你的生命就會得到滿足。」","單位",[],["比爾吉沃特"],"英雄"],"03BW002":["貴公子蜥蜴","回合開始：對此牌造成2點傷害。","","「唉，人們就是蠢！只要有冰涼的飲料跟溫暖舒適的椅子，他們就會把各式各樣的祕密告訴貌似善良的人。你說，還有誰的臉比年輕的李奧納德看起來更友善呢？」——蟾蜍算命師","單位",[],["比爾吉沃特"],"普通"],"03BW014":["耍猴戲","召喚1隻火藥猴。\n洗劫：下次回合開始再召喚1隻。","","「哎喲，你看牠們一副天真可愛的樣子？才怪！牠們會到處搗亂，比暈船的嚮導還槽糕，而且一直吵個不停！猴子不准上船，這是規矩！」——肖狗水手","法術",[],["比爾吉沃特"],"普通"],"03BW007":["章魚拳師","出牌：對此牌造成3點傷害。","","「當然，帕布羅的確是遇上了小低潮，而且也吃了不少拳頭……不過你知道嗎？這兒真還沒有其他人能用八拳流打遍天下無敵手的。」——奸巧魚老大","單位",[],["比爾吉沃特"],"普通"],"03BW016":["轟隆戰艦","對1個單位造成1點傷害，\n然後召喚與造成傷害量\n相同數量的火藥桶。","","「年輕的吉朗特才剛發出警報，第一發攻擊就來了。船體劇烈搖晃，船首三角帆也起火了，但熱鴉號還撐得住。我以為這樣就結束了，但當我隨著吉朗特的視線望向大海，才看到還有四艘划艇正駛向我們，全都載滿了火藥。」\n——熱鴉號倖存者","法術",[],["比爾吉沃特"],"稀有"],"03BW001":["殘惡碼頭","回合開始：亂擲1張牌。若我方已探底，則摧毀此牌以隨機召喚1個海怪單位。","","每天當地居民都會在殘惡碼頭流連，想一探比爾吉沃特的水手們，從深淵中把什麼樣的怪物捕了上來。那些海怪們通常都已經死了……嗯，通常啦。","地標",[],["比爾吉沃特"],"史詩"],"03BW015":["硬脾氣老蠍","出牌：對此牌造成2點傷害。","","「還不敲鐘開打？我要讓那個帶刺的老傢伙見識見識我的眾多名號是怎麼來的，沒錯，他們叫我『八拳帕布羅』、『大猛海怪』，還有『駭人觸手』！這場打完絕對讓你夾著螫針哭著回家叫媽媽！」——章魚拳師","單位",[],["比爾吉沃特"],"普通"],"03BW003":["奸巧魚老大","出牌：對所有其他友軍單位造成1點傷害，且每傷害1個友軍單位，便賦予此牌+1|+0。","","奪權的過程通常都會發生暴力事件……但通常不會這麼隨便。","單位",[],["比爾吉沃特"],"稀有"],"03BW017":["搖擺泡泡魚","本牌局我方每打出1張法術，此牌魔耗值便-1。\n召喚此牌時，在手牌隨機生成1張魔耗值為1、我方區域的法術牌。","","「哩正，猜鳥！你的楞務是潛路敵軍陣線，儘量骯裝泡泡，郎後回報你縮抗到的一切！一、切！東瞭嗎？！」——貝殼電擊者，海軍上將雪利","單位",[],["比爾吉沃特"],"史詩"],"03BW008":["蟾蜍算命師","出牌：對此牌和1個友軍單位造成1點傷害以抽1張牌。","","「老芭布斯出過一些事。她年輕時殺了幾個當地人，不過我想這讓她建立了一些口碑。」——貴公子蜥蜴","單位",[],["比爾吉沃特"],"普通"],"03BW020":["火藥大騷亂","本牌局每發動1次洗劫，便召喚1隻火藥猴。","","「噢，這些小黑炭沒那麼不好。給你個建議，牠們喜歡煙火，所以等你奪來了敵方的火藥庫，嗯，剩下的交給猴子們來處理就好。」——好運姐","法術",[],["比爾吉沃特"],"史詩"],"03BW009":["勒索","對1個友軍單位造成2點傷害以賦予2個敵軍單位弱勢。","","「嫩咖，要告訴我你是從哪搞來那些『額外的桶子』嗎？嗯？不然我們可以讓你的舌頭和勁波的手臂來場拔河比賽。兄弟……我可不會賭你贏。」——奸巧魚老大","法術",[],["比爾吉沃特"],"稀有"],"03DE010":["偉大廣場","召喚友軍單位時，本回合給予其+1|+1與挑戰者。","","塔蒂雅娜瞭望人群，打量著集合的部隊。廣場上只聽得到微風吹動她的旗幟的聲音。她滿意地點了一下頭，然後舉起旗幟大聲呼喝：「誰準備好為蒂瑪西亞而戰？」集合的部隊齊聲高喊，連群山都為之震撼。 ","地標",[],["蒂瑪西亞"],"史詩"],"03FR009":["咆嘯深淵","回合開始：在手牌生成1張不存在於我方手牌、牌組或場上的隨機等級2英雄。","","受到未知的呼喚，英雄們來到這座橋上，面對刺骨寒風和搖搖欲墜的橋面，他們無一絲畏懼，只想知道未來的命運——不論是勝利或死亡。","地標",[],["弗雷爾卓德"],"史詩"],"03MT005":["分歧之路","抽1張地標牌或摧毀1個地標。","","巨石峰瞬息萬變，堅硬之處會破碎，崩落之地卻能\n復原。","法術",[],["巨石峰"],"普通"],"03SI009":["希利亞寶庫","回合開始：擊殺魔耗值最高的友軍單位，並從我方牌組召喚1個魔耗值+1的友軍單位（若無則不發動效果）。","","要引誘靈魂到這個鬼地方，有什麼能比承諾給予永生和無盡的財富來得有用呢？","地標",[],["闇影島"],"史詩"],"03IO006":["希安那修道院","回合開始：在手牌生成1張庇護所。","","隱身於愛歐尼亞深山中的幾座修道院，是想聚精會神、潛心修練之人的庇護所。","地標",[],["愛歐尼亞"],"史詩"],"03NX013":["焦土作戰","擊殺1個負傷單位或摧毀1個地標。","","「龍犬聞到味道了，牠們會找到她，然後做個了結，除此之外別無他法。」——獵捕手艾瑞兒","法術",[],["諾克薩斯"],"普通"],"03NX004":["諾薩克拉亞競技場","回合結束：使最強友軍單位與最弱敵軍單位互相打擊。","","「哈囉，各位角鬥競技迷，你們準備好迎接烈火之環最火燙刺激的夜晚了嗎？哇，看來小崔克今天抽到了籤王，他要對決強大的戰士葛納——克大王！醫護人士請到場邊待命，這場很快就會結束！」——競技場主持人","地標",[],["諾克薩斯"],"史詩"],"03DE004":["艾莉卡上尉","出牌：俘虜1個單位或地標。","","艾莉卡小時候親眼目睹諾克薩斯軍隊摧殘她的家園。入伍時，她發誓絕不再讓諾克薩斯的旗幟插在蒂瑪西亞的土地上，也不會讓任何孩子淪為孤兒。","單位",["菁英"],["蒂瑪西亞"],"稀有"],"03IO005":["歸途","召回1個友軍單位或地標，以召回1個敵軍單位或地標。","","「崔弗，回來啊啊啊……」——崔弗的樹屋","法術",[],["愛歐尼亞"],"普通"],"03MT052":["星泉","回合結束：先治療所有負傷友軍單位1點生命值。接著，此牌在場上時，若我方治療友軍單位22點以上，則贏下牌局。","","「聖流之上，\n水池深處，療癒之泉\n閃耀之光，微明之水，\n聆聽河流之歌，\n水晶山脈之巔。」\n——〈獺人詩篇〉","地標",[],["巨石峰"],"史詩"],"03MT064":["巨石峰之巔","回合開始：本回合使雙方手牌中1張隨機卡牌的魔耗值降至0。","","巨石峰的守護者以晶體雕刻而成，看守著通往天界的大門。在他面前，希望、懷疑、恐懼……一切都將不復存在。他的試煉會剔除一切世間煩惱，登峰者的靈魂將展露無遺。守護者將審判他們的靈魂，因為他就是偉大的凜峰仲裁者。 ","地標",[],["巨石峰"],"史詩"],"03SI008":["同命","擊殺1個友軍單位，以擊殺1個單位或摧毀1個地標。","","這些鬼島上沒有永恆之物，一切都將終結。","法術",[],["闇影島"],"稀有"],"03PZ001":["皮爾托福大學","回合開始：棄置我方所有手牌，接著在手牌生成3張隨機卡牌，並賦予其飛逝。","","賽爾．畢．漢默丁格教授的發明讓他出了名，但卻是他生動的講課風格，以及難以預測的可怕教學示範，在皮爾托福的聰明人士心中留下了難以磨滅的印象。","地標",[],["皮爾托福&佐恩"],"史詩"],"03FR003":["虛厄凝獸","出牌：泯滅所有地標或對所有其他單位造成3點傷害。","","「根本沒時間帶上家當或警告其他人。我們只能狂奔向森林，眼睜睜看著牠夷平我們的家園。」\n——艾伐洛森爐衛","單位",[],["弗雷爾卓德"],"稀有"],"03MT026":["日光之矛拉馮","破曉：在手牌隨機生成1張破曉牌。\n此牌在場上時，我方卡牌\n不論日夜皆可觸發破曉。","","「拉克爾，保持信念，我們的光輝就會永不熄滅！」","單位",[],["巨石峰"],"稀有"],"03MT067":["晶角野山羊","出牌：賦予1個友軍單位蠻力。","","想攀登巨石峰的人會和當地的野生動物好好相處。這裡的動物最瞭解巨石峰的危險，也能用更快的速度通過結冰的地勢。","單位",[],["巨石峰"],"普通"],"03MT084":["星之誕","祈望1張魔耗值為7以上的天界牌，並治療1個友軍單位或我方主堡5點生命值。","","「仰望星空吧。幸運的話，還會跟我四目相對呢。」\n——翱銳龍獸","法術",[],["巨石峰"],"普通"],"03MT221":["劍齒獸座","出牌：祈望1張魔耗值為3以下的天界牌。","","「月亮母親，請為我指引方向，\n撕裂蒼穹，\n讓我得見更高境界。」\n——月環教禱辭","單位",[],["巨石峰"],"史詩"],"03MT093":["星迴百轉","對1個遭到擊暈或本回合攻擊過的敵軍單位造成5點傷害。","","「砰！」——柔依","法術",[],["巨石峰"],"普通"],"03MT073":["月環喚暮者","召喚此牌時，在手牌生成1張暮花之塵。","","「暮花只在滿月時綻放，是月環教引以為傲的象徵。我們使用暮花之塵已有數百年歷史，只有我們知道正確的採集方式。」","單位",[],["巨石峰"],"普通"],"03MT002":["天界殞落","我方場上每有1位龍族或天界友軍單位，此牌魔耗值便-2。對所有敵軍單位造成15點傷害。","","「等時機成熟，也許我會拿符文大地來殺雞儆猴。或許我可以拖著這個被焚為灰燼、了無生機的空殼，作為他人永世的警惕。就像一個毫無用處的玩具一樣。再看看吧，目前還沒考慮太多。」——翱銳龍獸","法術",[],["巨石峰"],"史詩"],"03MT217":["亞菲利歐","夜臨：挑選1張月之武器，在手牌中生成。\n每回合首次打出2張其他卡牌時，若我方尚未擁有已變取的月之武器，則在手牌中生成1張。","我方打出月之武器4次以上。","「每一次對抗，我們都是在向日輪教證明，我們應該得到尊重。我們已經讓他們知道，月光能與他們的日光平起平坐，我們已經讓他們知道，不要看輕自己不懂的事物，以及那些他們還沒學會的教訓……」——月環教陰晴講者","單位",[],["巨石峰"],"英雄"],"03MT044":["耀日守護者","破曉或我方發動其他破曉效果時：賦予此牌+1|+1。","","「光明的守護者啊，你的憤怒如同正午的烈日一般燃燒，請務必懲罰闖入聖地的無禮之徒。」——耀日守護者銘文","單位",[],["巨石峰"],"史詩"],"03MT056":["黛安娜","夜臨或我方發動其他夜臨效果時：\n本回合給予此牌挑戰者。","我方發動4次以上夜臨。","她傲然立於眾人之間，隨時準備戰鬥——她散發著耀眼的光芒，身穿銀色搭配藍色的盔甲，雙眸如星星般閃爍。當月亮升起，月光灑落在她身上，在場的月環教徒便閉上眼睛，為她的安全默默祈禱，也表達他們的感激之情。","單位",[],["巨石峰"],"英雄"],"03MT020":["光輝星角獸","出牌：治療1個友軍單位與我方主堡3點生命值。","","「看到那個橫跨夜空的星星嗎？那是一隻成體的星角獸。年幼的星角獸會把牠們的療癒法力借給我們使用，而成體的星角獸則能自己駕馭那股力量。能看到並認出成體的星角獸，是一件非常幸運的事。不過，能夠照顧牠更為幸運。」——守星者里達利","單位",[],["巨石峰"],"普通"],"03MT091":["酷炫星圖","祈望1張魔耗值為3以下的天界牌。","","「這三顆特別亮的星星，我叫它們……『天界跳跳繩』！還是這更像倒過來的笑臉呢？」——柔依","法術",[],["巨石峰"],"稀有"],"03MT047":["月隱者席格納斯","夜臨：本回合給予1個友軍單位隱密。","","席格納斯靜等日落，等待黑夜的掩護。雖然前面的路看起來寂寥無人，但這名月環教徒很清楚日輪教營地就在前頭。他擺出手勢，跟隨者便無聲無息地在他身後列隊。","單位",[],["巨石峰"],"史詩"],"03MT094":["月環潛影者","夜臨：賦予此牌隱密。","","「讓我們仰望天際，仰望太陽，仰望女神之……等等……什麼……？那是什麼……？」——日輪祭司","單位",[],["巨石峰"],"普通"],"03MT036":["巨石峰的祝福","賦予1個友軍單位+3|+3。","","「來自巨石峰的一點小心意。」——塔里克","法術",[],["巨石峰"],"稀有"],"03MT092":["紫角山羊","打擊：在手牌生成1張靈力寶石。","","巨石峰的山羊比普通山羊更加危險，因為牠們的角由寶石組成，撞擊時會在傷口裡留下碎片。 ","單位",[],["巨石峰"],"稀有"],"03MT060":["巨力捍衛者","回合開始：治療我方主堡3點生命值，並對此牌造成等值傷害。","","「沒人比我更熟悉巨石峰的山徑，所以有些，呃，任性的星角獸總是纏著我。幸好牠們有我來照顧！」 ","單位",[],["巨石峰"],"史詩"],"03MT001":["頑皮妖精","出牌：擊暈力量值為2以下的所有敵軍單位。","","冰塊落地時的清脆叮鈴聲，在山腰的一片寂靜之中傳來，而在旅人的上方遠處，他們發誓說聽到了……嘻笑的聲音？","單位",[],["巨石峰"],"普通"],"03MT055":["索拉卡","支援：治療此牌及受此牌支援的\n友軍單位4點生命值。","我方治療負傷友軍單位4次以上。","「療癒的本質是無私。你不需要從中汲取力量，力量是自願流出。只要展現憐憫，你就能看到治癒之光閃耀。」","單位",[],["巨石峰"],"英雄"],"03MT048":["送禮人","召喚此牌時，在手牌生成1張靈力寶石。","","「人們說守護者祝福了這些寶石。戴上它們，他的靈魂便會與你同在。」","單位",[],["巨石峰"],"普通"],"03MT082":["旭日晨光","本回合給予所有友軍單位+1|+1，\n並發動1個友軍單位的破曉效果。","","「我們隨著黎明而起！邁向光明！」——雷歐娜","法術",[],["巨石峰"],"稀有"],"03MT058":["塔里克","支援：本回合給予此牌及受此牌支援的友軍單位堅忍。複製本回合我方只對此牌打出的最後一個法術，並對該友軍單位打出（該法術無法再次複製）。","此牌在場上時，我方以友軍單位為法術/技能目標或支援友軍單位7次以上。","「塔里克的溫柔與善良照亮了所有遇見他的人，激勵他們找到內心深處的溫暖，就算夜晚再怎麼寒冷，他們也能繼續前進。」——群峰占術師","單位",[],["巨石峰"],"英雄"],"03MT062":["亮晶晶研究家","出牌：若我方掌控天界牌，則賦予1個友軍單位+1|+1與法盾。","","「……然後呢，星晶蝶就像掉到地上的星塵一樣，然後呢，又飛起來，超棒的，然後呢，我昨晚看到一隻，超漂亮的，然後呢，我肚子餓了，然後呢，它飛上天空，變成了星星，然後呢……」","單位",[],["巨石峰"],"稀有"],"03MT040":["星晶蝶","","","「希望之為物，翩翩高飛而脆弱，永遠不該被抓住。」——月環女祭司","單位",[],["巨石峰"],"普通"],"03MT086":["異想畫師","出牌：棄置1張牌以祈望1張\n魔耗值為3以下的天界牌。","","「這是我的最愛！我叫它『形而上的意識心理』，除非你這樣歪著頭看……這樣看起來就像兩支湯匙了。」","單位",[],["巨石峰"],"稀有"],"03MT016":["害怕的星界象","","","「哎喲，大大的星界象不想穿過小小的傳送門？沒關係，那我們……哈哈哈，騙你的，給我去吧！」\n——柔依","單位",[],["巨石峰"],"普通"],"03MT054":["雷歐娜","破曉：擊暈最強敵軍單位。","我方發動5次以上破曉。","她傲然立於眾人之間，隨時準備戰鬥——她散發著耀眼的光芒，身穿深紅搭配金色的盔甲，雙眸如火焰般炯炯有神。當太陽升起，她頭上絢爛的光芒彷彿日光的加冕，在場的日輪教徒不禁垂下眼簾，不是因為羞愧，而是因為這是對耀眼的領袖應有的尊重。","單位",[],["巨石峰"],"英雄"],"03MT220":["穿雲座","夜臨：擊暈1個敵軍單位。若該單位為侍從，則下次回合開始再次將其擊暈。","","「月亮母親，我們的夜晚已經降臨，\n讓我們阻止那些試圖傷害我們之輩，\n讓他們後悔莫及。」\n——月環教禱辭","單位",[],["巨石峰"],"稀有"],"03MT021":["無垠歧心龍","出牌：挑選2個敵軍單位。\n回合開始：擊暈他們。","","傳說與這隻生物視線交錯的旅行者，會被灌輸深奧知識、淵深洞見，以致於在其凝視之下精神崩潰。","單位",["龍族"],["巨石峰"],"史詩"],"03MT006":["音無龍獸","每回合擁有血怒的友軍單位\n首次擊殺敵軍單位時，在手牌\n生成1張隨機龍族侍從單位。","","「仰望天際，看見我目中的景色！首先你會看到信號，因為它們在夜晚格外耀眼；接著感受到憤怒，因為等到太陽升起，一切都將燃燒。你會見證的！每個人都將見證這一切！」——龍族先使","單位",["龍族"],["巨石峰"],"史詩"],"03MT015":["望穿無垠","祈望。","","璀璨繁星高掛天上，替遼闊夜空綴滿點點星光。與廣大無邊的天空比起來，你是那麼的渺小。你會首先望向哪處呢？","法術",[],["巨石峰"],"普通"],"03MT013":["刺眼月光","本回合沉默2個敵軍單位。\n夜臨：被此牌沉默的敵軍單位，本回合無法進行格擋。","","「不習慣月光的人必須學會讓它照亮眼前事物，否則他們什麼都看不清。」——黛安娜","法術",[],["巨石峰"],"普通"],"03MT009":["柔依","打擊主堡：在手牌生成1張酷炫星圖。若手牌中已有該牌，則改為使其魔耗值-1。","此牌在場上時，我方打出10張名稱不同的卡牌。","「嘿，哈囉哈囉！在幹嘛呀？你們在玩牌嗎？我可以加入嗎？什麼？！我是你的牌？哈！這個維度太搞笑了……」","單位",[],["巨石峰"],"英雄"],"03MT087":["翱銳龍獸","出牌：祈望1張魔耗值為7以上的天界牌。\n回合開始：在手牌隨機生成1張天界牌。","回合結束：我方場上友軍單位力量值總和為20以上。","「我才不在乎你們人類怎麼寫我的介紹呢！\n只要提到我英俊非凡，而且超～級聰明就好。\n這麼簡單應該不會寫錯字吧？」","單位",["龍族"],["巨石峰"],"英雄"],"03MT019":["星護壁壘","賦予1個友軍單位+1|+1與法盾。","","「應當敬畏群峰。」——塔里克","法術",[],["巨石峰"],"普通"],"03MT214":["飛鳥座","打擊主堡：抽1張牌，並將此牌洗入我方牌組最上方3張牌中。","","「月亮母親，請賜予我信心，\n讓我獲得飛翔的信念，\n指引我前進的方向。」\n——月環教禱辭","單位",["鳥族"],["巨石峰"],"稀有"],"03MT071":["漂泊旅者泰亞歷","支援：賦予受此牌支援的友軍單位+0|+2。","","旅行時，你必須對這趟旅程敞開心胸，因為它必將改變你。旅行時，你會帶走一些新事物……並留下一部分過去的自己。 ","單位",[],["巨石峰"],"普通"],"03MT008":["祈願","治癒所有負傷友軍單位。","","「以生之名！」——索拉卡","法術",[],["巨石峰"],"稀有"],"03MT023":["萬丈朝陽","對1個單位造成6點傷害。\n破曉：造成傷害前，本回合先沉默該單位。","","能夠承受烈日凝視的生物屈指可數。","法術",[],["巨石峰"],"稀有"],"03MT045":["星之護佑","治療1個友軍單位4點生命值，並賦予其+0|+4。","","「你以為打敗我們了嗎？哈！還早得很呢。」\n——巨力捍衛者","法術",[],["巨石峰"],"普通"],"03MT080":["護泉者","召喚此牌時，在手牌生成1張泉之禮讚。","","「大多數時候，我都在照料泉水，不過對牧羊人來說，還是羊群第一，有時只能從中取捨。」","單位",[],["巨石峰"],"普通"],"03MT042":["法術竊盜","顯化1張本牌局敵方打出的法術牌。","","「噢，那張牌打得好！但由我來一定更棒吧！那我就不客氣地收下囉！」——柔依","法術",[],["巨石峰"],"稀有"],"03MT057":["日輪陽鍛師","破曉：本回合給予此牌吸血。","","陽光灑入房間時，日輪鍛造師高舉神器，將陽光聚焦在他的武器上，將太陽的燦爛光芒化為強大附魔。","單位",[],["巨石峰"],"普通"],"03MT041":["群岩導師","支援：賦予受此牌支援的友軍單位+2|+2。\n遺願：在手牌生成3張靈力寶石。","","「剛才他說的，你聽得懂嗎？」\n「一個字都不懂，但應該是好話。」\n——居山者埃爾米和海利","單位",["約德爾人"],["巨石峰"],"史詩"],"03MT027":["太陽聖劍","賦予1個友軍單位+1|+2，且本回合給予其蠻力。\n破曉：抽出1張太陽聖劍。","","「讓耀日的力量在你身上充盈灌注！」——日輪祭司","法術",[],["巨石峰"],"普通"],"03MT096":["日輪女祭司","破曉：祈望1張魔耗值為4、5或6的天界牌。","","和其他巨石峰人一樣，日輪教徒也會尋求星星的指引，因為他們深深信仰的太陽也是一顆星星。","單位",[],["巨石峰"],"稀有"],"03MT028":["日輪持盾兵","破曉：本回合給予此牌+0|+4。","","「真愚蠢，竟然不選擇在夜晚偷襲。」日輪持盾兵挺直身體。「放下武器投降吧。」\n月環教徒一言不發，蹲下來，緊握彎刀擺好架勢。\n同樣地，日輪持盾兵舉起盾牌，反射日出太陽的光芒。\n一場激戰在所難免。 ","單位",[],["巨石峰"],"普通"],"03MT089":["新月守護者","夜臨：賦予此牌+2|+0。","","「堅毅的守護者啊，溫柔的滿月之光將恢復你的力量。甦醒吧，請保護我們，阻止闖入聖地的無禮之徒。」\n——新月守護者銘文","單位",[],["巨石峰"],"稀有"],"03MT051":["引導之觸","治療1個友軍單位或我方主堡2點生命值。抽1張牌。","","星角獸開心時會散發最亮的光芒。","法術",[],["巨石峰"],"普通"],"03MT003":["巨龍蛋","抽出2張不同的龍族牌或賦予\n龍族友軍單位+1|+1與蠻力。","","「牠們的叫聲聽起來就像刺耳的貓叫，聽到時一定要拔腿就跑，並通知最近的守衛，知道了嗎？因為龍蛋附近一定有龍族徘徊。」——巨石峰覓食者","法術",[],["巨石峰"],"稀有"],"03MT098":["日鋼護體","賦予1個友軍單位+0|+2。","","「我們的盾代表我們的信念、決心和對光明的信心！」——日輪持盾兵","法術",[],["巨石峰"],"普通"],"03MT215":["彼方餽贈","挑選1張月之武器，在手牌中生成。","","「亞菲利歐，伸出手……」——亞盧妮","法術",[],["巨石峰"],"普通"],"03MT063":["白月夢舞者","出牌：祈望。\n夜臨：使該牌魔耗值-1。","","「看看夜空中的朋友們！看到那顆特別亮的星星了嗎？那是靈犬座的眼睛，正盯著我們看呢！外邊那一簇黯淡的群星呢？那是躲在雲層後面的狡鼬座！還有那邊那……庫倫，噓！星星沒辦法抓下來啦……！」","單位",[],["巨石峰"],"普通"],"03MT100":["陰蝕巨龍","破曉：我方打出的下一個龍族或\n天界單位魔耗值-2。\n夜臨：在手牌生成1張隨機\n龍族和天界侍從單位。","","龍鱗（屬於陰蝕巨龍，其學名為Draco Obscuratus）\n筆記：龍鱗有極佳的反光性，\n陽光直射時會強烈反光。\n潦草筆記：它晚上還會發光！\n——蛋頭學者安登．梅恩的筆記","單位",["龍族"],["巨石峰"],"稀有"],"03MT076":["群峰占術師","我方的天界牌魔耗值-1。\n效忠：祈望。","","「在星星的指引下，我們可以學到很多。對我們來說，恆常不變的星星能幫助我們找到方向。」","單位",[],["巨石峰"],"稀有"],"03MT029":["星辰牧羊人","我方治療負傷友軍單位時，賦予此牌+2|+0。","","「自從我看到一隻星角獸劃破夜空之後，我就喜歡牠們。誰知道，現在我竟然會遇上這麼多！」","單位",[],["巨石峰"],"稀有"],"03MT219":["月蔽神殿","每回合我方首次打出2張其他卡牌時，恢復2點魔力，並賦予最強友軍單位+1|+0。","","正是在這精神領域之中，亞盧妮與其手足亞菲利歐交流著。她以溫柔的言語安慰這位沉默刺客，也會穿越界限把復仇的武器送到他手中。","地標",[],["巨石峰"],"稀有"],"03MT079":["調皮星孩","若我方掌控天界牌，則此牌魔耗值-2。","","「大人好遜！這裡唯一的酷小孩是柔依和她的夥伴。我從他們身上學到了很多，不像那個老是愛說教的蠢蛋女祭司。呃，真受不了她。」","單位",[],["巨石峰"],"普通"],"03MT007":["星角幼獸","","","「就如任何幼獸一樣，年幼的星角獸終有一日必須首次飛翔。在這個意義上，牠們跟夜空流星一樣，一瞬間就會墜落。幸好有我們在這裡接住牠們，然後等牠們準備好了，讓牠們回歸天空。」——守星者里達利","單位",[],["巨石峰"],"普通"],"03MT038":["白燄衛龍","","","「首先結識這些較年輕且愛好和平的龍族，是居住在巨石峰的孩童。也許是由於這些幼龍能夠感應到孩童的純真好奇之心，所以牠們選擇不傷害他們，反過來保護他們。」 ","單位",["龍族"],["巨石峰"],"普通"],"03MT014":["龍族先使","我方龍族魔耗值-1。","","牠們巨大的身軀周圍雲霧繚繞，牠們悲哀的叫聲，似乎連天也為之而震。她知道接下來將會發生什麼，但她感受到的不是恐懼，而是命運溫暖的懷抱。","單位",[],["巨石峰"],"稀有"],"03MT110":["別擋路","打出此牌後，友軍單位所獲得的「本回合」增益一直持續到牌局結束（光盾除外）。抽1張牌。","","「我這人說話句句認真\n識相就快快滾出大門\n現在我來大開殺戒\n塵埃落定我就征服世界」——凱莎〈THE BADDEST〉","法術",[],["巨石峰"],"史詩"],"03MT017":["靈犬座刻碑","在我方牌組生成5張靈犬座。","","「時光流逝，星移斗轉，靈犬座取代了巨蛇座的位置，豐收的季節即將到來……」——月環女祭司","法術",[],["巨石峰"],"稀有"],"03MT025":["石峰破片","以靈力寶石補滿我方手牌。","","「把寶石轉動到適當的角度，便能反射出奪目光輝；每個人的生命也一樣，內心都有一把燃燒著的火。」\n——塔里克","法術",[],["巨石峰"],"史詩"],"03MT216":["天影魚座","召喚此牌時，若我方掌控夜臨卡牌，則恢復2點法術魔力。","","「月亮母親，請讓我記住，\n即使我孓然一身，\n但我並不孤單，\n因為你的子民在天上翩翩起舞。」\n——月環教禱辭","單位",[],["巨石峰"],"普通"],"03MT012":["凜峰仲裁者","本牌局我方每次指定友軍單位為法術/技能目標，或支援友軍單位，此牌魔耗值便-1。","","仲裁者是登山的最終考驗，因為只有這個守護者的視線能穿透登山者外在的成就，直視他們內在的靈魂。","單位",[],["巨石峰"],"史詩"],"03MT085":["靜寂噓鳴","本回合沉默1個單位。","","「他們會明白何謂寧靜。」——索拉卡","法術",[],["巨石峰"],"稀有"],"03MT081":["群峰旅者","支援：賦予受此牌支援的友軍單位+2|+2。若該單位有支援特性，則同樣賦予受其支援的友軍單位+2|+2，以此類推。","","所有敢於挑戰巨石峰的人都有自己的原因。有些人是為了向同儕證明自己，有些人則全然是為了自己。","單位",[],["巨石峰"],"史詩"],"03MT030":["占星家","我方治療負傷友軍單位時，本回合給予其隱密。","","「星星只會待在我們身邊一段時間，等到受到充分的照顧，我就會讓星子帶著閃耀的光芒……還有揮動的蹄子回歸天際。」","單位",[],["巨石峰"],"稀有"],"03MT088":["日輪士兵","破曉：本回合給予此牌+1|+1。","","當升起的太陽溫暖了他的身子，他看守著異教徒的牢房，對囚犯的輕聲哀求充耳不聞，\n對方也很快就沉默了。","單位",[],["巨石峰"],"普通"],"03MT033":["魯姆爾爺爺","出牌：賦予2個友軍單位+0|+4。","","「奧蘇，你聽到嗎？有鈴聲！爺爺回來了！」——星辰牧羊人伊利","單位",[],["巨石峰"],"稀有"],"03MT035":["蒼白月瀑","本回合給予1個友軍單位+1|+1。\n夜臨：抽1張牌。","","「在夜色掩護下，被蒼白的月亮守護著。」\n——黛安娜","法術",[],["巨石峰"],"普通"],"03MT075":["月環女祭司","夜臨：祈望。","","「在廣闊的夜空中前行，有如朝聖者般的星星啊，請稍稍停下腳步，與我們分享你們的所見所聞。」——《夜之頌歌》","單位",[],["巨石峰"],"稀有"],"03MT218":["星星骨頭","若我方掌控天界牌，則在我方牌組生成靈犬座，並賦予各處天界友軍單位+1|+1。","","「讓靈犬盡情玩耍，\n以其喜悅，\n點亮繁星。」\n——月環教禱辭","法術",[],["巨石峰"],"史詩"],"03MT074":["沉睡夢域","擊暈1個敵軍單位。在手牌生成1張飛逝星迴百轉。","","「睡覺覺時間到囉！一隻星晶蝶、兩隻星晶蝶，三……嘿，那是什麼東西？！」——柔依","法術",[],["巨石峰"],"稀有"],"03MT072":["混源龍怪","","","無數挑戰等待著想登上巨石峰頂的人，有些像無止盡的攀升一樣，會慢慢削弱胸懷大志者的精力，有些則是更加急迫的威脅。","單位",["龍族"],["巨石峰"],"普通"],"03MT039":["普蝶","","","在太空中，再怎麼大聲尖叫都不會有人聽見。","單位",["普羅"],["巨石峰"],"普通"],"03PZ019":["拼裝普羅機器人","在手牌中時，此牌會擁有1項隨機特性（每回合會改變）。召喚此牌時，賦予此牌該特性。","","雖然不像真的那樣蓬軟好抱，但就像真的一樣可愛。","單位",["普羅"],["皮爾托福&佐恩"],"稀有"],"03PZ005":["彈道機器人","回合開始：在手牌生成1張爆燃。","","受試者請我們確保他的大腦完好無損，他說：「因為我所有的怨恨都積聚在那裡。」\n——替身機器人日誌，條目1011","單位",[],["皮爾托福&佐恩"],"普通"],"03PZ004":["死亡射線：1型","對1個單位造成1點傷害。在我方牌組最上方3張牌中生成1張死亡射線：2型。","","「今天，我成功證明了輻射能量可以集中成一束強大的射線！只要進行適當的調整，射線的精準度將無可匹敵，但要做的事還多著呢。」——維克特的設計稿註腳","法術",[],["皮爾托福&佐恩"],"稀有"],"03PZ003":["維克特","召喚此牌時及回合開始：在手牌生成1張海克斯核心升級。","我方打出7張以上生成的卡牌。","「佐恩，你見過的苦難已經夠多了，是時候迎來改變了，而所有偉大的進步都要從內部開始。」","單位",[],["皮爾托福&佐恩"],"英雄"],"03PZ010":["擬態機兵","攻擊：賦予此牌所有友軍單位身上的特性。","","「我跟你差不多，只是我更強。」","單位",[],["皮爾托福&佐恩"],"史詩"],"03PZ022":["全力以赴","將所有友軍單位的力量值和生命值，提升為友軍單位中力量值或生命值的最高數值。\n賦予所有友軍單位我方特性。","","\"I know I know\nYou want some more\nIf you ready let's go\nGiving it all\"\n「我懂我懂\n你想要更多\n準備好就一起走\n拼上全力不放手」\n——瑟菈紛〈MORE〉","法術",[],["皮爾托福&佐恩"],"史詩"],"03PZ014":["精密傑作","在手牌生成1張巨臂改裝迷、彈道機器人或生化喵，並賦予其+1|+1。","","「人之所以不會屈服於動物本能，是因為我們有理性去選擇。」——維克特","法術",[],["皮爾托福&佐恩"],"普通"],"03PZ013":["反覆改良","挑選1個侍從單位。在手牌生成1張該牌的複製牌，並賦予其+1|+1。","","「自我提升是一場遊戲，你是其中的英雄，同時也是壞蛋。你們會纏鬥不休，或許你還會以為自己贏了。但到頭來，擋在前方的還是你自己。」——擬態機兵","法術",[],["皮爾托福&佐恩"],"普通"],"03PZ025":["壓力測試","移除所有手牌的飛逝特性。此牌遭到棄置時，抽1張牌，並給予其飛逝。","","「其實這都很簡單。我發明了一種更堅固的合金替代了鋼鐵框架，然後把鉸鏈上的電路移到別處避免系統短路，太容易了。」——首席機械師澤維","法術",[],["皮爾托福&佐恩"],"稀有"],"03PZ012":["巨臂改裝迷","","","「好耶！新手臂！我老早就想要了。接下來要改造什麼？把腳換成重力輪？電動皮帶？鋼鐵牙？臉還是算了，我滿喜歡我的長相的。」","單位",[],["皮爾托福&佐恩"],"普通"],"03PZ020":["海克斯核心鑄造廠","回合開始：雙方各抽1張牌。","","「我才不在乎他們怎麼批評我的方法，他們不能否認進步這件事——我的知識之光就像一座燈塔，在無知的黑暗中閃耀！」——維克特","地標",[],["皮爾托福&佐恩"],"稀有"],"03PZ002":["生化喵","","","「我花了好幾年，在皮爾托福學術界苦苦掙扎，不斷往上爬，他們卻說我的技術『太危險』，還嫌我『太可愛』！佐恩我來了喵，我知道那裡至少會有個天才發明家能和我一起實現抱負……」","單位",["貓族"],["皮爾托福&佐恩"],"稀有"],"03PZ011":["射線餘波","對1個單位造成3點傷害或摧毀1個地標。","","「這道光將引領我們往皮爾托福邁進，沒有任何事物能阻礙我們的榮光進化！」——維克特","法術",[],["皮爾托福&佐恩"],"普通"],"03PZ017":["三雷射爆破炮","對1個單位造成1點傷害。隨機召喚1個魔耗值為1的侍從單位。此牌在手中時，我方每打出1張魔耗值為3的卡牌，則造成的傷害值與召喚單位魔耗值皆+1。","","「……一、二、三！！！噢。噢，我的天啊……又是無法預料的結果？！」——漢默丁格","法術",[],["皮爾托福&佐恩"],"史詩"],"03PZ018":["普羅大砲","棄置1張牌即可出此牌。\n在手牌生成2張大膽普羅。","","兩個毛茸茸的身影從熱情的群眾頭上劃過天際，在身後留下一團絨毛和淡淡的烘焙香。","法術",[],["皮爾托福&佐恩"],"普通"],"03SI004":["如影隨形","從我方牌組最上方4張牌中挑選1個侍從單位。\n抽出該牌、在手牌生成1張相同的閃靈複製單位，並將其餘卡牌洗回我方牌組。","","「去……包圍他們……」——夜曲","法術",[],["闇影島"],"稀有"],"03SI001":["重影潛蝠","夜臨：在手牌生成1張此牌的複製牌。","","「一開始只有一雙眼睛，還有一個聲音在黑暗中窸窣出聲。但我每次回頭，就會看到更多眼睛。聲音越來越大，越來越憤怒，我一看到鯨牙酒吧，就馬上往那裡狂奔。」——鯨牙酒吧掠奪者","單位",[],["闇影島"],"史詩"],"03SI018":["大胃王","擊殺1個擁有遺願的友軍單位，以從我方牌組召喚1個魔耗值+1的侍從單位。","","「開飯啦！」——無饜屠夫","法術",[],["闇影島"],"稀有"],"03SI012":["暗路難行","泯滅本回合所有被召喚但並非打出的單位。","","「當然，死亡也存在於蒂瑪西亞。我們看著它帶走所愛之人，也知道總有一天會輪到我們。但在這些島嶼上……我幾乎能嘗到死亡的味道。死亡的氣息充滿我的肺臟，我甚至能聽到它的耳語。這不是什麼抽象的概念，它此時此刻就坐在我身旁，沒有任何人逃得出它的魔掌。」\n——歷史學家延斯．托曼的筆記","法術",[],["闇影島"],"稀有"],"03SI014":["幽侵狂影","賦予我方牌組與手牌中的所有友軍單位+2|+2與閃靈。","","「我擔心闇影島的夢魘遲早會讓所有人的身心靈崩潰，只剩下無止盡的瘋狂。」\n——歷史學家延斯．托曼的筆記","法術",[],["闇影島"],"史詩"],"03SI016":["使盡全力","從1個單位汲取1點生命值，並在我方牌組生成2張使盡全力。每打出此牌3次，便會將各處相同卡牌幻化為做好準備。","","「使盡全力直至夢想到手\n使盡全力直到渾然忘我\n我們是Pop Stars 眼中只有勝利\n無人能敵」\n——伊芙琳〈POP/STARS〉","法術",[],["闇影島"],"史詩"],"03SI007":["夜幕庇護","我方下次於本回合召喚友軍單位時，本回合給予其+1|+0與法盾。","","「你一踏出去，就會感覺到他們，好像指尖拂過頸背，輕如雨水。就算作勢攻擊他們，那些怪物也不會退縮。他們既不怕刀，也不怕火，天不怕地不怕，實在是太恐怖了。」——鯨牙酒吧掠奪者","法術",[],["闇影島"],"普通"],"03SI005":["夜曲","夜臨：賦予1個敵軍單位弱勢，且本回合給予所有敵軍單位-1|-0。","我方以5個以上夜臨或威嚇友軍單位攻擊。","「看來，一旦驚動太多靈魂，牠就會入侵我們的世界。只有希望才能把怪物送回原本的世界……但希望早已隨著皇后的最後一口氣，以及國王無盡的痛苦哀號，永遠消逝了。」——歷史學家延斯．托曼的筆記","單位",[],["闇影島"],"英雄"],"03SI006":["末日豹","夜臨：從敵方主堡汲取2點生命值。","","每晚，旅人只感到更加疲憊。他們在睡夢中不得安寧，惡夢與現實的分界變得模糊。睡眠不再是一種休息，反而像是在一點一點吸取他們的生命。","單位",[],["闇影島"],"普通"],"03SI015":["煩人幽靈","遺願：在敵方牌組生成2張此牌的複製牌。","","闇影島大部分的鬼魂都是極為恐怖和病態的怪物。有一小部分則是……這個嘛……非常非常煩人。","單位",[],["闇影島"],"普通"],"03SI003":["冥鬼梟","夜臨：本回合給予此牌+2|+0與威嚇。","","當太陽沒入地平線，此地的駭人之物便會甦醒，開始虎視眈眈，等待獵物上鉤。","單位",["鳥族"],["闇影島"],"普通"],"03SI002":["深宵斷魂","從任1目標汲取1點生命值。\n夜臨：在手牌隨機生成1張夜臨牌。","","「隨著時間過去，我的精神，以及當初驅使我找到這裡的幹勁都逐漸被消磨殆盡。鯨牙酒吧的人個個形容枯槁，似乎已放棄做任何努力，我怕我在這裡待越久，就會變得越來越像他們。」\n——歷史學家延斯．托曼的筆記","法術",[],["闇影島"],"普通"],"03SI010":["夢魘馬","夜臨：本牌局我方每發動1次夜臨，便賦予此牌+1|+0。","","每當夕陽西下，夜晚就會張開漆黑的翅膀，抹去白天最後一絲希望。","單位",[],["闇影島"],"稀有"],"03SI013":["鬼魅夜襲","召喚1個霧魅。","","霧魅在凡人看不見的空間中移動，毫無預警地出現，並折磨眼前所見的一切。","法術",[],["闇影島"],"普通"],"03IO025":["快拳流","賦予1個友軍單位+1|+0與快速攻擊。若其已有快速攻擊，則改為賦予雙重攻擊。","","「打得快、打得狠、打得準。」——龍角力士","法術",[],["愛歐尼亞"],"稀有"],"03IO017":["皮克斯！","支援：本回合給予受此牌支援的友軍單位+2|+1。","","「皮克斯超棒的！他是個小不點，又酷，人又好。\n他最喜歡負鼠，嗯，還有還有……」——露璐","單位",["妖精"],["愛歐尼亞"],"普通"],"03IO008":["幻想曲！","本回合將1個侍從單位幻化為1|1小松鼠並沉默該單位。","","「變可愛！」——露璐","法術",[],["愛歐尼亞"],"普通"],"03IO001":["尋花松鼠","此牌受到支援時，賦予其+2|+0。","","每個人都想要有一隻使魔，但沒有人願意負責。必須帶牠們去散步，確保牠們飲食均衡，還要訓練牠們，照顧牠們一點都不簡單。","單位",["妖精"],["愛歐尼亞"],"普通"],"03IO019":["孤注一擲","挑選1個友軍單位，召回所有其他單位與地標。","","「我獨行我路。」——獨身修女","法術",[],["愛歐尼亞"],"史詩"],"03IO002":["露璐","支援：本回合受此牌支援的友軍單位成長到4|4。","友軍單位受到支援3次以上。","「皮克斯，別擔心！我們會脫離林地的，而且我們會把所有東西都『變可愛』！準備好了嗎？！」","單位",["約德爾人"],["班德爾城","愛歐尼亞"],"英雄"],"03IO011":["健壯松鼠","打擊：使此牌力量值加倍。","","他之所以這麼壯，是因為他每天喝四杯橡果奶昔。","單位",["妖精"],["愛歐尼亞"],"稀有"],"03IO009":["美味茄妖","","","能量：104千焦耳（25大卡）；碳水化合物：5.88克；糖分：3.53克；膳食纖維：3克；脂肪：0.18克；蛋白質：0.98克；水：92克……","單位",["妖精"],["愛歐尼亞"],"普通"],"03IO003":["妖燈嚮導","出牌：賦予1個友軍單位隱密。","","「噓，這邊！過了那個會走路的樹屋之後，我們得向左急轉彎，然後直走經過那些會說話的花朵。露璐，你有在聽嗎？露璐？露璐！露~璐！不。要。餵。它。們。」","單位",["約德爾人"],["愛歐尼亞"],"稀有"],"03IO007":["瞌睡仙崔弗","支援：生成1個攻擊中的夢中小鬼，其能力值與受此牌支援的友軍單位相同。","","你應該在自己的床上作夢就好，不用一邊「夢飄」\n在魔法古森林裡，一邊漫不經心地喃喃唸著咒語，\n把夢境變成真的！","單位",["約德爾人"],["愛歐尼亞"],"史詩"],"03IO010":["少女巫","支援：本回合給予受此牌支援的友軍單位快速攻擊與+1|+0。","","列貝利．蒙塔古爵士離鄉背井，心想完成偉大任務，或討好豪門世家。只不過造物弄人，命運帶領他走進班德爾之森，結果被年輕的布莉變成青蛙，並被迫陪伴她冒險，真可憐！","單位",[],["愛歐尼亞"],"普通"],"03IO020":["抗拒！","抵銷1個魔耗值為3以下的快速或慢速法術。","","「別這樣，你這個毛茸茸的傻瓜！你可能會傷到那些羚羊！」——露璐","法術",[],["愛歐尼亞"],"稀有"],"03IO022":["努力爭取","召回1個友軍單位，本回合其魔耗值降為0，並在原處召喚1個與之相同的閃靈複製單位。","","\"More\nKnow I got it，\nSo here you go，\nYou look like you could use some more.\"\n「我瞭\n你要更多\n拿去吧\n你看起來很缺。」\n——阿卡莉〈MORE〉","法術",[],["愛歐尼亞"],"史詩"],"03IO018":["毛茸茸園丁","此牌受到支援時，本回合給予其+0|+3。\n支援：本回合給予受此牌支援的友軍單位+3|+0。","","紫色精靈是一群可愛的小生物，牠們會被遇上的所有人照顧……除了一些例外。","單位",["約德爾人"],["愛歐尼亞"],"稀有"],"03DE008":["龍衛中尉","召喚此牌時，若我方掌控龍族牌，則賦予此牌挑戰者。","","「我以為我的決心已在威沃之戰中隨著同袍一同逝去了……但後來發現，只要再次經歷戰鬥便可以重新喚醒老兵的意志。」","單位",[],["蒂瑪西亞"],"普通"],"03DE001":["迎敵之息","賦予1個友軍單位挑戰者。\n若為龍族，則抽1張牌。","","「沒人能逃出我們手掌心！」——希瓦娜","法術",[],["蒂瑪西亞"],"普通"],"03DE015":["抗魔英石雕","所有法術的魔耗值+1。","","一開始說不上是什麼樣子，只是粗略鑿下的一塊反魔法英石，在雕刻家的巧手之下迅速成形，作品開始變得栩栩如生。","單位",[],["蒂瑪西亞"],"稀有"],"03DE006":["銳嘯飛龍","","","保護幼子是所有生物的天性，不過論應付威脅的能力，\n能比得上龍族的不多。","單位",["龍族"],["蒂瑪西亞"],"普通"],"03DE025":["熔解吐息","使1個擁有血怒的友軍單位\n輪流打擊2個最弱敵軍單位。","","好幾個世紀以來，蒂瑪西亞人對於龍族怒火的了解，僅限於傳說故事；但威沃一戰，他們終得親歷。","法術",["元素"],["蒂瑪西亞"],"稀有"],"03DE002":["掠翼轟擊","使1個友軍單位與1個敵軍單位互相打擊。若友軍單位為龍族，打擊後可恢復5點生命值。","","當騎士和龍族從廝殺中分開後，殘喘負傷的龍似乎又重獲力量。牠聞到了鮮血的味道，並渴望更多。","法術",[],["蒂瑪西亞"],"稀有"],"03DE011":["希瓦娜","攻擊：本回合給予此牌+1|+1。","龍族友軍單位造成16點以上傷害。","「一方面，她的本質與我們最痛恨的敵人相同，她的族類過去為蒂瑪西亞帶來的只有災禍。但另一方面，她又深受王子信賴，也看似足以成為意志堅定的戰士，和我們可貴的友軍。我只希望她不會背叛我們對她的信任。」\n——傑里克中尉的威沃見聞","單位",["龍族"],["蒂瑪西亞"],"英雄"],"03DE003":["龍衛瞭望兵","召喚此牌時，若我方掌控龍族牌，則進行備戰。","","「遠方有東西！會不會是……？」\n「似乎是。」\n「你怎麼知道？」\n「相信我，我絕不會看錯。快摀住耳朵，這東西超大聲的。」——安登和耶夏妮亞","單位",[],["蒂瑪西亞"],"稀有"],"03DE013":["潛行龍母","","","「小心點士兵！如果我們能注意步伐，不驚動巢穴，就能避免讓母龍作出激進的行為。但如果再激怒牠……那麼，你只能祈禱你跑得夠快。」\n——蛋頭學者安登．梅恩","單位",["龍族"],["蒂瑪西亞"],"普通"],"03DE005":["蛋頭學者","召喚此牌時，在手牌生成1張隨機龍族單位。","","龍蛋（屬於銳嘯飛龍，其學名為Draco Murmurationis）\n地點：學者安登．梅恩遠征時發現。\n筆記：孵化期不明，繼續保溫。最近觀察到殼內有活動。蛋對熱、光和敲擊有反應。\n研究目前仍沒有結論。\n——蛋頭學者安登．梅恩的筆記","單位",[],["蒂瑪西亞"],"普通"],"03DE007":["煉燄飛龍卡卓格林","召喚此牌時，賦予各處其他龍族友軍單位+4|+4。","","當蒂瑪西亞突然遭受巨龍猛攻時，希瓦娜便知道這都是煉燄飛龍卡卓格林幹的好事。其他巨龍被他放肆的天性和猛烈的火焰所煽動，使蒂瑪西亞陷入恐懼之中。 ","單位",["龍族"],["蒂瑪西亞"],"史詩"],"03DE012":["哀兵必勝","召喚菁英單位時，此牌魔耗值-1。\n本回合每有1個友軍單位陣亡，便召喚1位無畏先鋒。","","「一個士兵倒下，另一個就得頂上。不能讓我們的旌旗倒下。」——蓋倫","法術",[],["蒂瑪西亞"],"史詩"],"03DE014":["銳目","本回合給予1個友軍單位+1|+2與銳目。","","膽敢突破蒂瑪西亞城牆的人會發現，後頭有一整支重裝軍隊，正在虎視眈眈地等著他。","法術",[],["蒂瑪西亞"],"普通"],"03FR020":["戰痕之地","友軍單位承受傷害且未陣亡時，賦予其+1|+0與堅忍。","","冬之爪有很多榮譽之地，但其中最偉大的地方就是戰痕之地。在突擊中受損的船艦被改建為戰士及其親屬聚會的廳堂。這些戰艦正體現了建造者的韌性與適應力。","地標",[],["弗雷爾卓德"],"史詩"],"03FR007":["拾荒巨魔","召喚此牌時，若我方掌控魔耗值為8以上的卡牌，則賦予此牌+3|+0。","","斥候蹲在一塊埋藏在雪下的爛布前，寒冷的空氣混雜著人汗和火煙的臭味。\n他把爛布拉出來，並看到有一個護符吊在其中一角。護符在烏雲密布的天空下顯得黯然無光，但他還是認出這個護符的產地：艾伐洛森。 ","單位",[],["弗雷爾卓德"],"普通"],"03FR004":["復甦咆嘯","挑選手牌中的1個單位進行揭示，並為我方主堡回復等同其力量值的生命值。\n開悟：使該牌魔耗值降為0。","","「成年巨魔皮厚骨硬，且傷口會迅速痊癒，是一群頑強的敵人。要俐落了斷他們的性命，否則他們不久就會痊癒歸來。」——艾伐洛森神射手","法術",[],["弗雷爾卓德"],"稀有"],"03FR017":["古魔占卜師","出牌：若我方掌控魔耗值為8以上的卡牌，則賦予1個友軍單位蠻力與再生。","","據說懂得古神之歌的巨魔不多，但學會便能呼喚祖先之名，賦予同胞驚人力量。","單位",[],["弗雷爾卓德"],"稀有"],"03FR006":["特朗德","召喚此牌時，在手牌生成1張通天冰柱。","此牌在場上時，我方打出通天冰柱。","火把接二連三點起，點亮了整條小徑。那裡站著幾十甚至上百隻巨魔，每隻都身軀龐大，殺氣騰騰。\n「我再問一次，」特朗德大聲咆哮，並把凍骨者托在肩上。「你們要投降，還是要我敲破你們的腦袋？」","單位",[],["弗雷爾卓德"],"英雄"],"03FR008":["地裂冰川","本回合給予所有單位-3|-0，並對所有單位造成3點傷害。","","「把他們統統活埋！」——特朗德","法術",["元素"],["弗雷爾卓德"],"史詩"],"03FR002":["巨魔戰歌","本回合給予1個友軍單位+0|+2，並給予1個敵軍單位-2|-0。","","巨魔戰歌的種類繁多，不同部落各有特色，且往往難以理解，不過它們都有一個相同之處，就是必定會令聽者膽顫心寒。 ","法術",[],["弗雷爾卓德"],"普通"],"03FR011":["遠古巨魔烏孜珈","","","聽到聲音前，他們便先感覺到了——大地在他們腳下震動，如雷巨響也隨即而來。\n梅里克抬起頭來，豎起耳朵，仔細聆聽。\n「是什麼東西？」安雅一邊連忙悄悄問道，一邊拉弓，但梅里克已經在跑回小徑了。\n「快跑！」","單位",[],["弗雷爾卓德"],"稀有"],"03FR005":["破壞狂巨魔","召喚此牌時，若我方掌控魔耗值為8以上的卡牌，則賦予此牌再生。","","當他們到了艾伐洛森木屋群的時候，便呼喚海格上前。她大聲一笑，舉起了她的武器「雪裂者」，預備把木屋敲成木碎。","單位",[],["弗雷爾卓德"],"普通"],"03FR018":["野性呼喚","從我方牌組最上方4張牌中，抽出所有雪怪、普羅與厄努克，並將其餘卡牌洗回我方牌組。","","「然後一隻超～巨大的厄努克從樹後衝出來，上面騎著一隻超～迷你的普羅，然後還有一隻友善的雪怪也想跟朋友一起玩，所以他們就大喊『哇啊啊啊啊』一起跑下山，然後……」——少女英格娃","法術",[],["弗雷爾卓德"],"普通"],"03FR010":["古魔頭首","回合開始：若我方掌控魔耗值為8以上的卡牌，本回合額外獲得1顆魔力寶石。","","「起來吧，眾大古魔，起來吧！\n冰雪支配者，劃破天空吧！\n起來吧，眾大古魔，起來吧！\n賜我們力量，則他們死亡！」\n——巨魔戰歌","單位",[],["弗雷爾卓德"],"普通"],"03FR019":["古魔之聲","獲得2格魔力寶石槽位。\n從我方牌組最上方的5張牌中，\n抽出所有魔耗值為8以上的牌，\n並將其餘卡牌洗回我方牌組。","","世代以來，艾伐洛森開拓者總會在冬季的暴風聲中聽到難以解釋的奇怪聲音。後來，當他們向北方更遠處探索時，終於發現聲音的來源——遠古的巨魔石雕。當風吹過其張開的嘴巴時，就會用早已失傳的語言呢喃出聲。","法術",[],["弗雷爾卓德"],"普通"],"03FR025":["巨魔餽贈","賦予1個友軍單位再生，若其已有再生，則改為賦予+2|+2。","","眼見傷了巨魔就自認勝利在望的人吶，著實可悲。","法術",[],["弗雷爾卓德"],"稀有"],"03FR022":["猛烈攻勢","從我方手牌和牌組中隨機召喚2個不同的英雄單位，並使其能力值升至10|10。","","「我們掌握了一切\n看你能不能應付我們的威？」\n——阿璃〈POP/STARS〉","法術",[],["弗雷爾卓德"],"史詩"],"04PZ001":["艾克","打擊：在手牌生成1張飛逝時間戲法。","我方預言4次以上。此牌升級時，在我方牌組生成3張計時開始。","時間多寡不是重點，重點是你如何去運用。","單位",[],["皮爾托福&佐恩"],"英雄"],"04PZ005":["奇里安汙水坑工人","召喚其他奇里安汙水坑工人時，泯滅此牌並將我方各處奇里安汙水坑工人幻化成汙水坑暴徒。","","首位發現奇里安的佐恩礦工以為牠們是溫馴單純的生物。但隨著時間過去，適應與人類共存後，牠們逐漸展現出緊密的社會性，而且似乎與生俱來就能瞭解科技。","單位",[],["皮爾托福&佐恩"],"普通"],"04PZ014":["產能爆發","此牌魔耗值等於我方所剩魔力。隨機召喚數量不定的砲臺，其總魔耗值等於所消耗魔力。","","「資源不夠？！你在跟我開玩笑吧？我的第一個機器發明，是用廢棄時鐘零件和生鏽保暖爐拼裝製成的。沒有辦法就想辦法，物盡其用！」——漢默丁格","法術",[],["皮爾托福&佐恩"],"稀有"],"04PZ003":["時光樞紐","棄置1張牌即可出此牌。\n從敵軍單位與敵方主堡中挑選2個目標，各造成1點傷害。","","「當心了！」——艾克","法術",[],["皮爾托福&佐恩"],"普通"],"04PZ011":["打擊宣言","抽1張牌。\n在我方牌組生成1張時空攔截。","","「分割時間線……」——艾克","法術",[],["皮爾托福&佐恩"],"史詩"],"04PZ002":["落地喵喵","召喚此牌時，在我方牌組底部的10張牌中生成1張海克斯水晶。","","「我的計畫喵啊啊啊啊啊啊啊！」","單位",["貓族"],["皮爾托福&佐恩"],"稀有"],"04PZ020":["瑕疵拉霸機器人","出牌：此牌與另1個單位調換能力值。","","「新的拉霸機器人？製造這些玩意的工廠不是幾年前就關了嗎？」\n「應該是啊，好像說什麼『到處滾的炸彈』和『不慎引發火災』之類的。」\n「這樣啊。」\n「……要玩嗎？」\n「那還用說嗎？」\n——佐恩老主顧","單位",[],["皮爾托福&佐恩"],"稀有"],"04PZ013":["小白牛厄努克","召喚此牌時，在我方牌組最上方6張牌中隨機生成1張厄努克。","","「好了，小傢伙，坐在那裡別動，等我按下這個按鈕然後蹦！哈！厄努克萬歲！我們需要更多草，還有空間。」——務實完美主義者","單位",["厄努克"],["皮爾托福&佐恩"],"稀有"],"04PZ010":["平行時空","賦予手牌中的侍從單位「打出此牌時，從魔耗值相同的侍從單位中3選1，並幻化為該單位」。","","「這邊只有我說了算。」——艾克","法術",[],["皮爾托福&佐恩"],"史詩"],"04PZ016":["轟炸狒狒","召喚此牌時，在手牌生成1張咬咬手榴彈！","","吉茵珂絲原本有個很保守的供應商，但他後來就被轟出去了。我們的意思是，他是真的被吉茵珂絲從窗戶直接用大炮轟出去。","單位",[],["皮爾托福&佐恩"],"普通"],"04PZ007":["時間戲法","預言，然後抽1張牌。","","「未來我說了算……」——艾克","法術",[],["皮爾托福&佐恩"],"普通"],"04PZ012":["務實完美主義者","出牌：預言。在我方牌組生成3張所選卡牌的複製牌。","","「凱超讚的，她有那種『實驗造就完美』的努力心態，而且她真的實驗得超～級勤奮。」——秀米","單位",[],["皮爾托福&佐恩"],"稀有"],"04PZ017":["榮光進化","使我方各處卡牌魔耗值-1，擁有擴增，視為由榮光進化生成，且為機械單位。","","「進步就是一切。無論它準備好了沒有，我都會讓這座城市迎向未來。」——維克特","法術",[],["皮爾托福&佐恩"],"史詩"],"04PZ015":["適應創號3000","召喚機械單位時，與此牌共享特性。","","「有了！就叫適應創號3000！靈活多變、愛發明又超有型！如果這傢伙能說話，我們一定很聊得來。」\n——漢默丁格","單位",["機械"],["皮爾托福&佐恩"],"史詩"],"04PZ004":["滑板女孩","此牌在預言出現時，召喚此牌。","","「秀米是個懸浮飛板天才！有一次我看到她先輾磨滑行，接著卡板身，最後飛上空中，施展全場一致滿分的1080度前空翻……應該是這樣沒錯。總而言之，她超厲害的，你懂嗎？」——務實完美主義者","單位",[],["皮爾托福&佐恩"],"普通"],"04BW002":["刺骨串叉","使1個友軍單位打擊1個敵軍單位，然後移至牌組最上方。","","「這是小小的餞別禮……」——派克","法術",[],["比爾吉沃特"],"史詩"],"04BW007":["青囊魚","出牌：使我方每個潛伏者單位打擊1個隨機敵軍單位。","","「青囊魚最可靠了，可以告訴我誰能信，誰該死。」——派克","單位",["潛伏者"],["比爾吉沃特"],"史詩"],"04BW001":["紅鰭槌鼻怪","出牌：賦予1個敵軍單位弱勢。","","槌鼻怪把船擊沉似乎純粹只是因為好玩；牠們很少吞食落難的船員，而是留給別的怪物飽餐一頓。","單位",["潛伏者"],["比爾吉沃特"],"普通"],"04BW005":["派克","此牌潛伏時，將其幻化為汪洋死域。","我方派克總共造成15點以上傷害。","「……我又看見幻覺了。青囊魚的嘴緊緊攫住他的身體時，我看見他用充滿絕望的雙眼向上盯著我。我們想把他拉出來，但船太小，而那條魚太大了。我萬不得已只好把他的繩子割斷，我沒有選擇。」——染血的信","單位",["潛伏者"],["比爾吉沃特"],"英雄"],"04BW010":["巨怪魚叉","洗劫：此牌魔耗值-2。\n對1個單位造成5點傷害。","","「小子們，海獸已經受傷了！快刺到牠動彈不得，血染大海為止！」——殘鉤團監工","法術",[],["比爾吉沃特"],"普通"],"04BW014":["排排站","召喚1個火藥桶。\n在手牌生成1張排排炸。","","「按您吩咐的弄好了，船長。來點火花就可以開轟了。」——恐懼號水手","法術",[],["比爾吉沃特"],"普通"],"04BW011":["灌鉛骰子","下回合每當我方對敵方主堡造成傷害時，奪取1張牌。","","「我的朋友，你願意用什麼做擔保？」——貪啃奇","法術",[],["比爾吉沃特"],"史詩"],"04BW015":["幼鯊","","","「別看牠們小小隻的，可是個個嗜血如命呢。如果現在被咬到，等牠們長大就知道獵物在哪裡了。手套記得戴好。」——青囊魚獵人","單位",["潛伏者"],["比爾吉沃特"],"普通"],"04BW003":["鉗嘴魚群","出牌：此牌發動額外攻擊。","","「滴答滴答、滴答滴答、鮮血汩汩，\n成群結隊、蜂擁而來、小心落水，\n血盆大口、尖牙利齒、放聲尖叫，\n沉入深淵、陷入永眠、美夢永遠！」\n——比爾吉沃特童謠","單位",["潛伏者"],["比爾吉沃特"],"普通"],"04BW009":["開膛手海灣","我方攻擊時，在發動潛伏前，先賦予牌組最上方的友軍單位潛伏，且該牌視為潛伏者。","","比爾吉沃特最危險的海灣很快就成了各種海怪的老窩。牠們潛伏在水中，等著下一批不聽港務長警告的魯莽水手。","地標",[],["比爾吉沃特"],"稀有"],"04BW008":["失落寶藏","抽1張寶藏牌。若無寶藏牌可抽，則改為在我方牌組生成2張寶藏牌。","","「我們發財啦！」——殘鉤團屠夫","法術",[],["比爾吉沃特"],"稀有"],"04BW013":["掠奪者船頭","此牌倒數時，隨機召喚1個\n魔耗值為1的侍從單位。\n倒數2：賦予所有魔耗值為1的\n友軍單位+2|+1與威嚇。","","「臭小子，你認為自己有資格成為殘鉤團的一員嗎？好，我倒要看看你有什麼能耐。不夠格的話，就送你去餵魚！」——肖狗水手","地標",[],["比爾吉沃特"],"稀有"],"04BW004":["血餌","在我方牌組頂端生成1張鉗嘴魚群。","","「如果俺有得選，俺寧願給青囊魚吞了也不願意下那鬼東西的肚子。死得快總比被活活生吞，還要一邊叫破喉嚨請兄弟們了結我來的好。」——殘鉤團屠夫","法術",[],["比爾吉沃特"],"普通"],"04BW016":["殞落狂鯊砲","出牌：本回合我方每抽1張牌，則對敵軍單位隨機打出1次加農炮幕，最多6次。","","「狂鯊……是你嗎？」——肖狗水手","單位",[],["比爾吉沃特"],"稀有"],"04BW006":["殺戮名單","賦予1個敵軍單位弱勢。若其已有弱勢，則使最強友軍單位發動額外攻擊並挑戰該單位。","","「你名頭響亮很好，最好就出現在我的名單上。」\n——派克","法術",[],["比爾吉沃特"],"稀有"],"04IO008":["不屈祕舞","召回1個單位。\n劍舞1。","","「撤退！主角該換人了！」——鋼鐵終曲辛妮亞","法術",[],["愛歐尼亞"],"普通"],"04IO005":["伊瑞莉雅","召喚此牌時及回合開始：若我方擁有攻擊主動權，則在手牌生成1張無瑕重刃。","我方以14個以上友軍單位攻擊。","「我們曾經鑽研藝術與美，心神翱翔天際。但當他們摧毀了城牆，讓我們血染大地，我們便墜回了谷底……」","單位",[],["愛歐尼亞"],"英雄"],"04IO020":["散落鯨群","出牌：抽1張慢速、快速或疾速法術。\n開悟：此牌擁有隱密。","","飲雲飛鯨所唱的蒼穹之歌詭異卻幽美，並減緩了部分黯霧入侵的速度……但看來也擋不了多久。","單位",[],["愛歐尼亞"],"稀有"],"04IO004":["劍刃之花","出牌：劍舞2。","","「有人認為花朵嬌柔脆弱，但他們忘了扎根於大地，用花開帶來希望需要多大的力量。」\n——鋼鐵終曲辛妮亞","單位",[],["愛歐尼亞"],"普通"],"04IO003":["護劍化形","挑選1個友軍單位與劍刃一起攻擊，然後劍舞3。","","「別讓他們撤退！諾克薩斯人挑起了這場戰爭，就由我們來結束它。」——伊瑞莉雅","法術",[],["愛歐尼亞"],"稀有"],"04IO015":["舞動水滴","此牌被召回時，抽1張牌。","","「流水無形——它會應情勢所需而有所變化，無論是撲向岸邊還是流回大海。」——愛歐尼亞僧侶","單位",[],["愛歐尼亞"],"普通"],"04IO014":["闇影學徒","召喚閃靈友軍單位時，本回合給予此牌+1|+0。","","「如微風一般的輕聲細語，你如煙霧繚繞的輕拂；你的拳頭必須融入黑暗，如同陰影化為黑不透光的漆影一樣。好，再來一次！」——示師傅","單位",[],["愛歐尼亞"],"普通"],"04IO002":["鋼鐵終曲辛妮亞","我方進行劍舞時，此牌與劍刃一起攻擊。\n出牌：劍舞1。","","「孩子們靠過來。今天我們將會跳著家族流傳下來的舞步，在這片孕育我們的大地上舞動。我們是愛歐尼亞之子，今日我們為了藝術、為了自由、為了彼此而舞！」","單位",[],["愛歐尼亞"],"史詩"],"04IO007":["切分換位","調換2個友軍單位位置。","","「舞蹈就是隨著萬物運行和諧起舞。」\n——鋼鐵終曲辛妮亞","法術",[],["愛歐尼亞"],"稀有"],"04IO011":["一搭一唱","召回1個友軍單位以在手牌生成1張無瑕重刃。","","「我們的演出將會讓你……永生難忘。」\n——鋼鐵終曲辛妮亞","法術",[],["愛歐尼亞"],"普通"],"04IO013":["守衡聖樹","出牌：本回合給予1個友軍單位光盾，並抽出1張慎。\n擁有光盾的友軍單位獲得雙重攻擊。","","「當我們為了保護土地而奮戰時，土地也會起身守護我們。我們從大地之怒獲得力量，驅逐我們的敵人，讓平衡得以維持。」——愛歐尼亞祭司","單位",[],["愛歐尼亞"],"史詩"],"04IO012":["替身殘影","召回所有友軍單位，並在原處召喚相同數量的疾風殘影。","","「讓他們打影子，他們的武器什麼都碰不到。」——劫","法術",[],["愛歐尼亞"],"稀有"],"04IO009":["緞帶舞者","出牌：劍舞1。","","「真可惜，小子們！空有蠻力卻毫無節奏感？看來並非每個人都是當明星的料……！」","單位",[],["愛歐尼亞"],"稀有"],"04IO001":["戰地樂手","每回合召喚3個其他友軍單位後，恢復我方所有法術魔力並抽1張牌。","","音樂對某些人來說，是暫離苦難和暴戾的避風港；對另一些人來說，是讓自己更具韌性的力量來源。","單位",[],["愛歐尼亞"],"史詩"],"04IO006":["沿岸守軍","我方召喚其他單位時，本回合給予此牌+2|+0。","","親愛的凱，\n他們的艦隊在今早劃破地平線，遮住了日出。他們放火燒了銀白平原，濃煙瀰漫在夏日的空氣之中。我們無法再袖手旁觀了，無論手持的是鋤鏟鐮劍，我們都必須面對命運的安排。\n千言萬語都無法表達我對你和這個家的愛。\n——燒焦的信紙\n","單位",[],["愛歐尼亞"],"普通"],"04SH100":["悉心預備","將1張手牌洗入我方牌組即可出此牌。\n預言，並在手牌生成1張所選卡牌的複製牌。","","「我們今日種什麼因，未來就會得什麼果。」\n——新進時空術士泰","法術",[],["蘇瑞瑪"],"普通"],"04SH070":["不配飛昇","本回合給予1個敵軍侍從單位-4|-0。\n若我方的魔力寶石數量少於對手，則改為擊殺該單位。","","「陽光將再次照耀蘇瑞瑪的大地。」——重生者宣使","法術",[],["蘇瑞瑪"],"史詩"],"04SH081":["巴凱紡沙者","出牌：賦予1個敵軍單位-1|-0與弱勢。","","每撒出一粒沙，他們的生命就少了一秒，如同風一般慢慢侵蝕他們。","單位",[],["蘇瑞瑪"],"稀有"],"04SH077":["重生者宣使","若我方已升級英雄，則友軍單位獲得+2|+0。","","「很久以前，我聽過她說話。」老兵笑了，頓時，他的孫女能夠想像那片光景：蘇瑞瑪閃閃發光，阿祈爾氣宇軒昂地看顧著城市，重生者宣使高聲宣揚他的到來。「她激起了我們早以為失去的熱情。」","單位",[],["蘇瑞瑪"],"史詩"],"04SH019":["雷珂煞","此牌潛伏及攻擊時：賦予我方各處潛伏者單位+1|+0。\n回合結束：將此牌洗入我方牌組。","此牌以10點以上力量值進行攻擊。","「年輕的朱拉熱愛探險，某次他在一個神祕小洞穴裡發現了數匹古代卷軸。我們去到麥洛瑪找了翻譯，發現卷軸上記載著……我們的祖先受到了遠古邪魔的獵殺，那個邪魔是女王，煞族的女王！」——維庫拉長者費薩爾","單位",["潛伏者"],["蘇瑞瑪"],"英雄"],"04SH138":["赦罪之槍","本回合給予1個友軍單位+2|+1。若我方已升級英雄，則在手牌生成1張赦罪再臨。","","「所有人都跟我說不可使用這把武器，他們說：『如此強大的武器，任何人都不應使用。』」——埃可尚","法術",[],["蘇瑞瑪"],"普通"],"04SH089":["沙漠學家","出牌：摧毀1個地標。若是我方地標，則召喚1隻暴躁岩熊。","","「卡蒂拉今天又弄壞東西了！這次只是一面石牆，但看起來很有歷史，說不定對誰的祖宗八代很重要。她的藉口是特雷西尼的牆壁不像這裡的那麼脆弱，但我還是氣炸了！」——賽發的日記","單位",[],["蘇瑞瑪"],"稀有"],"04SH015":["血鬃拉茲","攻擊：本回合給予所有敵軍單位-2|-0。","","「這隻鱷魚出生時，就是發育最不良、外型最醜陋的，大家都在打賭牠能活多久。呵！沒想到牠竟然把手足吃得一乾二淨！」","單位",[],["蘇瑞瑪"],"史詩"],"04SH058":["沙術士","攻擊：召喚1位攻擊中的沙礫士兵。","","很少人知道沙漠的生存之道，更少人能夠像阿祈爾一樣操縱沙子。只有阿祈爾最忠誠、最厲害的侍從能夠有幸擁有這份力量，以及知曉沙漠的祕密。","單位",[],["蘇瑞瑪"],"普通"],"04SH080":["煞群呼喚","從手牌挑選1張牌置於我方牌組頂端即可出此牌。\n在手牌隨機生成2張潛伏者。","","「願太陽閃耀，煞族長眠。」——商人禱詞","法術",[],["蘇瑞瑪"],"普通"],"04SH035":["幸運日","在手牌生成1張挖到寶。","","「就和大家一樣，我經歷過很多好事，也有很多壞事。做這一行，差的時候，的確是差透，但好的時候，包你賺到笑。」——希維爾","法術",[],["蘇瑞瑪"],"普通"],"04SH028":["遠古計畫","出牌：預言。\n倒數2：召喚1位時鐘機器人。","","雖然它們已被沙塵深埋於地底多年，似乎已被時間遺忘，但其實這些機器人是按計畫被精準地安置於此地，只等著被喚醒。","地標",[],["蘇瑞瑪"],"普通"],"04SH054":["尋寶人","召喚此牌時，在手牌生成1張覺醒沙團。","","「好了，大甫。你要負責進去把那東西拿出來……管它是什麼，這樣我們，我是說我就可以發大財了，你要讓我\n發大財，懂嗎？還有，如果那是陷阱的話，我先跟你說\n聲抱歉。」","單位",[],["蘇瑞瑪"],"普通"],"04SH002":["巴凱收割者","我方屠殺單位時，賦予此牌+1|+0。","","「飛昇儀式失敗後，所有巴凱不是被遺棄，就是四散而逃，之後便行蹤成謎。背負著這樣的屈辱，和委身於暗黑墓地中的淒涼，又有誰能明瞭？」\n——《飛昇戰士團史》，書吏卡尼爾著","單位",[],["蘇瑞瑪"],"稀有"],"04SH042":["冬眠岩熊","倒數3：召喚1隻暴躁岩熊。","","「我的名字叫賽發，我喜歡在薩彌爾和大家都睡著的時候，在我無厘頭的本子裡寫些無厘頭的東西。」\n——賽發的日記","地標",[],["蘇瑞瑪"],"普通"],"04SH032":["冷酷碎骨者","名望：此牌魔耗值-1，且召喚此牌時，賦予此牌蠻力。","","士兵用盡全身力氣想把矛奪回來，卻讓她更使勁地壓在身上，使他痛得無法動彈。她故作好心地勸道：「不不不，別掙扎了。」接著，她微微邪惡一笑，不經意地露出她的尖牙，說道：「這已經是我的了。」","單位",[],["蘇瑞瑪"],"普通"],"04SH055":["遺跡獵人","","","寶庫先撇開不談，沙漠本身就潛藏著各種更明顯的危機，而蘇瑞瑪的傭兵和盜墓者必須先學會如何從這些威脅中生存下來。首先是無情的高溫，再來是排山倒海而來，嗜殺如命的盜匪。","單位",[],["蘇瑞瑪"],"普通"],"04SH039":["極靈","出牌：在我方牌組生成4張定時炸彈，然後預言。","此牌在場上時，我方摧毀2個以上友軍定時炸彈。","多年來，極靈穿梭時空，結識了許多來自不同時代的年輕法師，全都蘊藏著無窮潛力。這樣一來，萬一他自身遭遇不測，任何一人都可以延續他的畢生心血。雖然在這些年輕法師的眼中，極靈是個和藹可親、懂得鼓勵人的良師，當他獨處時，緊鎖的眉頭卻總透露出深沉哀傷，而那眼中的疲倦痛苦，唯有活過不只一輩子的人才能體悟。","單位",[],["蘇瑞瑪"],"英雄"],"04SH073":["塔莉雅","出牌：召喚1個我方地標的複製牌。","我方召喚5個以上地標。","「遊牧民族的步伐總是輕盈無比，因為他們不必落地生根，而家永遠都在地平線的另一端。」\n——蘇瑞瑪俗諺","單位",[],["蘇瑞瑪"],"英雄"],"04SH091":["學徒卡西歷","召喚此牌時，若本牌局我方已預言，則賦予此牌+1|+1。","","「記住我們學過的。」極靈用異常溫柔，但近乎沉重的聲音說道。「你確定你準備好了嗎？」\n卡西歷回以導師肯定的微笑。「我去去就回。而且我過去幾年來的每一天都是在為了這一刻做準備。此時不去待何時？」","單位",[],["蘇瑞瑪"],"普通"],"04SH024":["鹽塔","倒數2：召喚1隻暴躁岩熊。\n在本牌局中，若我方已召喚4個以上地標，則賦予最強友軍單位+2|+2。","","蘇瑞瑪的製鹽工人很快便學會哪些鹽礦適合採掘，哪些不該去碰。","地標",[],["蘇瑞瑪"],"普通"],"04SH003":["阿祈爾","我方攻擊時，召喚1位攻擊中的沙礫士兵。","我方召喚12個以上友軍單位或地標。","「當阿祈爾披上蘇瑞瑪神皇的龍袍時，他是自大盲目的。他不但擁權自重，還幫自己策劃飛昇儀式，好讓自己的統治版圖從蘇瑞瑪擴張到全世界。」\n——《飛昇戰士團史》，書吏卡尼爾著","單位",["飛昇者","鳥族"],["蘇瑞瑪"],"英雄"],"04SH011":["異形研究者","召喚此牌時，隨機賦予牌組中3個友軍單位+3|+3。","","虛空總是充滿驚喜，每天都在學習和尋找新方式滲入鐘塔，仿佛如荊棘一樣，但絕對更致命。因此要研究虛空並非易事，只有同樣機智博學的研究者，才能預測和理解來臨的威脅。","單位",[],["蘇瑞瑪"],"稀有"],"04SH130":["埃可尚","召喚此牌時及打擊：召喚\n1個軍閥府邸或快轉其1回合。","我方完成軍閥府邸的倒數。\n此牌升級時，召喚1個軍閥祕寶。","「哨兵的守則有各種繁文縟節，例如『不可以為了復仇而殺人』和『不可為自己而戰，應為世界而戰』等等。至於我呢……」","單位",[],["蘇瑞瑪"],"英雄"],"04SH114":["沙漠之怒","賦予我方各處沙礫士兵+1|+0。\n召喚2位沙礫士兵。","","他們永不止息。他們毫不猶豫。他們堅定、無情且絕不\n屈服。","法術",[],["蘇瑞瑪"],"稀有"],"04SH067":["雷尼克頓","此牌挑戰敵軍單位時，本回合給予此牌+2|+1。","此牌造成10點以上傷害。","「很難想像他曾經也是人類，因為他那鱷魚的外表與他對於血腥戰鬥的喜愛實在太過相襯……」——《飛昇戰士團史》，書吏卡尼爾著","單位",["飛昇者","爬蟲族"],["蘇瑞瑪"],"英雄"],"04SH120":["未來異想","在手牌隨機生成1張擁有倒數的地標，或快轉所有我方地標1回合。","","「時光疾如電。」——極靈","法術",[],["蘇瑞瑪"],"稀有"],"04SH119":["十字彈射","名望：此牌魔耗值-3。\n對1個隨機敵軍單位或敵方主堡造成1點傷害5次。","","「場面可能會有點慘烈。」——希維爾","法術",[],["蘇瑞瑪"],"普通"],"04SH068":["煞族喚獸","出牌：預言。","","不是所有煞族都是殺手。有些可以用撼動沙漠、震撼感官的叫聲召喚同族。","單位",["潛伏者"],["蘇瑞瑪"],"普通"],"04SH093":["砥礪石","本回合給予1個友軍單位+1|+1。\n在本牌局中，若我方已召喚地標，則改為給予其+2|+1。","","「有了大地相助，我們必能保護自己！」——塔莉雅","法術",[],["蘇瑞瑪"],"普通"],"04SH079":["占沙術","預言。\n本回合給予1個敵軍單位-2|-0。","","「我已看透自己的命運。而這次，我無人能擋。」——阿祈爾","法術",[],["蘇瑞瑪"],"稀有"],"04SH038":["躍岩者","召喚此牌時，召喚1個渾攪沙原。","","「今天，我們即將啟程前往娜敘亞麥！薩彌爾下定決心，要在下個滿月前穿越大煞沙漠，在過程中他造成了許多混亂！以前我想也沒有想到，一個簡單的沙板竟然能令一整座沙丘倒塌，薩彌爾也沒有料到，不過最後他沒事。」\n——賽發的日記","單位",[],["蘇瑞瑪"],"普通"],"04SH104":["珍存園丁","出牌：快轉1個我方地標3回合。","","每當極靈想要尋求一絲安寧的時候，他都會回到伊卡西亞的最後一座花園，那裡與他回憶中的景色一模一樣。","單位",[],["蘇瑞瑪"],"稀有"],"04SH128":["維庫拉浪客","召喚此牌時，召喚1個軍閥府邸或快轉其2回合。","","娜婭看著吊掛在四樓窗戶外的埃可尚，只能低聲咒罵——那美男子又搶先她一步了。娜婭把弄手中的匕首，反覆思考著要對他說什麼話。說不定這次他終於會認同她的實力。","單位",[],["蘇瑞瑪"],"普通"],"04SH109":["流沙陷阱","本回合給予1個敵軍單位-4|-0或2個敵軍單位-1|-0，並使其增益特性無效化。","","在沙漠某些地方，遺跡沉入沙底，造成空洞。旅人一不注意就會步上遺跡的後塵。 ","法術",["元素"],["蘇瑞瑪"],"普通"],"04SH043":["護砂瞬身","對1個單位造成4點傷害。\n召喚2位沙礫士兵。","","「上吧，包圍他們，面對大地他們無能為力。」\n——阿祈爾","法術",[],["蘇瑞瑪"],"稀有"],"04SH099":["砂漠禁軍","召喚1位沙礫士兵。\n在手牌生成1張飛逝砂漠禁軍。","","「命令已下達。」——阿祈爾","法術",[],["蘇瑞瑪"],"稀有"],"04SH048":["聖所內殿","名望：此牌魔耗值-3。\n倒數1：在手牌生成2張挖到寶。","","「有些地圖需要好幾年才能解讀；有些陷阱需要好幾個月才能解除，而有些寶庫需要好幾週才能摸透，但成功的那瞬間，每分每秒都值得。」——希維爾","地標",[],["蘇瑞瑪"],"普通"],"04SH056":["寶物獵人","召喚此牌時，在手牌生成1張挖到寶。","","「朋友，這是我在傳說中的帝王之墓中，從偉大的雷尼克頓本尊手裡，硬生生奪來的無價之寶。我衝出墓穴時，還被十個，不，二十個嗜血如命的騎兵團團包圍呢！這件寶貝能送到你的手中，根本就是一個奇跡！」","單位",[],["蘇瑞瑪"],"普通"],"04SH020":["希維爾","","我方造成30點以上傷害。","希維爾一直以傭兵之姿過日子，所有隨之而來的，無論是獎賞懲罰，自己選擇自己承擔。一次不幸的遠征任務差點讓她失去一切，但就在此時，當她的血滲入蘇瑞瑪的沙石，喚醒了能讓她和她的家鄉重返榮耀的遠古力量。","單位",[],["蘇瑞瑪"],"英雄"],"04SH057":["精神領袖","我方召喚其他單位時，本回合給予其+2|+0。","","獲得阿祈爾的祝福是一大榮耀——能以他之名給予祝福則是莫大榮耀。","單位",[],["蘇瑞瑪"],"稀有"],"04SH103":["無情獵手","出牌：賦予1個敵軍單位弱勢。","","「就這樣綁起來……好，搞定了。雷尼克頓最喜歡還活跳跳的食物。」","單位",[],["蘇瑞瑪"],"普通"],"04SH065":["地底巨獸煞沙雷斯","攻擊：若此牌的力量值為8以上，則本回合給予此牌威嚇、蠻力與法盾。","","「據說數百年前，卡麗河畔孕育出了一個繁盛的貿易站，名叫塔拉麗克。直到某天災難發生，一隻龐然大物破土而出，摧毀了貿易站，也殺害了所有以該地為家的人，但到底是多麼可怕的怪物才有這種能耐？」\n——蘇瑞瑪歷史學家","單位",["潛伏者"],["蘇瑞瑪"],"史詩"],"04SH034":["鐘樓守護者","召喚此牌時，在手牌生成2張百年一瞬。","","鍾樓守護者持續轉動著齒輪，接連不斷的隆隆聲正從鐘樓底層傳來。","單位",[],["蘇瑞瑪"],"史詩"],"04SH082":["殺戮之路","抽1張牌。\n若本回合我方已屠殺單位，\n則從敵方主堡汲取2點生命值。","","沙戮者的招募對象主要是他們的敵人。誰能活過他們的襲擊就能加入，或是領死。","法術",[],["蘇瑞瑪"],"稀有"],"04SH075":["空砂防壁","本回合給予所有敵軍單位弱勢並召喚6位沙礫士兵。","","「我的士兵昂首前進。」——阿祈爾","法術",[],["蘇瑞瑪"],"史詩"],"04SH018":["主宰儀式","擊殺1個友軍單位或摧毀我方1顆魔力寶石，以在本回合給予所有敵軍單位-2|-0。","","「迎戰吧！讓他們血流成河！」——雷尼克頓","法術",[],["蘇瑞瑪"],"稀有"],"04SH009":["暴怒巴凱","出牌：在本牌局中，若我方已屠殺4個以上單位，則使1個敵軍單位與此牌互相打擊。","","就算仇敵早已離開世間，身上背負著的怨恨只會愈來愈深。","單位",[],["蘇瑞瑪"],"稀有"],"04SH049":["天選普羅","回合開始：若我方已升級英雄，則將此牌幻化為至高普羅。","","她不確定自己發現了什麼……但看起來亮晶晶的很好吃。","單位",["普羅"],["蘇瑞瑪"],"普通"],"04SH045":["烈日當空","本回合給予1個敵軍單位-2|-0與弱勢。","","沙漠居民知道如何躲避烈陽的灼燒和高溫襲擊，但對毫無準備之人，烈陽將迅速耗損其力量與體力，不給任何喘息空間。","法術",[],["蘇瑞瑪"],"普通"],"04SH037":["碎裂地表","召喚2個渾攪沙原。\n抽1張牌。","","大煞沙漠擁有極致美景，但並非弱者生存之地。滾滾沙丘和煞族皆非善類，許多生命因此在此地逝去。","法術",["元素"],["蘇瑞瑪"],"稀有"],"04SH107":["飛昇者崛起","升級我方所有等級1的飛昇者。","","「未來由飛昇者譜寫！」——阿祈爾","法術",[],["蘇瑞瑪"],"史詩"],"04SH047":["納瑟斯","本牌局我方每屠殺1個單位，此牌便獲得+1|+1。","此牌單次打擊造成10點以上傷害。","「納瑟斯新獲得的祝福讓他有了無限的生命可以細細研究和深思生死的法則。但在蘇瑞瑪滅亡後，這份祝福也變成了詛咒。」——《飛昇戰士團史》，書吏卡尼爾著","單位",["飛昇者","犬族"],["蘇瑞瑪"],"英雄"],"04SH097":["聖所監管員","出牌：擊殺1個敵軍侍從單位。若本牌局我方已屠殺13個以上單位，則改為擊殺所有敵軍侍從單位，並召喚1個此牌的複製單位。","","巴凱的任務是保衛聖所內殿與裡面的遠古祕寶，還有制裁那些自以為夠聰明或夠強大，能夠承受監管員審判的凡人，免得他們自取其禍。","單位",[],["蘇瑞瑪"],"史詩"],"04SH026":["沙丘守護者","召喚此牌時，召喚1位沙礫士兵。","","「只要神皇一聲令下，眾沙塵與我皆將臣服。」","單位",[],["蘇瑞瑪"],"普通"],"04SH102":["黃金使者","效忠：抽1張英雄牌並賦予其+2|+2。","","「光明的未來就在沙漠底下，而我們要為阿祈爾鋪平道路。沙漠的黃金帝國將會再起！」","單位",[],["蘇瑞瑪"],"普通"],"04SH001":["新進時空術士","出牌：預言。","","在作為學徒修練時空術的過程中，泰總是得建立自信，來化解對於不確定未來的猶疑；比起想著可能出錯的環節，懷著可能會獲勝的希望還是比較好的。","單位",[],["蘇瑞瑪"],"普通"],"04SH022":["煞族陷丘怪","","","雖然所有的煞族都擅長挖洞，但只有陷丘怪才有足夠的體積和力量能夠挖穿大煞沙漠底下堅硬的岩脈，擴展煞族的獵場。","單位",["潛伏者"],["蘇瑞瑪"],"稀有"],"04SH030":["時光倒流","給予1個我方英雄：「本回合此牌下次將要陣亡時，反而會治癒此牌，並賦予其+3|+3」。","","「生命總會走到盡頭……但我們能拖延最後那段旅程。」——極靈","法術",[],["蘇瑞瑪"],"稀有"],"04SH013":["珍存之所","召喚此牌時，抽1張牌。\n倒數2：抽1張牌。","","極靈為那些他帶來鐘塔的人，展示他們想要修復的東西。珍存園丁能夠讓他們得償所願，即使每次只能匆匆一瞥。","地標",[],["蘇瑞瑪"],"稀有"],"04SH062":["埋沒的烈日巨環","牌局開始：若我方牌組皆為蘇瑞瑪卡牌，則從中召喚1張。\n倒數25: 復原烈日巨環。\n本牌局每有我方飛昇者升級時，快轉此牌9回合。","","當阿祈爾看到蘇瑞瑪首都的烈日巨環，他看到的不只是現在，更是未來——巨環可以讓蘇瑞瑪重返昔日榮光。","地標",[],["蘇瑞瑪"],"史詩"],"04SH016":["虹吸打擊","使1個友軍單位打擊1個單位。\n若該單位陣亡，則賦予各處我方英雄+2|+2。","","「你的靈魂由我來審判。」——納瑟斯","法術",[],["蘇瑞瑪"],"稀有"],"04SH125":["維庫拉盜庫者","出牌：本回合給予1個友軍單位+2|+0，並給予1個敵軍單位-2|-0。","","緹娜耐心等待她寵物的腐蝕唾液將宮殿後門的鍍金鐵欄融化。在大門的彼端，有數不清的無價珍寳等著她——足以讓維庫拉恢復昔日榮光。","單位",[],["蘇瑞瑪"],"稀有"],"04SH108":["迴旋之刃","使1個友軍單位輪流打擊\n最強與最弱敵軍單位。","","「勸你趕快閃。」——希維爾","法術",[],["蘇瑞瑪"],"稀有"],"04SH066":["時光之瓶","預言並快轉1個我方地標2回合。","","「若你能見我所見，就會明白時間並非無可改變。」——極靈","法術",[],["蘇瑞瑪"],"普通"],"04SH021":["回歸者卡西歷","召喚此牌時，在我方牌組生成1張此牌的複製牌。此牌在預言出現時，賦予我方各處相同卡牌+2|+2。","","卡西歷只暫時消失一陣子就突然回歸於眾人面前。他不僅幾乎老了十歲，還手握一個看似詭異又致命的武器。眾人不禁驚聲讚嘆，更暗地裡擔心著。","單位",[],["蘇瑞瑪"],"稀有"],"04SH101":["忠貞議會","回合開始：若我方已升級英雄，則治療我方英雄與主堡2點生命值。","","「我發誓效忠阿祈爾和我的家鄉蘇瑞瑪！你不一起來嗎？」","單位",[],["蘇瑞瑪"],"稀有"],"04SH012":["崇高聖顯者","召喚此牌時，快轉我方埋沒的烈日巨環3回合。","","「喔，爸爸！那是娜敘亞麥的其中一位長老帕諸曼！今天是不是全部的人都到我們的城鎮裡來啦？」——興奮的圍觀者","單位",[],["蘇瑞瑪"],"普通"],"04SH031":["光明未來","賦予1個我方地標以下能力：\n「此牌的倒數效果發動2次」。","","「凡人一生花費大部分時間在等待。我誠摯希望他們的耐心能得到獎賞。」——極靈","法術",[],["蘇瑞瑪"],"史詩"],"04SH004":["審判之重","對1個英雄造成2點傷害，或對1個侍從單位造成4點傷害。","","「一人犧牲，眾人得救。」——納瑟斯","法術",[],["蘇瑞瑪"],"普通"],"04SH059":["相消儀式","擊殺1個友軍單位或摧毀我方1顆魔力寶石，以抵銷敵方所有快速法術、慢速法術與技能。","","分析乃時空術之基石，因為在採取大多數行動前，必須先停下來思考未來的解決方法。","法術",[],["蘇瑞瑪"],"史詩"],"04SH044":["發條管理員","出牌：快轉1個我方地標2回合。","","這些魔像抵禦沙漠的無情摧殘長達千年之久，一直以來守護著極靈的鍾塔，這並不是單靠精巧工藝便能夠達成。","單位",[],["蘇瑞瑪"],"普通"],"04SH076":["遠古沙漏","泯滅1個友軍單位，以在原處召喚1個凝滯雕像，並將該友軍單位保存在內。","","「阿泰！過來！我們需要你幫個忙。」\n——虛空研究者賽沙","法術",[],["蘇瑞瑪"],"稀有"],"04SH118":["覺醒沙團","召喚1位砂褐衝鋒者。","","「那個箱子可能值點錢，但裡面的東西肯定跟沙子一樣毫無價值。我的意思是叫你別浪費力氣打開了。這是我的經驗談。」——希維爾","法術",[],["蘇瑞瑪"],"普通"],"04SH072":["預言家","召喚此牌時，賦予所有我方英雄和地標法盾。","","「啊，你沒想到會在沙漠中找到水吧？別擔心，放心過來盡情飲用、清洗沾滿沙塵的腳跟、在樹蔭下稍歇片刻。這就是阿祈爾的新生蘇瑞瑪，沙漠中的綠洲。」","單位",[],["蘇瑞瑪"],"普通"],"04SH041":["大煞偵察兵","出牌：預言。\n若我方挑選的卡牌為地標，\n則賦予此牌隱密。","","「我們差點遇上大麻煩！那時西邊有個逐漸靠近的風暴，而塔莉雅正通過位於大煞沙漠南邊的隧道。好在被我發現北邊有個寺廟能躲避風暴，它的赤陶壁磚正保護著我們的安全。其他人都進入夢鄉了，我的火把也快燒到盡頭了。祝我自己有個好夢。」——賽發的日記","單位",[],["蘇瑞瑪"],"普通"],"04SH005":["嗜血流寇","","","沙戮者和同伴們關係緊密，連打架、打獵和吃飯都形影不離。","單位",[],["蘇瑞瑪"],"普通"],"04SH083":["野性直覺","預言。","","「背鰭使人恐懼，利牙卻能致死。」——蘇瑞瑪俗諺","法術",[],["蘇瑞瑪"],"稀有"],"04SH092":["時辰已到","召喚1位時鐘機器人。\n若本牌局我方已預言，則改為召喚2位。","","「別鬧了，快過來！你的齒輪裡卡沙子了。」\n——新進時空術士泰","法術",[],["蘇瑞瑪"],"普通"],"04SH046":["砂褐奇美拉","本牌局每有1個友軍單位攻擊1次，此牌魔耗值便-1。","","在阿祈爾的回歸之時，蘇瑞瑪人也目擊傳說中遠古怪物的蹤影。用沙做成的怪物？著實令人過目難忘。","單位",[],["蘇瑞瑪"],"稀有"],"04SH105":["古沙陵墓","我方攻擊時，召喚1位攻擊中的砂褐衝鋒者。","","當他們穿越河谷，沙術士念出咒語，一陣狂風便席捲峽谷，回音化為震耳欲聾的蹄聲。","地標",[],["蘇瑞瑪"],"稀有"],"04SH131":["鋼鉤射擊","使本回合被我方指定為法術/技能目標的1個友軍單位打擊1個敵軍單位。","","「沒料到我有帶鉤索吧！」——埃可尚","法術",[],["蘇瑞瑪"],"稀有"],"04SH074":["幼年煞族","","","商隊失去行動能力後，負責追獵的成體有時候會撤退下來，讓幼獸前往覓食。幼小的煞族就是以此培養直覺，\n從沙漠中辨識出獵物的聲音。","單位",["潛伏者"],["蘇瑞瑪"],"普通"],"04SH137":["轟鳴蟲群","召喚此牌時，若我方已升級英雄，則在手牌生成1張此牌的複製牌。","","蘇瑞瑪帝國覆亡時，人們以為那些巨大的甲蟲也隨之滅絕。不過，黯霧成功滲透沙漠地底深處，並使這些古老生物臣服於維爾戈。\n","單位",[],["蘇瑞瑪"],"史詩"],"04SH069":["庖丁解牛","本回合給予1個友軍單位+2|+0，並給予1個敵軍單位弱勢。","","「撕裂他們！」——雷尼克頓","法術",[],["蘇瑞瑪"],"普通"],"04SH121":["呼喚儀式","擊殺1個友軍單位或摧毀我方1顆魔力寶石，然後抽1張英雄牌。","","「這點犧牲無可厚非。」——納瑟斯","法術",[],["蘇瑞瑪"],"普通"],"04SH110":["岩石編織","顯化1張我方有足夠魔力能打出的地標牌。","","「快來看，簡直目不暇給！」——塔莉雅","法術",["元素"],["蘇瑞瑪"],"史詩"],"04SH051":["神皇座台","我方攻擊時，召喚1位攻擊中的沙礫士兵。","","沙術士一抬手，沙子便化為那熟悉的無臉士兵整裝待發。不知疲倦為何物的軍團旋即準備好為了神皇而戰。 ","地標",[],["蘇瑞瑪"],"稀有"],"04SH106":["靈魂烈焰","本回合給予所有敵軍單位-2|-0以及「回合結束：對此牌造成2點傷害」。","","「他們的靈魂將會燃燒。」——納瑟斯","法術",[],["蘇瑞瑪"],"稀有"],"04SH129":["維庫拉壯漢","打擊：在手牌生成1張挖到寶。","","「芭芭拉，聽著。這層的守衛都解決了，\n但我們還是得低調行事，知道嗎？」\n「芭芭拉吧啦！」\n「太大聲了。」\n*小聲*「吧啦。」\n「真乖。」","單位",[],["蘇瑞瑪"],"稀有"],"04FR006":["凜冰仲裁官","召喚此牌時，召喚1位冰封奴魔。\n回合結束：若我方有倒數4以下的\n冰封奴魔，則將其快轉至歸零。","","「我夢到女王輕聲細語的邀請：『跟隨我的腳步吧。』我不敢抗命。」","單位",[],["弗雷爾卓德"],"史詩"],"04FR012":["寒冰滅頂","泯滅所有敵軍單位，以召喚相同數量的永凍墳地，並將所有敵軍單位保存在內。","","「寒冷終究會吞噬一切。」——麗珊卓","法術",["元素"],["弗雷爾卓德"],"史詩"],"04FR016":["搜刮戰利","賦予1個友軍單位+1|+2。\n洗劫：改為賦予+2|+4。","","「你們這些艾伐洛森人仰仗那肥沃土地坐吃山空，變得軟弱無能。虛弱的可憐蟲們啊，把握今晚最後的美夢吧，因為你們睜眼之時這一切都將屬於我們。」\n——戰痕之母芙蕊娜","法術",[],["弗雷爾卓德"],"普通"],"04FR013":["極寒防禦","獲得1格魔力寶石槽位並賦予1個友軍單位+0|+2。","","「小心那些寒冰……更加要提防的是……冰裡的東西！」——某弗雷爾卓德旅店牆上的潦草字跡","法術",["元素"],["弗雷爾卓德"],"普通"],"04FR005":["麗珊卓","召喚此牌時，召喚1位冰封奴魔並快轉其2回合。","我方召喚2個以上魔耗值為8以上的友軍單位。此牌升級時，在手牌生成1張守望者。","「在高牆的另一邊，潛伏著被冰雪包覆、時間被暫停\n的守望者。就讓他們再等等吧，我有一些計畫必須先\n進行……」","單位",[],["弗雷爾卓德"],"英雄"],"04FR011":["極寒冰噬","凍傷1個敵軍單位。\n召喚1位冰封奴魔。","","「每個人對寒冷的反應不同，來看看你又是如何吧。」——麗珊卓","法術",["元素"],["弗雷爾卓德"],"普通"],"04FR001":["冰封奴魔","倒數9：召喚1位寒冰護衛的奴魔。","","在特朗德那毫無紀律的軍隊中，的確有許多笨頭笨腦的兵卒，可以拿來當前線的砲灰；不過麗珊卓要的是更高級的貨色，不僅要更忠心、還只能對她一人忠心……","地標",[],["弗雷爾卓德"],"普通"],"04FR007":["冰葬","泯滅1個單位，以在原處召喚1個永凍墳地，並將該單位保存在內。","","「臣服吧！否則我將冰封伺候。」——麗珊卓","法術",["元素"],["弗雷爾卓德"],"稀有"],"04FR017":["先祖恩澤","賦予牌組最上方的友軍單位+2|+2。\n開悟：改為賦予牌組中所有友軍單位+2|+2。","","寒冷風暴無情地肆虐本已貧瘠的弗雷爾卓德，更奪走了無數性命。不過大難不死必有後福，倖存者們磨練出更加堅定的意志力，能夠面對未來的考驗。","法術",[],["弗雷爾卓德"],"普通"],"04FR014":["蠻荒冰壑","召喚此牌時，治療我方主堡2點生命值。倒數1：對所有單位造成2點傷害。","","各種奇形怪狀的黑暗冰晶從山壑中冒出，密密麻麻的尖刺，任何入侵者都逃不過它們的天羅地網。","地標",[],["弗雷爾卓德"],"稀有"],"04FR009":["幽影碎冰","對所有目標造成1點傷害。","","「我將冰埋這個世界。」——麗珊卓","法術",["元素"],["弗雷爾卓德"],"普通"],"04FR015":["傳奇普羅","召喚此牌時，賦予所有普羅友軍單位1項隨機特性。","","普羅之間流傳著一個傳說：有一個四處流浪的普羅，當牠遇上乖普羅時，便會賜予牠們各種各樣的魔法禮物。","單位",["普羅"],["弗雷爾卓德"],"稀有"],"04FR019":["冰霜尖牙狼之母","召喚此牌時，召喚1個冰霜尖牙狼群。","","冰霜尖牙狼群謹慎地壓低身子，團團圍住散發出強烈死亡氣息的德魯瓦斯克野豬。","單位",["犬族"],["弗雷爾卓德"],"稀有"],"04FR018":["雪怪守護者","此牌在手中時，回合開始：若我方場上有2個以上雪怪單位，則召喚此牌並在我方牌組生成1張此牌的複製牌。\n出牌：抽1張雪怪。","","「……而且牠們還會神不知鬼不覺地出現！上次我出門在外，找到一個洞穴歇息，裡面卻有小雪怪在睡覺。我想保持距離，但有隻大的回來了，跟山一樣高而且渾身是冰！你給我聽好了，因為……」——碎碎念的比亞","單位",["雪怪"],["弗雷爾卓德"],"史詩"],"04FR010":["三姊妹","在手牌生成1張飛逝急速冰凍、北境之怒或冰葬。","","艾伐洛森、席利妲和麗珊卓，這弗雷爾卓德三姊妹都擁有強大的力量，但她們發揮所長的方式不盡相同；一個慈悲為懷、一個熱愛戰爭，而另一個殺戮成性。","法術",[],["弗雷爾卓德"],"稀有"],"04NX002":["流言蜚語","名望：此牌魔耗值-2。\n抽2張牌。","","處心積慮設局讓流言滿天飛，而真相永遠只有一個。","法術",[],["諾克薩斯"],"稀有"],"04NX010":["玫瑰棘兵","召喚此牌時，在手牌生成1張狡詐。","","「艾連娜，我的摯友和同僚！你有見到都因領主嗎……？啊，真是太可惜了，我本想和他敘敘舊。若那老朋友出了什麼差錯，我可是會傷心欲絕的……」\n——黑玫瑰間諜，奧芙蕊夫人","單位",[],["諾克薩斯"],"普通"],"04NX021":["退役角鬥士","我方指定此牌為法術/技能目標時，賦予此牌+1|+0。","","經歷了無數戰役後，伯溫發下誓言，即使要賠上自己的生命，也不再拿起刀劍爭戰。不過，一股詭異濃霧橫掃諾克薩斯，希婭也被其所吞沒。伯溫深知自己終將違背誓言；為了解放希婭，他會不惜一切代價。","單位",[],["諾克薩斯"],"稀有"],"04NX022":["殞落角鬥士","召喚此牌時，在手牌生成1張午夜突襲。","","雖然希婭的刑期已結束，但她知道自己再也無法回到族人身旁。她已被戰爭——還有諾克薩斯——徹底改變了，變得嗜殺成性，永遠無法得到安寧。因此，她選擇利用自己學到的新技巧，在競技場搏鬥謀生。","單位",[],["諾克薩斯"],"稀有"],"04NX015":["血腥事件","名望：此牌魔耗值-2。\n使1個力量值為5以上的友軍單位打擊1個敵軍單位。","","「最可怕的威脅都是躲在不見光處的。」——勒布朗","法術",[],["諾克薩斯"],"普通"],"04NX019":["狂暴四不像","此牌被敵軍單位格擋時，本回合給予此牌+3|+0。","","諾克薩斯軍隊在愛歐尼亞海岸邊發現了一種生物，其過人的生存能力令年輕的將軍十分訝異，便堅持把牠帶回去，想要發掘牠真正的力量。","單位",["爬蟲族"],["諾克薩斯"],"史詩"],"04NX008":["敏銳謀略家","名望：此牌魔耗值-2。\n召喚此牌時，進行備戰。","","在「黑玫瑰」最深處的房間裡，諾克薩斯貴族只要動一步棋，某處就會有人喪命。","單位",[],["諾克薩斯"],"稀有"],"04NX006":["黑玫瑰間諜","名望：召喚此牌時，將此牌幻化為本回合進行過打擊的最強友軍單位的複製單位。","","「一旦曝光，祕密就不值錢了。」","單位",[],["諾克薩斯"],"史詩"],"04NX001":["模仿","名望：此牌魔耗值-3。\n本回合我方打出法術時，對相同目標再複製一次。","","模仿是最真誠的讚美，而讚美有時候反而是最致命的。","法術",[],["諾克薩斯"],"稀有"],"04NX004":["勒布朗","","此牌在場上時，我方造成15點\n以上傷害。此牌升級時，\n在手牌生成1張鏡像。","「好了好了，起內鬨沒意義。暫時不要草率行事，待探子捎來消息後我們再開議，畢竟……」","單位",[],["諾克薩斯"],"英雄"],"04NX016":["尖嘯蜘蛛","攻擊：本回合給予蜘蛛友軍單位+2|+0。","","「盡情地嘶吼讓眾人都聽到吧，我的寶貝！讓他們『興奮』難耐，讓我愉悅痛快！」——伊莉絲","單位",["蜘蛛"],["諾克薩斯"],"稀有"],"04NX007":["滅世者亞塔坎","出牌：復甦最強已陣亡友軍單位。\n攻擊：賦予此牌力量值，賦予量等同於場上所有友軍單位力量值的總和。","","密室裡煙霧瀰漫，無名的異形矗立在他們面前。魔法師們吟唱著不和諧的咒文，恐懼使得他們的聲音愈發尖銳狂熱。異形深吸著他們逐漸加深的恐懼，每吸一口就讓牠更加壯大。","單位",[],["諾克薩斯"],"史詩"],"04NX018":["血色怪貓 ","我方下次召喚友軍單位時，對其造成1點傷害，並賦予此牌+1|+1。","","「被牠們的利爪輕輕一劃就會血流如注，所以很少人會把牠們當寵物……但我絲毫不介意。」\n——血色門徒，克拉拉","單位",["貓族"],["諾克薩斯"],"普通"],"04NX003":["惡意印記","名望：此牌魔耗值-2。\n對任1目標造成2點傷害。","","得勝後絕不能手下容情，必須乘勝追擊，將仇敵趕盡殺絕。","法術",[],["諾克薩斯"],"普通"],"04NX017":["人多勢眾","召喚2位軍團流寇。","","雖說諾克薩斯士兵甚少留下活口，但流寇更加無情。","法術",[],["諾克薩斯"],"普通"],"04NX009":["玫瑰劍","本回合給予1個友軍單位+5|+0。","","「你必須表現得優雅有禮；奉承他人，解除戒心，掌握情報。等時候到了，就發動攻擊，置人於死地！」\n——勒布朗","法術",[],["諾克薩斯"],"普通"],"04SI005":["鏡爪","每回合我方首次屠殺單位時，\n此牌標記最弱敵軍單位。\n回合結束：擊殺此牌標記的單位。","此牌在場上時，我方屠殺此牌標記的單位2個以上。","曾有一人，孑然一身\n他將己身，為二一分\n一化為二，重獲新生\n從此不再，孤獨一生","單位",[],["闇影島"],"英雄"],"04SI055":["維爾戈","每回合首次有其他友軍單位陣亡時，召喚1個幽侵黯霧。","此牌在場上時，陣亡友軍單位的力量值總和為20以上。","「年輕的國王散發著某種氣息，令我深感不安。他的內心好像有一種……無法滿足的飢渴，抑或永無止境的欲望。」——摘自迦瑪沃爾人努諾．奈克利特之手記","單位",[],["闇影島"],"英雄"],"04SI016":["靈蛭 ","出牌：擊殺1個友軍單位以抽2張牌。","","潛伏於黑暗之中，等待著獵物睡著或恍神。接著尖爪一揮、大嘴一咬，最後只剩黑暗。","單位",[],["闇影島"],"普通"],"04SI007":["幻影魔鷹","出牌：擊殺1個友軍單位，以擊殺1個敵軍單位。","","「當我氣數將盡時，我發現自己思考的不是這一次的死亡，而是下一次的。最後一個記得我的人會是誰？而當他也回歸塵土後……我會變成怎樣？」——大善人","單位",["鳥族"],["闇影島"],"稀有"],"04SI011":["身陷黃昏","抽1張牌。\n夜臨：發動1個友軍單位的夜臨效果，其中需指定目標的效果不會被觸發。","","「來吧，孩子，毋須害怕。」——假面之母","法術",[],["闇影島"],"稀有"],"04SI018":["扭曲叢林","此牌在場上時，3個以上擁有威嚇或夜臨的友軍單位攻擊後，摧毀此牌以召喚威洛魔。","","祭壇無人造訪，小徑人跡罕至，\n但怪物依舊穿梭暗處，等著健忘的傻子送上門來。","地標",[],["闇影島"],"史詩"],"04SI015":["深海甲蟲","每有1個其他友軍單位陣亡或遺願：亂擲1張牌。","","「好了，大夥們——把陷阱拉上來！記得，如果看到深海甲蟲，就切斷繩索換下一個。我才不想為了拿到牠們吃剩的垃圾而沉船，聽見沒？」——比爾吉沃特船長","單位",["海怪"],["闇影島"],"稀有"],"04SI004":["生死相倚","出牌：打出起源之浪或終結之息。","","從均衡組織的教義來看，神只有兩位：藉其溫暖海水孕育生命的「起源之浪」，以及藉其嚴寒嘆息奪去生命的「終結之息」。","單位",[],["闇影島"],"史詩"],"04SI017":["闇影島之歌","賦予1個友軍單位吸血、威嚇與閃靈。","","「來吧，孩子。見我所見、觸我所觸。毋須害怕黑暗。」——燃魂人","法術",[],["闇影島"],"普通"],"04SI054":["迦瑪沃爾士兵","召喚此牌時，召喚1個幽侵黯霧。","","在生前，迦瑪沃爾的士兵在維爾戈的命令下征戰四方；在死後，他們仍然忠貞不二。","單位",[],["闇影島"],"普通"],"04SI001":["神羊喘息","本回合給予最弱友軍單位\n「此牌免疫傷害及死亡」。","","「在斷氣前再一次發光發熱。」——神羊","法術",[],["闇影島"],"史詩"],"04SI056":["吸魂黯霧","從2個敵軍單位汲取2點生命值。","","「凡是我想要的，就一定會拿到手；凡是我不要的，\n就一定會除掉。」——維爾戈","法術",[],["闇影島"],"稀有"],"04SI012":["天幽狐","出牌：擊殺1個友軍單位，以對敵方主堡造成3點傷害。","","少數巨石峰部族之間流傳著天幽狐的傳說：祂是死神，是夜空中孤獨的一顆星星。根據傳說，每當有人死亡，天幽狐就會降臨巨石峰，將死者的靈魂帶回天上，變成祂黑暗星座的一部分。","單位",[],["闇影島"],"普通"],"04SI029":["絕望","挑選1個單位打擊我方主堡，然後擊殺之。","","「為了找到她，我付出了一切，然而還是不夠。」——維爾戈","法術",[],["闇影島"],"普通"],"04SI009":["織魂者","召喚此牌時，若本回合有友軍單位陣亡，則賦予此牌+1|+1與威嚇。","","「曾經有位不幸的年輕人想要和蜘蛛交往，卻從來沒想過自己可能也會淪為牠的獵物……」","單位",["蜘蛛"],["闇影島"],"普通"],"04SI013":["假面之母","出牌：擊殺1個友軍單位，並賦予此牌該友軍單位的能力值與特性。","","據說假面之母創造了鏡爪，如同她創造所有死亡的化身。但她的面具若非自己打造，又是從何而來？","單位",[],["闇影島"],"普通"],"04SI021":["百足蛇龍","此牌打擊1個友軍單位或對我方主堡造成3點傷害即可出此牌。","","起初，蒂瑪西亞士兵聽到了從廣場傳來大量爪子與地磚摩擦的聲音。等到牠攻破了瞭望臺之後，他們才察覺到那些無數的爪子，全都屬於同一隻怪物。","單位",["龍族"],["闇影島"],"普通"],"04SI002":["靈魂之旅","擊殺1個單位，再將其復甦。","","「這只不過是個小插曲而已。」——神羊","法術",[],["闇影島"],"稀有"],"04SI053":["九頭蔓侵襲","召喚此牌時及回合開始：召喚1個幽侵黯霧。","","茂凱不眠不休地試圖在闇影島孕育生命；而黯霧一邊吞噬生命，一邊卻造就墮落的生物，其中蘊含的諷刺同樣\n殘酷。","單位",[],["闇影島"],"史詩"],"04SI003":["褪色死神","召喚此牌時，召喚1個螢火靈。","","除了受到永生詛咒的人以外，誰會忘記死神？而對於死神來說，除了被遺忘以外，還有什麼更可怕的？ ","單位",[],["闇影島"],"普通"],"04SI028":["迦瑪沃爾巨龍","此牌打擊1個友軍單位或對我方主堡造成3點傷害即可出此牌。\n此牌擊殺其他單位時，從敵方主堡汲取1點生命值。","","數百年來，黯霧吞噬了世界各地的生物，扭曲牠們的心靈，使其化為惡夢般的存在。","單位",["龍族"],["闇影島"],"稀有"],"04MT014":["拉克爾之眼","倒數1：擊暈2個最弱敵軍單位。\n破曉：召喚1個此牌的複製地標，其為倒數2。","","「讓太陽的光輝照耀我們。不配的弱者將畏懼她的亮光！」——日輪女祭司","地標",[],["巨石峰"],"稀有"],"04MT008":["墨菲特","出牌：擊暈1個敵軍單位。","我方召喚魔耗值總和為10以上的地標。此牌升級時，若我方擁有攻擊主動權，則在手牌生成1張勢不可擋。","「石奇偶的巨石峰之旅來到最後一站惹！這係老爹！他係巨石峰上最大的巨人，還很會唱歌。不過，可不要在他森上爬喔！刺刺的東西會害他森上癢，你可不希望爬到一半害他打噴嚏吧！」\n——《石奇大冒險》第六部","單位",[],["巨石峰"],"英雄"],"04MT010":["星角峰","倒數2：在手牌隨機生成2張\n魔耗值為3以下的天界牌。","","挑戰攀登巨石峰的人們，在旅途前段就可以欣賞到幾幅符文大地上最壯觀的奇景；當山壁益加陡峭，景觀也會隨之更加震憾人心。","地標",[],["巨石峰"],"稀有"],"04MT005":["石奇","在本牌局中，我方召喚地標後，賦予此牌+2|+2。","","「大家好偶係石奇，偶要來帶大家探索巨石峰！巨石峰超大超高，希望你們穿的鞋爬起山來夠蘇湖！走吧！」\n——《石奇大冒險》第一部","單位",[],["巨石峰"],"普通"],"04MT009":["蜿蜒長城","倒數3：在手牌生成1張力量種子。","","「這裡係巨石峰之旅的第一站！偶叫這裡『腳必軟』，因為這個樓梯超長！景色也酷，巨石峰這點最棒惹。好了粗花吧！」——《石奇大冒險》第二部之一","地標",[],["巨石峰"],"稀有"],"04MT001":["落石小徑","倒數2：泯滅最弱敵軍單位。","","「所——有——人給偶看好，這懸崖真滴高。偶摔下來這裡好幾次了，你們聽偶縮，這裡可深了！偶係鐵打的所以不會受傷，但你們不一樣……所以要小——克里夫來啦！去打個招呼吧！」\n——《石奇大冒險》第三部","地標",[],["巨石峰"],"普通"],"04MT018":["膽小野山羊","此牌受到支援時，本回合給予此牌及支援此牌的友軍單位+1|+1。","","「狂風呼呼地大吹\n穿越山谷也不衰\n我的寶貝不要怕不要慌\n你的母親永遠守在身旁。」——巨石峰搖籃曲","單位",[],["巨石峰"],"普通"],"04MT004":["遠古魔像","遺願：召喚1個智慧的餘燼。","","「所——有——人一起縮『嗨小藍！』嗨小藍！偶有次以為他也回答『嗨小藍！』，但現在想想那大概係偶的回音。總之他很神奇而且藍藍的，不用縮話沒關係辣！好了掰小藍走囉！」\n——《石奇大冒險》第五部","單位",[],["巨石峰"],"普通"],"04MT013":["日隼","破曉：擊暈最強敵軍單位。","","日輪教徒堅信是巨石峰的亮麗日隼吸引了不死鳥的注意，讓牠開始展開死亡與重生的循環。","單位",["鳥族"],["巨石峰"],"普通"],"04MT003":["大地龜","在本牌局中，我方召喚4個以上地標後，賦予此牌+3|+0。","","「他就係克里夫！這個大塊頭很見多係廣喔。偶知道他看起來很酷，也很善良，但他背上有一堆重物，有時候還會砸到人，所以要小心點，好嗎？謝謝，繼係往前吧！」\n——《石奇大冒險》第四部","單位",[],["巨石峰"],"普通"],"04MT002":["碎石巨像","出牌：在本牌局中，若我方已召喚4個以上地標，則對1個敵軍單位造成4點傷害，並對敵方主堡造成2點傷害。","","巨石峰的巨像偶爾會從沉睡中甦醒，並在高山上四處遷徙。這種事發生時可一點都不平靜，更遑論安全了。","單位",[],["巨石峰"],"史詩"],"04MT006":["星幕聖顯","祈望。\n若我方場上有天界單位，則將我方牌組替換成20張望穿無垠。","","「看啊，庫倫！天上的繁星有好多故事！今晚要讀哪一則呢？」——白月夢舞者","法術",[],["巨石峰"],"史詩"],"04MT012":["天命選召","賦予手牌中1個友軍單位+8|+8。","","「接納你的命運，綻放前所未有的光芒吧！」——塔里克","法術",[],["巨石峰"],"史詩"],"04MT007":["大地震顫 ","擊暈1個敵軍單位。在本牌局中，若我方已召喚地標，則對該單位造成3點傷害。","","「沒錯，那只係山在搖，絕對不係老爹在亂拍亂晃噢不對係耶算惹，繼續往上爬吧！」——石奇","法術",["元素"],["巨石峰"],"稀有"],"04MT015":["天體並行","破曉：在手牌隨機生成1張夜臨牌。\n夜臨：在手牌隨機生成1張破曉牌。","","日夜循環便是如此，日以繼夜、夜以繼日。","法術",[],["巨石峰"],"普通"],"04DE004":["鐵血偵察兵","召喚菁英單位時，此牌魔耗值-1。","","蒂瑪西亞的偵察兵對森林瞭若指掌，無論諾克薩斯人的陷阱設得再怎麼隱密，每根斷枝、每個腳印都是引導他們接近王子的線索。","單位",["菁英"],["蒂瑪西亞"],"稀有"],"04DE014":["巨龍點心","我方打出龍族時，該龍族單位會打擊此牌，接著我方抽1張牌。","","「你說那遠在天邊的尖銳叫聲？兒子，那並不是鳥鳴，而是正在捕食的巨龍所發出的尖嘯。」——蒂瑪西亞農夫","單位",[],["蒂瑪西亞"],"普通"],"04DE001":["名譽領主","此牌首次挑戰敵軍單位時，本回合給予此牌光盾。","","國王嘉文三世在得知皇子失蹤後，委託摯友貝瑞特．布斐利領主組織搜救隊，以找回皇子。後來皇子平安返國，但不幸的是，布斐利領主卻沒有歸來，這也成為了嘉文三世的終生遺憾。","單位",["菁英"],["蒂瑪西亞"],"普通"],"04DE012":["戰場晉升","本回合我方下次打出單位時，賦予其先遣，並視為菁英單位。","","蒂瑪西亞人受到考驗時，就更能展現臨危不亂的精神。","法術",[],["蒂瑪西亞"],"普通"],"04DE003":["浩劫降臨","使1個友軍單位發動額外攻擊並挑戰1個敵軍單位。","","「國王萬歲！」——嘉文四世","法術",[],["蒂瑪西亞"],"稀有"],"04DE002":["光盾庇護","本回合給予1個友軍單位光盾，進行備戰。","","「蒂瑪西亞的士兵們，繼續戰鬥吧！」——嘉文四世","法術",[],["蒂瑪西亞"],"稀有"],"04DE006":["戰技專精","賦予1個友軍單位+1|+1。","","「我來教你兩招。」——布斐利領主","法術",[],["蒂瑪西亞"],"普通"],"04DE008":["嘉文四世","我方攻擊時，支付此牌的魔耗值，\n並召喚此牌挑戰最強敵軍單位。","友軍單位承受敵方格擋單位\n打擊3次以上，且未陣亡。","諾克薩斯人不僅把嘉文皇子的打獵行程摸得一清二楚，還知道會有多少蒂瑪西亞衛隊隨行，更清楚皇子為了自己的榮譽，是不可能逃跑的；陷阱已經設計妥當。","單位",["菁英"],["蒂瑪西亞"],"英雄"],"04DE005":["雲霄戰士希莉亞","召喚此牌時，使其他友軍單位的力量值與生命值加倍，並賦予其挑戰者。","","「能夠拯救蒂瑪西亞王子的非雲霄戰士莫屬！」\n——嘉文三世國王","單位",["菁英"],["蒂瑪西亞"],"史詩"],"04DE020":["殞落龍衛","擁有血怒的友軍單位擊殺單位時，額外賦予其+1|+1。","","黯霧扭曲了葛雷格姆的心靈，使威沃之戰的痛苦回憶在他腦中揮之不去，喚起他埋藏已久的怨恨與憤怒，驅使他和曾出生入死的戰友反目成仇。","單位",[],["蒂瑪西亞"],"普通"],"04DE010":["嘉文三世國王","召喚此牌時，抽1張嘉文四世。\n若該牌已在場上，則改為本回合給予所有友軍單位挑戰者與先遣。","","「試問，父親會願意付出什麼代價來拯救孩兒呢？甚或，那父親是一國之君呢？」——勒布朗","單位",["菁英"],["蒂瑪西亞"],"史詩"],"04DE016":["殞落飛龍卡卓格林","出牌：賦予1個友軍單位挑戰者與+1|+1。","","遠在黯霧抵達蒂瑪西亞之前，卡卓格林早已在該地四處散播災厄和恐懼。不過，在維爾戈的控制下，卡卓格林的能力卻能用於增强殞落軍勢。","單位",["龍族"],["蒂瑪西亞"],"稀有"],"04DE013":["魁偉石角鹿","敵方法術/技能無法對此牌造成傷害。","","傳說反魔法英石森林還很年輕時，這些偉大的石角獸就已存在了。牠們的鹿角和那些古老的樹木，材質上還有幾分相似。","單位",[],["蒂瑪西亞"],"普通"],"04DE015":["銀翼鷲飛行隊","出牌：在手牌生成1張銀翼鷲先鋒、飛鷹突擊或疾羽獵鷹。\n攻擊：本回合給予其他挑戰中的友軍單位+1|+1。","","光是看見銀翼鷲飛行隊就能讓戰場上的蒂瑪西亞士兵士氣高昂；看見他們從雲間降臨，地面上的士兵便隨即重振士氣，準備繼續奮戰。","單位",["菁英","鳥族"],["蒂瑪西亞"],"史詩"],"04DE007":["懺罪隨從","召喚此牌時，若我方掌控菁英牌，則在手牌生成1張殘破戰旗。","","那負罪的隨從撐著疲累的身軀，一直走到城牆邊才終於軟下雙腳來。如此一來，無畏先鋒終能把口信傳給國王，好派人去搜救皇子；她也終能將功折過，保全自己的名聲。","單位",[],["蒂瑪西亞"],"普通"],"04DE009":["英勇騎兵","此牌首次挑戰敵軍單位時，將其幻化為先鋒騎兵。","","一聲令下，所有蒂瑪西亞士兵都被徵召投入搜尋皇子的行動；這時靈活權變才是達成任務的關鍵。","單位",["菁英"],["蒂瑪西亞"],"稀有"],"05BC058":["凱能","召喚此牌時，在手牌生成1張風暴印記。","我方召喚同一友軍單位5次以上。","凱能也聽見了，卻看不見發出吼聲的是誰……是什麼東西。是人或是怪物都不重要，均衡組織會盡一切努力保護土地。","單位",["約德爾人"],["班德爾城","愛歐尼亞"],"英雄"],"05BC010":["馴鯊師","我方攻擊時，召喚1隻攻擊中的短齒鯊。","","馴鯊師每晚的行程都一樣，晚餐吃魚配酒，呼個泡泡菸斗，然後親親鯊魚鼻，講床邊故事哄鯊魚睡覺。","單位",["約德爾人"],["班德爾城","比爾吉沃特"],"稀有"],"05BC102":["老巫師","回合開始：恢復1點法術魔力。","","如果這世上沒有比被紙割傷還要痛苦的事，那就沒有人比圖書館員還要更瞭解痛楚為何物。","單位",["約德爾人"],["班德爾城"],"普通"],"05BC230":["靈界之門","棄置1張牌即可出此牌。賦予所有友軍單位+1|+1。","","「我怎樣都記不住這些東西是怎樣運作的。」——波比","法術",[],["班德爾城"],"普通"],"05BC099":["猛男偵察兵","召喚此牌時，我方場上每有1個其他約德爾友軍單位，便賦予此牌+1|+1。","","「我的祕訣是什麼？就讓我的二頭肌來告訴你吧！」","單位",["約德爾人"],["班德爾城"],"稀有"],"05BC133":["崔絲塔娜","本牌局我方每召喚1個多區域友軍單位，此牌便獲得+1|+0。\n我方召喚多區域友軍單位時，賦予其+1|+0。","我方召喚5個以上多區域友軍單位。","「好，A計畫如下：我們炸出一條路然後邊開火邊殺進去，如果沒用就換B計畫：炸出一條路然後邊開火邊殺出來。接著我們重新會合然後進行C計畫，內容跟A計畫差不多……」","單位",["約德爾人"],["班德爾城"],"英雄"],"05BC023":["小海獸","回合結束：若本回合我方已對敵方主堡造成傷害，則將此牌幻化為超大海獸。","","拿可塔族領地附近有些夏岩，小海獸喜歡在這些暖暖的夏岩上打瞌睡，但討厭被調皮愛玩的約德爾人從夏岩上推下來……","單位",[],["班德爾城"],"史詩"],"05BC029":["悠咪","回合開始：若此牌附著在友軍單位上，則賦予其+1|+1，若無則改為賦予此牌+1|+1。","此牌或此牌附著的友軍單位攻擊3次。","儘管悠咪整天抱怨不停，她還是得承認自己很喜歡本本——喜歡它的書香、插圖，甚至是它打開的傳送門……不過無論如何，還是讓諾拉平安回家最重要。","單位",["妖精","貓族"],["班德爾城","巨石峰"],"英雄"],"05BC078":["高壓電魚叉","棄置1張牌即可出此牌。對1個單位造成2點傷害，並對敵方主堡造成2點傷害。","","「讓他們好好見識一下！」——藍寶","法術",[],["班德爾城"],"稀有"],"05BC106":["咕嚕蟲","","","「咕嚕蟲體型嬌小，胃口卻非常大，而且『態度真的很有事』，除此之外我不知道該如何形容了。」\n——《貝殼學家生態日誌，第十七日》","單位",[],["班德爾城","比爾吉沃特"],"普通"],"05BC161":["吶兒","打擊：在手牌生成1張戳戳棍。若手牌中已有該牌，則改為使其魔耗值-2。","回合結束：本回合我方已對敵方主堡造成傷害。","很久以前，吶兒跟族人在拿可塔山谷快樂生活，蓬勃發展。當時那裡是個凡塵不染的地方，但不幸的是，時間的流逝將山谷從吶兒手中奪走了。不過幸運的是，在班德爾城，時間的流動跟外界有所不同。","單位",["約德爾人"],["班德爾城","弗雷爾卓德"],"英雄"],"05BC073":["靈巧化學家","召喚此牌時，召喚1枚土製炸彈。","","吉賽兒原本是漢默丁格教授底下最傑出的學生，但自從她聽說了希格斯在佐恩的詭異實驗後，她就一天到晚說著「海克斯爆彈怎樣怎樣」和「你可不可以幫我寫封推薦信」這些話。 ","單位",["約德爾人"],["班德爾城"],"普通"],"05BC039":["暴躁擲彈兵","效忠：召喚1個魔耗值為3以下的隨機約德爾侍從單位。","","「這邊這位愛麗絲裡面裝了兩發砲彈：一發跟你說聲嗨，一發跟你說掰掰！這位先生要賞個臉嗎？」","單位",["約德爾人"],["班德爾城"],"稀有"],"05BC148":["飆悍茄妖","召喚此牌時，若本牌局我方已對敵方主堡造成傷害4次以上，則賦予此牌衝擊4次。","","外表彈性十足，裡面卻是硬骨子。","單位",["妖精"],["班德爾城","皮爾托福&佐恩"],"普通"],"05BC119":["法師小兵","遺願：下次回合開始時，在手牌\n生成1張此牌的複製牌。","","「真正的超級壞蛋手下永遠不嫌多！矮小的傢伙越多越好！要找知道分寸、唯命是從，而且總會跑回來等待進一步命令的那種。」\n——節錄自《如何成為超級壞蛋》第二章，維迦大王著","單位",[],["班德爾城","闇影島"],"普通"],"05BC019":["彩虹魚","","","空中偵察對彩虹魚來說是前所未有的大任務，但她還是非常樂意執行。只要能夠遠離悠咪虎視眈眈的目光，即使最後難逃一死，她也在所不辭。","單位",["妖精"],["班德爾城"],"普通"],"05BC093":["維迦","召喚此牌時，若手牌中沒有黑暗，則在手牌生成1張。回合開始：賦予我方各處黑暗1點額外傷害。","我方以黑暗造成12點以上傷害。","「這個世界將會懼怕我，我將給這個世界帶來永傳後世的創傷；我的力量將令世界懾服，我的巨影將使世界瑟縮！」\n——節錄自《如何成為超級壞蛋》第一章，維迦大王著","單位",["約德爾人"],["班德爾城","闇影島"],"英雄"],"05BC007":["玩石約德爾人","","","約德爾人還搞不太懂何謂重力，不過重力也拿班德爾城沒轍就是了。","單位",["約德爾人"],["班德爾城"],"普通"],"05BC174":["友情萬歲！","本回合給予1個友軍單位光盾或法盾。","","「我一定會守護你，就用我這狂野、憤怒的……喵！」——悠咪","法術",[],["班德爾城"],"稀有"],"05BC185":["貝殼把戲","恢復我方所有法術魔力。本回合給予1個友軍單位隱密與+1|+1。","","「我親眼看見他們進去左邊的貝殼裡了！但等我選了那個貝殼，打開後卻是空的！我開始懷疑這個局是不是有詐了……」\n——《貝殼學家生態日誌，第十四日》","法術",[],["班德爾城"],"稀有"],"05BC096":["恐怖難高音","召喚此牌時，若本牌局我方已打出生成的卡牌或用法術擊殺單位，則召喚1個重砲難低音。","","如果維迦需要人幫他用魔音穿腦的方式傳揚邪惡，沒有人比這兩位更合適了。他們熟知所有相關音樂，除了用米索利地安調式寫的以外。","單位",["約德爾人"],["班德爾城","闇影島"],"稀有"],"05BC088":["藍寶","出牌：最多棄置3張牌，第1張賦予我方各處藍寶衝擊，第2張賦予快速攻擊，第3張賦予法盾。","此牌在場上時，機甲約德爾友軍單位造成12點以上傷害。","「好……沒問題了吧。」\n「發生錯誤。」\n「什麼？我才剛修好耶！」\n「系統即將發生故障。」\n「關掉！趕快關掉！」\n——藍寶與堅尼","單位",["機甲","約德爾人"],["班德爾城","諾克薩斯"],"英雄"],"05BC056":["勁風修士","召喚此牌時，在手牌生成1張雲捲式。","","「我們這個學派的技巧，都源自於控制呼吸，就如同風暴始於微風。」","單位",["約德爾人"],["班德爾城"],"稀有"],"05BC190":["競技場機甲轉播員","攻擊：本回合給予其他攻擊中友軍單位+2|+0。","","「每晚大聲吼叫播報比賽，我是怎麼保養喉嚨的？用機油漱口，早晚五分鐘。」","單位",["約德爾人"],["班德爾城","諾克薩斯"],"史詩"],"05BC042":["紫莓果昔","本回合使1個友軍單位成長到3|3。","","「我以前就跟你一樣手無縛膨菇之力，但自從我開始喝『紫莓果昔』後，一切就不一樣了！『紫莓果昔』裡面有所有必要成分，可以讓約德爾人身強體壯；辛苦健身後別忘了來杯『紫莓果昔』，你也可以搖身一變，成為跟我一樣的肌情猛男！」\n——廣告傳單","法術",[],["班德爾城"],"普通"],"05BC205":["扭曲空間","擊暈1個敵軍單位，且同時擊暈\n所有力量值為2以下的敵軍單位。","","「站好……不要亂動……」——維迦","法術",[],["班德爾城"],"普通"],"05BC223":["設陷阱","從敵方牌組的單位牌或法術牌中3選1，並在每張相同卡牌上各植入3張劇毒膨菇。","","「第986條守則：陷阱可不是玩具……但的確很好玩！」","法術",[],["班德爾城"],"稀有"],"05BC091":["競技場叫賣員","出牌：棄置1張牌以顯化1張機甲約德爾，並使其魔耗值-1。","","「門票！來買門票！現在半價喔！唉，可惡，要是不把這些票賣光，老大會殺了我……講真的。」","單位",["約德爾人"],["班德爾城"],"普通"],"05BC163":["希格斯","攻擊：對格擋此牌的單位與敵方主堡造成1點傷害。","我方摧毀4個以上友軍地標。","「我們一定要給對方一個好印象，新的安檢員要來了，\n你知道這意味著什麼吧！」\n「不能再搞爆炸了？」\n「什麼？！才不是！意思是我們要在他看不到的地方搞爆炸！竟然說『不能再搞爆炸』……你腦子也爆了是不是？！」——希格斯和奧圖的對話","單位",["約德爾人"],["班德爾城","蘇瑞瑪"],"英雄"],"05BC151":["鏡法大師","我方打出生成的侍從單位時，召喚1個該單位的複製牌。我方打出生成的法術時，對相同目標再複製一次。","","「沒錯，她的確很會變鏡子戲法。她讓我的設計看起來更上一層樓，而且只要稍微利用一點視錯覺，就可以讓某個小矮子看起來高人一等……」——浮華長袍狂","單位",["約德爾人"],["班德爾城"],"史詩"],"05BC027":["海克斯地雷帶","召喚此牌及此牌被我方摧毀時，擊暈最強敵軍單位。","","「什麼叫『這看起來不太安全』？」——希格斯","地標",[],["班德爾城"],"普通"],"05BC200":["約德爾傳送門","棄置1張牌即可出此牌。顯化1張魔耗值為3以下的約德爾牌並召喚之。","","「絕不抛下槍手！」——崔絲塔娜","法術",[],["班德爾城"],"普通"],"05BC021":["彈跳炸彈","對1個單位造成2點傷害，\n或對2個敵軍單位造成1點傷害。","","「炸彈要爆啦！」——希格斯","法術",[],["班德爾城"],"普通"],"05BC167":["班德爾突擊兵","打擊主堡：在手牌生成1張飢餓貓耳鴞。","","「白天送敵人下地獄，晚上哄孩子睡覺去！」","單位",["約德爾人"],["班德爾城"],"普通"],"05BC179":["約德爾遊俠","攻擊：賦予所有力量值不高於此牌的友軍單位+0|+1。","","「波比！我們上次想的那一招你用得棒透了！叫它『花生亂舞』如何？」\n「我，呃，只是用槌子槌了壞人而已。不能叫『巨槌』就好嗎？」\n「可是之前三招都叫這個名字！」——奇普和波比的對話","單位",["約德爾人"],["班德爾城","蒂瑪西亞"],"史詩"],"05BC214":["煉獄炸彈","對所有敵軍單位造成1點傷害，然後再重複1次。","","「把『大傢伙』……拿出來！」——希格斯","法術",[],["班德爾城"],"稀有"],"05BC221":["帽子蘑菇","召喚此牌及回合開始：本回合給予此牌額外力量值，數值等同於場上或處於附著狀態的其他妖精友軍單位的數量。","","這些小蘑菇是挺可愛的，而且懂得自我繁殖。","單位",["妖精"],["班德爾城","愛歐尼亞"],"稀有"],"05BC041":["波比","攻擊：賦予所有力量值不高於此牌的友軍單位+1|+1。","此牌與友軍單位一起攻擊3次。","謙虛是英雄的象徵，但大部分史學家都同意波比有點謙虛過頭了。","單位",["約德爾人"],["班德爾城","蒂瑪西亞"],"英雄"],"05BC176":["奇幻圖騰","賦予1個友軍單位+1|+0。對1個敵軍單位造成1點傷害。","","「好快喔！」——悠咪","法術",[],["班德爾城"],"稀有"],"05BC105":["班德爾炮手部隊","本牌局我方每召喚1個多區域友軍單位，此牌魔耗值便-1。\n召喚此牌時，賦予此牌衝擊3次。","","九條好漢在一班。","單位",["約德爾人"],["班德爾城"],"稀有"],"05BC066":["神速卷軸","","","「諾……拉……在……哪……？哎喲，我應該跟它說什麼呢？」——老鼠管家","單位",["妖精"],["班德爾城"],"普通"],"05BC177":["摺紙龍","","","「再摺一下，然後你看，這就摺成一隻長頸鹿了！牠叫『襪襪』。」\n「為什麼叫襪襪？」\n「當然是因為諾拉喜歡襪子囉！她肯定也會愛死牠！」——老鼠管家","單位",["妖精"],["班德爾城"],"史詩"],"05BC136":["廢物利用","棄置1張牌即可出此牌。\n顯化1張機甲約德爾。","","「垃圾、廢物、破東西……嘿，這才像話嘛！」——藍寶","法術",[],["班德爾城"],"普通"],"05BC164":["劇毒吹箭","對任1目標造成1點傷害，並將3張劇毒膨菇植入敵方牌組。","","「哈哈！正中紅心！」——提摩","法術",[],["班德爾城"],"普通"],"05BC194":["班德爾神木","回合開始：先在手牌生成1張新區域的侍從單位。接著，此牌在場上時，若我方打出或召喚10個區域的單位，則贏下牌局。","","高聳入雲的班德爾神木是位於市中心的奇觀。有些約德爾人從它虯結雜錯的枝幹中看到了希望與友誼，但這棵樹在其他人眼中卻是一棵充滿謎團的不祥巨木。不過所有人都一致認同，從這棵樹中可以看到某種遠古而強大的靈魂。","地標",[],["班德爾城"],"史詩"],"05BC127":["沉默風暴莉蘇","召喚此牌時，召喚1朵雷雨雲。","","製造雷雨雲需要時間，而莉蘇最缺的就是時間。她的雙手動作飛快，而異種步步進逼。這裡加點雲，那裡加點閃電，然後……劈啪！碰！她成功了，但是這樣夠嗎？","單位",["約德爾人"],["班德爾城"],"史詩"],"05BC216":["約德爾怪裝置","摧毀1個地標或在手牌隨機生成2張多區域侍從單位。","","「撐著點，我們滾在路上了！」——爆力拍檔","法術",[],["班德爾城"],"普通"],"05BC212":["安檢員","回合開始：在手牌生成1張安檢合格！","","威佛原本心存懷疑，到中途他也還在懷疑，老實說他直到最後都還在懷疑——但希格斯和其他魔法爆破專家證明了他們知道怎麼策劃一場美麗的煙火秀。 ","單位",["約德爾人"],["班德爾城"],"稀有"],"05BC141":["英雄讚歌","本回合給予2個友軍單位+2|+1。","","「英雄們堅守陣地，背對背——」\n「屁股對屁股！嘿嘿嘿！」\n「不！佩比，你要插嘴的話，拜托別選這種高潮時刻！」\n——約德爾營火故事","法術",[],["班德爾城"],"普通"],"05BC209":["抗壓防禦","本回合將1個單位的能力值設為1|6。","","咕咕鳥在正常情況下是忠心穩重的坐騎，不過牠們壓力太大的話就會……做出很奇怪的反應。","法術",[],["班德爾城"],"普通"],"05BC210":["火焰噴射器","賦予1個友軍單位+2|+0與衝擊。","","「沒叫出聲就是還不夠燙！嘿嘿。」——藍寶","法術",[],["班德爾城"],"普通"],"05BC013":["頑皮觸手","使對手棄置魔耗值最低的手牌。","","「提醒自己：下次出來考察記得把貴重物品放在胸前口袋裡。」——《貝殼學家生態日誌，第十九日》","法術",[],["班德爾城"],"普通"],"05BC100":["膨菇小狗","打擊：將3張劇毒膨菇植入敵方牌組。","","「小子，你說什麼？兩個新人在森林裡探路的時候遇到了可怕的草叢怪物，現在可能要被慢慢折磨到死了？快帶路吧！」——提摩","單位",["犬族"],["班德爾城"],"普通"],"05BC098":["邪惡助長者","打擊：賦予我方各處黑暗1點額外傷害。","","黑暗各種大小形狀都有，有些還可愛到嚇死人。","單位",["約德爾人"],["班德爾城"],"普通"],"05BC122":["約德爾新兵","我方召喚其他約德爾單位時，本回合給予此牌+2|+0。","","「巨草怪是一種可怕的生物，牠們會偽裝成一般的雜草，然後攻擊踩到牠們的倒楣鬼。遇到的話，拔腿快逃！」——優等生艾娃","單位",["約德爾人"],["班德爾城"],"普通"],"05BC120":["約德爾隊長","我方召喚其他力量值不高於此牌的單位時，賦予其+1|+1。","","「冒險的意義就是尋找壞蛋，再把他們變成朋友！」","單位",["約德爾人"],["班德爾城"],"普通"],"05BC046":["震雷之拳","召喚此牌時，若本牌局我方已召喚震雷之拳，則將此牌幻化為粉碎震雷瑪沙。","","瑪沙攻擊訓練假人，一道閃電從拳頭迸發，把木頭劈成兩半，也燒焦了他雙手的毛髮。他拉著繩子，把銅手收捲回來，回想自己受過的訓練。他終於準備好了。突然間，一聲恐怖的怒吼在遠方迴盪。","單位",["約德爾人"],["班德爾城"],"普通"],"05BC018":["浮誇騎士","","","「九百九十八……九百九十九……一千！好了，巴奇，你看起來無懈可擊，接著換我了！」","單位",["約德爾人"],["班德爾城","蒂瑪西亞"],"稀有"],"05BC132":["毀滅射擊","若我方場上有崔絲塔娜或本牌局已打出4個不同區域的卡牌，則此牌魔耗值-2。\n對1個單位造成3點傷害。","","每場爆炸都必將伴隨著更多的爆炸。","法術",[],["班德爾城"],"普通"],"05BC168":["班點蛤蟆","回合結束：若本回合我方已對敵方主堡造成傷害，則將此牌幻化為巨型啾吉。","","住在拿可塔山谷的約德爾人花了幾個世代的時間，嘗試了解他們的啾吉鄰居。首先，赫加波酋長嘗試用棍子戳牠們，接著，巴波布酋長也嘗試用棍子戳牠們。最後，拿可塔酋長想出一個似曾相識的新點子：用棍子戳牠們。","單位",[],["班德爾城"],"稀有"],"05BC014":["小翼獸","回合結束：若本回合我方已對敵方主堡造成傷害，則將此牌幻化為恐怖翼獸。","","拿可塔山谷裡的生物猶如其棲身之地一樣，五花八門且充滿活力……也同樣容易爆發。","單位",["鳥族"],["班德爾城"],"普通"],"05BC138":["修理鼠","我方首次棄置卡牌或對敵方主堡造成傷害時，賦予此牌+2|+1。","","「打得好，各位，表現很精彩。好了，把這裡清一清，規矩都知道吧：只要是有價值的東西就修理一下，放進商店裡，倒賣回去給他們！啊哈哈哈！」——競技場老闆卡爾","單位",[],["班德爾城"],"普通"],"05BC198":["團體照","對1個單位造成1點傷害。\n若我方場上有4個以上友軍單位，\n則改為造成2點傷害。","","「好了，這張是要放在通訊報上的，這次別忘了微笑！\n一……二……三……！」——崔絲塔娜\n","法術",[],["班德爾城"],"普通"],"05BC181":["雲捲式","本回合給予1個友軍單位+2|+0與「回合結束：召回此牌」。","","「注意力回到呼吸上，找到自己的力量！」——勁風修士","法術",[],["班德爾城"],"普通"],"05BC160":["原始普羅","","","原始時代的普羅相比現在頭殼更加厚重，雖然讓牠們笨了點，但撞起人來也更有力。","單位",["普羅"],["班德爾城","弗雷爾卓德"],"普通"],"05BC005":["海藻少女","打擊主堡：在手牌生成1張惡搞。","","「親愛的我自己，我剛做了一個有史以來最怪的夢。我在海藻叢中找我的貝殼帽，然後突然聽到美麗動聽的歌聲，等我回過神來我就坐在這裡，握著筆寫日誌了。我不記得我有坐下來睡午覺啊……」\n——《貝殼學家生態日誌，第二十二日》","單位",[],["班德爾城"],"稀有"],"05BC020":["圖書舘助理","打擊主堡：抽出1張魔耗值為3以下的法術牌。","","「凍凍是我最要好的朋友！當然是繼你和諾拉之後啦，本本。那麼讓我糾正一下：『凍凍是我第三要好的朋友』，還算不錯吧，對嗎？！」——悠咪","單位",["妖精"],["班德爾城"],"普通"],"05BC049":["貝殼學家","出牌：顯化1張魔耗值為3以下、我方區域的法術牌。","","「今天可真是個大好日子！可以去深海探險了！我相信這場探險對我勢必是……如魚得水！呵呵！」\n——《貝殼學家生態日誌，第一日》","單位",["約德爾人"],["班德爾城"],"稀有"],"05BC001":["縮小術","將1個單位幻化為3|3迷你海獸，並沉默該單位。","","「喔吼！多可愛！多玲瓏！多小巧！」——維迦","法術",[],["班德爾城"],"稀有"],"05BC026":["神奇祕道","在本牌局中，若我方已生成2張以上卡牌，則此牌魔耗值-2。抽2張牌。","","很少外人知道班德爾城要怎麼去；但對於知情者來說，符文大地的草木樹石上刻著的古怪記號，都是他們尋路的線索。","法術",[],["班德爾城"],"普通"],"05BC152":["失興旅人","召喚此牌時，雙方各抽1張牌，然後使對手棄置魔耗值最高的手牌。","","「史，上，最，爛，旅，行。」——艾莉","單位",["約德爾人"],["班德爾城","皮爾托福&佐恩"],"普通"],"05BC070":["優等生艾娃","召喚此牌及回合結束：將3張劇毒膨菇植入敵方牌組。\n使敵方牌組的陷阱發動2次。","","「第378條守則：優秀的斥候隨時都要拿出勇氣、做好準備、不畏冒險！」","單位",["約德爾人"],["班德爾城"],"史詩"],"05BC015":["小蜥蜴","回合結束：若本回合我方已對敵方主堡造成傷害，則將此牌幻化為熔岩蜥蜴。","","「把火椒吃掉！」拿可塔大喊道。「不要，你才把火椒吃掉！」喬喬回答道。其實沒人知道他們在說什麼，但應該跟火椒有關。就在這時，一隻小蜥蜴追著一隻更小的蒼蠅爬過。那兩個約德爾人看著那隻蜥蜴，看看火椒，然後四目相接。如果這個世界有燈泡的話，那他們頭上肯定會靈光一現那樣亮起一顆。","單位",["爬蟲族"],["班德爾城"],"普通"],"05BC145":["約德爾隨從","出牌：在手牌生成1張小小矛或小小盾。","","「我的矛曾經也屬於一位英雄……我請波比幫我拿了一下！」","單位",["約德爾人"],["班德爾城"],"普通"],"05BC140":["普羅雪橇","攻擊：隨機召喚1個魔耗值為1、攻擊中的普羅。","","「然後辣個叫波金的普羅就一副『往辣邊走！』的樣子，然後就往地平線的另一端衝過去惹，其他的普羅在後面跳呀跳的死命要跟上！」——少女英格娃","單位",["普羅"],["班德爾城","弗雷爾卓德"],"史詩"],"05BC129":["競技場老闆","","","「每分鐘都有個新的遜咖誕生，而我要狠狠敲他們一筆……這機器競技場肯定會讓我發大財！」","單位",["約德爾人"],["班德爾城","諾克薩斯"],"普通"],"05BC004":["八爪水獺","召喚此牌時，在手牌生成1張惡搞。","","「八爪水獺是一種好奇心旺盛，愛玩又活潑的生物；牠們算水獺還是章魚？是說，我不是帶了三個三明治嗎？」\n——《貝殼學家生態日誌，第七日》","單位",[],["班德爾城"],"普通"],"05BC155":["火焰修士","我方召喚其他單位時，賦予此牌+1|+0。","","「小火花匯聚成熊熊烈焰。我們是即將摧毀你的\n毀滅之火！」","單位",["約德爾人"],["班德爾城"],"稀有"],"05BC104":["原初力量","賦予1個友軍單位+2|+2與衝擊。","","他的確很可愛，但脾氣也很壞，最好還是不要見識到。","法術",[],["班德爾城"],"普通"],"05BC218":["妖精援助","在手牌生成1張飢餓貓耳鴞，然後賦予我方手牌中的所有妖精單位+1|+1。","","「是誰在餵這些東西？」——波比","法術",[],["班德爾城"],"稀有"],"05BC192":["爆力拍檔","召喚此牌時，在手牌隨機生成1張魔耗值為2以下的地標。","","「橫衝直撞轟地機X」完美達成了它的目標：散布混亂，而且它的設計要路邊停車根本小事一樁。 ","單位",["約德爾人"],["班德爾城","蘇瑞瑪"],"普通"],"05BC162":["拿可塔酋長","友軍單位幻化時，治癒該牌並賦予其+1|+1與衝擊。","","拿可塔在隨處可見的雪磧中找到一塊巨型恐龍骨後，就自立為酋長。除他以外，沒有人知道恐龍骨是酋長身分的證明，不過大家也都無所謂，所以拿可塔就這樣當上酋長了。","單位",["約德爾人"],["班德爾城"],"稀有"],"05BC032":["藍色小鬼火","每回合我方打出的第1個妖精單位魔耗值-2。","","「燐燐跟著諾拉走，月蛾跟著燐燐走，老鼠跟著月蛾走！大家一起跟著走！」","單位",["妖精"],["班德爾城"],"稀有"],"05BC166":["戳戳棍","對任1目標造成1點傷害。抽1張牌。","","實驗守則第一條：戳戳看，然後觀察會發生什麼事。","法術",[],["班德爾城"],"普通"],"05BC006":["軍火庫管理員","召喚此牌時，本牌局我方每摧毀1個友軍地標，便賦予此牌1項隨機特性。\n我方摧毀友軍地標時，賦予此牌1項隨機特性。","","不管希格斯去哪裡，阿尼總是如影隨形，他的沉靜更加彰顯了希格斯的瘋狂熱情。他的工作包山包海，不只要管理武器、幫忙滅火，還要在希格斯忘了戴耳罩隔音的時候，趕緊幫他摀住耳朵，而且他老是忘記。 ","單位",["約德爾人"],["班德爾城"],"史詩"],"05BC110":["登山學者","","","「是是是，你跟我講過很多遍她喜歡茶、襪子、紐扣、你，還有收集小東西，不過到現在你還沒跟我講她長什麼樣子！」 ","單位",["約德爾人"],["班德爾城","巨石峰"],"普通"],"05BC063":["旋風戰士","召喚此牌時，賦予此牌+1|+0與1項隨機特性。此牌被召回時，數值增益與特性都會保留。","","旋風為了保持冷靜，不斷調整呼吸……並將她內心的混亂轉化為兇殘的刃風。 ","單位",["約德爾人"],["班德爾城"],"普通"],"05BC217":["茄妖幼苗","顯化1個妖精單位，並賦予其+1|+1。","","任何生物都需要營養，妖精也不例外，不過不太清楚牠們是怎樣吸收的。","法術",[],["班德爾城"],"稀有"],"05BC180":["加速","召回1個力量值為3以下的單位。","","「我們速度很快！我們就是風！」——凱能","法術",[],["班德爾城"],"普通"],"05BC040":["以物易物","顯化1張八爪水獺或2張魔耗值為3以下、我方區域法術牌的其中1張。","","「立刻放下我的三明治！」——貝殼學家","法術",[],["班德爾城"],"稀有"],"05BC213":["原始衝撞","對1個敵軍單位造成1點傷害並擊暈之。","","「Ahanga！」——吶兒","法術",[],["班德爾城"],"普通"],"05BC208":["英勇衝鋒","使1個友軍單位打擊1個敵軍單位，若其未陣亡，則擊暈之。","","「讓開！」——波比","法術",[],["班德爾城"],"稀有"],"05BC085":["淘氣海賊鼠","出牌：棄置1張牌以顯化1張機甲約德爾，並賦予其法盾。","","「小聲點，行嗎？我都聽不到我自己數錢的聲音了！」——競技場老闆卡爾","單位",["約德爾人"],["班德爾城"],"稀有"],"05BC112":["爆破毬果幼苗","出牌：賦予此牌衝擊，或本回合給予此牌光盾。","","爆破毬果幼苗是一種害羞的生物，它們通常是走為上策，不過當感到威脅時……","單位",["妖精"],["班德爾城","愛歐尼亞"],"普通"],"05BC135":["雙重射擊","使1個友軍單位打擊1個敵軍單位。若該友軍單位為多區域單位，則再打擊1次。","","「M1-85橡果式步槍是一把搭載班德爾木瞄準鏡的紫莓色橡木槍身全自動步槍。沒錯，今晚有好料了！」——班德爾突擊兵","法術",[],["班德爾城"],"普通"],"05BC084":["尖嗓明星鼠","出牌：棄置1張牌以顯化1張機甲約德爾。","","雖然個子小，但個性倒是挺大牌的。","單位",[],["班德爾城"],"普通"],"05BC184":["唱蝦毀吟遊組合","召喚此牌時，在手牌生成1張飢餓貓耳鴞。","","「這是一首關於強者波比的歌！\n威武波比、兇猛……猛將！」\n——節錄自《非凡吟遊詩人雷吉納戴克托與法爾第密斯奇之歌曲集》，這一段歌詞被上了刪除線","單位",["約德爾人"],["班德爾城"],"普通"],"05BC116":["班德爾城市長","每回合我方打出的第1個多區域單位魔耗值-1。出牌：顯化1個多區域侍從單位。","","雖然不知道班德爾城到底有沒有選過市長，但要真有的話，看來留一臉大鬍子肯定是參選條件之一。","單位",["約德爾人"],["班德爾城"],"史詩"],"05BC111":["約德爾出征 ","本回合給予所有友軍單位+2|+2。若我方已打出4個不同區域的卡牌，則改為給予所有友軍單位+3|+3。","","「我們……看起來有夠酷。」——崔絲塔娜","法術",[],["班德爾城"],"稀有"],"05BC224":["瞬間轉移","召回1個友軍單位，本回合打出下一個魔耗值不高於該牌的友軍單位時無需消耗魔力。","","「身軀之速，即心靈之速！」——凱能","法術",[],["班德爾城"],"稀有"],"05BC130":["燒烤狂人","攻擊：賦予我方牌組最上方的英雄+1|+1與1項隨機特性。","","奧圖舉辦的夏日燒烤大會小有名氣。雖然他對燒烤充滿熱情，但他煎的牛排不是「十分熟」，就是「十二分熟」。","單位",["約德爾人"],["班德爾城","蘇瑞瑪"],"普通"],"05BC191":["守護者裁決","將1個敵軍單位放回敵方牌組最上方。","","「不要再回來了！」——波比","法術",[],["班德爾城"],"稀有"],"05BC052":["珍貴垃圾","將我方手牌補滿魔耗值為0的隨機飛逝卡牌。本回合我方只能再打出3張牌。","","一個人的垃圾是另一個約德爾人的超大堆破銅爛鐵。\n","法術",[],["班德爾城"],"稀有"],"05BC050":["溫柔海葵","召喚此牌時，在手牌生成2張惡搞。","","「容易暈船的人如果要接觸這溫柔的龐然大物務必小心再小心，你的五臟六腑會感謝你的……話說回來，我不該吃掉兩個蘑菇三明治的……」\n——《貝殼學家生態日誌，第三日》","單位",[],["班德爾城"],"普通"],"05BC094":["闇燈泡隨侍","召喚此牌時，若手牌中沒有黑暗，則在手牌生成1張。","","「是，我知道那個天花板上的傢伙有很多話要說，大家都知道他有講不完的故事，我們只是完完全全搞不懂他到底說的是哪國語言而已。」——浮華長袍狂","單位",["約德爾人"],["班德爾城"],"普通"],"05BC146":["班德爾畫家","出牌：棄置1張牌以在手牌生成1張多區域侍從單位，並使其魔耗值-1。","","「繪畫不是複製你眼前所見，而是詮釋你眼中的世界！我看你好像又動了喔，請別亂動！」","單位",["約德爾人"],["班德爾城","皮爾托福&佐恩"],"普通"],"05BC235":["約德爾鐵匠","攻擊：本回合給予所有力量值不高於此牌的友軍單位快速攻擊。","","「我說的話波比從來不聽，所以你最好別跟她一樣：槌子不是重點，重點是哪個約德爾人去揮它。」\n","單位",["約德爾人"],["班德爾城"],"普通"],"05BC175":["行走望遠鏡","出牌：顯化1張魔耗值為3以下的天界牌、1張史詩牌或1張多區域侍從單位。","","最詭異的不是望遠鏡起來伸了懶腰然後開始四處走動，而是它堅持要穿得暖一點，所以它得找一條合身又舒適的圍巾給自己圍。","單位",["妖精"],["班德爾城","巨石峰"],"稀有"],"05BC182":["閃電衝擊","召回1個友軍單位以對任1目標造成2點傷害。","","「首先是裂響，接著就是爆炸！」——凱能","法術",["元素"],["班德爾城"],"稀有"],"05BC069":["約德爾說教魔人","攻擊：在手牌生成1張飛逝劇毒吹箭。","","別逼他開始說教。","單位",["約德爾人"],["班德爾城"],"稀有"],"05BC057":["浮華長袍狂","召喚此牌時，使我方各處黑暗魔耗值-1。","","「要成立祕密組織時，最重要的一點就是每個瘋狂成員都要有獨特的超級壞蛋特色。舉例來說，我有一個部下的時尚風格就殺到不行……」\n——節錄自《如何成為超級壞蛋》第四章，維迦大王著","單位",["約德爾人"],["班德爾城"],"稀有"],"05BC108":["約德爾探險家","我方召喚其他約德爾單位時，賦予其+1|+0。","","「探險的榮耀無法用利益衡量，但最偉大的發現通常……很有利可圖，咳嗯。」","單位",["約德爾人"],["班德爾城"],"普通"],"05BC183":["妖精爺爺","召喚此牌時，在手牌生成1張飢餓貓耳鴞。\n我方召喚其他妖精單位時，賦予其+1|+0。","","「快過來坐下聽好，\n我要講妖精爺爺的悲傷故事了。\n每天他都會用摻雜種子的奇怪凝乳，\n來餵肚子餓的小鳥……」\n——班德爾城怪談","單位",["妖精"],["班德爾城","愛歐尼亞"],"稀有"],"05BC188":["好奇貝殼人","我方挑選非英雄隨機卡牌時，在手牌生成1張該牌的複製牌，並使其魔耗值-1。","","以害羞聞名的貝殼人善於躲藏，他們會躲在貝殼裡，直到按捺不住好奇心。一探出頭來，他們愛玩的本性就會顯露無遺，用高超的技巧模仿其他海底生物的叫聲，也是他們的習性與把戲之一。","單位",[],["班德爾城"],"史詩"],"05FR001":["魔狼族薩滿","回合結束：若本回合我方已對敵方主堡造成傷害，則將此牌幻化為魔狼族怒靈。","","「我們不會死得像懦夫一樣！我們會亮出利爪，露出獠牙，如此才能帶給魔狼神榮耀。」——全知希亞拉","單位",[],["弗雷爾卓德"],"普通"],"05FR002":["猛瑪象族薩滿","回合結束：若本回合我方已對敵方主堡造成傷害，則將此牌幻化為猛瑪象族怒靈。","","遇到捕食者時，猛瑪象獸群會包圍住幼象和懷孕的母象。正是因為這點，偉大猛瑪象獸靈的薩滿呼喚的不只是牠們強大的力量，還有牠們為了守護家人而發揮出的團結之力。","單位",[],["弗雷爾卓德"],"稀有"],"05FR013":["烏迪爾","召喚此牌時及打擊：在手牌生成\n1張四形之喚，若手牌中已有該牌，\n則改為使其魔耗值變為0。","我方打出四形之喚3次以上。","「獸靈塑造我們的世界，就如同我們及我們的世界塑造獸靈一樣。從祂們身上汲取力量便是引出我們內在的力量。」","單位",[],["弗雷爾卓德"],"英雄"],"05FR016":["薩滿呼喚","在手牌生成2張魔耗值為0的飛逝四形之喚。","","「你會看見祂們的……擁有尖牙與利爪、鱗片和羽毛的偉大獸靈。在那一刻，你便會因恐懼及敬畏而顫抖，並了解古老神祇並沒有遺忘我們。」——全知希亞拉","法術",[],["弗雷爾卓德"],"普通"],"05FR012":["全知希亞拉","召喚此牌時，在手牌生成\n1張四形之喚。每回合我方打出的第1張四形之喚魔耗值為0。","","全知希亞拉是受眾人景仰的偉大薩滿。她很久以前失去了視力，現在透過在她山頂住居附近的鷹與鵰來看世界。預見了可怕的消息後，她便動身下山……希望這些凶兆只是單純的幻象而已。","單位",[],["弗雷爾卓德"],"稀有"],"05FR014":["弗雷爾卓德之怒","出牌：凍傷1個敵軍單位。\n力量值為3以下的敵軍單位無法進行格擋。","","「多年以前，我就在現場……首先是刺骨無情的寒冷，接著是凶猛無情的風暴，最後是一聲巨吼，如此尖銳，深入骨髓。我跪了下來，祈禱我們沒有釀下大錯。呼喚獸靈便要請其發揮復仇心……以及慈悲心。」——全知希亞拉 ","單位",[],["弗雷爾卓德"],"史詩"],"05FR017":["內在野性","本回合給予1個友軍單位+1|+1。\n在手牌生成1張四形之喚。","","「眾獸靈，請回應我的召喚……」——烏迪爾","法術",[],["弗雷爾卓德"],"普通"],"05FR006":["海象牙語者","出牌：對雙方主堡造成1點傷害。","","很少薩滿家族服務冬之爪部族的時間有像丘盧恩家那麼長的。身為巨大海象的薩滿，他能預測海洋何時會帶來獎賞……或是危險。 ","單位",[],["弗雷爾卓德"],"普通"],"05FR015":["釋放獸靈","賦予各處友軍單位+1|+1，然後對所有目標造成1點傷害。","","「遠古獸靈啊，請賜予我們抵禦嚴寒的力量，並用冰雪風暴驅趕我們的敵人。我們並未忘記您，以及屬於您的榮耀。」\n——魔狼族薩滿的禱詞","法術",[],["弗雷爾卓德"],"稀有"],"05FR005":["靈骨占術師","此牌承受傷害且未陣亡時，對敵方主堡造成1點傷害。","","很少人能像侍奉骨鹿神的薩滿那樣擅長占卜未來，更少人能夠忍受看見前來占卜的人死期將至。","單位",[],["弗雷爾卓德"],"普通"],"05FR004":["靈狐漫遊者","召喚此牌時，在手牌生成1張四形之喚。","","「積極但謹慎，迅速卻安靜；狐狸的生存之道便是看見但不被看見。無論是旅行還是打仗，明智的領導者會懂得尊重追隨靈狐之人，因為沒有尋路人或偵察兵，就贏不了任何戰鬥。」——戰痕之母芙蕊娜","單位",[],["弗雷爾卓德"],"普通"],"05IO003":["無徑古猿","本回合每召回1個單位，此牌魔耗值便-2。","","「希夢許，很榮幸能和你一起旅行。其他人告訴我你智慧無邊。我們現在是要去哪裡？」\n「喔，呃，我只是跟著你走而已！」——阿璃與無徑古猿","單位",[],["愛歐尼亞"],"普通"],"05IO004":["阿璃","攻擊：此牌首次進行攻擊打擊時，將此牌與右側的友軍單位調換位置，並召回該單位。","我方召回5個以上單位。","她從他人的祕密中找尋自己，透過許多人的眼睛看見自己。她走近森林，想知道這次遇到的是否又會是他人之眼，或許這一次，她能遇到一面鏡子。","單位",[],["愛歐尼亞"],"英雄"],"05IO023":["魅惑","召回1個友軍單位，以在本回合給予1個敵軍單位弱勢。","","「跟我說個祕密。」——阿璃","法術",[],["愛歐尼亞"],"普通"],"05IO020":["風吟鳥人","出牌：召回1個單位。","","混亂給予溫馴者利爪。狼追捕獵物，卻被落下的粗樹枝擋住去路。突來一陣強風，使向獵物俯衝的老鷹被吹得暈頭轉向。我們就是那樹枝。我們就是那強風。","單位",[],["愛歐尼亞"],"普通"],"05IO007":["千尾賽南","召喚此牌時抽2張牌，且本回合給予所有友軍單位+1|+1。","","森林不吝於分享祕密……但少有勇者敢於提問。","單位",[],["愛歐尼亞"],"史詩"],"05IO021":["神之柳樹幼苗","出牌：召回1個友軍單位以召喚1個閃靈複製單位。\n倒數3：再召喚1個該單位的閃靈複製單位。","","從前，神之柳樹生長在歐米迦亞蘭境內。現在，從那個地方萌發的東西可能更強大，也可能更弱小。重要的是，那是新生之物。","地標",[],["愛歐尼亞"],"稀有"],"05IO024":["森林之子","召回1個友軍單位或消耗8點魔力，以召喚我方在本牌局中召回的3個最強侍從單位之閃靈複製單位。","","回憶帶有傷人的獠牙。","法術",[],["愛歐尼亞"],"史詩"],"05IO001":["鹿角兔","召喚此牌時，本回合給予此牌+1|+0與隱密。","","「大家都說你不講話是因為不想讓其他人受你淵博的知識所苦。嗯……我賭你八成只是懶得回答而已。」——阿璃","單位",[],["愛歐尼亞"],"普通"],"05IO025":["尾袍女族長","每回合我方首次召回侍從單位時，召喚1個該單位的閃靈複製單位。","","謎底揭曉，神祕猶存。","單位",[],["愛歐尼亞"],"稀有"],"05IO026":["森之殤","打擊主堡：召回此牌。","","如果對狩獵懷有崇敬之心，就應該停下來為獵物默哀。","單位",[],["愛歐尼亞"],"稀有"],"05IO006":["九命","召喚1名限界守護者。","","森林需要守護者，需要有個哨兵時時守護邊界，經歷數年、數百年都不離開。蓋許積極自願擔任這項職責，而且他在原地一打瞌睡就過了十年，立刻證實自己確實有為這份工作奉獻的決心。","法術",[],["愛歐尼亞"],"史詩"],"05IO002":["記憶鱗甲","挑選1個友軍單位，抵銷所有以其為目標的敵方單體快速法術、慢速法術與技能。","","箭矢不會知道獵人的意圖或獵物的價值。","法術",[],["愛歐尼亞"],"普通"],"05SH014":["齊勒斯","我方摧毀友軍地標時，對最弱\n敵軍單位造成1點傷害。","我方摧毀4個以上友軍地標。","「原本就是好友的兩人，隨著時間過去變得如膠似漆、情同手足。若沒有齊勒斯常伴左右，阿祈爾絕不可能達成他所有的成就。」\n——《飛昇戰士團史》，書吏卡尼爾著","單位",["飛昇者"],["蘇瑞瑪"],"英雄"],"05SH017":["遠古魔導宣使","召喚此牌時，若我方已摧毀4個以上友軍地標，則賦予我方各處英雄+2|+2與蠻力。","","宣使張開雙臂，仰臉望向懸掛在蘇瑞瑪上方的血紅太陽。「遠古魔導萬歲。」她歡呼讚嘆，因狂喜而顫抖的聲音在環狀的殘破柱子之間迴盪。「齊勒斯萬歲！」","單位",[],["蘇瑞瑪"],"稀有"],"05SH011":["無盡虔徒","遺願：召喚1個尊貴華棺。","","陵墓內部的裝飾再怎麼華麗，都對遭到放逐之人和其中的死者毫無用處。","單位",[],["蘇瑞瑪"],"稀有"],"05SH022":["沙漠決鬥","本回合給予1個敵軍單位-2|-0。使1個友軍單位與該敵軍單位互相打擊。","","「不懂得懼怕沙漠的旅人，根本不懂沙漠。」\n——蘇瑞瑪諺語","法術",[],["蘇瑞瑪"],"普通"],"05SH003":["力量方尖碑","倒數3、召喚此牌或此牌被我方摧毀時：賦予最強友軍單位+2|+0。","","閃閃方光、劈啪作響的石碑從沙海中升抬而起，這些毀壞的力量之地將能進一步強化齊勒斯本就強大的軍隊。","地標",[],["蘇瑞瑪"],"普通"],"05SH016":["毀滅侍者","出牌：摧毀1個我方地標，以賦予我方各處毀滅侍者+1|+1。","","每一名效忠齊勒斯的侍者為了獲得力量，都犧牲了自己的某一部分。而這些侍者當中最強大、最忠心的門徒，原本的人性早已所剩無幾，他們的軀殼成了新帝王能量的導體，也是他力量的來源。","單位",[],["蘇瑞瑪"],"普通"],"05SH018":["荒涼奴役","召喚1個凝滯雕像，將本回合所有陣亡的友軍單位及被摧毀的地標保存在內。","","魔法能量不會消散無蹤，只是轉換用途而已。","法術",[],["蘇瑞瑪"],"史詩"],"05SH012":["升抬祭壇","倒數3或此牌被我方摧毀時：召喚1名無縛者達米因。","","「在每一處力量之地都將有方尖碑聳立，遠古魔導將藉此汲取沙漠之下的力量。」——遠古魔導宣使","地標",[],["蘇瑞瑪"],"史詩"],"05SH020":["荒涼造物","在手牌生成1張毀滅侍者或力量方尖碑。","","「我必照我的形象重塑蘇瑞瑪。」——齊勒斯","法術",[],["蘇瑞瑪"],"普通"],"05SH015":["沙視者","召喚此牌時，抽1張牌。若我方抽到地標，則重複此效果。","","望向眼前遼闊無邊的沙漠，她看見了豐沛的能量在奔騰跳躍。凡人眼中只有大片黃沙，她卻看見了耀眼奪目的網格和線條，沙地中蘊含的純粹能量，只等她收為己有。","單位",[],["蘇瑞瑪"],"史詩"],"05SH004":["爆能釋放","本回合給予1個友軍單位+2|+1，或摧毀1個我方地標以在本回合給予1個友軍單位+4|+2。","","「我將伸手奪走沙漠的力量，摧毀所有膽敢違逆我的人！」——齊勒斯","法術",[],["蘇瑞瑪"],"普通"],"05SH002":["荒行者","我方摧毀友軍地標時，賦予此牌+1|+1。","","這些侍者前來尋找齊勒斯之前本就十分強大，現在更研讀了齊勒斯自己曾鑽研的奧祕，變得無人能擋。","單位",[],["蘇瑞瑪"],"普通"],"05SH007":["魔導祭典","摧毀1個我方地標或魔力寶石，\n以對1個單位造成4點傷害。","","「用微小的犧牲，換取極大的力量。」——齊勒斯","法術",[],["蘇瑞瑪"],"稀有"],"05NX009":["失喪亡魂","召喚或棄置此牌時，在手牌生成1張雙刃亡靈。","","蒂瑪西亞人連滾帶爬回哨站，打算死守基地，卻只能眼睜睜看著死亡的化身朝他們襲來。雖然他們殺死了不少灰暗軍團的士兵，但仍無力抵擋戰爭的洶湧暗潮。","單位",[],["諾克薩斯"],"史詩"],"05NX006":["重生擲彈兵","棄置1張牌即可出此牌。\n棄置此牌時，召喚1個此牌的複製單位。","","「我們當中出現了特例。我們復活的人大都極其厭惡重返世間，但這傢伙不僅了解自己的處境，也非常享受隨之而來的契機，真是有趣極了。」\n——艾斯林傑醫生的筆記","單位",[],["諾克薩斯"],"普通"],"05NX005":["遠古好戰者","棄置此牌時，賦予最強友軍單位+2|+0。","","隨著諾拉迪夫人的力量越來越強，她不禁想知道自己的力量是否能復甦諾克薩斯古老墳墓中的那些屍體。她發現在那些軀殼之中，生命的亮光宛如風中殘燭，但戰爭的陰影仍然在微弱的火光下幢幢舞動。","單位",[],["諾克薩斯"],"稀有"],"05NX001":["賽恩","棄置此牌時，賦予最強友軍單位蠻力，並將此牌洗入我方牌組。\n本牌局我方每棄置1張牌，則此牌獲得+1|+0（最多+7|+0）。","我方棄置或召喚單位的力量值總和為35以上。","賽恩腦中浮現了許多模糊的記憶，一閃即逝。佇立在他身前的威武大軍、授勳典禮、王冠、戰爭、一名國王垂死的掙扎、無盡虛無、鮮血。但這些畫面才剛襲來就已消散，猶如蒼白慘澹的絲帶隨風飛逝。","單位",[],["諾克薩斯"],"英雄"],"05NX003":["復活手術","棄置1張牌即可出此牌。\n召喚1名重生擲彈兵，且本回合給予其+2|+0。","","「重新站起來吧，我的孩子……」\n——憂鬱的艾斯林傑醫生","法術",[],["諾克薩斯"],"稀有"],"05NX015":["陣亡角鬥士","召喚此牌時，賦予最弱敵軍\n單位無法進行格擋。\n遺願：在手牌生成\n1張重生角鬥士。","","「我復活的第一批牛頭怪只是一群溫順無用的野獸。不論是戰爭的廝殺聲還是死亡的威脅都沒辦法喚醒牠們的鬥志。」\n——艾斯林傑醫生的筆記","單位",[],["諾克薩斯"],"稀有"],"05NX019":["為了榮耀！","名望：此牌魔耗值-3。召喚2名特菲利安求譽者。","","追求榮耀的人總不惜一切代價。","法術",[],["諾克薩斯"],"稀有"],"05NX013":["陣亡騎兵","棄置此牌時，在手牌生成1張重生騎兵。","","「我用黯影草塗抹騎兵的盔甲，凶暴的巨異蜥才不再對他們抱有敵意。這種藥草和這些野獸一樣生長於這片腹地，氣味濃烈、毒性剛猛。」\n——艾斯林傑醫生的筆記","單位",[],["諾克薩斯"],"普通"],"05NX012":["殺戮怒吼","棄置1張牌即可出此牌。\n擊殺最弱敵軍單位。","","「是敵，是友……都一樣。」——賽恩","法術",[],["諾克薩斯"],"普通"],"05NX014":["亡者武器","對1個單位造成3點傷害，並召喚1名特菲利安破盾兵。","","「破盾兵！」——賽恩","法術",[],["諾克薩斯"],"普通"],"05NX004":["陰鬱醫師","出牌：棄置1張牌以抽1張單位牌。","","艾斯林傑醫生曾是一名受人敬重的外科醫生，即將退休的他已行醫多年，總是盡心盡力，為自己累積了無懈可擊的好名聲。但有一天，一名年輕貴族女性被送來給他研究，她的血因背叛而污黑。從這一天起，艾斯林傑醫生才真正開始為諾克薩斯效勞。","單位",[],["諾克薩斯"],"普通"],"05NX016":["血腥夫人","從我方手牌棄置非飛逝單位時，在手牌生成1張該單位的飛逝複製牌。","","法莉絲．諾拉迪夫人在夜幕的掩護下，率領她的灰暗軍團離開了諾克薩斯都城。他們歷經了千辛萬苦，花了整整三週的時間，才終於接近手下斥侯向她回報的那座蒂瑪西亞小哨站。展示成果的時候到了。","單位",[],["諾克薩斯"],"史詩"],"05NX002":["叛軍貴族","在本牌局中，我方棄置3張以上卡牌後，賦予此牌+2|+1。","","「對一名密謀背叛的叛徒來說，有什麼比看到自己的同夥慘遭殺害之後，重返人世繼續為諾克薩斯的大旗而戰，更能讓他下定決心盡忠報國？他們都將效忠，無人能免。」——血腥夫人","單位",[],["諾克薩斯"],"普通"],"05BW005":["娜米","我方打出法術時，賦予沒有定身的最弱友軍單位+1|+0（不含此牌）。","我方娜米在場上時，我方打出法術5次以上。","「你向大家道別了嗎，年輕的海潮之音？」\n「道過了，聖母大人。」\n「你害怕嗎？」\n「……是的，聖母大人。」\n「很好，懂得害怕才會小心。不過還是要相信你自己，如同我們相信你一樣。去吧，願洋流保佑你。」","單位",[],["比爾吉沃特"],"英雄"],"05BW006":["潮落","隨機對1個敵軍單位或敵方主堡造成2點傷害，並在手牌生成1張浪起。","","「當心汪洋之怒……」——娜米","法術",["元素"],["比爾吉沃特"],"普通"],"05BW002":["旅行蝦族人","","","「是沒錯，有些陸行者會把我們當一般的獵物來看待，但你知道嗎，我遇過的陸行者幾乎都只是想在這片汪洋大海中找樂子，就跟我們一樣，大家都是人。」","單位",[],["比爾吉沃特"],"普通"],"05BW008":["深淵衛士","我方打出法術時，本回合給予此牌+2|+0。","","「大部分族人都多少有點懼怕羅多。他們只看見一個奮戰不懈的鬥士，還有那不安的眼神中透出的疏離。但我理解他真正的內心——他害怕自己不夠強大，無法拯救我們所有人……而他的愛更是無比恢弘。」——瑪拉族歌姬托瑪","單位",[],["比爾吉沃特"],"普通"],"05BW011":["海軍上將雪利","每回合打出2張法術後，賦予其他友軍單位+1|+1。","","「你各位給我聽好！你們最好知道我撒敵山百，還素整個海軍最逆害的元曬！縮以我叫你們游泳的俗候，最好東東給我游氣來，瞭嗎？很好，甘溫蛤！」","單位",[],["比爾吉沃特"],"史詩"],"05BW003":["驚滔駭浪","隨機對2個不同敵軍單位造成1點傷害，並在我方牌組生成1張排山倒海。","","「海洋吞噬一切！」——娜米","法術",["元素"],["比爾吉沃特"],"稀有"],"05BW004":["潮汐聖使","我方獲得魔力寶石時，改為恢復我方所有法術魔力。我方打出法術時，在手牌生成1張魔耗值為3以下的飛逝隨機法術牌。","","對於瑪拉族來說，雷歐萊是預示重大變化的使者。據說牠優雅的翅翼每揮舞一下都會影響浪潮的流動。","單位",[],["比爾吉沃特"],"史詩"],"05BW001":["瑪拉族守衛","召喚此牌時，隨機召喚1個魔耗值為1的侍從單位。","","瑪拉族幾乎不會有遠離家鄉出外冒險的想法，但艾拉一出生就好奇心旺盛——雖然必須在部落盡忠職守，但她醒著的每一刻都在想像自己擁抱自由的那一天。","單位",[],["比爾吉沃特"],"稀有"],"05BW010":["瑪拉族聖母","召喚此牌時，在我方牌組隨機生成5張魔耗值為6以上的法術牌，並將其魔耗值降為3。","","瑪拉族的祖地由月之石的神聖光輝守護著。每一百年，月之石的光輝就會開始衰退，瑪拉族會任命新的海潮之音，由他負責尋找下一顆月之石——因為沒了它，瑪拉族將被黑暗吞噬，化為深海怪物的餌食。","單位",[],["比爾吉沃特"],"普通"],"05BW013":["瑪拉族歌姬","召喚此牌時，若本回合我方已打出法術，則賦予此牌隱密。","","「海洋相信浪潮終將歸來，\n相信潮起潮落，白浪翻騰。\n海浪打上陸地之際，\n浪峰的怒吼將化為海洋的喜悅。」\n——節錄自《海潮之音小夜曲》","單位",[],["比爾吉沃特"],"稀有"],"05PZ015":["正義騎士","對手抽牌時，將1張閃光炸彈陷阱\n植入敵方牌組最上方8張牌中。","","「目擊者稱此探員與嫌犯展開高速追逐，直到嫌犯落入自己設下的陷阱。這名探員將嫌犯逮捕歸案後，開給自己一張超速罰單並自行繳納罰鍰，並（十分戲劇化地）表示：『正義是大家要共同持守的。』」\n——節錄自一篇皮爾托福警備隊的專題報導","單位",[],["皮爾托福&佐恩"],"史詩"],"05PZ012":["警局檔案專員","出牌：從我方牌組最上方5張牌中挑選1個法術，在手牌生成1張飛逝複製牌，然後將那5張牌洗回我方牌組。","","如果沒有線索，再怎麼厲害的警探也派不上用場。檔案專員的工作就是彙整各種零碎的情報，開創嶄新契機。","單位",[],["皮爾托福&佐恩"],"稀有"],"05PZ026":["生產線","召喚2名鍛造場工人。","","「換班！」——鍛造場主管","法術",[],["皮爾托福&佐恩"],"普通"],"05PZ019":["頭號要犯","挑選一名玩家，使其棄置魔耗值最低的手牌並抽3張牌。","","「凡事都有代價。」——可瑞娜．瓦拉撒","法術",[],["皮爾托福&佐恩"],"史詩"],"05PZ031":["亞布斯．斐羅仕","召喚此牌時，抽出1張杰西。攻擊：對敵方主堡造成3點傷害。本牌局我方每打出1次魔耗值為6以上的法術，則造成的傷害值+1。","","「出手闊綽的亞布斯．斐羅仕再度把自己推到聚光燈下；他的出價徹底壓過凱得華德和吉歐佩拉氏族，取得了杰西的海克斯飛門研究贊助權。俗話說得好，『斐羅仕有好日子過，皮爾托福就有好日子過。』顯然昨天對斐羅仕氏族而言是個大好日子！」\n——節錄自《皮爾托福日報》上的廣告欄","單位",[],["皮爾托福&佐恩"],"史詩"],"05PZ027":["電磁脈衝","從敵軍單位與敵方主堡中挑選2個目標，各造成3點傷害。","","「開火！」——杰西","法術",[],["皮爾托福&佐恩"],"稀有"],"05PZ022":["杰西","出牌：賦予此牌快速攻擊或挑戰者。","我方打出2次魔耗值為6以上的法術。此牌升級時，在手牌生成1張中子加速裝置。","「羅莎，你也知道，這個動力成形技術會改變世界。」\n「確實很有突破，杰西。那些共能抑制器銜接在一起的\n方式真的很讓人驚嘆。」\n「沒錯。這些也都是艾克索的主意！對吧，兄弟？」\n「呃，你知道我的個性，我不喜歡自吹自擂……」","單位",[],["皮爾托福&佐恩"],"英雄"],"05PZ017":["汙水坑毒霧","對1個單位造成2點傷害。若本回合我方已將2張以上卡牌加入手牌，則改為造成3點傷害。","","「最好通風一下，剛接觸的人會受不了那味道。但我跟你說……習慣之後，那感覺簡直無可比擬！」——膨菇小販","法術",[],["皮爾托福&佐恩"],"普通"],"05PZ013":["鎮暴射擊","對1個單位造成2點傷害，並將2張閃光炸彈陷阱植入敵方牌組最上方8張牌中。","","「收下我的名片吧。」——凱特琳","法術",[],["皮爾托福&佐恩"],"普通"],"05PZ020":["埋伏突襲","本回合給予1個友軍單位+2|+0。若本回合我方已將2張以上卡牌加入手牌，則另外給予其隱密。","","「我們會在煙霧的掩護下包圍現場……」——凱特琳","法術",[],["皮爾托福&佐恩"],"普通"],"05PZ024":["斐羅仕金主","出牌：顯化1張魔耗值為6以上、我方區域的法術牌。","","「讓斐羅仕贊助資金協助發明的唯一好處就是能夠藉此和雷吉合作。他不但是我合作過最有能力的人之一，也是個好傢伙。」——節錄自杰西的日誌","單位",[],["皮爾托福&佐恩"],"普通"],"05PZ010":["進階情報","將2張閃光炸彈陷阱植入敵方牌組最上方8張牌中。\n抽1張牌。","","「聽我指示。」——凱特琳","法術",[],["皮爾托福&佐恩"],"普通"],"05PZ014":["謀略大師可瑞娜","出牌：將5張閃光炸彈陷阱植入敵方牌組最上方5張牌中，或發動其中所有陷阱的效果。","","看著皮爾托福警備隊破門而入，踩扁她寶貴的花朵，揚起一團團有毒花粉，可瑞娜露出了一抹微笑。一切正如她所料。","單位",[],["皮爾托福&佐恩"],"史詩"],"05PZ002":["內線消息","雙方各抽2張牌。","","「你知道嗎，這是一樁熱門案件。剛剛才有個傢伙來這裡調閱呢。好好享用吧！」——警局檔案專員","法術",[],["皮爾托福&佐恩"],"普通"],"05PZ021":["明日鍛造場","召喚此牌時，召喚1名鍛造場工人。我方打出魔耗值為6以上的法術時，摧毀此牌並恢復我方所有法術魔力。","","如果說皮爾托福是由發明驅動的城市，那鍛造場就是這座城市的引擎。","地標",[],["皮爾托福&佐恩"],"稀有"],"05PZ025":["鍛造場主管","打擊：恢復1點法術魔力。","","「要實現紙上的構想需要兩項要素：資金是其中一項，\n另一項就是好的鍛造場。而且好不只是好在工具和硬體，\n如果負責的主管沒有能力，那你的構想還是只能停留在\n紙上。」——杰西","單位",[],["皮爾托福&佐恩"],"普通"],"05PZ006":["凱特琳","打擊：將2張閃光炸彈陷阱植入敵方牌組最上方8張牌中。","我方發動5個以上陷阱。","凱特琳調查案件一向鍥而不捨、細心徹底，這些特質讓她在皮爾托福警備隊迅速晉升。但凱特琳這次似乎終於遇到勁敵了，一個牽涉不明人士「C」的案件讓無數探員舉手投降，看起來連凱特琳都束手無策……才怪。","單位",[],["皮爾托福&佐恩"],"英雄"],"05PZ004":["警備小隊","召喚此牌時，在手牌生成1張頭號要犯。","","悄悄走上街頭，破門鎚準備就緒。警備小隊很快就在旁待命，只等凱特琳一聲令下。","單位",[],["皮爾托福&佐恩"],"稀有"],"05PZ009":["臥底探員","打擊主堡：將2張閃光炸彈陷阱植入敵方牌組最上方8張牌中。","","贊恩．阿薩科就像所有在佐恩長大的小孩一樣，被逼著在充斥著暴力的陰暗街頭迅速成長。在弟弟捲入一場毫無意義的幫派鬥爭，並且無辜喪命之後，贊恩．阿薩科便下定決心加入了皮爾托福警備隊，期盼總有一天，法律與秩序能還他一個安全的家。","單位",[],["皮爾托福&佐恩"],"普通"],"05PZ016":["致命一擊","將1個敵軍侍從單位洗入敵方牌組，然後對手抽1張牌。","","皮爾托福這座偉大的城市中，居住著許多符文大地最聰明的天才。皮爾托福的各座監獄也關著許多符文大地最聰明的天才。","法術",[],["皮爾托福&佐恩"],"稀有"],"05PZ030":["海克斯科技異常","抽到或在手牌生成此牌，以及\n回合開始：此牌在手中時，隨機\n幻化為魔耗值為6以上的法術牌。","","「……把海克斯科技配置成穩定的狀態是我遇過最大的難關。幾乎每個夜晚，水晶和海克斯水晶就像在聯合起來整我，只有經過不斷嘗試與改良，才能讓每個零件和諧運作……」——節錄自杰西的日誌","法術",[],["皮爾托福&佐恩"],"稀有"],"05PZ028":["斐羅仕巡航機","在本牌局中，我方打出魔耗值為6以上的法術牌後，賦予此牌+2|+0。","","「這座城市的人會拜倒在『智慧』腳下，但再怎麼聰明，別人看不到的話又有什麼用呢？當然沒用，所以我要讓皮爾托福見識何謂真正的偉大。這東西會凌駕在他們上空，遮雲蔽日，上面還會有我的名字。」——亞布斯．斐羅仕","單位",[],["皮爾托福&佐恩"],"普通"],"05PZ038":["火箭亂發","對1個敵軍單位造成4點傷害，並對所有其他敵軍單位造成1點傷害。","","「火箭應該往上飛，不是四處亂飛！噢，天啊！」\n——漢默丁格","法術",[],["皮爾托福&佐恩"],"普通"],"05PZ035":["惡臭呼碰","遺願：在敵方牌組生成1張此牌的複製牌，並附帶2張劇毒膨菇。","","每當膨菇季節來臨時，呼碰散發的氣味真是臭不可當。想像下水道裡塞滿死了好幾天的魚和臭掉的雞蛋，那氣味差不多就有一半臭了。","單位",[],["皮爾托福&佐恩"],"稀有"],"05PZ029":["海克斯科技搬運機","在本牌局中，我方打出魔耗值為6以上的法術牌後，賦予各處機械友軍單位+1|+0。","","海克斯科技搬運機一開始是為了在皮爾托福各處運送原料而製造的，但當地人顯然越來越喜愛他。杰西的鍛造場員工幫他取了「小金塊」的綽號，一位皮爾托福的地主據說捐了一頂帽子給他，而來往的孩子也會把手邊的小東西都裝飾在他身上。","單位",["機械"],["皮爾托福&佐恩"],"稀有"],"05SI014":["遺憾典冊","回合開始：若上回合我方打出了\n非飛逝法術，則在手牌隨機\n生成其中1張的飛逝複製牌。","","天堂島遺忘，闇影島記得。闇影島遺忘，天堂島記得。","地標",[],["闇影島"],"史詩"],"05SI013":["黯霧看守者","每回合我方首次用法術擊殺單位時，召喚1個閃靈霧魅。","","受困黯霧的靈魂會陷入自我折磨的無限循環。藉助黯霧捕捉者的力量，泰克與卡娜為這些受苦的靈魂提供了一個自己突破循環的機會。\n","單位",[],["闇影島"],"稀有"],"05SI009":["姍娜","召喚此牌時及攻擊：若手牌中沒有黑暗，則在手牌生成1張。我方的傷害與擊殺法術加速為快速。","此牌在場上時，我方用法術擊殺3個以上單位，或我方路西恩陣亡。","「成為光之哨兵就是踏上戰鬥的不歸路，不是自己喪命，就是失去所愛的人。但成為哨兵代表要更努力活下去，為了自己……也為了所愛的人。」","單位",[],["闇影島"],"英雄"],"05SI016":["黎明之影","擊殺1個單位，且本回合給予所有敵軍單位-2|-0。","","「無光不生影，曾生方知死。」——姍娜","法術",[],["闇影島"],"普通"],"05SI004":["島嶼守望者","每回合我方首次用法術擊殺單位時，對敵方主堡造成2點傷害。","","「狗崽子就是狗崽子。」——刻畫在靈魂上的智慧","單位",[],["闇影島"],"稀有"],"05SI012":["日輪哨兵","召喚此牌時，若手牌中沒有黑暗，則在手牌生成1張。","","「我已感受不到陽光的溫暖，儘管如此，太陽的記憶仍與我同行，這樣就足夠了。」","單位",[],["闇影島"],"普通"],"05SI008":["伊克斯塔爾哨兵","召喚此牌時，若手牌中沒有黑暗，則在手牌生成1張。我方下次於本回合打出黑暗時，對敵方主堡複製其效果。","","「姍娜，你問我為何而戰。黯霧未曾奪走我什麼，也沒有威脅我的家鄉。黯霧明明不該存在，卻仍存在於世上，我來此是為了找出原由。難道非要有傷痛才能與你們並肩作戰嗎？」","單位",[],["闇影島"],"稀有"],"05SI003":["穿透黑暗","從1個單位汲取5點生命值。","","「死亡深深被生命吸引。」——姍娜","法術",[],["闇影島"],"普通"],"05SI010":["戴絲與艾達","召喚此牌時，若手牌中沒有黑暗，則在手牌生成1張。本回合我方施放的下一張黑暗魔耗值為0，並獲得「此牌對所有敵方目標造成傷害」。","","「又做惡夢了？」\n「也沒那麼糟啦，你不在夢裡。」\n「傻瓜，最糟的是什麼？」\n「你不在夢裡。」","單位",[],["闇影島"],"史詩"],"05SI011":["新星哨兵","我方首次用法術擊殺單位時，賦予此牌+2|+1。","","黯霧遇見梅芙時會看見什麼呢？熱情洋溢、自信滿滿，擋都擋不住的樂觀態度。黯霧一定恨不得熄滅梅芙耀眼奪目的火焰，畢竟能讓死亡害怕的，也只有生命了吧？","單位",[],["闇影島"],"普通"],"05SI015":["布爾魯哨兵","我方首次用法術擊殺單位時，賦予此牌+2|+1。","","布爾魯文明和光之哨兵的理念有一個核心共通點：萬物皆有盡時，而其中有些須強制終結。","單位",[],["闇影島"],"普通"],"05MT004":["疑心魔坎芙","召喚此牌時，若我方已指定友軍單位為目標累計4回合，則賦予此牌法盾、蠻力與挑戰者。","","數百年來，惡魔坎芙都在巨石峰的土地上為虐，奪走受害者賴以為生最重要的能力。她從強大的人身上奪走力量，從聰明人身上奪走智慧。但是她對這些能力毫無興趣，能餵養她的是她所施加的痛苦、懷疑、不幸。從任何角度來說，坎芙都是真正的怪物。","單位",[],["巨石峰"],"史詩"],"05MT006":["負傷白燄龍","","","「巨石峰居民不需要更多證據來證明神的殘酷。看看祂們對我們做了什麼。看看祂們對我們最珍視的夥伴做了什麼。」——潘森","單位",["龍族"],["巨石峰"],"稀有"],"05MT008":["盾之躍擊","賦予1個友軍單位+1|+1並擊暈1個敵軍單位。","","潘森熟知如何戰鬥。從無數次的經驗中，他知道敵人的目光幾乎每次都會追著他的矛，而非他的盾。","法術",[],["巨石峰"],"稀有"],"05MT014":["天界奇觀","擊暈2個敵軍單位。","","「巨石峰的夜空擁有一種罕世之美。仰望著那片一望無際的星空，讓人不禁陶醉其中。不過，說不定在宇宙的彼端，也有某種存在正在凝視著我們……」\n——巨石峰登山者","法術",[],["巨石峰"],"普通"],"05MT003":["潘森","","我方指定友軍單位為目標累計5回合以上。","亞崔斯站立於此，他的自由遭到自己所崇敬的星靈剝奪。戰爭的餘燼站立於此，留給亞崔斯少有凡人能領會的贈禮。一個男人站立於此，準備為了他所珍視的一切戰鬥並犧牲。","單位",[],["巨石峰"],"英雄"],"05MT013":["尤拉","出牌：賦予1個友軍單位法盾或蠻力。若未指定其他單位，則賦予此牌。","","尤拉還記得聽聞自己丈夫死訊之後，身體裡湧現像火焰一樣灼熱的悲傷。潘森前來拜訪時，問她願不願意幫忙消滅靠這種痛苦飽餐的生物，她毫不猶豫就答應了。","單位",[],["巨石峰"],"普通"],"05MT009":["生死同袍","賦予2個友軍單位+2|+2。","","對抗諸神的戰爭看似愚不可及，但勇者們經歷的苦痛和傷痕，給了他們寶貴的教訓：諸神的思想單一而自私，也喪失了生死與共的同袍情誼——這將成為他們最銳利的武器、最堅實的裝甲。","法術",[],["巨石峰"],"普通"],"05MT010":["盲眼祕術師","出牌：賦予1個友軍單位+1|+1並沉默1個敵軍侍從單位。","","艾許玫曾經是受人敬仰的神諭使，運用她的預視能力來指引有需要的人。但這份天賦被坎芙奪走，只因為坎芙想要使她痛苦欲絕，藉此飽餐一頓。惡魔實在是太小看勇敢的艾許玫了。","單位",[],["巨石峰"],"普通"],"05MT002":["攜手同行","本回合給予2個友軍單位+1|+2。","","「我們必須從親族之間的羈絆中找到力量。」——潘森","法術",[],["巨石峰"],"稀有"],"05MT012":["自由巨像","召喚此牌時及攻擊：在手牌生成1張靈力寶石。","","巨像非常古老，負責保護巨石峰最受敬仰的地點，自身也備受崇敬。傷害他們就是對山的侮辱。折磨他們則是任何巨石峰居民都無法原諒的嚴重罪行。","單位",[],["巨石峰"],"普通"],"05MT011":["逆勢而行","若敵方場上單位多於我方，則每多出1個單位，便賦予1個友軍單位+1|+1。","","這幾位勇者知道自己交戰的對手擁有超乎想像的力量。他們知道自己很有可能是去送死，但還是決定前進。","法術",[],["巨石峰"],"史詩"],"05MT005":["傳奇追尋者","","","他感覺到生命隨著一次一次的心跳逐漸流失，但身在那座黑暗的墳裡，他本該感到害怕，但他卻反而堅定了決心。他不只要主動迎向死亡，還要帶走敢讓他死於非命的惡魔。這就是他留給後世的事蹟。這就是托爾的傳奇。","單位",[],["巨石峰"],"普通"],"05DE003":["巨鷲像戈里斯","出牌：此牌與我方主堡調換生命值。\n生命值低於此牌的敵軍單位無法格擋此牌。","","「向那些離開了，卻未被遺忘的人致敬：當蒂瑪西亞人民看到陽光照亮其身影時，希望就會顯現在他們眼前，而且當初激發人去建造他的不屈精神，也會透過他傳承下去。」\n——杜蘭德工作坊銘文","單位",[],["蒂瑪西亞"],"史詩"],"05DE009":["加里歐","召喚此牌時，賦予其他友軍單位+0|+3。","回合結束：我方場上友軍單位生命值總和為25以上。","加里歐誕生後，一直處於休眠狀態許多年，沒有知覺、也沒有感覺。直到魔法讓他活了過來，他感受到戰鬥帶來的緊張快感後，他才理解活著的喜悅。現在每當他進入沉眠，他都會想念起這些美好的事物！","單位",[],["蒂瑪西亞"],"英雄"],"05DE020":["杜蘭德之盾","賦予1個友軍單位+0|+3。於下次回合開始再賦予其+0|+2。","","光是看到加里歐就足以激起蒂瑪西亞人的榮耀之心。","法術",[],["蒂瑪西亞"],"稀有"],"05DE021":["先鋒之力","此牌魔耗值等於我方所剩魔力。召喚1名無畏先鋒，並使其能力值提升至等於所消耗魔力。若消耗9點以上魔力，則賦予其他菁英友軍單位+2|+2。","","陷入絕望時，蒂瑪西亞士兵就會把最後的希望寄託在先鋒部隊身上。","法術",[],["蒂瑪西亞"],"史詩"],"05DE017":["征戰風暴","治癒1個友軍單位，然後使其與1個敵軍單位互相打擊。","","「那就來打一場吧！」——加里歐","法術",[],["蒂瑪西亞"],"稀有"],"05DE010":["杜蘭德雕刻家","我方召喚其他單位時，賦予其+0|+1。","","「未經訓練的人可能不懂，但偉大雕刻家的過人之處就藏在每一刻每一鑿之中。」","單位",[],["蒂瑪西亞"],"普通"],"05DE013":["反魔法英石巨鹿像","支援：本回合為受此牌支援的友軍單位承受所有傷害。","","這個反魔法英石製成的守護者雖跟隨著巨角鹿遊俠的帶領，卻讓身為它原型的動物相形見絀。","單位",[],["蒂瑪西亞"],"史詩"],"05DE015":["裂地飛龍","血怒會改為賦予此牌+0|+2。","","溫和的裂地飛龍雖然外表兇猛，但脾氣其實很好。即便身邊有其他山中猛獸，牠們也處之泰然，因此自然成了弱小動物的守護者。","單位",["龍族"],["蒂瑪西亞"],"史詩"],"05DE019":["杜蘭德建築師","支援：本回合給予受此牌支援的友軍單位+0|+2與重壓。","","「遊俠艾姆哈特帶來了令人沮喪的消息，」建築師鎮靜地說道，一邊專心捲著手中的羊皮紙，企圖掩飾他雙手的顫抖。他轉向等待他說下去的雕刻家們，並僵硬地點點頭。「暗中保護蒂瑪西亞的守護者該站出來了。」","單位",[],["蒂瑪西亞"],"稀有"],"05DE014":["杜蘭德門徒","出牌：賦予1個友軍單位+0|+1與堅忍。","","聽到鹿蹄踏地的聲音，原本在埋頭工作的雪琳抬起頭來。遊俠看似十分匆忙，讓她不怎麼自在，但也好奇了起來。她讓反魔法英石飛鳥拍動翅膀，跟著遊俠飛去。","單位",[],["蒂瑪西亞"],"普通"],"05DE012":["反魔法英石巨翼像","我方召喚其他單位時，賦予此牌挑戰者。","","當狼狽不堪的蒂瑪西亞士兵看見巨翼像從頭頂飛過，他們無不紛紛歡呼，因其歷久不衰的雄偉英姿振奮不已。","單位",[],["蒂瑪西亞"],"稀有"],"05DE018":["反魔法英石巨犬像","","","「每當看到作品活起來時，總是讓人開心不已。你往往會忘記每件作品都是獨特的，反映了製作者的個性。」——杜蘭德雕刻家","單位",[],["蒂瑪西亞"],"普通"],"06NX024":["寬鬃領主","出牌：對1個敵軍單位造成2點傷害。\n我方的快速法術、慢速法術與技能擁有「此牌對遭到擊暈或負傷的敵軍單位造成傷害時，擊殺之。」","","「第二幕：一位名下幾乎空空如也的奸詐領主，卻用一件偷來的袈守里手爪武器吸引了一群愛歐尼亞人，然而他的言行舉止漏洞百出，一眼就被看穿了。他乞求眾人饒命，說他什麼也不知道。他企圖用那手爪統治一方，但手上卻什麼也不剩了。」","單位",[],["諾克薩斯"],"稀有"],"06NX033":["戰略性執行","擊暈2個敵軍單位或消耗6點魔力召喚1位軍團大將軍。","","人員配置是每場戰鬥前最初的重大決策之一。優秀的指揮官知道勝利的關鍵就是……","法術",[],["諾克薩斯"],"稀有"],"06NX012":["安妮","攻擊：對格擋此牌的單位造成2點傷害。若該單位已陣亡或離開場上，則改為對敵方主堡造成2點傷害。","此牌在場上時，我方打出6次快速法術、慢速法術或技能。此牌升級時，在手牌生成1張泰貝爾。","十幾年前，阿莫琳．奇歐沙帶著一件燦爛奪目的珍貴寶物逃離了雷文布魯學院。雷文布魯的偵察隊找遍了帝國上下，但打聽到的傳聞沒有一個能帶他們找到阿莫琳。過了幾年後，鐵脊山脈北方傳來一個消息，有人發現了一個怒火中燒的迷路小女孩，芬恩．瑞崔克便心不甘情不願地打包前往調查。他本以為又是一場空，但他錯了。","單位",[],["諾克薩斯"],"英雄"],"06NX029":["灰暗藥房","力量值為5以上的友軍單位陣亡時，在手牌生成1張力量值為5以上的隨機侍從單位。","","「今天我回憶起了潘羅斯丘的小醫院，還有我在那裡企圖解開生理學奧祕的歲月。我花了好幾年！我受雇於諾拉迪夫人才不過幾個月，但我現在明白了當初的我根本一無所知。當時的我多單純、多幸運啊。」\n——艾斯林傑醫生的筆記","地標",[],["諾克薩斯"],"史詩"],"06NX032":["乖順龍犬","友軍單位攻擊時，此牌與其一起攻擊。","","「龍犬很可愛，對吧？牠們多愛討好主人，又很好控制。如果我的敵人也像這樣就好了。」——玫瑰棘兵","單位",["犬族"],["諾克薩斯"],"普通"],"06NX030":["軍團逃兵","此牌獲得我方所有各處增益。","","「第一幕：一位士兵偷了一件古代袈守里聖物之後就拋下崗位逃跑了。他躲進卡燕維的一間酒吧，喝得爛醉後開始大肆吹噓，但他不知道他偷的這件寶物會將所有的一切悄悄告訴它真正的主人！他的性命正如同杯中的紅酒迅速消逝，諾克薩斯血染愛歐尼亞之寶。」","單位",[],["諾克薩斯"],"稀有"],"06NX013":["蜘術士","出牌：擊暈1個敵軍單位，若其已遭到擊暈，則改為造成2點傷害。","","「學生：希德爾．凱瑟拉\n教師：J.．維洛\n報告：我的左前臂被蜘蛛咬了。希德爾說這是場誤會，但他的賊笑證明了他在說謊。他被罰在食堂做額外兩週的\n雜務。」\n——雷文布魯學院獎懲卡","單位",["蜘蛛"],["諾克薩斯"],"普通"],"06NX040":["特菲利安訓練場","每回合力量值為5以上的友軍單位首次攻擊時，進行備戰。","","「我一下令，你們就開始訓練！若訓練對手倒下死了，那就找其他人！若你倒下死了，那就安心地走吧，因為你的死意味著諾克薩斯將變得更強大！特菲利安士兵們……訓練開始！」——特菲利安鑑定員","地標",[],["諾克薩斯"],"史詩"],"06NX028":["雷文布魯學院","倒數11：在手牌生成1張泰柏克。\n本牌局我方每打出1張快速法術、慢速法術或技能，此牌便快轉1回合。","","「……你一定已經聽說薔薇之衛學院的事了吧？希望姊妹校慘痛的失敗能讓你們學到教訓。希望你能好好管理你的學校，為帝國效力。」\n——在學院廢墟發現的燒焦信件","地標",[],["諾克薩斯"],"稀有"],"06NX014":["瓦解怒焰","挑選1個單位，本回合該單位下一次受到至少1點傷害時，擊殺之。","","泰爾希校長滔滔不絕說著諾克薩斯的信條，讓她眼前的孩子們越來越無聊，漸漸開始躁動。雖然大多數的學生都忍住不爆發，安妮卻有所行動：首先是黑煙，再來是火焰。","法術",["元素"],["諾克薩斯"],"普通"],"06NX031":["雪怪戰奴","名望：此牌魔耗值-4。","","當兩隻雙手被銬住的雪怪被帶進波登的傳奇競技場時，觀眾不禁倒吸一口氣。他們未曾見識過雪怪的力量，因此沒料到這些猛獸竟能拉斷手上的鎖鏈。","單位",["雪怪"],["諾克薩斯"],"普通"],"06NX009":["馴化灰背獸","攻擊：對格擋此牌的單位造成3點傷害。若該單位已陣亡或離開場上，則改為對敵方主堡造成3點傷害。","","「第三幕：殘忍的飼育員與她的寵物。就算被用來執行殘忍的命令，灰背獸也是無辜的，因為牠的頭飾會強迫牠服從指令。就算被丟去餵她的寵物，飼育員也拒絕尖叫。如果所有諾克薩斯人死時都像她那麼高尚就好了。」","單位",[],["諾克薩斯"],"普通"],"06NX015":["法魂學徒","每回合我方首次打出快速法術、慢速法術或技能時，此牌打出魔法藍焰。","","「我第一次見到丹尼應該是好幾年前的事了。他是個友善的小子，他的家人也很和藹可親。但在我最後一次去他們的村莊時，我看見可憐的丹尼一個人坐在廣場上，說他在等家人回來。那可憐的小子肯定坐在那邊好幾個月了，我不忍心告訴他我在來的路上看到了什麼……」\n——芬恩．瑞崔克","單位",[],["諾克薩斯"],"普通"],"06NX037":["諾克薩斯泰爾石","在手牌生成1張飛逝打磨心志、迴轉死神或亡者武器。","","「克拉拉，親愛的，你得把棋子上的血擦乾淨才行。」血色貴族奧菲莉亞．諾拉迪","法術",[],["諾克薩斯"],"稀有"],"06NX008":["模範學生","我方打出快速法術、慢速法術或技能時，賦予此牌+1|+0。","","「許多孩子都處在容易違抗大人指示的年紀，這是天性使然。幸好當中最年長的孩子不只受其他人喜愛，還容易被我們教育。如果學生們繼續無視我們的教訓，我們就會透過她實行教育。」——女校長泰爾希","單位",[],["諾克薩斯"],"史詩"],"06MT044":["日輪星角獸","破曉：本回合給予其他友軍單位+0|+2。","","星角獸出生於群星之間，有些會釋放出更強的熱力。","單位",[],["巨石峰"],"普通"],"06MT036":["求問天界","治癒所有友軍單位，並使其力量值提升至等同於生命值。","","「我們必須先憐憫自己，其他人才會同情你。」——索拉卡","法術",[],["巨石峰"],"史詩"],"06MT039":["龍棲峰","倒數3：召喚1隻音無龍獸。","","「據說天界的龍族是從星雲誕生的，從朦朧的宇宙塵埃中以完整的姿態顯現，但區區凡人又怎能理解呢？在遙遠地方的我們，只看得見牠們的光輝。」——龍族先使","地標",[],["巨石峰"],"史詩"],"06MT045":["天界三連冠","祈望魔耗值低、中和高的天界牌各1張。","","「星辰正在預告著強大力量的到來，有東西要來了。它們會以什麼形式出現呢？這不是我能知道的！你覺得呢，庫倫？」——白月夢舞者","法術",[],["巨石峰"],"稀有"],"06MT043":["巨石峰泰爾石","在手牌生成1張飛逝望穿無垠、靜寂噓鳴或巨石峰的祝福。","","「索林，最奇怪的事是……就算不把石頭翻過來，我也無比清楚上面刻畫著什麼星座。」——漂泊旅者泰亞歷","法術",[],["巨石峰"],"稀有"],"06MT029":["世界之音艾斯莫","召喚此牌時，在我方牌組最上方的牌中植入1張編鐘。\n支援：賦予受此牌支援的友軍單位+1|+1。","","「……但我聽說艾斯莫是守望者親手創造的，她的誕生為世界帶來了聲音！」\n「胡說！明明艾斯莫的臉孔屬於一位老歌者，傳說那歌者有著天使般的善良心靈與亡靈般的恐怖嗓音……直到巴德親自賦予了她絕美的歌聲！」\n「你才胡說！艾斯莫是……」\n——詩人之間流行的遊戲，艾斯莫的誕生一景","單位",[],["巨石峰"],"普通"],"06MT038":["曲光獸座","夜臨：本回合給予所有其他友軍單位+2|+1與蠻力。","","「月亮之母，將你的力量借給我們吧，\n即使黑暗籠罩我們，\n用你的光讓我們克服一切。」\n——月環教禱詞","單位",[],["巨石峰"],"普通"],"06MT047":["神祕星旋","召喚此牌及此牌倒數時，將3張編鐘植入我方牌組。倒數2：抽1張牌。","","「然後我看見了，數以千計的它們到處在唱歌跳舞。接下來我看見一道閃光，然後它們就全部不見了，神廟也憑空消失，連顆石子都不剩。我這老糊塗手裡拿著一個編鐘，而整個地方只剩我孑然一身。」——《老糊塗奇譚》，第三部","地標",[],["巨石峰"],"稀有"],"06MT041":["星犬群","將此牌的命定增益賦予我方各處星犬群。","","無論登山者怎樣招手或引誘星犬，牠們都漠不關心，似乎對高山的魔力有免疫力。","單位",["犬族"],["巨石峰"],"普通"],"06MT049":["米凱的祝福","賦予1個友軍單位+1|+2，並移除其所有負面特性。","","凡是聽到鈴聲的人，都會被其純潔的音色所打動。","法術",[],["巨石峰"],"稀有"],"06RU025":["伊芙琳","起源：臨終擁抱。\n召喚此牌時，隨機召喚1個空殼。","此牌在場上時，我方或友軍單位擊殺我方空殼時，本回合將其增益特性給予此牌，且此牌會升級。","女祭司睜大雙眼，雙手因期待而不斷顫抖。她已做好準備了。這正是伊芙琳所渴望的瞬間，她咧嘴一笑，並慢慢撕開自己的假面孔。每到此刻，笑聲都會被尖叫聲取代，這次也不例外。","單位",[],["符文大地"],"英雄"],"06RU001":["巴德","起源：漂泊守望者。\n攻擊：將3張編鐘植入我方牌組。","我方提升場上或手牌中友軍單位的總能力值達20以上。","「老糊塗這輩子可見識過不少奇聞異事呢！第一次呢，我想是守望者本人吧。他就像流星一樣劃過天空，感覺簡直就像全世界都靜止了一分鐘，只剩下我和他獨立於停止的時間之外……」——《老糊塗奇譚》，第一部","單位",[],["符文大地"],"英雄"],"06RU002":["燼","起源：炫技大師。\n攻擊：對所有遭到擊暈的敵軍單位造成2點傷害。","我方打出12張以上的快速法術、慢速法術或技能。","「序幕：場景是一個名叫卡燕維的城市，一名年邁的大師喚來一位學徒，要他去解決一群為非作歹的惡徒，並取回被偷的聖物。演員很急切，但還沒輪到他上場。現在他只需要準備，並在舞台旁邊待命。」","單位",[],["符文大地"],"英雄"],"06FR029":["凍彈不得","凍傷1個敵軍單位，並召喚1群冰霜尖牙狼群。","","伴隨著寒風一起來臨的冰霜尖牙狼，無需費力追蹤獵物……只需等待他們倒下。","法術",["元素"],["弗雷爾卓德"],"史詩"],"06FR033":["狩獵野豬","遺願：獲得1格魔力寶石槽位。","","弗雷爾卓德的生死循環不太一樣，嚴酷的環境讓一點血肉都不會被浪費。","單位",[],["弗雷爾卓德"],"普通"],"06FR038":["冰晶鳳凰之翼","對所有單位造成3點傷害。\n開悟：改為對所有敵軍單位造成3點傷害，並治療我方主堡3點生命值。","","在偉大冰晶鳳凰的雙翼下，她的追隨者歡欣鼓舞，敵人則顫抖不已。","法術",["元素"],["弗雷爾卓德"],"稀有"],"06FR030":["奴魔先使","出牌：召喚1位冰封奴魔或快轉我方所有冰封奴魔1回合。","","頭頂上的生物所發出的詭異鳴聲幾乎聽不清楚，但隨著牠們的叫聲迴盪在深谷的石壁之間，偵察隊可以從骨子裡感受到這份震撼，並看到巨大的裂痕在眼前的冰壁上快速擴散。","單位",["鳥族"],["弗雷爾卓德"],"普通"],"06FR039":["狂爪兇性","將1個友軍侍從單位幻化為狂爪虎王。","","「偉大的狂爪獸靈，賜我們力量吧！」——烏迪爾","法術",[],["弗雷爾卓德"],"稀有"],"06FR028":["傳智者蕾芙娜","召喚此牌時，賦予我方牌組裡所有單位此牌的能力值，然後抽1張力量值為5以上的單位牌。","","艾伐洛森傳智者通常都是部族中歷練豐富的長老，他們會保護族人，而且擅長說故事。他們會用故事及歌曲把狩獵及戰鬥的傳統傳承下去。 ","單位",[],["弗雷爾卓德"],"史詩"],"06FR037":["冰層龜裂","賦予1個敵軍單位「於下次回合開始凍傷此牌。」","","無論冰層看起來有多厚，都必須步步為營。","法術",["元素"],["弗雷爾卓德"],"普通"],"06BC045":["蘑菇幻塵","本回合給予所有友軍單位+1|+1。若是生成的單位，則改為給予+2|+2。","","「嗨。我是個蘑菇。我在說話。我毫無頭緒。我繼續當蘑菇就行了。拜托啦。謝啦。拜拜。」——蘑菇","法術",[],["班德爾城"],"史詩"],"06BC036":["巨賈帕帕羅","出牌：顯化1張約德爾牌。\n攻擊：賦予約德爾友軍單位+1|+0。","","「每個人都愛帕帕羅！每年夏天，他都會為我們從世界各地帶來各種小物，這些小物有的美味、有的漂亮，有的莫名其妙！有的甚至會結合三種特點！」——優等生艾娃","單位",["約德爾人"],["班德爾城"],"史詩"],"06BC040":["班德爾泰爾石","在手牌生成1張飛逝英雄讚歌、約德爾怪裝置或高壓電魚叉。","","約德爾人總是喜愛玩遊戲……但如果他們中途改變規則，也別感到驚訝！","法術",[],["班德爾城"],"稀有"],"06BC039":["丟炸彈","對1個單位造成2點傷害，並召喚1枚土製炸彈。","","「嗯，情況不妙。」吉賽兒小聲說道，然後躲到掩蔽物後面。","法術",[],["班德爾城"],"普通"],"06BC044":["宇宙制約","對1個敵軍單位造成2點傷害，並擊暈另1個敵軍單位。將6張編鐘植入我方牌組。","","「媽媽，守望者去哪裡了？」\n「親愛的，任何地方都有可能，放眼望去看得到的地方他都會去。」\n「為什麼？」\n「啊，親愛的，別問為什麼，就連有智慧的長老都無法參透守望者的行動……」\n——母子之間的對話","法術",[],["班德爾城"],"稀有"],"06BC026":["響鈴者博德","召喚此牌時，在我方牌組最上方的牌中植入1張編鐘。","","「……第二次更離譜了。我那時在掃地，突然發現我的晚餐翻倒了，灑得整桌都是，鍋碗瓢盆都長了兩隻腳，在那邊晃呀晃的，往門外衝出去！我的老膝蓋拚了命地追上去，然後發現它們在那座神廟，翻箱倒櫃像是在尋找什麼東西一樣。」——《老糊塗奇譚》，第二部","單位",[],["班德爾城"],"普通"],"06BC030":["感應膨菇","對1個單位造成1點傷害。若本回合我方發動了陷阱或祝福，則改為造成3點傷害。","","「如果開始發光，就代表要爆炸啦！」——班德爾偵察隊第463條守則","法術",[],["班德爾城"],"普通"],"06BC031":["守門者馬杜利","召喚此牌時，在我方牌組最上方的牌中植入1張編鐘，然後使我方牌組內的祝福加倍。","","「我差點被牠嚇死。牠全身上下長滿了手臂，牙齒宛如一塊塊巨石。噢，當那怪物用大槌敲遍牙齒，就發出了詭異的曲調，我還以為自己要死掉了。我死命逃跑，但卻看見了……天上出現無數大洞！好幾百個跑不掉！」\n——《老糊塗奇譚》，第四部","單位",[],["班德爾城"],"稀有"],"06BC035":["摺紙魔樹","有附著單位或裝備的友軍單位攻擊時，賦予該附著單位或裝備+1|+0。","","從摺紙魔樹的葉子散發的妖精魔力，就是創造這棵樹的魔力；這顆樹形狀的靈感來源於鳥，也可能因為這個原因，閃閃發亮的東西令其無法抗拒。","地標",[],["班德爾城"],"稀有"],"06IO005":["驚駭劇場","召回1個生命值為3以下的單位。","","「藝術是急不得的。」——燼","法術",[],["愛歐尼亞"],"普通"],"06IO038":["精神支持","若我方在本牌局中曾經支援友軍單位，則此牌魔耗值-2。本回合給予1個友軍單位光盾。","","「信靠均衡，跨越分裂。」——慎","法術",[],["愛歐尼亞"],"普通"],"06IO012":["均衡之喚","立即或於下次回合開始召喚1位面具看守者。抽1張牌。","","「戴上古老面具，年輕的雙眼更清晰。」\n——面具看守者","法術",[],["愛歐尼亞"],"普通"],"06IO009":["靈龍突襲","用2隻幼龍發動額外攻擊。","","「慾望的化身。」\n——馴龍大師","法術",[],["愛歐尼亞"],"普通"],"06IO033":["劍刃風暴","我方劍舞時，召喚另一個攻擊中的劍刃，此效果持續到牌局結束。\n劍舞1。","","「由你帶領，我隨你起舞！」——緞帶舞者","法術",[],["愛歐尼亞"],"史詩"],"06IO004":["創造者","出牌：召回1個力量值小於此牌的單位。","","「創造者是名非凡的創作者，她是傳說的工匠！她的作品舉世無雙！她的表現手法完美無缺！能夠親自謁見她已經是無上的光榮了，更何況還能親手使用她所打造的作品。」——袈守里見證者","單位",[],["愛歐尼亞"],"稀有"],"06IO010":["迎風小丘","召喚此牌時，抽張犽宿並擊暈最強敵軍單位。\n我方獲得攻擊主動權時，擊暈最強敵軍單位。","","對大部人來說，平安指的是擁有一個幸福的家庭，並在投入愛人的溫暖懷抱時享受的寧靜時刻；對犽宿來說，平安則是強風平靜下來，並為他帶來希望，而不是喚起過去的難得時刻。 ","地標",[],["愛歐尼亞"],"史詩"],"06IO036":["愛歐尼亞泰爾石","在手牌生成1張飛逝驚駭劇場、重生儀式或並肩作戰。","","「學習看透你的對手是不可或缺的技巧，就算是在戰鬥之外也一樣。但最重要的是，對弈的目的是讓人玩得愉快。現在去把我的泡腳桶拿來！」——精神導師","法術",[],["愛歐尼亞"],"稀有"],"06IO003":["舞台助手","出牌：擊暈1個敵軍單位。","","「第四幕：一名年輕的女祭司登場。她的經歷是場悲劇，由遭她所背叛之人，張開蒼白雙唇娓娓道來。她急切地想要贖罪，雙臂中有一份沉重的鍍金大禮、為了送給被她迎接到自己故鄉的諾克薩斯人。而我們只能猜想：使她心碎的是子彈、還是哀愁？」","單位",[],["愛歐尼亞"],"普通"],"06IO035":["均衡學徒","其他友軍單位獲得光盾時，若此牌沒有光盾，則本回合給予其光盾。","","「 全身、全心、全靈擁抱均衡，壓制年輕的衝動，提升自己的境界。」——慎","單位",[],["愛歐尼亞"],"稀有"],"06PZ032":["爆音唱片機","從2張魔耗值為2的新法術中挑選1張在手牌生成，本回合其魔耗值降為0，之後重複此效果兩次。","","佐恩第一代的唱片機意外地好用，唯一的缺點就是沒有人知道怎麼調整音量。","法術",[],["皮爾托福&佐恩"],"史詩"],"06PZ042":["邪惡不完美主義者","出牌：選1張手牌，在我方牌組生成4張與之相同的複製牌，並使其魔耗值-1。","","「我只能說，今天的事情本來可以做得更好，就這樣吧。未來的我……你知道我們做了什麼了。」\n——凱的日記","單位",[],["皮爾托福&佐恩"],"史詩"],"06PZ025":["孤獨遊女","召喚此牌時，隨機召喚1個空殼。\n我方召喚魔耗值為1的單位時，賦予其1項隨機特性。","","「從半樓回家中途，我又在小巷看到那個可憐的遊民。很多人一看到她就會刻意避開，看到這個情況及她那失望沮喪的神情，令我心如刀割。如果明天我再遇到她的話，我一定會盡力幫助她。」\n——森佩斯庫夫人日記裡的隨筆","單位",[],["皮爾托福&佐恩"],"稀有"],"06PZ043":["皮爾托福泰爾石","在手牌生成1張飛逝射線餘波、海克斯變形儀或進步日！","","「這世界上沒有比這更精緻的泰爾石了，先生。每一顆都是我的女兒全心全意雕刻而成的。」——柯林．李維克 ","法術",[],["皮爾托福&佐恩"],"稀有"],"06PZ027":["祕密邀請函","在手牌生成1張飛逝可疑人物或化學龐克撕裂樂手，並使其魔耗值-1。","","想體驗佐恩最頂級的夜生活，就必須要受邀才行。如果你不在那圈子裡，那你可得成為大人物才有可能加入，或是在地上撿到入場券也行。","法術",[],["皮爾托福&佐恩"],"普通"],"06PZ038":["廢棄隱蹤器","賦予1個友軍單位隱密與「打擊主堡：抽1張牌。」","","「你們看我今天找到什麼！保證你們不敢相信！」 \n——汙水坑拾荒者","法術",[],["皮爾托福&佐恩"],"普通"],"06PZ039":["回收廢料","棄置最多2張牌即可出此牌。生成相同數量且魔耗值+1的我方區域侍從牌，並使其魔耗值-1。","","居住在佐恩深處的居民被逼循環再用回收的廢料和殘渣。經過幾十年的磨練後，這已成為他們的拿手絕活。","法術",[],["皮爾托福&佐恩"],"稀有"],"06BW006":["伊羅旖","攻擊：海祭1，然後本回合將我方最強觸手的力量值加到此牌上。","此牌或我方觸手總共造成15點以上傷害。","「娜葛卡布爾之眼」只是個名號，但伊羅旖視其為挑戰，彷彿她所敬畏的神是個無所不在且容易感到無聊的夥伴\n一樣。","單位",[],["比爾吉沃特"],"英雄"],"06BW036":["鯊鼠","本牌局我方每1回合對敵方主堡造成傷害，此牌便獲得+1|+0。","","「比爾吉沃特沒有地方比海灣更血腥了。看看那些被鮮血養大的鯊鼠，牠們貪婪無比，一群詭異的小東西。」——殘鉤團屠夫","單位",[],["比爾吉沃特"],"史詩"],"06BW038":["巨牙海怪","我方探底後，治療所有友軍單位與我方主堡3點生命值。","","「牠想要什麼？！」\n「牠……牠是衝著柳橙來的！」\n「我的倒刺女神啊，那就把整桶給牠啊！」\n——倒楣的水手","單位",["海怪"],["比爾吉沃特"],"普通"],"06BW030":["娜葛卡布爾之眼","海祭2。\n抽2張牌。","","娜葛卡布爾是保佑之神——前提是你得在崇拜牠的過程\n當中存活下來。","法術",[],["比爾吉沃特"],"普通"],"06BW011":["娜葛卡布爾","召喚此牌時及回合開始：海祭2。若我方最強觸手力量值為12以上，則在手牌生成1張娜葛卡布爾之怒。","","「不管是海蛇之母、偉大海怪或倒刺女神都可以，娜葛卡布爾不在乎我們如何稱呼祂，更不在乎蠢蠢欲動的亡魂。」——伊羅旖","單位",[],["比爾吉沃特"],"史詩"],"06BW021":["海怪教訓誡","對1個敵軍單位造成3點傷害。\n海祭3。\n對敵方主堡造成1點傷害。","","「我們從小就學著在危險海域中要順流而行。一旦與海洋相爭，就是等著葬身魚腹。而祭司的第一項考驗，自然就是要忘卻這個教導；你必須全力與大海搏鬥。因為真傳之人並不隨波逐流，真傳之人就是海洋之流。」——伊羅旖","法術",[],["比爾吉沃特"],"史詩"],"06BW045":["嗅血獵殺","對任1目標造成1點傷害，然後進行備戰。","","沒有什麼東西能夠趕跑在開膛手海灣打轉的鯊魚。牠們一嘗過鮮血的味道，就更加貪得無厭了。","法術",[],["比爾吉沃特"],"普通"],"06BW028":["鞭笞觸手","海祭2，然後使我方最強觸手與1個敵軍單位互相打擊。","","「人生是場考驗，而苦痛是我們的老師，給我們帶來震撼教育。」——伊羅旖","法術",[],["比爾吉沃特"],"稀有"],"06BW035":["深海之聲","攻擊：海祭1，並在本回合給予我方最強觸手蠻力。","","召喚娜葛卡布爾並不需要什麼儀式。只要你的靈魂足以與海洋對抗，祂就會響應你的召喚。每次漲潮、大浪拍打，都是只有少數人才能撐過來的戰鬥。","單位",[],["比爾吉沃特"],"稀有"],"06BW015":["回應祈禱","海祭2，或消耗5點魔力海祭4。","","向娜葛卡布爾祈禱並不是單純的拜求、要求或收受。祂的祝福就像人生一樣：努力、掙扎、督促自己，獎勵有時候就會自然來到你身邊。","法術",[],["比爾吉沃特"],"普通"],"06BW007":["守望神像","回合開始：對此牌造成2點傷害並海祭1。","","當駭人之物從闇影島蜂湧而出，神像就會發出耀眼光芒，宛如海天之際的閃亮燈塔。","單位",[],["比爾吉沃特"],"普通"],"06BW037":["萬貫賞金","顯化1張我方有足夠魔力能打出的侍從單位。","","「巴茲，你確定要再試一次嗎？」\n「無三不成禮啊，蓋夫。何況這座臭城市的所有目標，我們應該都打過了。」\n「是打過沒錯，但打不過。」——未成氣候的賞金獵人巴茲和蓋夫","法術",[],["比爾吉沃特"],"史詩"],"06BW041":["耍老千","從敵方手牌的非英雄牌中2選1，在手牌生成1張該牌的複製牌。洗劫：此牌魔耗值-1。","","「我有『五』張Ace，看來又是我贏了！」——鼬詐老千","法術",[],["比爾吉沃特"],"稀有"],"06BW016":["布爾魯瞭望兵","召喚此牌時，海祭3。","","簡單的人生最甜美。海水灑在臉上，鳥兒在耳邊高歌……而海平線上有著簡單明瞭的敵人。","單位",[],["比爾吉沃特"],"普通"],"06BW009":["布爾魯首領","出牌：使1個魔耗值為1的友軍單位發動額外攻擊。","","「想起海洋的智慧吧！如果你不動，就會被浪潮推動！如果你迷失了，就聽從我聲音的引導，因為你的敵人必定知道前進的方向。」 ","單位",[],["比爾吉沃特"],"稀有"],"06BW043":["比爾吉沃特泰爾石","在手牌生成1張飛逝海之霸主、調皮小飛或更多的火藥！","","「玩泰爾石的時候別想識破吹牛的人，比爾吉沃特到處都是大騙徒。如果你真的想要贏，就好好看著對方的手。」——逆命","法術",[],["比爾吉沃特"],"稀有"],"06BW018":["史帝姆","召喚此牌時，隨機召喚1個空殼。\n我方召喚魔耗值為1的單位時，給予最強敵軍單位弱勢。","","伊芙琳和史帝姆的初次相遇既暴力又刺激。伊芙琳還記得當時她鞭打他時，他露出的笑容洋溢著喜悅，而輪到他反擊時，他也熱情地回敬她。伊芙琳終於戰勝史帝姆後，選擇不殺這隻下等惡魔，反而使他永遠成為自己的部下。她會這樣做，說不定是想跟他同享屠殺生靈的好滋味。","單位",[],["比爾吉沃特"],"普通"],"06SH014":["虛空怪物","召喚此牌時，賦予此牌本牌局我方場上出現過的所有增益特性。\n若我方召喚擁有新增益特性的友軍單位，則賦予此牌該特性。","","「我曾經聽說關於虛空入侵的傳說，以及它所帶來的破壞。但現在親眼見識到後……我應該永遠不會忘記那一幕，或是心裡的恐懼。」——貝爾薇斯倖存者","單位",[],["蘇瑞瑪"],"史詩"],"06SH016":["巢穴使者","出牌：賦予1個單位與此牌彼此的增益特性。","","「牠對我說話……好像牠認識我一樣，好像要我去見……某個東西……」——凱莎","單位",[],["蘇瑞瑪"],"稀有"],"06SH009":["凱莎","召喚此牌時及回合開始：若我方擁有攻擊主動權，則在手牌生成1張二階蟲甲。","我方已進化。","幾天前，凱莎感覺到自己的蟲甲在興奮地顫抖，並不斷把她拉向蘇瑞瑪的海岸。事情有點不對勁，凱莎心想。接近貝爾薇斯時，她很快就發現，一場可怕的大襲擊 \n即將來臨。","單位",[],["蘇瑞瑪"],"英雄"],"06SH048":["傳承儀式","顯化1個本牌局遭摧毀的我方地標並召喚之。","","「保存這一刻。」——極靈","法術",[],["蘇瑞瑪"],"普通"],"06SH037":["枯爪巴凱","出牌：賦予1個敵軍單位弱勢。\n敵軍單位受到挑戰時，本回合給予其-2|-0。","","牠們逐漸陷入瘋狂，心智宛如被狂風吹襲的沙丘般，只剩下憤怒的種子發芽而成的怒火，沒有任何綠洲的甘泉能夠澆熄。","單位",[],["蘇瑞瑪"],"普通"],"06SH008":["貝爾薇斯長老","","","看到眼前的可怕景象，莎拉泰不禁往後退。屠夫善良的女兒菲萊被壓死了，躺在那裡一動也不動。趴在她身旁的是漁夫的兒子哥魯布，他那毫無生氣的手，仿佛依然還在伸向他的愛人。許多回憶、生命都消失了。莎拉泰咬緊牙關，轉頭面對那個邪惡怪物，準備好犧牲生命，以拯救其他族人。","單位",[],["蘇瑞瑪"],"普通"],"06SH042":["蘇瑞瑪泰爾石","在手牌生成1張飛逝庖丁解牛、審判之重或靈魂烈焰。","","「玩泰爾石的重點不是在有沒有贏，而是你玩的時候有沒有型！」——埃可尚","法術",[],["蘇瑞瑪"],"稀有"],"06SH050":["時間之砂","本回合給予所有敵軍單位-2|-0。在手牌生成1張飛逝百年一瞬。","","時間之砂毫不留情地流動著，它們的大局殘酷又冷漠，但不是所有人都是其無情計畫下的奴隸……","法術",[],["蘇瑞瑪"],"稀有"],"06SH049":["榮耀之喚","本牌局我方每召喚1位不同的飛昇者，此牌魔耗值便-2。\n顯化1張魔耗值為9以下的神皇牌組卡牌。","","「看看我們的偉業，看看我們所建立的一切！」\n——阿祈爾","法術",[],["蘇瑞瑪"],"稀有"],"06SH036":["重生墓室","我方召喚英雄時，摧毀此牌以賦予其+2|+1與法盾。","","納瑟斯從石棺中出來，他的心智清晰，傷口也痊癒了。他寫下了一些筆記，然後看著懸吊在上方的石棺，思索裡面異形野獸的精神狀態如何。這個魔法是否能夠讓巴凱的心智恢復正常，只有時間才知道。其他的飛昇者曾經反對使用這個魔法，但他們現在都已不復存在，而雷尼克頓瘋狂依舊。納瑟斯又寫下了幾個字，希望自己終於找到了拯救弟弟的方法。","地標",[],["蘇瑞瑪"],"史詩"],"06SH011":["極速充能","賦予1個友軍單位蠻力與法盾。","","「我來教你戰鬥的方法。」——凱莎","法術",[],["蘇瑞瑪"],"普通"],"06SH017":["虛空探索者","對1個侍從單位造成1點傷害。若我方已進化，則改為對1個單位造成 3點傷害。","","「很痛吧？」——凱莎","法術",[],["蘇瑞瑪"],"稀有"],"06SH007":["虛空幼獸","在手牌中時，此牌會擁有1項隨機特性（每回合會改變）。召喚此牌時，賦予此牌該特性。","","達哈娜記得當天早上打開窗戶，便立即聞到新鮮出爐的麵包香味。在更遠處，漁夫已經開始將當天的漁獲拖到市場去了。她記得自己心裡想著，這天一定會是美好的一天。","單位",[],["蘇瑞瑪"],"普通"],"06SH010":["虛空能量炮","","","貝爾薇斯城突然發生恐怖的虛空大爆發。大部分市民都陷入混亂恐慌，立刻拼命逃離城市。但可耶米似乎不急著走。","單位",[],["蘇瑞瑪"],"普通"],"06SH034":["主宰狂女","召喚此牌時，隨機召喚1個空殼。\n我方召喚魔耗值為1的單位時，賦予其+1|+0。","","有時候，強大的人也希望感到無力。","單位",[],["蘇瑞瑪"],"史詩"],"06DE045":["鼓舞之光","賦予所有友軍單位活力。","","「不用再躲藏了！走進光芒之中，與我一起閃耀吧！」——拉克絲","法術",[],["蒂瑪西亞"],"普通"],"06DE038":["狙魔首領埃德雷德領主","其他友軍單位及我方主堡獲得堅忍。\n友軍單位承受傷害且未陣亡時，賦予其+1|+1。","","「親愛的妻子，我無意中聽到你熱切地喃喃自語。在公共場所談家事時得小心一點，隔牆有耳啊。」","單位",[],["蒂瑪西亞"],"史詩"],"06DE037":["皇家法令","本回合給予1個友軍單位+2|+2和挑戰者，或召喚1位名譽領主。","","「遵命，嘉文國王陛下。我們會不惜代價完成\n任務。」——名譽領主貝瑞特．布斐利","法術",[],["蒂瑪西亞"],"稀有"],"06DE035":["反魔法英石柱","所有法術的魔耗值+2。\n倒數2","","狙魔者會在他們的根據地周圍豎立起巨大的反魔法英方尖碑，讓最強的法師都拿他們沒轍。","地標",[],["蒂瑪西亞"],"普通"],"06DE042":["蒂瑪西亞泰爾石","在手牌生成1張飛逝稜光障壁、束縛或蒂瑪西亞萬歲！","","「為什麼要叫『果敢王策』？女王也得冒險啊！」——克勞菲爾德的希莉亞","法術",[],["蒂瑪西亞"],"稀有"],"06DE036":["護子龍父","攻擊：抽1張單位牌，若為龍族，則以攻擊中狀態召喚之。","","「還好根據我的研究，龍父大多數的時間都在離幼雛遙遠的地方捕食。萬一牠回來，我們就會全部變成龍飼料啦！哈哈！」——蛋頭學者安登．梅恩","單位",["龍族"],["蒂瑪西亞"],"史詩"],"06DE030":["咒慾迷塵","隨機召喚1個空殼，並賦予其+1|+0。","Missing Translation","「親愛的，靠近點……」——伊芙琳","法術",[],["蒂瑪西亞"],"普通"],"06SI012":["關","攻擊：此牌跟友軍單位一起獲得聖化增益。從敵方主堡汲取2點生命值。","此牌造成10點以上傷害。","關一路剪剪剪，深入黯霧，心裡想著它怎麼會完全覆蓋這個地方。就在那時，陰暗的森林中出現一間魔法宅邸，猶如一座燈塔照亮周圍。它是那麼的引人注意、那麼的雄偉——難怪關會被它所吸引。","單位",[],["闇影島"],"英雄"],"06SI020":["憎恨尖刺","擊殺1個友軍單位，對1個單位造成3點傷害。若起始牌組裡有伊芙琳，則隨機召喚1個空殼。","","「叫越大聲越好。」——伊芙琳","法術",[],["闇影島"],"稀有"],"06SI013":["永恆舞者","攻擊：復甦1個力量值不大於此牌的最強已陣亡友軍單位（永恆舞者除外），使其處於攻擊中並賦予閃靈。","","第一個踏入舞池的人，往往需要最大的勇氣。不過這對雙胞胎總是樂意承擔這個重任。","單位",[],["闇影島"],"史詩"],"06SI037":["闇影島泰爾石","在手牌生成1張飛逝同命、靈魂之旅或闇影島印記。","","「精美的……裝飾。棋子……學習規則。有趣的遊戲。驚人……舉世無雙的手藝……無法忘懷。」——拼湊起來的無名日記","法術",[],["闇影島"],"稀有"],"06SI040":["哈洛威歸來","復甦最強已陣亡友軍侍從單位，並賦予其閃靈與威嚇。本回合給予所有敵軍單位-1|-0。","","我們可以暫時擊退亡魂，但他們永遠都會捲土重來。","法術",[],["闇影島"],"史詩"],"06SI027":["穿針引線","擊殺1個友軍單位，以對1個敵軍單位造成等同該友軍單位力量值的傷害。","","「出針！」——關","法術",[],["闇影島"],"普通"],"06SI018":["沃拉","召喚此牌時，隨機召喚1個空殼。","","沃拉跟其他惡魔不同，她不會用假面孔去引誘獵物，因為她一心只想著充飢，沒空去管其他事。她不是一隻會耐心跟蹤獵物的捕食者，而是一隻瘋狂進食的野獸。","單位",[],["闇影島"],"稀有"],"06SI015":["演奏開始","召喚2個幽靈樂團。","","「炒熱氣氛！雙倍速度！」——黯霧指揮","法術",[],["闇影島"],"普通"],"06SI030":["正式邀請","在手牌生成2張曾在本牌局中陣亡的友軍侍從單位牌。","","「我們到了，親愛的。聽說今晚會非常棒，而且應該會看到很多熟面孔！」——幽靈派對客","法術",[],["闇影島"],"稀有"],"06SI026":["黯霧指揮","遺願：在手牌生成1張幽靈樂團。","","「朋友們，不停地演奏吧！讓這場演奏會前所未有地熱烈起來！」","單位",[],["闇影島"],"稀有"],"06SI033":["鬼影陵墓","倒數2：復甦最強已陣亡友軍單位。","","劍擊盾牌的聲音像是在宣告死神的到來一般，吸引了留戀人世的靈魂，就連死亡也無法澆熄他們的意志。","地標",[],["闇影島"],"史詩"],"06SI016":["狂歡主持人","","","「誠摯邀請您蒞臨『午夜狂歡』，參加一場永生難忘的派對。歡迎來到白瓷宅邸，跟我們一同盡情跳舞、飲酒作樂！（派對將於午夜13時結束）」\n——字跡優美的邀請卡","單位",[],["闇影島"],"稀有"],"06SI028":["幻影管家","","","超棒的派對，怎麼少得了超棒的茶點呢？","單位",[],["闇影島"],"普通"],"06SI043":["林下新生","亂擲3張牌。從1個單位\n汲取2點生命值。","","就算是在闇影島，枯老的植物也會冒出新芽。","法術",[],["闇影島"],"普通"],"06SI022":["幽靈情人","","","不知道他是一隻鬼、一個回憶，或是一個夢，總之他看起來很熟悉……","單位",[],["闇影島"],"普通"],"06SI019":["蘇特爾","召喚此牌時，隨機召喚1個空殼。","","「在這些鬼島上，要提防那些面帶笑容的人。有三種可能性：第一，他們是新來的，不知道這個地方有多殘酷；第二，他們可能已經瘋了；第三，他們可能根本不是人，是某種完全不同的存在。無論如何，總之要小心。」\n——延斯．托曼的筆記","單位",[],["闇影島"],"普通"],"06NX022":["軍團重任","抽1張力量值為5以上的友軍單位，或本回合使1個友軍單位成長到力量值5。","","「極其少數的人有幸為特菲利安軍團效命，可別浪費這個機會。」——特菲利安鑑定員","法術",[],["諾克薩斯"],"史詩"],"06NX019":["諾克薩斯逃兵","攻擊：本回合此牌的力量值提升至等同於有裝備的最強友軍單位。","","「又開始做夢了，在黑暗中聽見了那個聲音。十年……做為帝國的狗奴才度過了天殺的十年。被命令去到不知道哪裡，殺死不知道是誰還是什麼東西。這一切到底是為了什麼？諾克薩斯的榮耀？榮耀是個美麗的謊言，而我上當了。但我不會再受騙了。慨影為我展示了一條不同的道路——復仇之路。」\n——羅伊斯，屠夫的日記","單位",["邪教徒"],["諾克薩斯"],"普通"],"06NX023":["愛歐尼亞釣魚大師","召喚此牌時，此牌進行應變。","","崔絲克的人生在她最後一次參加釣魚大賽時發生了巨大的變化，她居然釣到了差點淹死的賈克斯。他不願談論發生了什麼事，但崔絲克每次炫耀這件事時，差點吃掉賈克斯的海怪都會被她描述得越來越大隻。","單位",["武器大師"],["諾克薩斯","愛歐尼亞"],"普通"],"06NX044":["潛伏拉網者","攻擊：使本回合其他攻擊中友軍單位的力量值成長至此牌的力量值。","","「盡責的母親會教導孩子狩獵，但要更上一層樓……就要親自為他們狩獵。」——伊莉絲","單位",["蜘蛛"],["諾克薩斯"],"普通"],"06NX041":["吸血鴿","支援：本回合對受此牌支援的友軍單位造成1點傷害，並賦予此牌+1|+1。","","「餵鳥還挺有趣的。我跟可憐的費歐瓦打賭說牠們跟波登的巨異蜥一樣嗜血。我只能說：真不愧是諾克薩斯的鴿子啊！」——血色督察愛德文．科坦","單位",["鳥族"],["諾克薩斯"],"史詩"],"06NX020":["冥血弩砲","可消耗8點魔力改為打出祖瑞塔的娜內卡。","","眾所周知，瓦羅然東部的乾草原非常貧瘠，不適合諾克希人圖個溫飽或居住。但是隨著幾個世紀過去，一個渴望擴張的新帝國誕生了。本來沒種穀物的土地在新的耕作技術幫助下變得肥沃，而過去安然地掩埋起來的武器也因此再次出土。","裝備",["冥血族"],["諾克薩斯"],"史詩"],"06NX039":["血色狂宴","對1個友軍單位造成2點傷害，以在本回合給予所有友軍單位+2|+0。","","「少了尖叫聲，怎麼能算是鮮血的盛宴呢？所以快放聲尖叫吧，小子。」——弗拉迪米爾","法術",[],["諾克薩斯"],"普通"],"06NX026":["大錘","","","維錫德不是波登速度最快的角鬥士，但當他的大錘命中目標時，對手通常會直接被打成肉醬。","裝備",[],["諾克薩斯"],"普通"],"06NX034":["飆悍戰士","使1個已裝備的友軍單位打擊1個敵軍單位。","","「血盟兄弟，再次結成！」——諾克薩斯叛逃者","法術",["邪教徒"],["諾克薩斯"],"稀有"],"06NX036":["符文隨從","召喚此牌時，進行重鑄。","","幾個月來，他在寒風和冷雨中艱難跋涉，做著吃力不討好的工作，似乎看不到盡頭。然而，盡頭終究是到了。他終於要出人頭地了。","單位",[],["諾克薩斯"],"普通"],"06NX027":["野蠻衝突","摧毀1個敵軍單位的裝備，並使1個友軍單位與其互相打擊。","","「一二三，哀哀叫，\n士兵全身火跳跳，\n四五六，被火燒，\n泰貝爾咧嘴哈哈笑！」——安妮","法術",[],["諾克薩斯"],"稀有"],"06MT035":["鮮血編織者修蘭妮","每有1個力量值提升過的友軍單位陣亡，此牌便獲得+2|+2。\n強化16：將此牌幻化為星靈之禍修蘭妮。","","修蘭妮看著阿納可跪倒在她面前，臣服於他誓言要用盡一切力量消滅的惡敵。慢慢地，他的心跳逐漸與其他人同步。於是又有一個人的心智落入了她的掌控之中，成為了她的傀儡。","單位",["冥血族"],["巨石峰"],"史詩"],"06MT007":["天外六足龍","強化5：蠻力。","","「啊，我明白了……山上的圖形只不過是印記，讓來自星際的存在可以降臨於此……」——傳智者斯坎因","單位",["龍族"],["巨石峰"],"稀有"],"06MT037":["武器之封","泯滅1個友軍單位，然後生成1張能力值相同的墮落之形。","","埋葬在這些武器中的墮落神鬥士無法輕易被擊敗，因此只能封印。","法術",[],["巨石峰"],"稀有"],"06MT031":["正義星靈彌赫菈","回合結束：賦予手牌及場上所有友軍單位+1|+1。\n強化5：隱密、吸血與蠻力。","","「有些人將星靈視為神祇，有些人視他們為來自他界的信使，有些人則害怕著他們……或許他們是該恐懼沒錯。」——傳智者斯坎因","單位",[],["巨石峰"],"史詩"],"06MT010":["聖劍審判","本回合給予1個友軍單位「此牌免疫傷害及死亡」。\n本回合給予所有友軍單位+1|+0。","","「正義之炎將會守護你！」——凱爾","法術",[],["巨石峰"],"稀有"],"06MT016":["飛翼信使","強化3：隱密。","","「啊啊……我認得你。你的出現只代表一件事……那就是我受到了召喚。」——雷茲","單位",[],["巨石峰"],"普通"],"06MT015":["淨化聖炎","賦予手牌中2個友軍單位+2|+2。","","「正義之火啊，燃燒一切罪惡吧！」——凱爾","法術",[],["巨石峰"],"普通"],"06MT042":["暮光鴞","破曉：本回合給予所有破曉友軍單位+1|+1。\n夜臨：賦予所有夜臨友軍單位+1|+0。","","在黃昏時分和破曉前，可以聽見貓頭鷹的咕咕叫聲，那聲音提醒著人們，黃昏與黎明之間存有的幽微界域。","單位",["鳥族"],["巨石峰"],"稀有"],"06MT008":["凱爾","力量值提升的友軍單位每攻擊1次，此牌便獲得+1|+0。\n召喚此牌時，賦予所有友軍單位+1|+0。\n強化6：快速攻擊。","回合開始：此牌力量值為11以上。","「蒂瑪西亞人稱她為雙翼守護者，但對我們這些星空之下的巨石峰人來說，她是正義女神的女兒，背負著神聖使命，揮舞著星火熾刃。」——傳智者斯坎因","單位",[],["巨石峰"],"英雄"],"06MT004":["流浪牧人","出牌：挑選1個友軍單位，使其進行應變。若未挑選，則改為此牌進行應變。","","賈克斯從發狂妖精的手中救出洽斯卡的牧群；然後換洽斯卡從發狂妖精的手中救出賈克斯。只要他們兩個都沒有亂跑，就會一起旅行。","單位",["武器大師"],["巨石峰","班德爾城"],"普通"],"06MT017":["聖火管理者","強化3：吸血。","","「傳說彌赫菈離開這裡時留下了她的一部分：一團猛烈耀眼的神聖火焰。多年以來，我的家族一直看顧著聖火，一邊不讓它熄滅，一邊期盼著她的歸來。」","單位",[],["巨石峰"],"稀有"],"06MT040":["蒼穹庇護","本牌局我方裝備單位後，此牌魔耗值-2。\n本回合給予1個友軍單位法盾。","","仰望夜空，將目光集中在蒼穹的一小塊。現在想像一下所有生活在其中的人，所有的知識和經驗都傳承了數千年。想像一下，把所有資訊都濃縮成一個小碎片，小到足以握在你的掌心。想想你會得到多少智慧、多少力量。","法術",["邪教徒"],["巨石峰"],"稀有"],"06MT034":["天界衝擊","泯滅1個單位或地標。治療我方主堡3點生命值。","","「誰會在我們亟需之時前來伸出援手呢？」\n——蘇瑞瑪長老","法術",[],["巨石峰"],"稀有"],"06MT033":["龍族臂鎧","此牌的裝備者視為龍族。","","許多人會呼喚龍族的力量，不過這在符文大地各處會以不同的形式表現。那些祈求天界龍族之力的人，可能會發現他們的內在擁有一股力量，如同星星一樣明亮熾熱。","裝備",[],["巨石峰"],"普通"],"06MT053":["慷慨寶石匠","我方打出法術時，隨機賦予手牌中1個友軍單位+1|+1。","","她的雙眼傳達出來的是良善，但表情卻隱藏在面紗之後。她給予準備朝聖者水晶念珠，卻不求一點回報，因為巨石峰頂將會索求代價。","單位",[],["巨石峰"],"史詩"],"06MT006":["冥血磁石","支援：賦予受此牌支援的友軍單位+1|+1。\n可消耗8點魔力改為打出霍菈姿。","","那些囚禁冥血族的人或許認為，將傳說戰士霍菈姿困在星辰金屬球中就足以讓她的暴躁之性逐漸衰褪。但隨著她的將軍開始蠢蠢欲動，霍拉茲也脫離蟄伏的狀態；她發現即使是巨石峰的古代守護者，也會受到來自遠方耳語所說的承諾誘惑。","裝備",["冥血族"],["巨石峰"],"史詩"],"06MT018":["護律神使","出牌：擊暈力量值小於此牌的敵軍單位。","","「恐怕那天真的到了……金色雙翼的正義女神帶著聖光軍團回來了！」——傳智者斯坎因","單位",[],["巨石峰"],"普通"],"06MT052":["天賜聖典","賦予手牌與場上1個友軍單位活力。","","「以神聖恩典之名。」——凱爾","法術",[],["巨石峰"],"普通"],"06MT032":["月環邪教徒","召喚此牌時及本牌局我方裝備友軍單位後，在手牌生成1張靈力寶石。","","她企求停止日與月、晝與夜之間的衝突。那把弓給了她力量，雖然她付出了沉痛的代價──但她還是立下誓言，希望能徹底結束戰爭。 ","單位",["邪教徒"],["巨石峰"],"普通"],"06RU008":["賈克斯","起源：武器達人。\n自動裝備：伊卡西亞之光。","進行攻擊的已裝備友軍單位力量值總和為16以上。","幾個世紀前，賈克斯的家鄉被虛空摧毀了。現在他行走大江南北，尋找具備堅強意志和過人膽識的戰士，以便將來某一天能挺身對抗虛空這個可怕的敵人。","單位",["武器大師"],["符文大地"],"英雄"],"06RU006":["雷茲","起源：符文法師。\n召喚此牌時及回合開始：在我方牌組生成2張發掘過往。","此牌在場上時，場上出現\n3種不同的世界符文。","雷茲爬上了山脊，身旁凱爾的使徒不發一語。他俯瞰著飽受戰爭所苦的大地，看見了底下不斷爭鬥的冥血怪物。幾個世紀以來，他看著人類一次又一次地讓自己陷入危機，令他不禁心想他至今的努力是否都是徒勞？難道無論如何，符文大地都注定會毀滅嗎？","單位",[],["符文大地"],"英雄"],"06RU005":["慨影","起源：闇魂收割者。\n自動裝備：冥血罪鐮。\n此牌擊殺敵軍單位時，治療此牌2點生命值。","此牌打擊2次。此牌升級時會被召回。","當另一具屍體倒下時，慨影樂得大笑，他知道自己很快就會解放第二把冥血武器。在其體內，勒哈斯特已經迫不及待，他知道慨影的末日終於到來了。","單位",["冥血族"],["符文大地"],"英雄"],"06RU026":["厄薩斯","起源：滅世劍魔。\n自動裝備：冥血劍魔。\n召喚此牌時及打擊：治療我方主堡2點生命值，若手牌中沒有劍魔滅世，則在手牌生成1張。","我方打出劍魔滅世。","就算遠在大陸的彼岸，厄薩斯也感覺得到她的甦醒，復仇的業火依舊在他心中燃燒著。他已經摧毀了她的雕像，準備好與那伊卡西亞孬種展開最終決戰。只要殺死她，他就能離開這可悲的世界。","單位",["冥血族"],["符文大地"],"英雄"],"06RU009":["法洛士","起源：懲戒之箭。\n自動裝備：冥血之弓。","我方指定7個以上友軍單位為目標。","假若經過時間推移，現已成為冥血族的那個男人，想起了過去的自己，聽見了內心的聲音呢？假若他並未一味壓抑那些聲音，轉而為相信的話呢？","單位",["冥血族"],["符文大地"],"英雄"],"06FR004":["武器工匠學徒","首次裝備友軍單位時，鑄煉該單位。","","鄂爾在很多年前就創造出活火爐，直到最近才開始想找回它。但鄂爾從沒想過它會為了尋找新主人而浪跡天涯。","單位",[],["弗雷爾卓德"],"普通"],"06FR011":["鄂爾","出牌：此牌裝備1個友軍單位的複製裝備牌，或是手牌中的最強裝備。\n攻擊：鑄煉此牌2次。","友軍單位單次打擊造成8點以上傷害。","如果有人問鄂爾為什麼他沒有耐心，他只會回答自己是有耐心的。事實上，他驚人地有耐心，這就是為什麼他的工藝無人能及。他只是對人沒有耐心。但是沒人問到這點，所以他也從沒說明過。","單位",[],["弗雷爾卓德"],"英雄"],"06FR035":["熱心相助","本回合給予1個友軍單位+0|+3。若該單位已負傷，則改為給予其+2|+3。","","「別擔心，小普羅，我來保護你！」——布郎姆","法術",[],["弗雷爾卓德"],"普通"],"06FR034":["無情酷寒","凍傷最強敵軍單位。若本牌局已裝備過友軍單位，則再複製一次。","","阿娜卡跑速之快，弗雷爾卓德本身都像是被她拋在身後。在她的血腥屠殺中倖存下來的那些人，很快就感覺到皮膚冰冷，心臟也逐漸停止跳動。","法術",["邪教徒"],["弗雷爾卓德"],"普通"],"06FR018":["冥血戰矛","攻擊：賦予我方牌組最上方2個友軍單位+1|+1。\n可消耗8點魔力改為打出阿娜卡。","","「戰爭之母，酷寒日漸嚴峻，艾伐洛森人已經一路竄逃到哨站之後，而北方則是大海……我們只能往東邊前進了。」\n「不，戰爭之母啊，別聽他的。那是蒼白之地的方向，接著便是呢喃荒野。我認為寧可受死，也比踏上受詛咒的土地好。」\n「你倆真該慶幸，族人性命的重擔並非扛在你們的肩膀上。」\n「說得不錯，戰爭之母。但或許有第三種辦法。讓我先前往東方一探究竟吧，一名斥侯之死，總比全族人賠上性命來得好。」\n——戰爭之母史瓦妮，正與將軍商討著對策","裝備",["冥血族"],["弗雷爾卓德"],"史詩"],"06FR012":["王牌工匠","召喚此牌時，在手牌生成1張時間與奉獻。","","「我母親告訴過我鄂爾的故事，就像她母親告訴她的一樣，還有她母親之前的世代……現在我也會告訴你。仔細聽，不要打斷。很久以前，在一片廣闊、炎熱、翻騰的大海……」","單位",[],["弗雷爾卓德"],"普通"],"06FR005":["鄂爾的鍛造場","召喚此牌時和回合開始：在手牌生成1張飛逝時間與奉獻。","","獨自一人在爐心之家的鍛造場裡，這裡只有熔化的金屬在下方緩慢流動的聲音，還有鐵鎚在鐵砧上打出的叮叮聲響……他很享受這種感覺。","地標",[],["弗雷爾卓德"],"稀有"],"06FR040":["雪麒麟","召喚此牌時，本牌局我方每召喚1個卡牌次類，便賦予所有友軍單位+1|+1。","","「……然後有個超大生物，在照顧所～有的小生物……」——少女英格娃","單位",[],["弗雷爾卓德"],"史詩"],"06FR020":["冰裂","對所有目標造成1點傷害，或摧毀1個單位的裝備。","","酷寒不會對任何人事物顯露慈悲。","法術",["元素"],["弗雷爾卓德"],"稀有"],"06FR027":["絨面硬殼巨魔","強化8：再生。","","雖然巨魔的腦筋通常都不太靈光，但卻能夠克服各種環境生存。","單位",[],["弗雷爾卓德"],"稀有"],"06FR032":["爐血族的贈禮","治療我方主堡4點生命值，並賦予我方牌組所有單位與裝備+1|+1，再抽出其中1張牌。","","「來吧，在火堆邊暖暖身子。」——爐血族修補匠","法術",[],["弗雷爾卓德"],"史詩"],"06FR022":["熾焰吹息","鑄煉1個友軍單位並對所有單位造成1點傷害，然後再重複1次。","","「鋼鐵般的意志必定經過鍛鍊！」——鄂爾","法術",["元素"],["弗雷爾卓德"],"稀有"],"06FR021":["氣噗普羅","強化3：蠻力、再生與堅忍。","","「拜託，你得吃藥才行！吃了你才會康復啊！」\n——少女英格娃","單位",["普羅"],["弗雷爾卓德"],"普通"],"06FR023":["鍛造巨像","此牌首次裝備時，在手牌生成1張此牌魔耗值為4的複製牌。賦予該牌裝備的能力值。","","雖然他不想承認，但鄂爾對這尊巨像還是很滿意的。它不僅確切達成了鄂爾交付的任務，而且最棒的是，它從不說話。","單位",[],["弗雷爾卓德"],"史詩"],"06FR008":["爐血族修補匠","出牌：鑄煉1個友軍單位2次，並治療該單位與我方主堡3點生命值。","","當鄂爾決定要離開這個世界時，所有的爐血族就此消失。幾個世代過去了，他們的名字被全然遺忘。然而最近，鄂爾的傳說重新傳了開來，有傳言說有些人已經開始回歸爐血族之道。","單位",[],["弗雷爾卓德"],"普通"],"06FR009":["武器工匠大師","出牌：鑄煉1個友軍單位。","","最初，菲斯克對學徒的想像是，一個敬業、認真對待自己的技藝、強壯、有能力的人。金卓拉完全不符合上述條件。她經常做白日夢，勤於玩樂倦於工作，總是在逗弄她那隻傻乎乎的小烏龜。不過……她的確有在學習，這才是最重要的。","單位",[],["弗雷爾卓德"],"普通"],"06FR024":["骨製棒槌","","","「喀嘣脆！」——獨行狂戰塔卡茲","裝備",[],["弗雷爾卓德"],"普通"],"06FR017":["冰谷邪教徒","已裝備的友軍單位擁有蠻力。","","冬之爪說得沒錯，艾伐洛森人一直都太過軟弱。我們需要新的領導者，一個不是透過和平手段統一弗雷爾卓德，而是征服他族，統治凍土的領導者。 ","單位",["邪教徒"],["弗雷爾卓德"],"稀有"],"06FR041":["凜冬之觸","獲得1格魔力寶石槽位。開悟：此牌魔耗值為1。抽1張牌。","","你手中的寶石表面傳出了奇異的符文脈動。伴隨著一道詭異的閃光，寶石的光芒脫離表面，化作冰冷的漩渦環上你的手臂，但你感覺到的並不是刺骨寒意，而是一股活力，彷彿這份冰冷是在將其中的力量注入給你一般。 ","法術",["元素"],["弗雷爾卓德"],"史詩"],"06FR036":["野性祕術","獲得1格魔力寶石槽位。\n召喚1位野魂祕術師。","","「眾靈與群星……再次將我們團結在一起。」\n——全知希亞拉","法術",[],["弗雷爾卓德"],"史詩"],"06BC015":["諾拉","打擊主堡：將1張神祕傳送門植入我方牌組最上方4張牌中。","我方召喚6個以上生成的友軍單位。","諾拉工作的速度很快，心繫著家鄉。傳送門工藝是出了名的棘手工作，她甚至還沒喝到今天的第一杯茶。但是諾拉就是喜歡這種難題，尤其是會讓她絕望地迷失在時空空隙中的那種。她的工作速度又加快了，心心念念著她的貓，怕牠會擔心並期待著主人回來餵晚餐。","單位",["約德爾人"],["班德爾城"],"英雄"],"06BC043":["普羅故事","在手牌隨機生成3張魔耗值為1的普羅牌。","","「……然後辣個普羅就一副『嘿，偶也想要點心！』的樣子，於係縮有的普羅都聚集起來，舉辦普羅大會，討論普羅的問題，像係點心在哪裡、怎摸沒有更多普羅，還有……」——少女英格娃","法術",[],["班德爾城"],"普通"],"06BC051":["香蕉大炮","出牌：對1個單位造成等同此牌力量值的傷害。","","「喂！有人需要補充鉀的嗎？」——出大事前的蕉蕉 ","單位",["約德爾人"],["班德爾城"],"稀有"],"06BC047":["有福同享","本回合給予1個友軍單位其附著單位或裝備的能力值與特性，並將該附著單位或裝備移至另一個友軍單位身上。","","你可能會認為牧羊人在戰場上無用武之地，但他們的才能卻意外實用；只要將所有戰鬥人員視為放牧的綿羊就行了。","法術",["武器大師"],["巨石峰","班德爾城"],"稀有"],"06BC019":["茶藝蝶","召喚此牌時，將1張神祕傳送門植入我方牌組最上方4張牌中。","","雅珊迷失在世界盡頭之前，曾經是一位著名的茶藝師。在嘗試新口味時，兩種茶葉的意外組合讓她陷入了沉睡。她做著奇怪的夢，當中有奇怪的生物和不可能存於世上的建物，在無盡的地平線上映出剪影。但醒來後，她發現這根本不是夢。","單位",["妖精"],["班德爾城"],"普通"],"06BC029":["冥血法杖","打擊：恢復1點法術魔力。\n可消耗8點魔力改為打出巴爾庫克斯。","","巨石峰人推斷，班德爾之森是藏匿冥血兵器的絕佳地點。就性質上而言，班德爾之森是凡人無法駐足的領地，約德爾人也知道要該避開此等邪惡的存在。然而他們卻小看了這種奇妙魔法的力量，以及它對當地植物造成的影響。","裝備",["冥血族"],["班德爾城"],"史詩"],"06BC038":["力量湧現","本牌局我方裝備單位後，\n此牌魔耗值-2。本回合使1個友軍單位成長到4|4。","","「我們體內有如此強大的力量。」——法洛士","法術",["邪教徒"],["班德爾城"],"稀有"],"06BC017":["傳送門嘉年華","將2張神祕傳送門植入我方牌組最上方4張牌中。\n抽1張牌。","","「我應該多走走不起眼的道路！我真蠢，總是忘了整理我的思緒……」\n——諾拉","法術",[],["班德爾城"],"稀有"],"06BC020":["摺紙迴旋刀","本回合我方每發動一個陷阱或祝福，便給予此牌+1|+0。","","折紙工藝的魔法有時實在是難以預料。創造新事物時灌注的想法，與創造物想被創造的渴望一樣重要。","裝備",[],["班德爾城"],"稀有"],"06BC028":["班德爾邪花","本牌局我方裝備友軍單位後，賦予此牌隱密。","","只要是冥血族所經之處，無論是人、植物還是動物都難逃墮落的命運。","單位",["邪教徒"],["班德爾城"],"普通"],"06BC021":["雜物怪","遺願：將1張神祕傳送門植入我方牌組最上方4張牌中。","","雖然前一天才剛剛誕生於世上，然而他很自豪自己是諾拉的助手。而諾拉對他親切的暱稱是馬福。他極度堅持別人要稱自己為「雜物」而不是「廢物」，因為後者帶有負面的意涵。","單位",["妖精"],["班德爾城"],"普通"],"06BC042":["好奇變色龍","友軍侍從單位幻化為其他單位時，將此牌幻化為與之相同的複製單位。","","變色龍眼見之物，即為變色龍自身。","單位",[],["班德爾城"],"稀有"],"06BC023":["迷惑路標","使1個快速或慢速法術重返手牌，或摧毀1個單位的裝備。抽1張牌。","","「唉呀！到底是這邊、那邊，還是……這邊那邊都可以？我老是記不住！」——諾拉","法術",[],["班德爾城"],"稀有"],"06BC041":["零件百貨倉庫","若此牌遭到棄置，則反而會被召喚。召喚機甲約德爾單位時，賦予其1項隨機特性。","","無論大小，無論死活，如果你想找個什麼玩意兒，就來廢料阿比的店看看！只是不要問廢料阿比東西在哪裡，因為她從不編排商品。","地標",[],["班德爾城"],"稀有"],"06BC011":["奇幻旅程","將1張神祕傳送門植入我方牌組最上方4張牌中，並將1張編鐘植入我方牌組最上方的牌中。","","巴德隨心所欲漫遊各界，一邊留心聆聽，因為他知道有劇烈的衝突即將發生，而且那將會是一場終結創生之歌的浩劫。","法術",[],["班德爾城"],"普通"],"06BC032":["五花八門","我方場上每有1個友軍單位，便將1張神祕傳送門和3張編鐘植入我方牌組最上方10張牌中，並將1張閃光炸彈陷阱和3張劇毒膨菇植入敵方牌組。","","「傳送門，到處都是傳送門！」\n——諾拉","法術",[],["班德爾城"],"史詩"],"06BC024":["盡頭守望者","每回合我方首次發動陷阱或祝福時，本回合給予所有友軍單位+1|+1與衝擊。","","賈士博是第一個到達世界盡頭的約德爾人。多年來，他獨自徘徊在曲折的道路和無數傳送門之間，而這些通道似乎讓你哪都去不了。他認為沒人應該走他走過的冤枉路，於是現在賈士博總是幫助迷途旅人找到回家的路。","單位",["妖精"],["班德爾城"],"稀有"],"06BC033":["拳擊機甲","棄置1張牌即可出此牌。","","「看哪！我從沉船的殘骸裡，打撈出了這個拳擊手套；從那叫做佐恩的城市深處，找到了彈簧；還有從蒂瑪西亞的鍛造場中，我找到了金屬！這真可謂是世界的造物！」——巨賈帕帕羅","裝備",[],["班德爾城"],"普通"],"06BC016":["卷軸天使","召喚此牌時，若本回合我方發動了陷阱或祝福，則抽1張牌。","","他認為擁有豐富的知識是自己的職責，因此從行經世界盡頭的旅者手中收集到各種典籍。不幸的是，他似乎被這些知識沖昏頭了。","單位",["妖精"],["班德爾城"],"普通"],"06IO044":["青天歌者","召喚此牌時，使我方牌組法術魔耗值減半，四捨五入。","","「有些人透過冥想尋求祥和，有些則透過自省追求知識。透過展現自我、創作新生找到自身價值的人或許也能帶給他人同樣的平和。」——卡瑪","單位",[],["愛歐尼亞"],"史詩"],"06IO013":["無極劍道","本回合給予1個友軍單位+2|+0。\n在手牌生成1張冥想。","","「無數斬擊的序曲。」\n——易大師","法術",[],["愛歐尼亞"],"稀有"],"06IO023":["冥血龍扇","攻擊：召喚1隻攻擊中的幼龍。\n可消耗9點魔力改為打出裂縫行者卜萊。","","「長久以來，我在世界之間的橋梁感受到一股黑暗的脈動，不斷散發著無聲的憤怒。我心知肚明，不可深入探究那黑暗，然而近來那股脈動卻跳得更快且日漸壯大。我擔心那股力量會開始吸引精神領域的生物。」——慎","裝備",["冥血族"],["愛歐尼亞"],"史詩"],"06IO029":["無極之靈","川流：此牌魔耗值-2。\n召喚此牌時，抽1張法術牌。","","「多蘭大師相信，無極之靈的每隻眼睛，都能賦予人獨特的洞察力。但無論我怎麼努力，從頭盔的鏡片看出去，只看見不同深淺的綠色而已。我到底遺漏了什麼？」\n——多蘭弟子陸伊","單位",[],["愛歐尼亞"],"普通"],"06IO037":["黑焰祭壇","出牌：俘虜1個友軍單位。每回合我方首次攻擊時，召喚1個該單位攻擊中的閃靈複製單位。","","「生命只不過是存在的影子。擁抱黑暗，你將獲得永生。」——劫","地標",[],["愛歐尼亞"],"史詩"],"06IO031":["靈魂之劍","川流：此牌魔耗值-2。","","「人劍合一。」——易大師","裝備",[],["愛歐尼亞"],"普通"],"06IO014":["梵斯塔雅弟子","打擊主堡：召回此牌並幻化為什蒙之風。","","當敵人湧入神殿時，汀咧嘴一笑，終於有機會證明自己了！先是悟空，後是易……他們都對他的天賦不屑一顧。就讓其他人爭先恐後去找他們的「師傅」好了！汀已經準備好了，他就是什蒙之風。 ","單位",[],["愛歐尼亞"],"史詩"],"06IO008":["易大師","回合開始：使手牌中1張法術牌的魔耗值-1，接著川流：賦予我方各處易大師+2|+0。","我方易大師造成12點以上傷害。","易大師一分神，心思又回到了冥血兵器上。自從這武器出現後，易大師就一直有種不祥的預感。他有些學生對其有濃厚的興趣——或許有點太濃厚了——因此他把彎刀放在神殿深處看守著。他努力把這些念頭消除，回到清淨的心繼續冥想。傳承無極之道的教誨是最重要的，而潤兒的潛力無窮，可望繼承衣缽。","單位",[],["愛歐尼亞"],"英雄"],"06IO040":["風分身之術","挑選1個侍從單位，召喚1個該單位的閃靈複製單位；若為敵軍單位，則擊暈之。","","對愛歐尼亞人來說，風是最反覆無常的元素；雖反覆無常，但並非桀驁不馴。 ","法術",[],["愛歐尼亞"],"稀有"],"06IO011":["奇才 潤兒","此牌首次裝備時，本回合給予此牌光盾與吸血。","","易大師一給出指示，潤兒馬上發動一連串的攻擊，精準而無瑕，一如易大師自己的高超身手。在矯捷地閃避過一波攻勢後，易大師向潤兒鞠了個躬，行禮致意，臉上掛著驕傲的微笑。","單位",[],["愛歐尼亞"],"稀有"],"06IO015":["見證者","川流：此牌魔耗值-2。\n出牌：擊暈1個敵軍單位。","","這個人在這場奇異又可怕的表演中扮演著什麼角色？啊，她不僅僅是觀眾，她還是個觀察者，萬物必將映入她的眼簾，接受真理與美的評判。她就是見證者！","單位",[],["愛歐尼亞"],"普通"],"06IO030":["幻霧劍地","召喚此牌時，抽1張裝備牌。\n每回合首次有未裝備的友軍單位裝備時，恢復2點法術魔力。","","「幻霧劍地是神聖之地，這裡的劍已經放了幾個世紀……我相信，只要劍柄上刻著詩句，就會引導持劍者的迷途靈魂，在劍上灌注他們的祝福。」\n——多蘭弟子的手寫捲軸","地標",[],["愛歐尼亞"],"稀有"],"06IO034":["重大抉擇","若本牌局我方已裝備友軍單位，則此牌魔耗值-1。\n本回合給予1個友軍單位+2|+0或+0|+2。","","看著地上四處橫倒的屍體，潤兒的臉上流下憤怒的淚水。她辜負了他們，辜負了師父。而現在，她只剩一條路可走……","法術",["邪教徒"],["愛歐尼亞"],"稀有"],"06IO028":["迷人誘餌","本回合給予1個友軍單位挑戰者；若該單位已裝備，則另抽1張牌。","","只要有正確的餌，就能抓到任何獵物。","法術",["武器大師"],["愛歐尼亞","諾克薩斯"],"稀有"],"06IO025":["暗影之刃狂熱者","本牌局我方裝備友軍單位後，在手牌生成1張暗影之魔。","","在一片黑暗中，他看見了，一個可以劃破陰影的武器。就在這時，他聽到了有聲音在呼喚他，遙遠但十分有力。他循著聲音找到了慨影，是那武器訴說的真理引導著他。","單位",["邪教徒"],["愛歐尼亞"],"普通"],"06IO039":["那歐長尾飛鼠","出牌：召喚1位那歐竊匪，或本回合給予其他友軍單位+1|+1。","","某年冬天的夜晚，這隻長尾飛鼠找到廢棄的營火取暖，而當時也窩在營火邊的，正是他現在的竊匪好夥伴。相識一週後，他們發現彼此都很喜歡惡作劇，並且也都對金幣發出的閃亮光芒著迷不已。","單位",[],["愛歐尼亞"],"普通"],"06IO032":["不配的靈魂","川流：此牌魔耗值-2。\n召回1個單位或地標。若該牌擁有附著單位或裝備，則先將其摧毀。","","「你配不上你所擁有的力量。」——勒哈斯特","法術",[],["愛歐尼亞"],"稀有"],"06IO001":["多蘭弟子","召喚此牌時，在手牌生成1張有備無患。","","「我已經學會了足夠的知識，讓我能繼續延續這個神聖技藝。至於多蘭、他的師父，以及更之前的師父……希望他們的精神能夠引導我的錘子。」\n——多蘭弟子的手寫捲軸","單位",[],["愛歐尼亞"],"普通"],"06IO016":["喚龍者","回合開始：川流：召喚蒼天龍並賦予其閃靈。","","「水的形狀會反映出你的渴望。告訴我，浪人……你看見了什麼？」","單位",[],["愛歐尼亞"],"史詩"],"06PZ034":["海克斯泯滅者","對1個單位造成6點傷害。若該單位將要陣亡，則改為將其泯滅。","","對某些生物來說，光是死還不夠。","法術",[],["皮爾托福&佐恩"],"稀有"],"06PZ006":["震撼回響","在手牌隨機生成1張魔耗值為2的新法術牌，使其魔耗值-2並賦予其飛逝。","","世界上沒有任何聲音比完美的殘響還要動聽。","法術",[],["皮爾托福&佐恩"],"稀有"],"06PZ021":["瑟菈紛","召喚此牌時，在手牌隨機生成1張魔耗值為2的新法術牌。","我方打出9張以上的新法術牌。","瑟菈紛的爸爸從來沒有和她談論過她的地下城「祕密」之旅，也不過問她對舞台偷偷進行升級的事。她本來很確定老爸會禁止她參加佐恩最地下的音樂比賽，但某一天晚上，爸爸卻把比賽傳單塞進了瑟菈紛的門縫底下。她忍不住微笑，然後開始準備。","單位",[],["皮爾托福&佐恩"],"英雄"],"06PZ040":["陋巷酒吧","召喚此牌時，召喚1位陋巷酒吧老闆。\n我方新卡牌魔耗值-1。","","擦乾最後的酒杯後，酒吧老闆停下來看了看他的店。這個地方，這個家外之家，見證過許多陌生人成為朋友，到處留著許多暴亂鬥毆夜留下的塗鴉和凹痕。老闆自顧自地笑了。這裡並不完美，但這是屬於他的地方。","地標",[],["皮爾托福&佐恩"],"史詩"],"06PZ008":["冥血豎琴","可消耗8點魔力改為打出史媞拉圖。","","就在巨石峰人思考著應該將冥血武器分散藏起時，其中一人建議放置在未來將成為佐恩的那塊土地。他們認為，將武器深埋在錯綜複雜的曲折通道牆內是最完美的作法，那地方遠非人類所能及；但對奇里安來說可不是如此。","裝備",["冥血族"],["皮爾托福&佐恩"],"史詩"],"06PZ018":["樂音高亢","對1個單位造成2點傷害。若本牌局我方已打出6張以上的其他新法術牌，則對另1個單位造成1點傷害。","","簡單而純淨。","法術",[],["皮爾托福&佐恩"],"普通"],"06PZ014":["後援會會長","出牌：顯化1張魔耗值為5的法術牌，並將其魔耗值設為2。","","「重點不是誰比較大聲，而是誰的愛心比較大顆！」——後援會會長","單位",[],["皮爾托福&佐恩"],"稀有"],"06PZ030":["靈感計畫","攻擊：在手牌生成1張魔耗值為2的新法術牌，並賦予其飛逝。","","「你知道鴨蛋跟雞蛋誰能畫出最厲害的設計圖嗎？」\n「我猜是……鴨蛋？」\n「不對！是雞蛋，因為——腦力雞蛋！」\n「老爸吼！」\n——瑟菈紛與父親","裝備",[],["皮爾托福&佐恩"],"稀有"],"06PZ046":["魔法方程式","抽2張牌。恢復我方所有法術魔力。","","「魔法只不過是我們還沒探索出的科學原理罷了。」——杰西","法術",[],["皮爾托福&佐恩"],"普通"],"06PZ007":["野心勃勃邪教徒","本牌局我方裝備單位後，在手牌生成1張魔耗值為2的新法術牌，本回合其魔耗值降為0。","","「我一直以來都願意為科學做出犧牲。不管要承擔什麼風險，透過這場交易所獲得取之不盡、用之不竭的力量，對我來說就已經足夠。」","單位",["邪教徒"],["皮爾托福&佐恩"],"普通"],"06PZ041":["狡猾小貓","召喚此牌時，若此牌為生成卡牌，則抽1張牌並賦予此牌+2|+1。","","除了正中午睡大覺和大半夜吐毛球時，貓咪滿腦子都在想要怎麼調皮搗蛋。","單位",["貓族"],["皮爾托福&佐恩"],"普通"],"06PZ036":["佐恩天后","出牌：對所有敵軍單位造成1點傷害。若本牌局我方已打出6張以上的新法術牌，則改為造成3點傷害。","","「佐恩！希望你們準備好要尖叫了，因為我們要再一次把這裡搞得天翻地覆！」——佐恩天后","單位",[],["皮爾托福&佐恩"],"稀有"],"06PZ010":["聲學家","打擊：在手牌隨機生成1張魔耗值為2的新法術牌。","","他曾經夢想要離開佐恩，帶著欣喜雀躍的心情環遊世界。而現在，他的全世界就在她的房間裡沉睡著，等待著明天將帶來的希望之歌。","單位",[],["皮爾托福&佐恩"],"史詩"],"06PZ022":["鼓手獨奏","抽2張牌。\n川流：使其魔耗值各-1。","","音樂的節奏掌握非常重要，但有時候你就是得隨興一點。","法術",[],["皮爾托福&佐恩"],"普通"],"06PZ029":["人見人愛","本回合給予1個友軍單位+2|+0與快速攻擊。\n川流：在手牌生成1張魔耗值為2的新法術牌。","","「佐恩，大聲一點！」——瑟菈紛","法術",[],["皮爾托福&佐恩"],"普通"],"06PZ020":["海克斯技師 橡果","打擊主堡：使手牌中魔耗值最高的法術牌魔耗值-1。","","你不會在任何藍圖上找到他的名字，也不會在任何歌曲的製作名單中找到他，但知情人士都同意一件事：橡果是整個行動的核心。","單位",[],["皮爾托福&佐恩"],"史詩"],"06PZ009":["傳腦魔音","川流：此牌魔耗值-2。\n對所有敵軍單位造成1點傷害。","","只有特別的聲音才不會被佐恩街頭的喧囂蓋過，但這對我們的天后來說不成問題。","法術",[],["皮爾托福&佐恩"],"普通"],"06PZ037":["猛爆琴音","對1個單位造成1點傷害。若本牌局我方已裝備過單位，則對相同目標再複製並施放一次。","","若不和諧音是破壞的噪音，那就繼續亂彈奏吧。","法術",["邪教徒"],["皮爾托福&佐恩"],"稀有"],"06PZ019":["佐恩門房","回合開始：川流：恢復2點法術魔力。","","如果事情順著他的意，那就沒有人進得去。","單位",[],["皮爾托福&佐恩"],"普通"],"06PZ033":["三管頑皮槍v1.0","使我方法術與技能造成1點額外傷害。","","「地點：第3區，19B地下道路\n物品：非法槍枝\n備註：於『汙水坑之光』行動期間沒收。武器非常危險，處理時務必小心。」\n——皮爾托福警備隊現場報告","裝備",[],["皮爾托福&佐恩"],"普通"],"06BW029":["皮爾托福放逐者","召喚此牌時，此牌進行應變。","","佩許在碼頭鬥毆中遇到了賈克斯，他們一起及時逃脫比較像是情勢所逼，而不是建立在夥伴關係上。不過從那時開始，佩許就一直在為賈克斯開船，因為賈克斯周圍的東西總是會壞掉；對於佩許來說，如果有什麼比優質回收廢料更吸引人的，那就是等著人來修理的損壞物品。","單位",["武器大師"],["比爾吉沃特","皮爾托福&佐恩"],"普通"],"06BW034":["重金屬","摧毀1個單位的裝備，並對其造成2點傷害。","","「有誰會在酒吧鬥毆中丟船錨啊？！你們是有什麼問題啊？！！」——比爾吉沃特酒保","法術",[],["比爾吉沃特"],"稀有"],"06BW027":["結合力量大","棄置1張牌即可出此牌。抽2張牌，且若棄置的是裝備，則召喚1個伊卡西亞幻影。","","賈克斯的夥伴證明了團結可以發揮更強大的力量。儘管如此，佩許堅持不同的理念：有時，不用結合在一起也可以發揮得很好。","法術",["武器大師"],["比爾吉沃特","皮爾托福&佐恩"],"稀有"],"06BW039":["無盡波濤","本牌局我方裝備單位後，此牌魔耗值-2。\n抽2張牌並賦予其飛逝。","","雖然伊巴羅斯的一把老骨頭走得很慢，但他面前洶湧的海浪卻以難以置信的速度向前奔騰。","法術",["邪教徒"],["比爾吉沃特"],"稀有"],"06BW026":["布爾魯邪教徒","已裝備的友軍單位攻擊時，對敵方主堡造成1點傷害。","","力量從何而來並不重要，她的女神不會在意。重要的是藉由這股力量殺死的怪物，會為她帶來榮耀。","單位",["邪教徒"],["比爾吉沃特"],"普通"],"06BW014":["冥血魚叉","攻擊：於下次回合開始抽1張牌，並賦予其飛逝。\n可消耗9點魔力改為打出伊巴羅斯。","","「繞路，繞路，達雷海峽可不能靠近，\n那兒的潮水細語風向不可信，\n海怪和鳥類也沒膽接近，\n懼怕達雷海峽的黑暗無盡。」\n——比爾吉沃特歌謠","裝備",["冥血族"],["比爾吉沃特"],"史詩"],"06BW004":["祖靈之試","本回合給予1個敵軍單位弱勢。若該單位於本回合陣亡，則對敵方主堡造成1點傷害。","","「你要起身對抗，還是轉身逃避？」——伊羅旖","法術",[],["比爾吉沃特"],"稀有"],"06BW044":["狡猾蠑螈","打擊主堡：抽1張牌並賦予其飛逝。","","「這些小偷怪物有夠討厭。幸好牠們在偷東西的時候很容易發現。」","單位",["爬蟲族"],["比爾吉沃特"],"普通"],"06BW047":["調皮瑪拉人","我方打出法術時，召喚1個火藥桶。","","「比比是有點……脫線沒錯啦，但這就是她可愛的地方！」——瑪拉族守衛艾拉","單位",[],["比爾吉沃特"],"稀有"],"06BW023":["鋸齒彎刀","洗劫：此牌魔耗值-2。","","「俗話說，在比爾吉沃特，沒有什麼能比一把彎刀更快解決紛爭。」\n「也許除了手槍吧。」\n「閉嘴，巴茲。」\n——未成氣候的賞金獵人巴茲和蓋夫","裝備",[],["比爾吉沃特"],"普通"],"06BW042":["火藥滿載","對1個單位造成2點傷害。每造成1點傷害，便於下次回合開始時\n抽1張牌，並賦予其飛逝。","","「狂鯊砲會負責轟炸，別擔心。然後我會負責寶藏，我也會拿走狂鯊砲的那一份，不然他又會想辦法塞進砲管，那下場都很糟糕。」——肖狗水手","法術",[],["比爾吉沃特"],"史詩"],"06BW040":["神祇之眼","攻擊：海祭2。","","「在她的凝視下站穩腳步！」——伊羅旖","裝備",[],["比爾吉沃特"],"稀有"],"06SH032":["萬人塚陷阱","倒數2：在手牌生成1張沙漠祕寶。","","「你為什麼一定要走到哪摸到哪？」\n「蛤，你覺得這是什麼鬼陷阱嗎？你覺得等等就會有顆大石頭滾出──」\n「快跑啊！」\n——盜墓者雅各斯與薛維爾","地標",[],["蘇瑞瑪"],"普通"],"06SH035":["血之祭壇","我方屠殺單位時，下一次打出的\n冥血族單位魔耗值-1。","","祭壇再次搏動著生命能量，以緩慢而穩定的節奏震動周圍的沙地。所有修蘭妮的門徒內心深處都感受到了相同的共振。每一塊肌肉、每一個念頭、每一個當下……他們已經全然落入她的控制當中。","地標",[],["蘇瑞瑪"],"稀有"],"06SH046":["侍者聖物箱","召喚此牌時，在手牌生成1張毀滅侍者。此牌被我方摧毀時，在我方牌組最上方5張牌中生成1張侍者聖物箱。","","「沙漠掌握在吾等的手中！」——毀滅侍者","地標",[],["蘇瑞瑪"],"稀有"],"06SH033":["古墓詛咒","預言：本回合給予1個單位「此牌承受雙倍傷害，若此牌將要陣亡，則改為將此牌泯滅」。","","「只有愚者會追求超越自身所能控制的力量。」\n——齊勒斯","法術",[],["蘇瑞瑪"],"稀有"],"06SH028":["虛空之門","召喚友軍單位及友軍單位陣亡時，賦予我方牌組3個友軍單位其增益特性。","","巢穴使者朝眼前的巨大建築舉起了雙手。「是王座！」他高喊，「是女皇的王座！」生命的鼓動充滿著虛空之門，時候快到了。","地標",[],["蘇瑞瑪"],"史詩"],"06SH005":["見棄巴凱","出牌：預言。若我方挑選的卡牌為冥血族或裝備，則賦予此牌+1|+1。","","他手裡緊握著一條編織腰帶，這是好友勒哈斯特在他們的飛昇儀式前送他的禮物。即使他崇敬著冥血族的力量，但他野獸般的內心仍隱藏著一股怨恨。","單位",["邪教徒"],["蘇瑞瑪"],"普通"],"06SH056":["嚴懲","擊殺所有侍從單位。","","有時你會受光芒所吸引，有時情況則徹底相反。","法術",[],["蘇瑞瑪"],"稀有"],"06SH040":["強行復甦","本牌局我方裝備友軍單位後，此牌魔耗值-2。復甦最強的已陣亡我方英雄。","","「你永遠不會死，因為我永遠不會讓你死。」\n——修蘭妮","法術",["邪教徒"],["蘇瑞瑪"],"史詩"],"06SH021":["恐懼蟲怪","出牌：此牌打擊1個敵軍單位。","","攻擊持續著，大門逐漸擴大，也湧進更大型更兇猛的生物。貝爾薇斯城已經淪陷，但其名卻將永存於世，更顯命運的殘酷。","單位",[],["蘇瑞瑪"],"稀有"],"06SH051":["岩熊牧童","我方召喚其他單位時，快轉我方倒數最高的地標1回合。\n召喚此牌時，召喚1隻冬眠岩熊。","","「岩杜伯把沙蒂拉當成了牠們的同伴。我一不注意，那個小淘氣鬼就會跟著牠們跑了！」——沙漠學家卡蒂拉","單位",[],["蘇瑞瑪"],"稀有"],"06SH055":["漠光女祭司","回合開始：對此牌造成4點傷害。抽1張英雄牌，並賦予其+2|+2。若我方起始牌組有6張以上不同英雄牌，則改為召喚抽出的英雄牌。","","虔誠信者在邪惡來襲前仍矗立不動，用盡最後一絲力氣來召喚正義之光。這是拼命求來的召喚，但他們知道在黑暗吞噬他們之前，他們的祈禱將會獲得回應。","單位",[],["蘇瑞瑪"],"史詩"],"06SH004":["冥血骨鋸","遺願：若此牌的裝備者並非\n冥血奴僕，則召喚1位冥血奴僕。\n可消耗6點魔力並擊殺1個友軍單位改為打出修蘭妮。","","隨著戰鬥持續進行，絕望又身受重傷的潤兒將意識轉向了她腦海中的低語。「你永遠不會死。」那聲音如夏雨般輕柔地說著。「因為我永遠不會讓你死。」","裝備",["冥血族"],["蘇瑞瑪"],"史詩"],"06SH038":["擺盪大斧","打擊：在手牌生成1張挖到寶。","","「追求你的渴望，毫不留情。」——遺跡獵人\n","裝備",[],["蘇瑞瑪"],"普通"],"06DE048":["攔路獾熊","","","「若汝等不是敵人，那就歡迎汝等，但若帶著邪心踏入這片領域，那就準備受死吧，因為敵人將會體會到強大守護者的復仇之力！」","單位",["菁英"],["蒂瑪西亞"],"普通"],"06DE024":["接招！","本回合給予1個友軍單位+1|+1，或為其裝備手牌中1個魔耗值為2以下的裝備。","","如果大家還沒吃飯，這招打下去會更痛。","法術",["武器大師"],["蒂瑪西亞","弗雷爾卓德"],"稀有"],"06DE025":["善良新兵","召喚此牌時，本回合給予已裝備的友軍單位光盾。","","「這個男孩是個負擔。我堅持不應該讓他跟著我們來狩獵，因為他仍然把這個邪惡的生物稱為他的『姊姊』。實在是過於天真，簡直令我反胃。然而，我想我確實很同情他。至少，這對他來說將會是個重要的一課。」——節錄自狂熱遊騎兵賽利歐斯．羅威爾的私人日記","單位",[],["蒂瑪西亞"],"稀有"],"06DE033":["沉默與抑制","摧毀1個單位的裝備；若該單位為侍從，則亦沉默之。","","「這是你自找的。」——狙魔首領埃德雷德領主","法術",[],["蒂瑪西亞"],"稀有"],"06DE039":["伊卡西亞戰吼","召喚2個伊卡西亞幻影，並最多裝備2個在手牌中魔耗值為2以下的裝備。","","在數不盡的夜裡，賈克斯做著與失落的同胞並肩作戰的夢。縱使戰鬥有贏有輸，但他們自始至終都在彼此的身邊。","法術",["武器大師"],["蒂瑪西亞"],"稀有"],"06DE011":["冥血之盾","可消耗5點魔力改為打出喬拉爾。","","「聽好了兒子，絕對不能碰那面盾牌。很久以前，有人把盾牌送給我們家族，條件是要保管它，但不要動它。這是我的責任，當我走了之後，責任就落到你身上了。聽懂了嗎？你絕不能再爬上去，絕不能碰它。」\n「可是媽媽，裡面的聲音……對著我呼喊。它聽起來很難過。」\n「……那你就更不應該碰了，我的兒子。」\n——佛提斯夫人與她的兒子","裝備",["冥血族"],["蒂瑪西亞"],"史詩"],"06DE021":["汎","召喚此牌時及回合開始：在手牌生成1張翻滾瞄準。若手牌中已有該牌，\n則使其魔耗值-1。","此牌在場上時，我方進行4次攻擊。","「我們的目標曾經是人類，代表牠比一般的野獸更聰明。走錯一步就可能讓我們全軍覆沒。待在彼此的視線範圍內，回報任何可疑之處──但最重要的是，要記住……」","單位",[],["蒂瑪西亞"],"英雄"],"06DE043":["可靠攻城犬","我方首次召喚菁英單位時，賦予此牌+2|+2。","","「雖然她的速度不及銀翼鷲，但見識到她的腳程有多快後，你肯定會大吃一驚。」——雲霄戰士希莉亞","單位",["犬族"],["蒂瑪西亞"],"普通"],"06DE018":["重型弩箭","若本回合我方已攻擊2次以上，則此牌魔耗值-5。\n使1個友軍單位打擊1個敵軍單位。","","「淨化之箭。」——汎","法術",[],["蒂瑪西亞"],"普通"],"06DE041":["英雄之力","本回合給予所有友軍單位+4|+4並進行備戰。","","「心懷光明，勇敢奮戰吧！」——拉克絲","法術",[],["蒂瑪西亞"],"史詩"],"06DE026":["伊卡西亞神話","在手牌生成1張本回合魔耗值為0的伊卡西亞幻影，或在手牌生成\n1張黃金鍋鏟。","","據傳說，黃金鍋鏟最初的持有者是一個烹飪能力傑出的海洋生物──牠想成為像賈克斯一樣強壯無畏的戰士。\n\n其他更可信的說法則指出，那個傳說完全是某個爛醉如泥的廚師捏造出來的。","法術",[],["蒂瑪西亞"],"稀有"],"06DE044":["反魔法英石戰牛","敵方法術/技能無法對此牌造成傷害。","","「反魔法英石是最堅硬的材質。」——杜蘭德建築師","單位",[],["蒂瑪西亞"],"稀有"],"06DE017":["丟丟魚仔","使1個友軍單位與1個敵軍單位互相打擊，或使1個已裝備的友軍單位打擊1個敵軍單位，然後解除裝備。","","「魚兒啊，打個照面！」——愛歐尼亞釣魚大師","法術",["武器大師"],["蒂瑪西亞"],"普通"],"06DE040":["誘人前景","從我方牌組最上方4張牌中挑選1個侍從單位或裝備。抽出該牌並將其餘卡牌放回我方牌組。","","輕柔、誘人的耳語在內心深處種下渴望的種子。就像一根刺，讓骨肉潰爛並成長為飢餓。飢餓使人犯罪，犯罪又回過頭帶來死亡，如此不斷輪迴。","法術",["邪教徒"],["蒂瑪西亞"],"普通"],"06DE028":["血咒鳥妖","出牌：為此牌裝備手牌中1個魔耗值為2以下的裝備。此牌若已裝備且首次將要陣亡時，改為治癒此牌並摧毀該裝備。","","「齊安，如果你正在讀這封信……希望我已經死了。我無法控制發生在我身上的事情。我指甲下的血怎麼樣都洗不掉。我好癢，我抓了又抓，但沒有任何幫助，好痛苦。我只希望這一切都能結束。如果我還活著，答應我你不會再試著要找我了。\n\n我想請求你的原諒，但我並不值得原諒。對媽媽好一點，好嗎？」\n——破爛背包中一封皺皺的信","單位",[],["蒂瑪西亞"],"史詩"],"06DE027":["狂熱遊騎兵","攻擊：本回合給予已裝備的友軍單位+1|+1。","","「你叫迦楠，對吧？你知道什麼關於賽利歐斯的事嗎？」\n「哦，你是指遊騎兵羅威爾？他的頭銜早在幾年前就被撤銷了。他似乎故意無視下達的每一項命令，好像還四處為所欲為，並且從不接受他人拒絕。」\n「這樣啊。」\n「那……你為什麼還要讓他加入這場狩獵？」\n「我沒有啊。」\n「那為什麼……喔，我懂了，好極了。」\n——汎和喪偶女獵手迦楠","單位",[],["蒂瑪西亞"],"稀有"],"06DE019":["喪偶女獵手","出牌：為此牌裝備手牌中1個魔耗值為2以下的裝備。","","「儘管這個女人似乎是個足以獨當一面的戰士，但她才剛失去另一半，隨時有可能被悲傷的情緒所淹沒。絕望確實是絕佳的動力——這我自己也很清楚——但失控成這樣？或許她一心求死……」——節錄自狂熱遊騎兵賽利歐斯．羅威爾的私人日記","單位",[],["蒂瑪西亞"],"普通"],"06DE032":["蒂瑪西亞之鋼","","","蒂瑪西亞軍隊弟兄首選的標準劍與盾。","裝備",[],["蒂瑪西亞"],"普通"],"06DE029":["穩重羚鹿","我方首次裝備單位時，賦予此牌堅忍。","","「給我退下，邪惡的生物！你如果敢從菩瑞蹄純潔無暇的外皮上扯下一根毛髮，我保證會讓你嘗到無盡的痛苦！」——狂熱遊騎兵賽利歐斯．羅威爾","單位",[],["蒂瑪西亞"],"普通"],"06DE010":["叛逃遊騎兵","本牌局我方裝備友軍單位後，賦予此牌先遣。","","因為長年抑制自己的魔法能力，她心中滋生了一種深沉的自我仇恨，她惡意地將這股仇恨發洩在受害者身上。從遊騎兵叛逃後，她失去了發洩怒火的對象，直到黑暗中傳來了一個聲音。那聲音談到了一種新的秩序，使她可以不受拘束地進行她的暴行。","單位",["邪教徒"],["蒂瑪西亞"],"稀有"],"06DE006":["戰鬥廚師","召喚此牌時，此牌進行應變，然後鑄煉此牌。","","從蒂瑪西亞部隊退役之後，布雷希還以為自己會結束軍旅生涯，在安靜的村莊小酒館當廚師。他的退休生活全因賈克斯的酒館鬥毆和對全熟蛋的偏見給毀了。從那以後，布雷希擁抱了他的新生活：教導賈克斯一些品味。","單位",["武器大師"],["蒂瑪西亞","弗雷爾卓德"],"普通"],"06DE034":["忠誠狼犬","若本回合有友軍單位陣亡，則此牌魔耗值-2。\n出牌：為此牌裝備手牌中1個魔耗值為2以下的裝備，並鑄煉此牌。","","「我從瑪吉還小的時候就養了她。她雖然年紀大了，但她依然像剛磨過的刀刃一樣敏銳鋒利。我願意為她犧牲生命，反之亦然。」——喪偶女獵手迦楠","單位",["犬族"],["蒂瑪西亞"],"普通"],"06SI045":["一魂兩斷","擊殺1個友軍單位以召喚2個閃靈複製單位。","","反正沒人用也是浪費。","法術",[],["闇影島"],"稀有"],"06SI007":["冥血戟","擊殺1個友軍單位即可出此牌。\n可消耗10點魔力改為打出塔魯錫。","","塔魯錫奮力想掙脫牢籠，卻在這時聽到了將軍的呼喚。不論用什麼方法，他都會設法回應。","裝備",["冥血族"],["闇影島"],"史詩"],"06SI034":["回聲幽靈","回合結束：本回合每有1個友軍單位陣亡，便賦予我方各處與之相同的卡牌+1|+1。","","「我不知道他們用了什麼邪惡的魔法，我也不想知道。我只需要知道，如果他們再爬起來一次，就會再被殺一次。」——島嶼守望者","單位",[],["闇影島"],"史詩"],"06SI029":["煞星之矛","若本回合有友軍單位陣亡，則此牌魔耗值-2。","","「正義並不存在……只有復仇才是真理。」——克黎思妲","裝備",[],["闇影島"],"普通"],"06SI032":["永眠","擊殺1個力量值和生命值總和為4以下的單位，或摧毀1個單位的裝備。","","在闇影島上，不論死亡以何種形式襲來，但願能在剎那間結束。","法術",[],["闇影島"],"稀有"],"06SI031":["亡者之刃","本回合給予1個友軍單位：「遺願：召喚1個擁有此牌裝備的伊卡西亞幻影」。","","有時，面對倒下的同伴，最好的悼念方式就是拾起他們的武器繼續戰鬥。","法術",["武器大師"],["闇影島","蘇瑞瑪"],"稀有"],"06SI014":["奢華門廳","召喚此牌時，召喚1個幽靈樂團。\n回合開始：若我方擁有攻擊主動權，則召喚1個幽靈樂團。","","「樂團準備好了，舞台也已經就緒，賓客正在等著──大師，請跟我來！」——狂歡主持人","地標",[],["闇影島"],"史詩"],"06SI038":["自新奇才","攻擊：召喚1個攻擊中的幽靈樂團。","","力求完美只會限制自己，讓自己冥頑不靈。完美毫無生氣，沒有呼吸。完美的不完美才是真正值得追求的。","單位",[],["闇影島"],"稀有"],"06SI003":["沙漠死神 菲芮斯","召喚此牌時，此牌進行應變。","","在一起旅行的前幾週，賈克斯問了菲芮斯的名字不下二十次，但她只會吼道：「我是死神！」。布雷希想到了解決辦法：他剛剛烤好了一個蛋糕，需要寫上小隊最強成員的名字才能好好慶祝。","單位",["武器大師"],["闇影島","蘇瑞瑪"],"史詩"],"06SI006":["魔盒看守者","本牌局我方裝備友軍單位後，賦予此牌吸血。","","「魔盒不會輕易透露其中的祕密，席達．慨影，想知道就要付出沉痛的代價。但如果你有勇氣凝視陰影中更深處的黑暗，你會發現裡面藏著美妙而可怕的東西。」\n——魔盒看守者 伊斯德拉","單位",["邪教徒"],["闇影島"],"普通"],"06SI039":["恐懼形貌","擊殺1個友軍單位以召喚1個幽侵黯霧。","","只有愚者才會想在黯霧中找出熟悉的身影。","法術",[],["闇影島"],"普通"],"06SI042":["不死騎士","此牌將要獲得閃靈時，改為賦予此牌+1|+1。","","在生前接受訓練，忍耐苦痛的士兵死後會變得更勤奮有能，因為他們不畏寒冷，不知痛苦，也不明白恐懼為何物。","單位",[],["闇影島"],"稀有"],"06SI036":["全然毀滅","擊殺所有單位，冥血族友軍單位和已裝備的友軍單位除外。","","當她拿起武器時，人性隨之消逝，取而代之的是滿腔的憎恨，曾經是大師學徒的潤兒徒剩一具空殼。仇恨擴及全身、環繞四周，再向外擴散，打攪了沉睡的冥血族。","法術",["邪教徒"],["闇影島"],"稀有"],"06SI046":["無盡哨兵","遺願：抽1張牌。",""," 「……所以我會靜靜觀察，直到永遠，因我的使命早已超越生死。」","單位",[],["闇影島"],"普通"],"06SI041":["月照樹人","召喚閃靈友軍單位時，賦予該單位+1|+0。\n夜臨：召喚1個小樹精。","","闇影島內陸深處的樹叢，看似早已枯乾扭曲、了無生機、死氣沉沉，只有最敏銳的人可以看得出來，在那沐浴於月光下的土壤中，有新生命在萌芽。","單位",[],["闇影島"],"普通"],"07PZ009":["改裝時鐘機器人","出牌：預言，然後抽1張牌，並使其魔耗值-1。","","「這小傢伙只需要改造一下，加些新齒輪，再加一隻新手臂，然後就能繼續運作了。時間是一份寶貴的禮物，每個人都應該有多一點。」——艾克","單位",[],["皮爾托福&佐恩"],"史詩"],"07PZ017":["閃光炸彈小販","我方打出法術時，將1張閃光炸彈陷阱植入敵方牌組最上方8張牌中。","","「……你知道這些寶貝還有什麼地方比蘑菇好嗎？你可以決定他們什麼時候爆炸！絕對物超所值！」","單位",[],["皮爾托福&佐恩"],"稀有"],"07PZ005":["膛炸","對1個敵軍單位與敵方主堡造成1點傷害。每棄置1張牌可提升1點傷害，最多可棄置2張。",""," 「好啦、好啦，這東西可能只能用一次，但相信我，這一定會刺激到爆！」——吉茵珂絲","法術",[],["皮爾托福&佐恩"],"稀有"],"07NX009":["酷炫射擊","對敵方主堡造成1點傷害。本回合友軍單位再次打擊敵方主堡時，在手牌生成1張酷炫射擊。","","「就算我赤手空拳也沒有人打得過我，況且我現在是全副武裝，你還是死心吧。」——煞蜜拉","法術",[],["諾克薩斯"],"史詩"],"07NX008":["魅影刺客","洗劫：賦予此牌+2|+0。","","「我收費很貴，而且很會挑雇主。不過，如果你有幸聘請到我的話，那你大可放心，因為我辦事優雅沉著，且刀一出鞘必定見血。最重要的是我風格獨到，畢竟誰不愛華麗絢目的殺人手法呢？」","單位",[],["諾克薩斯"],"普通"],"07NX014":["芭蕾劍舞","洗劫：此牌魔耗值-2。\n對任1目標造成1點傷害，並擊暈1個敵軍單位。","","「怎樣？我只是在伸展而已，別跟我說你這樣就不行了。」——魅影刺客","法術",[],["諾克薩斯"],"稀有"],"07NX007":["煞蜜拉","洗劫或打擊：若手牌中沒有狂戰本能，則在手牌生成1張。","此牌在場上時，我方打出6張卡牌。我方在回合開始獲得攻擊主動權時重置。","「我追捕的目標，是那些欠債還不起，然後搞失蹤的人。這樣做只會招來更可怕的敵人——找我幫忙討債的債主。」","單位",[],["諾克薩斯"],"英雄"],"07NX006":["英俊公子","洗劫：使此牌力量值加倍。",""," 「聽著，通常我會定下一些規矩，例如『打人不打臉』，不過其實沒這必要，因為你根本就捨不得動我一根寒毛。」","單位",[],["諾克薩斯"],"普通"],"07NX015":["掠奪者達梅","洗劫：賦予所有友軍單位+1|+0。","","「達梅嗎？她的行為舉止是有點誇張，讓有些人受不了，但當她做得得心應手，我們就都有錢賺。」——魅影刺客","單位",[],["諾克薩斯"],"普通"],"07NX003":["全力出擊","本回合給予1個友軍單位+2|+0。\n洗劫：改為給予其+2|+1。",""," 「因達里在背後牽線，讓我們潛入時一點問題都沒有。希望離開時可以有時間讓我製造一點問題。」——煞蜜拉","法術",[],["諾克薩斯"],"普通"],"07NX004":["巧手工匠","召喚此牌時，發動所有友軍單位的洗劫效果。","","「在某些地方開店可能會比較棘手，但只要客人一看到我和藍尼的貨，我們就會收錢收到手軟。今晚我們的目標不在那些物色商品的人當中，但懷抱犯罪念頭的人倒是不少。畢竟，了解誰想幹掉誰，是掌握當前形勢的好方法。」——米爾","單位",[],["諾克薩斯"],"稀有"],"07NX001":["破天荒拆除者","出牌：對敵方主堡造成1點傷害，或發動1個友軍單位的洗劫效果。","","「身處軍火界，就必須與資料打好交道。概念設計、測試、重製及修改，這些程序都會用到資料。想要有足夠的樣本數，就得進行實地測試，反正就只是在地上轟出幾個坑洞而已！」——藍尼","單位",[],["諾克薩斯"],"稀有"],"07NX005":["因達里上尉","召喚此牌時，此牌進行應變。\n洗劫：鑄煉其他友軍單位。","","「我跟許多特工合作過……有些很好溝通，有些有點難搞……然後我遇到了煞蜜拉。她完全不受控制，但我後來接受了這個事實，開始把這混亂製造機往目標丟，然後時不時加入一下戰局。」","單位",["武器大師"],["諾克薩斯"],"稀有"],"07BW018":["老番顛芭布斯","我方恢復魔力時，每恢復1點魔力便賦予此牌+1|+0。","","「我親愛的傑克，快看過來！你對這東西可有興趣了，對吧？」","單位",[],["比爾吉沃特"],"普通"],"07BW021":["不要臉海盜","洗劫：隨機召喚1個魔耗值為1的侍從單位，並賦予其硬派。","","「是我就會離她遠一點。她總是可以把自己的麻煩變成別人的麻煩，有夠糟糕的個性。」—–煞蜜拉","單位",[],["比爾吉沃特"],"普通"],"07BW002":["傑克","打擊：在手牌生成1張金幣。\n我方恢復魔力時，每恢復1點魔力便治療此牌1點生命值。","我方在一回合中消耗12點以上魔力。","「敢挑戰我的，不是膽識過人，就是笨得可以，但不管是哪一個，結局都一樣。我勸你，最好想想該如何活著出去。」","單位",[],["比爾吉沃特"],"英雄"],"07BW040":["鯊人納可","召喚此牌時，在手牌生成1張飛逝鯊人瑪寇。","","「這邊挖一塊，那邊切一塊，好玩極了。在水中流一點血不會怎麼樣的。嗯，至少有事的不會是我。」——納可","單位",[],["比爾吉沃特"],"稀有"],"07BW001":["背信推銷員","我方恢復魔力時，在手牌生成1張魔耗值剛好等於現有魔力的飛逝隨機侍從單位。","","「如果你想要見血，那就找傑克。想知道地點、時間、對象跟價格嗎？那就來問我。」","單位",[],["比爾吉沃特"],"稀有"],"07BW003":["扒手","遺願：在手牌生成1張金幣。","","「喂，給我回來，鼻涕蟲！那是我買馬鈴薯的錢耶！」——安潔","單位",[],["比爾吉沃特"],"普通"],"07BW014":["五拳帕布羅","召喚此牌時，在手牌生成1張飛逝拳擊賽。","","「就是這樣，傑克老弟！只要你繼續展現比爾吉沃特的雄風，我就會讓你保持最佳狀態。哎呀，不免讓我想起我的全盛時期，當時他們都叫我『帥到冒泡帕布羅』……你說沒這回事？明明就有！肯定是你撞到頭的那一下讓你記不清楚了。」——五拳帕布羅","單位",[],["比爾吉沃特"],"普通"],"07BW013":["天使安潔","洗劫：在手牌生成3張金幣。","","「你就這點本事？真可愛。現在輪到我了。」","單位",[],["比爾吉沃特"],"普通"],"07BW006":["風險投資","對1個單位造成3點傷害。若擊殺該單位，則在手牌生成2張金幣。","","「不入虎穴，焉得虎子。我的大嘴就是為冒險而生的。」——傑克","法術",[],["比爾吉沃特"],"史詩"],"07BW026":["倒鉤鎖鏈","洗劫：此牌魔耗值-2。\n於下次回合開始抽2張牌，並賦予其飛逝。","","聽到金屬鋃鐺作響的聲音時，再怎麼跑都來不及了。","法術",[],["比爾吉沃特"],"稀有"],"07BW027":["狂怒老爹","洗劫：恢復1點法術魔力，並在手牌隨機生成1張魔耗值為1、我方區域的法術牌。","","狂怒老爹的身世成謎，真相就像籠罩著厚厚的雷雨雲一樣。即使有人問起，也從來沒有得到清楚的答覆；因為老爹所經之處，都會發出震耳欲聾的毀滅聲響，你根本聽不清楚他講什麼。","單位",[],["比爾吉沃特"],"稀有"],"07BW008":["拳擊賽","使1個友軍單位與1個敵軍單位互相打擊。互相打擊單位的生命值不會降到0以下。","","有時是一手交錢，一手交貨，有時則是一手扯頭髮，一手揍鼻樑。這檔事就是這樣，但只要是公平的交易就是好交易！","法術",[],["比爾吉沃特"],"普通"],"07BW041":["藤壺指虎","打擊：在手牌生成1張金幣。","","「嗯，我知道這東西看起來很不尋常，我懂你的意思。但就給它一次機會吧，用久了就會根深蒂固的。」\n——鯊人伯爾","裝備",[],["比爾吉沃特"],"稀有"],"07BW004":["王殿號","召喚此牌時，抽1張傑克。\n召喚友軍單位時，在手牌生成1張飛逝拳擊賽。\n友軍單位承受傷害且未陣亡時，賦予其硬派。","","傑克的私人船艦載著他和同黨橫跨符文大地的汪洋，從比爾吉沃特，到愛歐尼亞。沒人知曉這艘船究竟是如何在水底航行而不會沉沒，然而據說，真正的危險都潛藏在水面之下……","單位",[],["比爾吉沃特"],"史詩"],"07BW025":["炎之伊弗娜","我方發動洗劫時，抽1張牌並賦予其飛逝。","","「在海上當個縱火狂還是有點好處的。海水能控制住暴走的火焰，也不會吵著要分一杯羹。」","單位",[],["比爾吉沃特"],"稀有"],"07IO020":["換人","召回1個友軍單位，並在手牌生成1張金幣，或消耗5點魔力召回1個敵軍單位，並在手牌生成1張金幣。","","「遇到以下兩個情況我才會上場：一、對手把你打得落花流水；二、對手被你打得落花流水。這麼有趣的事，怎麼可以讓你獨享！」——黑市拳手","法術",[],["愛歐尼亞"],"稀有"],"07IO014":["篩選者 炳文大師","出牌：本回合我方下次打出單位時，召喚1個該單位的閃靈複製單位。","","炳文過去是一名格鬥家，人稱他為「白鶴」，原因是他的架勢猶如白鶴展翅，且身手敏捷。退休後，他扛起教練的重任，以他的敏銳眼光和鐵腕手段，篩選出有潛能的人才。","單位",[],["愛歐尼亞"],"史詩"],"07IO023":["老練拳手","出牌：召回最強敵軍單位。若本回合我方消耗16點以上魔力，則改為召回所有敵軍單位。","","「小姑娘，想都別想讓我拿下面罩。除非你想讓自己的臉變得跟這東西一樣，否則就別再問了。」","單位",[],["愛歐尼亞"],"稀有"],"07IO011":["賽特","若此牌首次在攻擊中生命值將降到0以下，則改為給予此牌光盾。","我方消耗40點以上魔力。","賽特的專屬地下格鬥場座無虛席，在觀眾的熱烈歡呼聲下，他難得陷入沉思，回想自己戰鬥的理由，以及展望未來會得到的一切。不管怎樣，有一件事不容置疑：當拳皇真好。","單位",[],["愛歐尼亞"],"英雄"],"07IO046":["皇家閃翼鳥","使其他鳥族友軍單位獲得+1|+0與快速攻擊。","","「在這片叢林之中，我發現最漂亮的動物往往都是最致命的掠食者。」——安努拉","單位",["鳥族"],["愛歐尼亞"],"稀有"],"07IO009":["細心會計師","打擊主堡：在手牌生成1張金幣。","","在野心勃勃的算計者和自私自利的陰謀家之中，莉絲擁有賽特最看重的一項特質——就是可靠。她從不缺席、從不拖欠帳款，也從來沒有讓賽特心生疑竇的理由。因此賽特成了莉絲的靠山，任何想找她麻煩的對象都會收到警告：「想跟莊家對賭，就等著輸得一塌糊塗。」","單位",[],["愛歐尼亞"],"稀有"],"07IO019":["圓滑調酒師","出牌：治療1個友軍單位或我方主堡3點生命值，並在手牌生成1張金幣。","","「第一輪先破冰，第二輪讓對方放下戒心，第三輪後就會開始訴苦，第四輪之後什麼祕密都抖出來了——我聽過的八卦，講了你也不會信！」","單位",[],["愛歐尼亞"],"普通"],"07IO017":["下注","抽2張牌，並在手牌生成2張金幣。",""," 「他們給我們錢，我們給他們機會。嘿……還真有人搞不懂為何莊家會穩贏不賠。」","法術",[],["愛歐尼亞"],"普通"],"07IO047":["蠱惑眼鏡蛇","每回合我方首次打出其他侍從單位時，召喚1個與之相同的複製單位。若我方盤面已滿，則改為將其能力值與特性賦予此牌。","","「你覺得這些花值錢嗎？我沒有瘋，但這些花是不是在……跳舞？」——皮爾托福盜獵者","單位",["爬蟲族"],["愛歐尼亞"],"史詩"],"07IO013":["黑市拳手","召喚此牌時，在手牌生成1張金幣。","","「有些人參賽，是為了錢；有些人是為了見血；有些人是為了觀眾的歡呼聲。至於我呢？我才不做選擇，我全都要，一個也不放過。」","單位",[],["愛歐尼亞"],"普通"],"07IO012":["格鬥場保全","召喚此牌時，在手牌生成1張飛逝格鬥場保全，並賦予其他格鬥場保全+1|+1。\n強化5：快速攻擊。","","「如果那些無能的傢伙以為你很蠢的話，就隨他們去就好了。讓他們誤以為自己能隨心所欲——當他們發覺自己低估了你，露出驚訝表情的那一刻，可謂人間至樂。」——賽特","單位",[],["愛歐尼亞"],"稀有"],"07IO007":["碎顱猛擊","擊暈2個敵軍單位，並在手牌生成1張金幣。","","「幹嘛？他叫我衝著下巴來，又沒說是誰的下巴！」——賽特","法術",[],["愛歐尼亞"],"普通"],"07SH023":["落沙將軍","本牌局我方每召喚1個閃靈友軍單位，此牌便獲得+1|+0。","","「雖然對你的敵人來說，你猶如一盤散沙，但我看得到你，在沙丘裡感受到你的存在。借我你的力量吧，讓我們合力擊倒敵人！」","單位",[],["蘇瑞瑪"],"稀有"],"07SH018":["祕密看守人","召喚此牌時，在我方牌組底部生成2張不存在於我方手牌、牌組或場上的隨機等級2英雄。","","他無法完全理解自己所見的事，也不清楚末日災難的全貌，或是會在何時發生——但他知道這個世界及其居民還沒準備好。或許他們永遠都不會準備好。","單位",[],["蘇瑞瑪"],"史詩"],"07SH008":["獸群攻擊","召喚所有場上貓族友軍單位的閃靈複製單位發動額外攻擊。","","一個獵手已經夠可怕了，但一整個獸群將會讓你體會到真正的恐怖。","法術",[],["蘇瑞瑪"],"普通"],"07FR008":["冰刺幼狼","可消耗6點魔力改為打出冰刺母狼。","","弗雷爾卓德處處充滿危險，對尚未經歷冷酷現實的幼獸來說更是如此。","單位",["犬族"],["弗雷爾卓德"],"普通"],"07FR009":["創新鐵匠","召喚此牌時，此牌進行應變。\n每回合我方首次鑄煉或裝備單位時，治療我方主堡1點生命值。","","「這小毛球不會讓我工作更有效率，但看到牠我就開心，這樣就夠了。」——創新鐵匠","單位",["武器大師"],["弗雷爾卓德"],"稀有"],"07FR005":["壁壘奴魔","我方法術/技能無法對此牌造成傷害。","","「雪崩一旦發生，便勢不可擋。」——麗珊卓","單位",[],["弗雷爾卓德"],"稀有"],"07SI002":["靈魂收割","擊殺1個力量值為3以下的侍從單位，或消耗3點魔力擊殺1個力量值為3以下的英雄。","","它的聲音輕得幾不可聞，但確實存在，擁有一命換一命的權能。","法術",[],["闇影島"],"稀有"],"07SI001":["滅絕","擊殺所有力量值為3以下的單位。","","見我身者，將感受到湮沒之觸，並永無脫身之日。","法術",[],["闇影島"],"史詩"],"07SI007":["墓穴狗靈","每回合首次有其他友軍單位陣亡時，抽1張牌。","","「他剛學會了一個新把戲！想看嗎？」——魅影搗蛋鬼","單位",["犬族"],["闇影島"],"普通"],"07MT003":["宇宙幼獸","回合開始：治療此牌與我方主堡1點生命值。","","牠們猶如極光之淚般高掛天空，光芒四射的目光帶來平靜，撫平傷痛，修補破碎的心靈。","單位",[],["巨石峰"],"稀有"],"07MT001":["降世星辰","對1個遭到擊暈或本回合攻擊過的敵軍單位造成4點傷害。","","人在做天在看，不論是善行或惡行都一樣。正義之士必受到頌揚，惡徒則會遭受審判。","法術",[],["巨石峰"],"普通"],"07MT007":["獻祭學者","遺願：在手牌生成我方對此牌打出的前3張法術的複製牌。","","「坎芙奪走太多東西，傷害太多人了。如果你要死的話，絕對不要讓她得手，不要讓她稱心如意。」——潘森","單位",[],["巨石峰"],"史詩"],"07BC005":["石雕旋刃者","","","「這倒是第一次見到。」——四尾旋刃者","單位",["妖精"],["班德爾城"],"普通"],"07BC009":["香蕉飛派","對1個單位造成1點傷害。在手牌生成1張砧的派。","","接好囉。","法術",[],["班德爾城"],"稀有"],"07BC015":["壓縮","挑選1個侍從單位。在手牌生成1張該牌魔耗值為1的複製牌，並將其能力值設為1|1。","","「嗯……看來變小也不一定會變可愛！」——露璐","法術",[],["班德爾城"],"稀有"],"07DE002":["搜索令","使1個力量值為4以上的友軍單位俘虜1個單位，或使1個友軍單位俘虜1個地標。","","「不許動，也別說話。別做不明智的反抗。」\n——狙魔調查員","法術",[],["蒂瑪西亞"],"稀有"],"07DE005":["重整隊形！","本回合給予1個友軍單位+2|+2。","","「站穩腳步！你們或許會受傷，但不會倒下！」\n——無畏先鋒","法術",[],["蒂瑪西亞"],"普通"],"07DE008":["團結祭壇","召喚此牌時，抽1張單位牌。\n召喚友軍單位時，使其能力值提升至與魔耗值相同。","","第一次看到祭壇時，希莉亞感動到說不出話來。有好一會，她只能站著景仰這些著名英雄的宏偉雕像。她是否有足夠的勇氣讓自己立足在他們身邊呢？","地標",[],["蒂瑪西亞"],"稀有"],"07PZ019":["化學科技毛毛車","本牌局我方每召喚1個魔耗值為1的友軍單位，此牌便獲得+1|+0。","","「我得給辣匹馬畫很多條腿，蜥蜴先生，因為我們得趕快去辣座城堡。噢不，它怎麼有點……黏糊糊，還有點綠綠的。」——少女英格娃","單位",[],["皮爾托福&佐恩"],"稀有"],"07PZ021":["安努拉與呼嚕噗","與場上其他友軍單位卡牌次類不同的友軍單位魔耗值-1。","","「我不會傷害你的，朋友！我來這座叢林是為了研究，不是破壞。」","單位",["爬蟲族"],["皮爾托福&佐恩"],"史詩"],"07PZ022":["聖潔清風","對1個敵軍單位或敵方主堡造成1點傷害，再對另1個目標造成1點傷害。","","皮爾托福人大多對風的流向毫不在意。但對許多佐恩人來說，任何一縷清新微風都是救贖。","法術",["元素"],["皮爾托福&佐恩"],"普通"],"07PZ013":["汙水坑銅像","若我方主堡將受到劇毒膨菇以外的傷害，則改為每有1點傷害，對手便在我方牌組植入5張劇毒膨菇。","","在佐恩街頭的地底深處，人如其食。","地標",[],["皮爾托福&佐恩"],"史詩"],"07PZ015":["廢料大改造","此牌魔耗值等於我方所剩魔力。召喚1台落跑廢料機，並使其能力值提升至等於所消耗的魔力。","","「科學家最重大的責任就是掌握好變因。如果我們這個領域的研究出了什麼差錯……天啊，後果我連想都不敢想！」——漢默丁格教授","法術",[],["皮爾托福&佐恩"],"普通"],"07NX028":["卡瑞克斯上尉","打擊主堡：對敵方主堡造成等同其當前一半生命值的傷害，無條件進位。","","擴張版圖是諾克薩斯帝國的宗旨。不管是木頭、石材還是鋼鐵，沒有任何東西擋得下諾克薩斯的攻城槌。","單位",[],["諾克薩斯"],"史詩"],"07NX034":["血色宴會廳","友軍單位魔耗值-1。召喚友軍單位時，對其造成2點傷害。","","「來吧，朋友們，請坐！這裡有喝不完的美酒，還有好友相伴，而我等不及要向各位上主菜了。」——弗拉迪米爾","地標",[],["諾克薩斯"],"史詩"],"07NX032":["闇鴉寶典","此牌的裝備者打出技能時，複製之。","","雷文布魯學院以藏書豐富聞名，但在某位特別難搞的學生放火燒了學院時，那些書幾乎都成了助長火勢的燃料……","裝備",[],["諾克薩斯"],"稀有"],"07NX033":["骨甲三尾獸","召喚此牌時，場上其他友軍單位每有1個不同卡牌次類，便賦予此牌+1|+1。","","「你們這些低能兒給我小心點！只要鬥獸有點傷，諾克薩斯人就不買了。如果你們碰掉了一根毛，就準備被扣薪水吧！」——巨獸大亨","單位",["貓族"],["諾克薩斯"],"普通"],"07RU015":["普羅王","起源：普羅王諭令。\n每回合我方首次召喚其他普羅單位時，在手牌生成1張普羅點心。","我方召喚6個以上的其他新普羅。此牌升級時，在手牌隨機生成1張特別點心。","英格娃一眼就能看出一樣東西有沒有潛力。先不論手工製的外觀，只要想像力夠豐富，她心愛的小夥伴輕鬆就能成為成千上萬隻普羅的統治者。 ","單位",["普羅"],["符文大地"],"英雄"],"07RU012":["妮可","起源：叢林朋友千百種！\n出牌：可從此牌起源魔耗值為2的侍從單位中3選1，將此牌偽裝成該單位。","攻擊：我方以6個以上不同卡牌次類的友軍單位攻擊。","妮可的外貌千變萬化，但內心始終如一，她永遠心繫著故鄉的家人與森林。","單位",["變形師"],["符文大地"],"英雄"],"07BW043":["潮汐祈喚","對1個單位造成1點傷害。每造成1點傷害，海祭1。","","唯有見識最廣的人，能夠命令元素遵從自己的意志。","法術",["元素"],["比爾吉沃特"],"稀有"],"07BW035":["騙徒老巢","我方手牌中的卡牌擁有飛逝。\n我方打出卡牌時，抽1張牌。","","「你要不知道自己手上有什麼牌然後緊緊抓好，不然就準備輸光一切。」——逆命","地標",[],["比爾吉沃特"],"史詩"],"07BW042":["鯊鼠獵手","出牌：顯化1張與場上友軍單位卡牌次類不同的侍從單位。","","「我們會養這髒兮兮的小傢伙不是沒有原因的：我們已經好幾年沒有鯊鼠的問題了！」——恐懼號水手","單位",["貓族"],["比爾吉沃特"],"普通"],"07BW039":["龍王子古林澤","每回合我方首次召喚魔耗值為1的單位時，恢復1點法術魔力。","","「蜥蜴先生，你怎麼會在這裡？你也喜歡普羅嗎！？」——少女英格娃","單位",["龍族"],["比爾吉沃特"],"稀有"],"07BW033":["海妖之歌","隨機召喚1個空殼。\n賦予各處魔耗值為1的友軍單位+1|+1。","","有些比爾吉沃特水手出海時，會在最寧靜的夜晚中戴上耳塞，因為他們知道從海面下傳出的音樂只會讓他們屍沉大海。","法術",[],["比爾吉沃特"],"普通"],"07IO041":["療癒清風","治療我方主堡3點生命值並抽2張法術牌。","","「風是浪人唯一的旅伴。」——犽宿","法術",["元素"],["愛歐尼亞"],"普通"],"07IO043":["全知神諭使","出牌：從敵方手牌或牌組的快速或慢速法術牌中3選1。生成1張該牌的占卜刻印。","","神諭使超脫物質世界的雙眼看穿了一切。他雖然眼盲，但小看他的人可是會受到他迅速無情的反擊。","單位",[],["愛歐尼亞"],"稀有"],"07IO049":["愛麗絲","打擊主堡：隨機召喚1個空殼。","","「噓，我們就快到了。是你說要見我的朋友的，對吧？相信我，她絕對會愛死你的。」","單位",[],["愛歐尼亞"],"稀有"],"07SH038":["帕卡幼豹","埋伏1\n打擊主堡：召喚1隻帕卡捍衛者。","","雖然外表可愛，但牠們天性凶猛。只要經過時間的洗禮與教育，就連最小隻的帕奇堤都會長成狂野強壯的猛獸。","單位",["貓族"],["蘇瑞瑪"],"普通"],"07SH041":["魯莽偵察","顯化1張埋伏牌。","","叢林偵察是大家最不想做的任務，主要是因為你永遠不知道會發現什麼。","法術",[],["蘇瑞瑪"],"稀有"],"07SH004":["穿梭","本回合給予1個友軍單位+2|+0。若該單位是樹叢暗影，則改為給予其+2|+2。","","「放輕腳步，帕奇堤，然後一擊斃命。」——奈德麗","法術",[],["蘇瑞瑪"],"普通"],"07SH013":["奈德麗","埋伏2","此牌在場上時，我方召喚或幻化4個其他友軍單位。","「我會永遠保護你，蜥蜴女孩。我們會一起讓那些盜獵者付出代價。」——奈德麗","單位",["貓族"],["蘇瑞瑪"],"英雄"],"07SH009":["梵斯塔雅復仇者","埋伏3\n此牌從梵斯塔雅復仇者 埋伏狀態幻化時，抵銷敵方所有快速法術、慢速法術與技能。","","「別害怕，小傢伙們，我會保護你們，然後回報奈德麗的恩情。」","單位",[],["蘇瑞瑪"],"普通"],"07SH039":["全地形士兵","埋伏0\n召喚此牌及此牌幻化時，賦予最弱敵軍單位弱勢。","","「就算是菜鳥，只要穿上這個好東西就能變成爬樹攀岩的專家。我花了不少錢，但只要能獵到一兩張珍獸的皮，肯定就能還清貸款……」","單位",[],["蘇瑞瑪"],"稀有"],"07SH044":["極光迷幻鳥","埋伏4\n此牌幻化時，召喚1隻極光迷幻鳥。","","「我多麼想親眼看看啊！大多數的探險家都認為極光迷幻鳥只是個傳說，但某個年輕人堅稱牠們真的存在。他說那種鳥色彩鮮豔，展翼的寬度跟成人的身高一樣。某天晚上，他向我透露一件事：看著牠的眼睛，就會明白自己是牠的獵物。」——摘自安努拉的調查日誌，第二十一日","單位",["鳥族"],["蘇瑞瑪"],"稀有"],"07SH003":["飛行盜獵者","埋伏3\n此牌從飛行盜獵者 埋伏狀態幻化時，本回合此牌下一次格擋或被格擋時，則俘虜敵軍單位。","","「哈！來抓我啊，愚蠢的野獸。就連重力都拿高等物種沒辦法！」","單位",[],["蘇瑞瑪"],"史詩"],"07SH011":["叢林伏擊陷阱","召喚此牌及每回合友軍單位首次幻化時，賦予最弱敵軍單位弱勢。","","「風中有血的味道。」——奈德麗","地標",[],["蘇瑞瑪"],"普通"],"07SH046":["仿谷","打出侍從單位時，本回合將此牌幻化為與之相同的複製單位。","","「這裡就係旅途中最漂——釀的人氣景點啦。好多人喜翻偶的導覽，就蓋了一個又大又壯的偶，從此變成景點辣。我們去打個招呼吧，『嗨大石奇！』大石奇很愛大家喔，尤——其係現在跟偶們一起踏上旅途的各位。」——《石奇大冒險》第六部","地標",[],["蘇瑞瑪"],"普通"],"07SH043":["叢林巨象","埋伏5","","叢林巨象是叢林裡最古老的生物，有些人說牠們擁有叢林本身的記憶與心靈。雖然牠們平常很溫順，但只要遇到威脅，不管大小，牠們都會奮力保衛家園。 ","單位",[],["蘇瑞瑪"],"史詩"],"07SH040":["剛刺豪豬","友軍單位首次幻化時，賦予此牌+2|+1。","","「小型的雜食性哺乳類動物，身上有著像是剛毛的刺，受到驚擾時可以高速射出。牠們的尾巴帶刺而且靈敏，看起來應該是用來防禦的武器。根據老練探險家的記錄，這些動物以暴躁易怒聞名，非常難搞……」——摘自安努拉的調查日誌，第三日","單位",[],["蘇瑞瑪"],"稀有"],"07SH005":["巨獸大亨","出牌：顯化1張埋伏牌。\n友軍單位幻化時，使其力量值與生命值加倍。","","「你們說獵物被誰搶走了？一個科學家跟一個蜥蜴怪咖？那你們這群蠢材還呆站在那邊幹嘛？去把我的錢搶回來啊！」","單位",[],["蘇瑞瑪"],"稀有"],"07FR011":["真霜神殿","召喚友軍單位時，使其生命值提升至與力量值相同。","","雖然這座神殿的意義早已消逝在時間的洪流當中，但守衛著神殿的石像依舊矗立著，不管經歷了多少次雪崩都不會被壓垮。結霜的石像似乎充滿了某種奇異誘人的微光……","地標",[],["弗雷爾卓德"],"史詩"],"07FR010":["利爪雪梟","洗劫：使1個友軍單位的能力值提升至與此牌相同。","","雖然利爪雪梟的主要獵物是小型哺乳類，但這種弗雷爾卓德野獸的爪子夠利，想要獵誰都可以。","單位",["鳥族"],["弗雷爾卓德"],"普通"],"07FR015":["少女英格娃","出牌：挑選1個友軍單位，賦予該單位與其他所有相同卡牌次類的友軍單位+1|+1，或顯化1張相同卡牌次類的侍從單位。","","英格娃自稱普羅管理員兼弗雷爾卓德探險家，她知道各式各樣的冒險正在外面的世界等著她去發掘，而她一定會做到。 ","單位",[],["弗雷爾卓德"],"史詩"],"07FR017":["水晶風暴鷹","出牌：對所有其他單位造成2點傷害。","","水晶風暴鷹擁有極強的破壞能力，其無差別的攻擊能夠在彈指之間扭轉戰局的走向。許多人認為這隻鳥預示著巨大滅世風暴的來臨——而大地的根基也注定要永久改變。","單位",["鳥族"],["弗雷爾卓德"],"稀有"],"07FR016":["冰河巨蜥怪","召喚此牌時，賦予我方牌組最上方3個單位+1|+1。若有友軍單位卡牌次類與此牌不同，則抽出其中1張。","","這些可靠的坐騎瘦削的外表底下藏了一副好心腸，是為山路除雪不可或缺的存在。","單位",["爬蟲族"],["弗雷爾卓德"],"稀有"],"07SI010":["屍靈巨蛛","召喚此牌時，召喚2隻屍靈幼蛛。\n每有1個其他友軍單位陣亡，便從敵方主堡汲取1點生命值。","","這種蜘蛛只棲息在闇影島的最深處。牠們會分泌一種致命的屍毒，可以麻痺獵物並讓血肉跟著腐爛。","單位",["蜘蛛"],["闇影島"],"史詩"],"07SI012":["毛毛織蛛","出牌：若有友軍單位卡牌次類與此牌不同，則本回合給予1個敵軍單位-2|-0。","","毛毛織蛛會用心地築巢。牠們特別寵自己的幼蛛……遇到威脅時也特別兇惡。","單位",["蜘蛛"],["闇影島"],"普通"],"07SI013":["蔓延闇靈","遺願：在牌組中生成我方牌組內最強蔓延闇靈的複製牌，並使牌組中蔓延闇靈的能力值加倍。","","「黯霧給了我許多寶貴的教訓，其中最重要的就是知道逃跑的時機。」——伊克斯塔爾哨兵","單位",[],["闇影島"],"稀有"],"07SI004":["神聖巨剪","攻擊：此牌的裝備者跟友軍單位一起獲得聖化增益。","","「只要有把好剪刀跟高級絲線，幾乎一切都能搞定！」——關","裝備",[],["闇影島"],"稀有"],"07MT009":["龍之紀元","從我方牌組最上方9張牌中，抽出所有龍族，本回合其魔耗值降為0，並將其餘卡牌洗回我方牌組。","","「了解一條龍就是理解自身；了解許多龍則等同理解整個世界。」——獺人拜龍者","法術",[],["巨石峰"],"稀有"],"07MT013":["星河呼喚","祈望1張魔耗值為7以上的天界牌，或是支付8點魔力，使我方各處的天界牌魔耗值減半，無條件進位。","","仲裁者的亙古職責，便是守望天界的祝福降臨。","法術",[],["巨石峰"],"普通"],"07MT006":["不幸戀人","出牌：召回1個友軍單位並賦予其此牌的能力值。","","「鮮少有能與日月交會之時比擬的美景。」——黛安娜","單位",[],["巨石峰"],"普通"],"07BC020":["勤儉先生","每當我方發動陷阱或祝福時，將2張該陷阱牌植入敵方牌組，或在我方牌組生成2張該祝福牌。","","沒人知道勤儉先生的出身來歷，或是究竟收集了多久的東西。他外表看似友善，只是要小心別被他身後遺落的物品絆倒了。","單位",[],["班德爾城"],"稀有"],"07BC016":["返回扳手","棄置此牌時，將此牌隨機裝備到1個沒有裝備的友軍單位上。","","「老實說，我動不動就會搞丟工具，但這一個總是會在我需要時突然出現！」——安檢員","裝備",[],["班德爾城"],"普通"],"07BC018":["傳送門研究者","召喚此牌時，將1張神祕傳送門植入我方牌組最上方4張牌中。\n召喚生成的友軍單位時，賦予其衝擊。","","不管是哪種研究的前沿，都一定會遇到意料之外的事——幸好這次是好事。 ","單位",["妖精"],["班德爾城"],"史詩"],"07BC011":["兇殘毛球","召喚此牌時，賦予其他擁有卡牌次類的友軍單位+1|+1與衝擊。","","牠們只是「看起來」人畜無害而已，這群皮爾托福盜獵者要倒大楣了。","單位",["鳥族"],["班德爾城"],"普通"],"07DE014":["細心徵兵官","出牌：從我方牌組最上方5張牌中挑選1個魔耗值為3以下的單位。召喚該單位並將其餘卡牌放回我方牌組。","","蒂瑪西亞徵兵官責任重大。他徵召的士兵將會齊心協力，帶著忠貞的愛國心駐紮到蒂瑪西亞各地。","單位",["菁英"],["蒂瑪西亞"],"史詩"],"07DE015":["羽冠獅鷹","出牌：若有友軍單位卡牌次類與此牌不同，則顯化1張蒂瑪西亞法術牌。","","「這是近50年來我們第一次親眼見到獅鷹。牠有著美麗的藍色羽冠，眼神機靈；身上有著硬甲，但骨骼夠輕，至少可以爬樹，或許還能滑翔一段距離。翅膀的構造與蒂瑪西亞銀翼鷲十分相似。我會再回來進一步調查。」——摘自安努拉的調查日誌，第十二日","單位",["鳥族"],["蒂瑪西亞"],"稀有"],"07DE011":["下級狙魔者","使魔耗值為3以下的法術魔耗值改為3。","","「閉嘴！這才不是什麼單純的遊戲，而是隱藏某種邪惡奧術的手法。就算要我燒掉這整個地方，我也會證明你這老狐狸不只耍老千，還是個法師！」","單位",[],["蒂瑪西亞"],"普通"],"07DE016":["仁慈之像貝倫","攻擊：賦予各處其他重壓友軍單位+0|+1。","","貝倫是杜蘭德家族長年以來的好夥伴，在他巨大的身形之下，卻有著一雙出人意料的溫柔巧手。雖然貝倫起初的設計只是作為助手，卻在工藝方面有著過人的天賦，並且具有許多獨到的巧思——也因此受到杜蘭德家族的賞識。","單位",[],["蒂瑪西亞"],"史詩"],"08SI042":["魔鬥凱薩","出牌：擊殺最多2個友軍單位。\n屠殺其他友軍單位時，復甦之。","15個以上友軍單位陣亡，力量值為5以上的友軍單位計數為2。","魔鬥凱薩受縛於不朽堡壘深處的盔甲之中，他在灰之國度打造了自己的王國。凡是想要消滅他的人，都只會成為他的奴僕，無論生前還是死後。","單位",[],["闇影島","諾克薩斯"],"英雄"],"08SI040":["恥辱的厄拉斯汀","召喚此牌時，賦予此牌不死。\n攻擊：本回合給予所有敵軍單位-1|-0。","","迦瑪沃爾的龍族曾經雄偉並受人敬重，但就連牠們都逃不了吞噬、腐化一切的殞落王者詛咒。厄拉斯汀也不例外，他早已失去皇族風範，現在只剩不死龍族扭曲與令人生畏的外表。","單位",["龍族"],["闇影島"],"史詩"],"08SI007":["亡靈軍團","出牌：賦予手牌中1個友軍單位不死。","","無論原本是什麼東西，只要靈魂來到灰之國度，一切就都無所謂了。在那裡，被囚禁的靈魂沒有受區分的價值，它們沒有五官、不知恐懼，整支軍團整齊一致，全部服從於金屬亡靈之下。","單位",[],["闇影島"],"普通"],"08SI003":["鐐銬邪靈","遺願：我方下次復甦友軍單位時，在手牌生成1張此牌的複製牌。","","「這些手銬腳鐐已有千古之久，很快你也會知道我們的痛苦，我們將會一起受苦，永遠永遠，直到主人願意消滅我們……」","單位",[],["闇影島"],"稀有"],"08SI021":["編鐘孤魂","每有1個其他友軍單位陣亡或遺願：將4張編鐘植入我方牌組。","","別在意那詭異的聲響，只是編鐘史萊姆在亂晃而已。他很喜歡客人來訪，但客人都不喜歡他。","單位",[],["闇影島"],"普通"],"08SI030":["海底墳場","從敵方牌組底部泯滅6張牌。","","對符文大地一些深海海怪來說，青囊魚漁船只不過是小點心罷了。","法術",[],["闇影島"],"史詩"],"08SI037":["惡靈鐵犬","擊殺1個友軍單位即可出此牌。\n召喚此牌時，召喚1隻千爪死鳴者。","","這些惡犬從不忘記逃亡者的氣味——而當牠們將獵物逼到角落時，死鳴者也會緊跟在後。","單位",[],["闇影島"],"稀有"],"08SI041":["死之爪","擊殺1個友軍單位，以對1個單位造成5點傷害。","","「等待著萬物的只有黑暗，除了我以外。」——魔鬥凱薩","法術",[],["闇影島"],"普通"],"08SI036":["灰之門檻","出牌：對1個敵軍單位下恐懼詛咒。\n我方召喚泰坦單位時，摧毀此牌以抽2張牌。","","「我們獻給您這些靈魂，我們以亡者之骨為您鋪路，我們毀滅這些國度，為您永垂不朽的金屬軍團開路。」\n——死爪邪教徒","地標",[],["闇影島"],"稀有"],"08SI004":["死亡領域","使1個友軍單位發動額外攻擊，挑戰最強敵軍單位。\n擊殺場上其他所有單位。","","「我將以死亡征服一切。」——魔鬥凱薩","法術",[],["闇影島"],"史詩"],"08SI026":["死爪邪教徒","召喚此牌及我方召喚泰坦單位時，對最強敵軍單位下恐懼詛咒。","","在追隨者的眼中，金屬亡靈是追求毀滅者唯一的希望。支配之下的和平——這些邪教徒敞開雙臂恭迎他的到來。","單位",[],["闇影島"],"稀有"],"08SI018":["冥魂勘測員","出牌：挑選1張冒險者法術，在手牌中生成。","","「這裡神祕莫測，伸手幾乎不見五指，處處都是敵人，但奇妙的是，有時也有朋友。」——冒險者公會實地考察紀錄，遙遠邊陲部，駐地：闇影島","單位",[],["闇影島","巨石峰"],"稀有"],"08SI015":["邪術融合體","擊殺1個友軍單位即可出此牌。\n遺願：治療我方主堡2點生命值。","","戰爭用的猛獸對任何軍隊都有用處。在灰之國度，戰爭用的野獸是眾多受苦靈魂融合在一起的怪物，每個靈魂都失去了知性，只想狂亂地吞噬一切。 ","單位",[],["闇影島"],"史詩"],"08BW008":["淣菈","攻擊：在我方牌組最上方6張牌中生成1張湍流淩步。","我方抽出15張以上卡牌。","淣菈與她狩獵怪物同夥的新目標：弗力貝爾，就居住在極北的弗雷爾卓德。這個生物威脅要摧毀曾經崇拜他的這片土地。對淣菈來說，能夠和自詡為神的怪物大打出手、測試自身實力，可說是一生難求的好機會。更別提一路上還能打敗許多小型怪物，為自己的豐功偉業更添上一筆。 ","單位",[],["比爾吉沃特"],"英雄"],"08BW032":["樂無止境","本回合給予所有友軍單位+1|+0，並治療負傷友軍單位2點生命值。","","「歡樂滿溢，永無止境！」——淣菈","法術",["元素"],["比爾吉沃特"],"普通"],"08BW038":["環刃舞者","出牌：對任1目標造成1點傷害。\n我方技能會汲取生命值。","","她跳著水與刃之舞，從攪動的泡沫與水霧中抽出刀刃。她不需要用眼睛看，即可感覺到武器的流動——水刃即是舞動的水，並終歸是水。","單位",[],["比爾吉沃特"],"史詩"],"08BW015":["舞潮號","召喚此牌時，抽1張淣菈。\n我方每回合第三次出牌時，賦予其他友軍單位本回合+2|+0與硬派。\n此牌將要獲得飛逝時，改為讓此牌現出原形。","","「聽說那艘奇形怪狀的艦艇，是比爾吉沃特速度最快的船，還十分靈巧。船長也是個奇人，但看來對自己的能力頗有自信。或許我們能從她身上學到一兩招。」\n——比爾吉沃特酒保","單位",[],["比爾吉沃特"],"史詩"],"08BW002":["百變之刃","對1個單位造成2點傷害。受此傷害後，目標的生命值不會低於1。","","「無論位在何處，只要自稱為神的怪物都終將倒下。」——淣菈","法術",["元素"],["比爾吉沃特"],"普通"],"08BW025":["瞭望大師","在本牌局中，我方在同一回合中抽出3張以上卡牌後，賦予此牌+1|+1與硬派。","","「喂，兄弟，有什麼好大驚小怪的？放輕鬆！海水裡沒有什麼我們應付不來的東西！」——挑戰狂","單位",[],["比爾吉沃特"],"普通"],"08BW026":["挑戰狂","召喚此牌時，吹升手牌，每吹升1張手牌便賦予此牌+1|+1，並抽2張牌。","","「天啊，你到底有沒有出力？不會真的要我放水吧？我跟你說，我超討厭放水的！」","單位",[],["比爾吉沃特"],"稀有"],"08BW028":["八腳探險家","出牌：挑選1張冒險者法術，在手牌中生成。","","「怪異的生物。非常藍，雙眼挺大的，大得讓人有點不舒服。準備帶回去進一步研究。」——冒險者公會實地考察紀錄，遙遠邊陲部，駐地：皮爾托福","單位",[],["比爾吉沃特","皮爾托福&佐恩"],"稀有"],"08BW009":["年長舵手","出牌：顯化2張本牌局中已打出的不同元素法術，並使其本回合魔耗值為0。","","「心智是一條長河。隨著時間過去，它會隨著付諸的努力而刻劃出山脈的面貌。而心智正如流水，只要加以催生動力，就能逐漸變得寬廣，最終抵達未知的彼岸。」","單位",[],["比爾吉沃特"],"稀有"],"08BW010":["洪水","我方所有元素法術與技能造成1點額外傷害，此效果持續到牌局結束。","","「在智者的手中，流水能形塑一切事物。」——智慧聖者","法術",["元素"],["比爾吉沃特"],"史詩"],"08BW031":["深淵災厄塞菲煞","我方消耗魔力打出另1個單位時，在手牌生成1張魔耗值相同的隨機卡牌，其為飛逝且魔耗值為0。","","無論是多奇怪的海獸，在比爾吉沃特都能找到買家，除了一些連最老練的船長都不敢捕獵的怪物以外。談到塞菲煞時，所有人都會輕聲細語，說牠棲息於大海深處，由沉船和死者堆積而成的巨大墳墓上，頭上發出的光引人入睡，而且再也醒不來。","單位",["海怪","龍族"],["比爾吉沃特"],"史詩"],"08BW037":["老實荷官","我方打出魔耗值等同此牌力量值的卡牌時，賦予此牌+1|+1。","","「嗯，難道你不想多下點賭注嗎？不冒點風險，怎麼會有高獲利呢，對吧。今晚這牌桌受到幸運之神的眷顧，我告訴你。這間高級賭場的莊家絕不會出老千，我用我媽的舌頭發誓。」","單位",[],["比爾吉沃特"],"稀有"],"08BW036":["瑪拉族珊瑚尖塔","我方消耗魔力打出單位時，恢復1點法術魔力。","","「珊瑚礁不僅提供我們居所，也是我們的戰友，一直以來我們共存共榮，才免於遭到黯域的黑暗所吞噬。」\n——瑪拉族聖母","地標",[],["比爾吉沃特"],"普通"],"08BW023":["熱血者維克拉許","召喚此牌時，在我方牌組最上方6張牌中生成1張湍流淩步。","","「朋友們，看過來！瞧這世界和我們一起舞動！浪濤在船身下起舞，海風挑動著船帆，鳥兒隨著微風飛揚。快加入我們崇高的志業，放聲歡笑吧！」","單位",[],["比爾吉沃特"],"史詩"],"08PZ007":["颶歌燕群","召喚1隻颶歌燕，本牌局我方每打出1張其他元素法術與技能便賦予其+1|+1。\n抽1張牌。","","當颶歌燕群出現，就代表暴風即將來臨。","法術",["元素"],["皮爾托福&佐恩"],"稀有"],"08PZ031":["可疑眼鏡","挑選1個友軍侍從單位，在此牌裝備期間，將裝備者幻化為與之相同的複製單位。","","別問這東西的原理是什麼。","裝備",[],["皮爾托福&佐恩"],"稀有"],"08PZ025":["原型普羅機器人","遺願：隨機賦予1個手牌中魔耗值為6以上的法術「打出此牌時，召喚1個原型普羅機器人。」","","「它只是試作品。」學徒一邊大叫，一邊看著火焰吞噬實驗室。「我沒有設計看到齒輪就吃掉的功能！我甚至不知道那些金屬都去哪了！」","單位",["普羅"],["皮爾托福&佐恩"],"稀有"],"08PZ005":["風暴之眼","本回合給予1個友軍單位+2|+0。\n抽2張牌。","","「不必驚慌！風暴雖然在你們四周呼嘯，但不會傷害你們。」——珍娜","法術",["元素"],["皮爾托福&佐恩"],"普通"],"08PZ019":["神聖旋風","若本回合我方抽了3張牌以上，則此牌魔耗值-2。\n對1個單位造成3點傷害，並對敵方主堡造成2點傷害。","","「風暴之力由我掌控。」——珍娜","法術",["元素"],["皮爾托福&佐恩"],"稀有"],"08PZ028":["生化科技飛龍","我方打出法術時，抽1張牌。抽牌時，若手牌全滿，則對敵方主堡造成1點傷害。","","佐恩講究適者生存，而生化科技飛龍也不例外。牠在城市下層出沒，身上的強化部件發出令人作嘔的綠光，其破爛雙翼產生的陰影，在漆黑的通道中若隱若現，腐化對其造成的痛苦，化為了會吞噬周圍的怒火。","單位",["龍族"],["皮爾托福&佐恩"],"史詩"],"08PZ001":["珍娜","出牌：吹升2張手牌，並於下次回合開始抽2張牌。\n每回合，我方抽的前3張牌，本回合魔耗值-1。","此牌在場上時，我方打出8張魔耗值降低的卡牌。","「如果要找到珍娜，那佐恩肯定是最有可能的地方，畢竟是她救了那些皮爾托福棄而不顧的可憐人。對啊，如果要尋求答案的話，來這裡準沒錯。」——乘風水手","單位",[],["皮爾托福&佐恩"],"英雄"],"08PZ026":["颶歌呼喚","召喚1隻颶歌燕。","","「所有的風之子女，回應我的呼喚吧。」——珍娜","法術",["元素"],["皮爾托福&佐恩"],"普通"],"08PZ006":["深淵海妖婭希拉","我方打出元素法術或技能時，對相同目標再複製一次。","","「來吧，婭希拉！如果連艾許勒蘇都知道你的名字，那你真的很老了。但不管年輕衰老、醜陋美麗，對怪物來說，最高的榮耀就是在海上死在我的劍刃之下。」——淣菈","單位",[],["皮爾托福&佐恩"],"史詩"],"08PZ018":["乘風水手","若本回合我方抽了3張牌以上，則此牌魔耗值-2。","","「對，我想要的一切都到手了，但都是搶來的，而搶奪會讓人失去一切。我跟隨著風，現在來到了這裡，希望她會將我推上更好的人生道路。」","單位",[],["皮爾托福&佐恩"],"普通"],"08PZ008":["神廟守望者馬爾雅姆","出牌：吹升1張牌以抽1張牌或恢復我方所有法術魔力。","","馬爾雅姆相信她小時候曾被珍娜所救，所以從家鄉的蘇瑞瑪散播風暴女神的福音，一路到佐恩。她現在是佐恩神廟的廟長，全心全意地將珍娜的善意傳給年輕與受欺壓之人。","單位",[],["皮爾托福&佐恩"],"史詩"],"08PZ009":["海底神廟","回合結束：吹升我方手牌。\n回合開始：抽出該張數+1的牌。","","將佐恩與皮爾托福分開的崩坍之災造成了巨大的傷亡，珍娜的神廟雖然被巨浪摧毀，但她拯救了當中的信徒。","地標",[],["皮爾托福&佐恩"],"史詩"],"08PZ002":["颶風呼嘯","對1個單位造成2點傷害。\n除此牌外，本回合我方每打出1張牌，便提升此牌1點傷害，最多3次。","","「我的怒火隨著颶風呼嘯！」——珍娜","法術",["元素"],["皮爾托福&佐恩"],"稀有"],"08PZ024":["江湖魚販","回合開始：雙方各抽1張牌，然後賦予對手的卡牌飛逝。","","「今天買一送一，只限今天！新鮮的魚，今……呃，這個月剛捕到的喔？買一送一！什麼叫你不要送的那條？是免費的欸！」","單位",[],["皮爾托福&佐恩"],"普通"],"08PZ020":["遊雲聖獸","若本回合我方抽了3張牌以上，則此牌魔耗值-2。\n召喚此牌時，於下次回合開始抽2張牌。","","「我親愛的西風啊，從雲端上下來，在我的肩上歇息一會，好嗎？」——珍娜","單位",[],["皮爾托福&佐恩"],"稀有"],"08FR012":["轟雷召喚","抽1張牌。\n召喚1個風暴之紋。","","「以法赫爾之名，我們獻上此祭品……」\n——法赫爾的先知","法術",["元素"],["弗雷爾卓德"],"普通"],"08FR033":["劍縛狂戰士","我方對單一友軍單位打出慢速法術時，對此牌再複製一次。","","「你以為一兩支箭就能阻止我嗎？哈！無論你朝我丟什麼，都會成為我的武器；無論我失去什麼，我都會用寒冰重鑄！」","單位",[],["弗雷爾卓德"],"普通"],"08FR019":["蒼穹裂隙","本回合給予1個友軍單位+1|+3。","","烏雲籠罩，雷電纏繞，巨熊之神在風暴的中心屹立不搖。","法術",["元素"],["弗雷爾卓德"],"普通"],"08FR001":["弗力貝爾","出牌：打出3次無情風暴，每次皆以不同的隨機敵軍單位為目標，若無則以敵方主堡為目標。","回合結束：我方造成50點以上傷害。","「凡人啊，臣服於我，我就考慮饒你一命！你的力量微不足道，但說不定夠格為我所用。跪下，不然就準備從地表上消失！」","單位",[],["弗雷爾卓德"],"英雄"],"08FR018":["猛獸大戰","隨機召喚2個泰坦侍從單位。\n本牌局我方每打出1張元素法術或技能，此牌魔耗值便-1 (最多-10)。","","「我用祂的身體雕刻出群山，用祂喉中之火劃出萬千峽灣。」——弗力貝爾","法術",["元素"],["弗雷爾卓德"],"史詩"],"08FR011":["羊角喚焰者","我方打出元素法術或技能時，鑄煉此牌。","","「鍛爐之主承諾要做出改變，卻打造出不動之鍊，只有懦弱之徒才會崇拜懦弱之神。只有法赫爾的神威能帶我們回到光榮的過往！」","單位",[],["弗雷爾卓德"],"稀有"],"08FR008":["風暴使者","對所有單位造成4點傷害，泰坦友軍單位除外。","","「血洗凍原吧！」——弗力貝爾","法術",["元素"],["弗雷爾卓德"],"稀有"],"08FR024":["雅達斯克雪地犬","攻擊：賦予牌組最上方2個友軍單位+1|+1。","","這些狗狗源自雅達斯克，但牠們已經被一些弗雷爾卓德部族馴養，用來追蹤、打獵和雪崩救援。牠們體格健壯又非常愛玩，是人們探索凍原和針葉林的好夥伴。","單位",["犬族"],["弗雷爾卓德"],"普通"],"08FR015":["岩漿蟒蛇隆德","出牌：召喚3個風暴之紋。","","雖然崇拜祂的人為數不多，所有弗雷爾卓德人都知道弗力貝爾與隆德的世紀大戰。很久以前，在北方凍土人煙未至時，這場撼天震地的大戰創造出了這片凍原的山脊與河流。","單位",[],["弗雷爾卓德"],"史詩"],"08FR030":["黑冰女王波蒂爾","召喚此牌時，召喚2名冰封奴魔，並將其快轉至2。","","「波、波蒂爾兇狠無比！她將奴魔燒成黑冰，利爪能引起雪崩，一發出咆哮，山上的積雪就被震掉了！我真心不騙，她是個戰士女王啊！因、因為殺死奴魔，是戰士女王才能做到的事。」——碎碎念的比亞","單位",["龍族"],["弗雷爾卓德"],"史詩"],"08FR002":["法赫爾的先知","召喚此牌時，召喚1個風暴之紋。","","「我能見他人所不可見：風暴將會摧毀高山，大地將會崩壞，古老的弗雷爾卓德將會在鮮血中重獲新生——只待時辰來到。」","單位",[],["弗雷爾卓德"],"普通"],"08FR028":["精巧輓具","本牌局我方每召喚1種不同的卡牌次類，此牌便獲得+1|+0。","","「這裡有些猛獸連雪崩都擋不了，所以花錢買好一點的輓具絕對是值得的。」——艾伐洛森捕獸人","裝備",[],["弗雷爾卓德"],"史詩"],"08FR003":["巨熊族狂戰士","我方打出法術或技能時，召喚1個風暴之紋。","","有時候，弗力貝爾的信眾會在狂熱之中發狂，彷彿像是弗力貝爾上身，法赫爾的意志無人能擋——就連曾經的同胞也不例外。","單位",[],["弗雷爾卓德"],"稀有"],"08RU014":["遠古巨龍","起源：巨龍威勢。\n本牌局我方每打出1張不同的龍恩，此牌魔耗值便-1。\n出牌：將所有龍恩附加在此牌上。","已進行攻擊的友軍單位力量值總和為75以上。","「傳說這條龍是所有龍中最古老的——牠是所有飛龍的王。如果我們馴服牠……怎麼了，亞拉提斯？還有什麼擋得了我們？世界終將了解人龍一體有多麼強大。」\n——龍族追隨者佛力克斯","單位",["龍族"],["符文大地"],"英雄"],"08NX003":["暴怒噴火龍","出牌：對1個敵軍單位造成2點傷害，並對敵方主堡造成2點傷害。","","諾克薩斯擴張領土時，吞併了許多民族、聚落，以及文化，就連野獸也逃不過這個戰爭機器——不過，這隻飛龍並不打算坐以待斃。諾克薩斯進軍時有多殘暴，牠便以同等的烈火狂焰招呼他們。","單位",["龍族"],["諾克薩斯"],"史詩"],"08NX024":["鋼鐵軍團士兵","出牌：對1個友軍單位造成3點傷害，對1個敵軍單位造成3點傷害。","","「把他們的魂魄扯出肉體的牢籠！」——魔鬥凱薩","單位",[],["諾克薩斯"],"稀有"],"08NX011":["野火","對敵方主堡造成1點傷害，且每打出另1張野火，傷害便+1。在我方牌組生成1張野火。","","「化為塵埃、塵埃……」——安妮","法術",["元素"],["諾克薩斯"],"普通"],"08NX028":["不滅之軀","賦予1個友軍單位不死。","","「永世之鋼。」——魔鬥凱薩","法術",[],["諾克薩斯"],"普通"],"08NX019":["紅刺利錘蜥","打擊主堡：對敵方下膿水詛咒。","","除了能夠幫助諾克薩斯打仗外，利錘蜥也是競技場的明星。不管是人還是動物，很少對手敢在競技場面對這種野獸，所以利錘蜥只要上場戰鬥，就會吸引全城的人過來觀賞。","單位",["爬蟲族"],["諾克薩斯"],"普通"],"08NX014":["泰爾希校長","我方攻擊與支援效果額外發動一次。","","泰爾希校長的自律課程充滿了難搞的作業、體罰和留校察看。這是雷文布魯學院的必修課，不修的話沒人可以入學。","單位",[],["諾克薩斯"],"史詩"],"08NX012":["武裝挖掘者","出牌：挑選1張冒險者法術，在手牌中生成。","","「我以為沙漠會比較好挖，但我錯了！只要時間夠久，沙地也會硬得跟石頭一樣。再次請求提供資金更換裝備。」——冒險者公會實地考察紀錄，遙遠邊陲部，駐地：蘇瑞瑪","單位",[],["諾克薩斯","蘇瑞瑪"],"稀有"],"08NX029":["袈守里揮擊","擊殺1個負傷的單位，若未負傷則改為對其造成2點傷害。","","「這樣對你最好，相信我。」——寬鬃領主","法術",[],["諾克薩斯"],"史詩"],"08NX009":["馬拉特領主","","","「我們花了好幾世紀才封印了那個可怕的戰爭狂——而你那些可悲的朋友們打算用『歡樂』來擊敗他？你這愚蠢的ㄚ頭，你這樣只會引起亡靈的憤怒，然後陷我們所有人於危險之中。」","單位",[],["諾克薩斯"],"普通"],"08NX025":["穿刃亡靈","友軍單位復甦時，賦予其挑戰者。","","「你滿臉笑容，但我知道你的心中只想著背叛！他們對我微笑，與我同桌共餐，卻想著要往我背後捅一刀。我不會再被騙了，你會跟他們一樣：一邊尖叫著乞求原諒，一邊死去！」","單位",[],["諾克薩斯"],"稀有"],"08SH009":["遠古詛咒","對1個敵軍單位下恐懼詛咒。","","有些東西最好不要挖出來。","法術",[],["蘇瑞瑪"],"普通"],"08SH014":["魔角喚群龍","出牌：賦予2個敵軍單位-1|-0，並使其增益特性無效化。","","雖然這種喚群龍體型巨大，但通常都十分溫馴。當牠的龍群靠近蘇瑞瑪村莊，村民會在附近的沙漠留下軟熟的水果當作祭品，誘使這些訪客遠離重要的作物。","單位",["龍族"],["蘇瑞瑪"],"普通"],"08SH004":["沙丘將軍","破曉或我方發動其他破曉效果時：賦予最弱敵軍單位弱勢。","","蘇瑞瑪大軍準備好證明沙漠的強大。一聲令下，他們就會毫無猶豫地向前行軍。","單位",["菁英"],["蘇瑞瑪"],"稀有"],"08SH005":["烈日巨環守軍","破曉：抽1張烈日巨環守軍。","","「沙漠永垂不朽，汝等為其守護者，是活歷史，同時也是光輝之道的行者。我們只服從於烈日巨環，不屈於任何人之下，以此讓全世界臣服在蘇瑞瑪的榮耀之下。」\n——阿祈爾","單位",["菁英"],["蘇瑞瑪"],"普通"],"08SH012":["古墓奇蜥芭芭拉","每回合首次有其他友軍單位陣亡時或遺願：在手牌生成1張挖到寶。","","「收穫真豐富啊，芭芭拉，就知道有你在就沒問題。等等——什麼叫他們看見你了？！」——維庫拉壯漢","單位",["爬蟲族"],["蘇瑞瑪"],"稀有"],"08SH002":["沙丘吞噬者","擊殺1個友軍單位或摧毀我方1顆魔力寶石3次，即可出此牌。","","與體型較小的煞族同胞相比，沙丘吞噬者棲息於黃沙的更深處。儘管有傳聞說牠能輕易吞噬其他煞族掠食者，但實際留下的紀錄卻少之又少——可能是因為牠一口就能吞下整座沙丘，包含目擊者。 ","單位",[],["蘇瑞瑪"],"史詩"],"08MT003":["魔甘娜","出牌：對1個敵軍單位下枷鎖詛咒兩次。","我方指定10個以上單位為法術/技能目標。","「你遍體鱗傷地來找我，但我從未見過如此歡喜的表情。你真是個奇怪的女人，但我保證你在這裡安全無虞。好好休息吧，等你身體好一些，我想聽聽你的故事。」","單位",[],["巨石峰","蒂瑪西亞"],"英雄"],"08MT005":["昇天星靈彌赫菈","出牌：對2個敵軍單位下枷鎖詛咒兩次。","","「以我的女兒之名，我擁抱神性。為了我的家人，我捨棄了人性。我將以這把烈焰之劍開創真理與正義的全新世界。」","單位",[],["巨石峰"],"史詩"],"08MT042":["罪者禁錮","對1個敵軍單位下枷鎖詛咒。\n使各處敵方詛咒魔耗值+1。","","「想尋得自由，就承認內心的黑暗面吧。」——魔甘娜","法術",[],["巨石峰"],"稀有"],"08MT024":["紅眼咒術師","出牌：賦予手牌中1個友軍單位法盾或蠻力。","","「別害怕！繼續走，別回頭！我們也曾經走過這段路，現在輪到我們守護你的旅程。快到她的庇護所去，蒙面者將給予你尋求的保護。」","單位",[],["巨石峰"],"普通"],"08MT045":["受縛法師","出牌：對此牌下枷鎖詛咒。","","狙魔者擅長讓人崩潰。他們束縛了他的雙手與魔法；他們奪走了他的聲音，但他都活了下來——而這次，他有蒙面女神的加護。","單位",[],["巨石峰"],"稀有"],"08MT015":["莉沙和多莉","出牌：對1個敵軍單位下枷鎖詛咒。","","「看，多莉！你教我的，我已經學會了！你覺得我們有機會讓媽媽看到我進步了多少嗎？你說她已經知道了？真的嗎？！希望真是如此。」——莉沙","單位",[],["巨石峰"],"普通"],"08MT030":["溫柔寶石龍","我方打出快速法術、慢速法術或技能時，賦予其他龍族友軍單位+1|+1。","","龍族因種類的不同，其性情和外表可能天差地遠。像赤燄飛龍這類的龍族會將眼前的一切毀滅殆盡，不過也有會保護家族和環境的龍族，像是動作緩慢，但富有感情的寶石龍。","單位",["龍族"],["巨石峰"],"稀有"],"08MT023":["暗影禁錮","擊暈1個敵軍單位，並對其下枷鎖詛咒。","","「你帶給他們痛苦，現在該你來嚐嚐痛苦的滋味！」——魔甘娜","法術",[],["巨石峰"],"稀有"],"08MT031":["獺人拜龍者","召喚此牌時，治療我方主堡2點生命值，並於下回合額外獲得1顆魔力寶石。","","巨石峰高處有個遺世獨立的獺人，將自己的一生獻給龍族。他會將龍族蛻下的鱗片和老舊的骸骨穿戴在自己身上，觀察龍牙散落的樣子和捲曲的煙霧來占卜前進的道路。","單位",[],["巨石峰"],"史詩"],"08MT009":["蒙面守護神獸","召喚此牌或我方召喚泰坦單位時，治療我方主堡3點生命值。","","這個蒙面的守護者，從未忘記使自己昇華為神獸的祝福，其回報這份恩情的方式，便是確保尋求巨石峰庇護的人，能夠安然無恙抵達目的地。","單位",[],["巨石峰"],"稀有"],"08MT006":["黑暗之盾","本回合給予1個友軍單位法盾，並對其下枷鎖詛咒。","","「永不再遭受迫害！」——魔甘娜","法術",[],["巨石峰"],"稀有"],"08MT027":["星蝕神梟","出牌：發動其他友軍單位的破曉與夜臨效果。\n破曉：賦予此牌蠻力。\n夜臨：賦予此牌法盾。","","「烈火之環燃燒在上，在即將到來的黑暗之中，一切不分你我。」——月環教陰晴講者","單位",["鳥族"],["巨石峰"],"史詩"],"08MT025":["地震碎片","若我方掌控泰坦單位，則此牌魔耗值-3。\n對1個單位造成7點傷害。","","「唉呦，噢不，不用擔心辣個，只係石頭晃了一下而已，小意外啦，絕對不係老爹真的不係啦！」沒什摸豪看滴！」——石奇","法術",["元素"],["巨石峰"],"普通"],"08DE006":["拓荒學者","出牌：挑選1張冒險者法術，在手牌中生成。","","「這裡好冷，我好冷，這裡一天到晚都好冷。有些地方就不是給人住的，下次拜託派我去溫暖的地方。」——冒險者公會實地考察紀錄，遙遠邊陲部，駐地：弗雷爾卓德","單位",[],["蒂瑪西亞","弗雷爾卓德"],"稀有"],"08DE020":["魔法束縛","賦予1個友軍單位+0|+2。對敵方下抑制魔力詛咒。","","「認清你罪惡的重量！」——魔甘娜","法術",[],["蒂瑪西亞"],"普通"],"08DE017":["狙魔仲裁官","召喚此牌時，對敵方下抑制魔力詛咒。","","「我們不能讓他們到達墮落女巫的庇護所。她的魔力既古老又邪門，以我的能力根本抑制不了。快點，把這些討厭的傢伙帶回船上，然後上山追趕他們的餘黨！」","單位",[],["蒂瑪西亞"],"稀有"],"08DE025":["疾風飛龍","召喚此牌時，使手牌中所有友軍單位魔耗值-1。","","這種龍身上有厚厚的毛皮抵禦寒冷，因此可以比大多數的龍飛得更高。這種龍天性活潑但來無影去無蹤，經常出現在高空中，牠們喜歡追逐狂風，看起來像是在騰雲駕霧一般。","單位",["龍族"],["蒂瑪西亞"],"史詩"],"08DE010":["紳士決鬥","本回合給予1個友軍單位+0|+2。\n使該友軍單位與1個敵軍單位互相打擊。","","「預備擊劍，朋友！你那麼勇敢，肯定不會拒絕紳士間的決鬥吧？」——羅倫特家族騎士","法術",[],["蒂瑪西亞"],"普通"],"08DE022":["翠鳥號","召喚此牌時，從我方牌組抽出所有英雄各1張。\n每回合我方首次召喚英雄時，進行備戰。","","「我的兒子，記住這件事：追求夢想的目的，必須是為了駛離的家園。」——嘉文三世國王","單位",[],["蒂瑪西亞"],"史詩"],"08DE027":["鷹爪打擊","賦予我方各處鳥族+1|+1。使1個我方鳥族打擊1個敵軍單位。","","銀翼鷲的尖嘯代表死亡將從天而降。","法術",[],["蒂瑪西亞"],"稀有"],"08DE026":["英勇飛龍亞拉提斯","我方的龍恩會以所有龍族友軍單位為目標。","","「有件事我要說清楚，我並非一直都是龍族追隨者。是自從亞拉提斯第一次救了我之後，我才開始信服牠。牠教了我很多事，但最重要的是，沒有比騎在龍背上效忠蒂瑪西亞更棒的人生了。」——龍族追隨者","單位",["龍族"],["蒂瑪西亞"],"史詩"],"08DE013":["龍族追隨者","召喚此牌時，若我方掌控龍族牌，則抽1張龍族牌。","","「我真的很不想這麼承認，但是老朋友，憑我們是馴服不了牠的。我們已經盡力了。我會派人傳話給將軍，有蒂瑪西亞這個強大後盾，我們絕對能讓那頭神獸臣服於我們。」","單位",[],["蒂瑪西亞"],"普通"],"08IO012":["癒水飛龍","打出快速法術、慢速法術或技能時，治療我方主堡1點生命值。","","「偉岸的巨獸啊！看你的爪子拂過水面，多麼優游自在啊。如果你厭倦了獵捕魚和飛鳥，我不介意與你一戰。」——淣菈","單位",["龍族"],["愛歐尼亞"],"稀有"],"08IO014":["世界之殼閉索","每回合我方打出的第1張牌魔耗值-9。","","對這座愛歐尼亞村莊的居民來說，閉索是受尊敬的守護者也是朋友。他從遠古時期就將他們的家園背在背上，在動亂的年代尋找平靜之岸。","單位",["爬蟲族"],["愛歐尼亞"],"史詩"],"08IO021":["蒼天龍之舞","抵銷敵方的快速法術、慢速法術或技能，召回1個敵軍單位，並召喚蒼天龍。","","「這支舞將成為我們的紀念。」——伊瑞莉雅","法術",[],["愛歐尼亞"],"稀有"],"08IO019":["可靠的艾尼爾","召喚此牌時，召喚艾尼爾的飼鳥助手。","","「這片大地是我們的導師，記住這件事：要歡慶每個季節，因為有終才有始。」","單位",[],["愛歐尼亞"],"稀有"],"08IO010":["傾覆","召回1個敵軍單位來使對手本回合下一個打出的單位魔耗值+2。","","「傷害吾等者將永眠於海底。」——人魚術士","法術",["元素"],["愛歐尼亞"],"普通"],"08IO023":["騰躍海靈","出牌：召喚1個此牌的閃靈複製單位。","","每年到了這個時節，當海風吹來時，就有佐恩人宣稱他們隱約看見兩隻巨大有鰭的生物在隨著浪潮快樂起舞。","單位",[],["愛歐尼亞"],"普通"],"08BC020":["早起鳥兒","使對手棄置魔耗值最高的手牌。","","「想像你是一條蠕蟲，你死前最後看到的是那雙眼睛。喔，蠕蟲看不見嗎？嗯，那還算走運。」\n——失興旅人艾莉","法術",[],["班德爾城"],"普通"],"08BC005":["爆滿的背包","本牌局我方每打出1張爆滿的背包，便將4張編鐘植入我方牌組，並將4張劇毒膨菇植入敵方牌組。在我方牌組生成1張爆滿的背包。","","「第207條守則：優秀的斥候身上只會帶著必需品！」——優等生艾娃","法術",[],["班德爾城"],"稀有"],"08BC021":["隱密調換","召回1個友軍單位，並在原處召喚1隻飢餓貓耳鴞。","","「啾哇？」——貓耳鴞","法術",[],["班德爾城"],"稀有"],"08BC002":["「珊瑚礁之王」奇普","出牌：從敵方手牌中的非英雄牌2選1。此牌俘虜之。","","「沒錯，我英俊瀟灑、頭腦靈活、酷到不行。老頭子，你看不出來嗎？我是這片珊瑚礁的王，而你侵犯到我王國的領土了！」\n「等、等一下！給我回來！那是研究要用的樣本！」——貝殼學家","單位",[],["班德爾城"],"史詩"],"08BC006":["傳送門先驅","出牌：挑選1張冒險者法術，在手牌中生成。","","「我好擔心邦奇！最近他感覺神經變得越來越緊繃，就連短距離的傳送門也會嚇到他！不知道是怎麼回事。」——冒險者公會實地考察紀錄，遙遠邊陲分區，駐地：班德爾城","單位",["約德爾人"],["班德爾城","愛歐尼亞"],"稀有"],"08BC004":["怪龍波希婭","出牌：顯化1個泰坦侍從單位，將其能力值設為1|1，並將魔耗值降為0。","","「我當然認識波希婭囉！她有點瘋瘋癲癲的，不過如果你急著趕去某處，她一定能幫到你：她尾巴一搖，就能開個傳送門給你了！」——傳送門先驅","單位",["龍族"],["班德爾城"],"史詩"],"08BC018":["甜蜜陷阱","將1個友軍單位洗入牌組底部，以召喚牌組最上方的友軍單位。","","「第571條守則：斥候必須隨時保持警覺。你永遠不知道什麼是美味的點心，什麼是甜蜜的陷阱。」\n——優等生艾娃","法術",[],["班德爾城"],"稀有"],"09SI015":["美麗災難","I：擊殺1個力量值和生命值總和為5以下的單位。\nII：從敵方主堡汲取2點生命值。\nIII：召喚1個友軍單位的複製單位，其能力值為1|1且為閃靈。","","他一步一步走上舞台，手中緊握寫好的詩。他並沒有為這場表演貼海報宣傳，因為他想看到的唯一一名觀眾已經到場了。","地標",["故事"],["闇影島"],"史詩"],"09SI013":["鐵血征程","I-II：挑選1個友軍侍從單位，在手牌生成1張與之相同的閃靈複製牌，並賦予其+1|+1。\nIII：復甦最強已陣亡友軍侍從單位，並賦予其閃靈。","","在灰之國度裡，飽受折磨的靈魂聚在一起，組成一支惡靈大軍。通往凡間的大門打開後，他們將無人能擋。","地標",["故事"],["闇影島"],"稀有"],"09SI012":["存在危機","賦予敵軍單位無望。","","「活著到底有什麼意義？」——薇可絲","法術",[],["闇影島"],"稀有"],"09SI017":["卡戎斯","每有1個非觸手友軍單位陣亡或遺願：海祭2。","","卡戎斯是被航海家稱為「終航號」的幽靈船上唯一一個船夫，傳聞他能夠與所有在前往闇影島的航程中身亡的水手的靈魂對話。","單位",[],["闇影島"],"史詩"],"09SI014":["格林","出牌：賦予1個單位4層無望。","","格林是位黑暗浪漫主義者、飽受折磨的詩人，以及哲學專家，一點憂鬱情節對他來說根本不算什麼。他所愛慕的對象有點棘手，但這只讓他的愛火燒得更旺。","單位",["約德爾人"],["闇影島"],"普通"],"09DE033":["精靈寶寶","","","「精靈寶寶很神奇，給他們足夠的時間，交給優秀的織夢者，他們便能發揮無限潛力！」——精靈之母","單位",[],["蒂瑪西亞","愛歐尼亞"],"普通"],"09DE039":["蒂瑪西亞之光","I：賦予1個友軍單位活力。\nII：賦予1個友軍單位2層活力。\nIII: 增幅所有友軍單位。","","當拉克絲安娜的聖光掃過仰視著她的民眾時，歡呼聲變得越來越響亮。她一直以來的希望，就是鼓勵並支持她的人民——而他們也同樣支持著她，大聲稱頌她的名字：「拉克絲安娜！拉克絲安娜！拉克絲安娜！」","地標",["故事"],["蒂瑪西亞"],"稀有"],"09DE034":["聖光無限 拉克絲","支援：賦予受此牌支援的友軍單位活力，且本回合給予此牌光盾。","友軍單位進行攻擊時擁有及獲得的增益特性總和達20以上。","光輝圍繞著拉克絲安娜，市民都看得目瞪口呆。\n在這裡，她是蒂瑪西亞的光之少女，皇冠守衛家族的傑出才女，以及天賦異稟的法師；\n在這裡，蒂瑪西亞是她理想中的模樣。","單位",[],["蒂瑪西亞"],"英雄"],"09DE047":["遺忘古物","召喚1名砂褐衝鋒者，本回合給予所有友軍單位挑戰者。","","在狙魔者存放沒收魔法物件的倉庫深處，有一件沒有標記的詭異雕刻品，它的用途早已被人遺忘……","法術",[],["蒂瑪西亞"],"稀有"],"09DE041":["反魔法英石廳堂","I：使1個友軍單位俘虜另1個單位。\nII：對敵方下抑制魔力詛咒。\nIII：泯滅所有遭到友軍單位俘虜的卡牌。","","隨著她步入廳堂，群眾的歡呼聲逐漸遠去。一座座雕像沉默地直視前方，她面前一片黑暗——但她不能轉身逃跑，因為除了她以外，還有誰能阻止蒂瑪西亞墮入噩夢？","地標",["故事"],["蒂瑪西亞"],"史詩"],"09DE030":["白熾光輝","增幅所有單位。","","「我們的光芒照亮四方！」——聖光無限 拉克絲","法術",[],["蒂瑪西亞"],"普通"],"09DE043":["聖光湧現","增幅所有單位3次。","","「沐浴在聖光之下吧！」——聖光無限 拉克絲","法術",[],["蒂瑪西亞"],"稀有"],"09DE031":["杰洛．光羽","出牌：賦予手牌中1個友軍單位活力。","","伴隨著隨風飛舞的玫瑰花瓣和發光生物，一位戴著化妝舞會面具的年輕男子出現在她的面前。「我叫光羽，杰洛．光羽。」他說道。「親愛的小姐，聽說你需要協助？」","單位",[],["蒂瑪西亞"],"稀有"],"09DE046":["性感媚笑","增幅2個友軍單位，然後使其輪流打擊1個敵軍單位。","","「女士們，別焦急。我會逐一滿足你們的需求。」\n——杰洛．光羽","法術",[],["蒂瑪西亞"],"普通"],"09DE045":["夢曦者艾琳娜","召喚此牌時，召喚5個精靈寶寶。若盤面上的位置不足，每多出1個單位，便改為賦予最弱友軍單位2層活力。","","「我跟你年紀差不多的時候，很害怕這道光。沒人告訴我，其實我的魔力是一份天賜的禮物，是有它的意義的。不過，你有我在。所以艾琳娜，別害怕，儘管綻放光芒吧。」——聖光無限 拉克絲","單位",[],["蒂瑪西亞"],"史詩"],"09DE040":["異常狙魔者","召喚此牌時，賦予其他友軍單位活力。","","「皇冠守衛小姐。」狙魔者從暗影中現身，一隻手伸向她。在他遮住一半的臉上，綻放著看似真誠但讓人不安的笑容。「可以請你跟我來嗎？」","單位",[],["蒂瑪西亞"],"普通"],"09DE036":["夢樹精靈","出牌：增幅所有其他單位。","","「小精靈們，去吧。為你們的織夢者帶路。」——莉莉亞","單位",[],["蒂瑪西亞","班德爾城"],"普通"],"09DE029":["光耀精靈","支援：本回合給予受此牌支援的友軍單位此牌的所有增益特性及其堆層。","","「快點，精靈先生。把那些詭異的影子都燒掉吧！」——夢曦者艾琳娜","單位",[],["蒂瑪西亞"],"稀有"],"09SH010":["帝國重建者","出牌：賦予1個我方地標「此牌被摧毀時，復甦此牌。」","","復活的神皇為蘇瑞瑪人民帶來了希望。有一位自稱「帝國重建者」的法師下定決心，要實現阿祈爾的願景，便周遊沙漠，重建被埋沒的遺跡，使其恢復昔日榮光。","單位",[],["蘇瑞瑪"],"普通"],"09SH009":["神皇大軍","I：召喚2名沙礫士兵。\nII：預言。\nIII：本回合召喚友軍單位時，本回合給予其+2|+0。","","阿祈爾知曉蘇瑞瑪的過去、現在，以及未來，並深信自己的願景不是一個夢想，而是一個註定會由他實現的預言。","地標",["故事"],["蘇瑞瑪"],"史詩"],"09SH012":["烈陽召喚","從起始牌組的英雄牌中3選1，並抽出該牌。","","許多遠古戰士的神器早已消逝在時間的洪流當中。不過，它們象徵的神鬥士卻依然存在。","法術",[],["蘇瑞瑪"],"稀有"],"09PZ044":["燭光祈禱","I-II：吹升1張牌以抽1張牌。\nIII：抽1張牌。","","這間供奉珍娜的神廟四面無牆，以提升與她力量的契合度。儘管如此，即使佐恩四處都出現狂風暴雨，這間廟內的無數蠟燭依然會發出亮光。","地標",["故事"],["皮爾托福&佐恩"],"史詩"],"09PZ045":["翺翔製圖師","出牌：吹升1張牌以抽1張魔耗值高於或低於該牌的卡牌。","","「所有曾經飛上高空的人，都會意識到自己有多麼渺小。」","單位",[],["皮爾托福&佐恩"],"稀有"],"09PZ046":["變異實驗體","挑選1個友軍侍從單位，召喚2隻飢餓貓耳鴞，然後將友軍單位幻化為所選友軍單位的複製單位。","","「再複製一次……下次必定會成功。」\n——邪惡不完美主義者","法術",[],["皮爾托福&佐恩"],"史詩"],"09IO055":["花瓣仙子","召喚此牌時，召喚精靈寶寶。","","「莉莉亞的頭髮一團亂！可以去幫她整理一下嗎？記住，第一綹頭髮代表願望，第二綹代表夢境，最後一綹則代表一切與表象不符的事物。」——精靈之母","單位",[],["愛歐尼亞"],"稀有"],"09IO056":["精靈之舞","召回1個友軍單位，並將其所有活力堆層賦予另1個友軍單位。","","「心中之夢，離現實只有一睡之差！」——莉莉亞","法術",[],["愛歐尼亞"],"稀有"],"09IO048":["精靈之母","召喚此牌時，賦予我方各處精靈寶寶和精靈之母活力。","","精靈活力充沛、性情多變，有時候也不太聽話。為了確保每位精靈都找到自己的織夢者，精靈之母耐心教導他們，當然也少不了嚴厲管教。","單位",[],["愛歐尼亞"],"史詩"],"09IO049":["露珠收穫祭","I：召喚精靈寶寶。\nII：使1個友軍單位陷入沉睡。","","母樹的每一滴露珠，都會透露符文大地某處的夢境，所以必須細心採集、養育，以及保護。","地標",["故事"],["愛歐尼亞"],"普通"],"09IO052":["莉莉亞","召喚此牌時及打擊：在手牌生成1張夢沉枝枒。若手牌中已有該牌，則改為使其魔耗值-1。","我方召喚15個以上友軍單位或地標。","一場露珠收穫祭，即將在遺忘花園的中心進行。儘管莉莉亞和其他園丁細心照料這些露珠，有某種詭異的腐化力量滲入了其中，它們展示的夢境都變為黑暗噩夢……","單位",[],["愛歐尼亞"],"英雄"],"09IO046":["奧菲莉斯園丁","出牌：治癒1個友軍單位，然後使其陷入沉睡。","","照顧夢之樹及其周遭的花園是無上的榮耀，但也要付出相應的代價：園丁每晚得進行感恩祭，獻上自己的記憶，失去自己的一部分。","單位",[],["愛歐尼亞"],"普通"],"09IO051":["沿根之路","I-II：抽1張牌。\nIII：本回合使我方所有手牌的魔耗值-1。","","遺忘花園是各種奇怪生物的家，在那處居住的生物有大有小，有些還擁有連自己都不想要的靈性。","地標",["故事"],["愛歐尼亞"],"稀有"],"09IO053":["樹根先生","召喚此牌時抽1張牌。","","「哇，終有一天，這些美麗的事物都會死去，包括我們在內。真希望我是第一個呢，嘿嘿！」","單位",[],["愛歐尼亞"],"普通"],"09IO045":["綻夢之花","使1個單位陷入沉睡。","","「美夢要開花結果了！」——莉莉亞","法術",[],["愛歐尼亞"],"稀有"],"09IO058":["夢樹之心","I：治療我方主堡3點生命值並召喚精靈寶寶。\nII：賦予各處友軍單位活力。\nIII：顯化1張魔耗值為8以上的卡牌，並使其魔耗值減半，無條件進位。","","夢精靈是最常見的花園住客之一，形狀、大小及性格各異，且經常會滲入露珠，引導織夢者，實現其內心深處的願望。","地標",["故事"],["愛歐尼亞"],"史詩"],"09IO059":["鋼鐵疾風","擊暈1個敵軍單位，下次回合開始再次將其擊暈。","","「此乃劍之極致。」——追風者．犽凝","法術",[],["愛歐尼亞"],"普通"],"09FR009":["普羅遊行","I-II：顯化1張與場上友軍單位卡牌次類不同的侍從單位。\nIII：每有1個有卡牌次類的友軍單位，便在本回合給予1個友軍單位+1|+1。","","自從英格娃探訪普羅王的國度後，便跟他的臣民建立了更親密的關係。一起在弗雷爾卓德四處奔馳，尋找新的冒險，是改善外交關係的最佳方法之一。","地標",["故事"],["弗雷爾卓德"],"史詩"],"09FR014":["頌雷者布倫希爾","出牌：泯滅手牌中的1個單位，以召喚1個有倒數的雷劈尖塔，其倒數等同於該單位魔耗值(最低1點)，並會召喚1個該單位的複製單位。","","「冰山的風暴與同胞的頌歌塑造了我！」","單位",[],["弗雷爾卓德"],"史詩"],"09FR010":["毛茸茸普羅","出牌：每有1個有卡牌次類的友軍單位，便治療我方主堡1點生命值。","","「呵呵呵，你看這毛茸茸的傢伙！」——普羅牧人","單位",["普羅"],["弗雷爾卓德"],"普通"],"09FR012":["冰川砍擊","賦予1個友軍單位等同其力量值的生命值與重壓，然後使其力量值歸零。","","在弗雷爾卓德，有些大樹必須用凜冬冰霜之力才能砍下。","法術",[],["弗雷爾卓德"],"稀有"],"09BC020":["鄙視眼神","賦予1個單位無望以抽1張牌。","","「恭喜，你被我討厭了。」——薇可絲","法術",[],["班德爾城","闇影島"],"普通"],"09BC012":["家族團圓","I：賦予1個單位無望。\nII：賦予1個友軍單位衝擊。\nIII: 增幅2個單位。","","俗話說：「眼不見，心更念」，但薇可絲可不同意。不過至少在這裡吃團圓飯很安靜，薇可絲就是喜歡這樣。","地標",["故事"],["班德爾城"],"史詩"],"09BC001":["薇可絲","攻擊：賦予最強敵軍單位無望。","我方賦予無望5次以上。","「呃，那個粉紅妹是怎樣？都跟她說我討厭派對了，尤其是有準備蛋糕的。真受不了……等她走了再叫醒我。」","單位",["約德爾人"],["班德爾城","闇影島"],"英雄"],"09BC002":["米爾提叔叔","完成1個故事後，賦予此牌活力2次。","","儘管米爾提跟他陰沉的侄女性格截然不同，他還是盡力嘗試跟她交流——目前來說，點蠟燭講鬼故事最有效。","單位",["約德爾人"],["班德爾城"],"稀有"],"09BC013":["翅膀大放送","I-II：挑選1個友軍單位，從魔耗值+1的侍從單位中3選1，並幻化為該單位。\nIII：挑選1個友軍單位，從魔耗值+2的侍從單位中3選1，並幻化為該單位。","","年邁的瞌睡仙崔弗整天在不同夢境之間遊蕩。幸好這個夢境還挺平靜的……不過，他在這裡遇到的每個人都想要跟他一樣的翅膀……","地標",["故事"],["班德爾城"],"稀有"],"09BC004":["艾蕾","出牌：賦予此牌活力，或賦予1個單位無望。","","「小薇！等等我！我有東西要給你！是你生日的邀請函！還有給你的禮物！雖然早了點，但我真的等不及了！你興奮嗎？我們還得討論該穿什麼，還有買什麼蛋糕，還有還有——小薇？你要去哪啊？」","單位",["約德爾人"],["班德爾城"],"普通"],"09BC016":["彈簧獸爪","本回合使1個友軍單位成長到力量值或生命值5。","","「史上。最爛。禮物。」——薇可絲","法術",[],["班德爾城"],"普通"],"09BC003":["醜怪禮物","敵方首次召喚單位時，賦予其無望。","","「啊，想不到這份禮物還不錯。」——薇可絲","單位",[],["班德爾城"],"稀有"],"09BC018":["黯影","召喚此牌時，抽出薇可絲。\n本牌局我方每賦予無望1次，此牌便獲得+1|+0。","","「就是這樣！黯影，給他們點顏色看看！禮物彩紙全部不要，派對帽更不用說。」——薇可絲","單位",[],["班德爾城","闇影島"],"史詩"],"09BC011":["無望冥靈","打擊：賦予此牌衝擊。","","「夢境對精靈有奇怪的影響。這些看來是……啊，那是蛋糕嗎？」——莉莉亞","單位",[],["班德爾城"],"普通"],"09BC006":["猛男市長","回合開始：增幅此牌。","","當肌肉異常發達的市長從巨大蛋糕中蹦出來時，時間彷彿慢了下來。「班德爾城最棒、最強壯的民選公職人員……」市長邊秀肌肉邊說道。「祝你生日快樂！」\n\n在所有的夢境中，薇可絲最討厭這個。 ","單位",["約德爾人"],["班德爾城"],"普通"],"09BW022":["競技場冠軍","I：使1個友軍單位與1個敵軍單位互相打擊。打擊後，雙方的生命值不會低於1。\nII：治癒1個友軍單位。\nIII：在手牌生成3張金幣。","","天使安潔策劃多年，為的是贏得終極比試。她每晚都夢到自己躺在一座由金幣堆成的山上，金幣多到能填滿比爾吉沃特灣，有這麼多錢，就可以去經營馬鈴薯農場了。","地標",["故事"],["比爾吉沃特"],"史詩"],"09BW028":["急切學徒","本回合每抽1張牌，此牌便獲得+1|+0。","","「你說我『缺乏鍛鍊』是什麼意思？我一直都有在練啊——你看！」","單位",[],["比爾吉沃特"],"稀有"],"09BW027":["傭兵鐵則","本回合控制1個生命值為3以下的敵軍侍從單位。若我方場上已有6個友軍單位或地標，則無法打出此牌。","","「拿別人的命來換錢，每天都開心。」——受僱槍手","法術",[],["比爾吉沃特"],"普通"],"09MT002":["煙鱗宿主","I-II：棄置1張牌即可發動。祈望1張魔耗值為7以上的天界牌。\nIII：使手牌中1張隨機卡牌的魔耗值-5。","","這個天涯孤獨的獺人全心信奉龍族，虔誠到不論是在現實或夢境都能看到這些雄偉的巨獸。","地標",["故事"],["巨石峰"],"史詩"],"09MT004":["蒙面祝福","賦予1個友軍單位2層活力。","","「我將成為他們的庇護所。」——魔甘娜","法術",[],["巨石峰"],"普通"],"09MT005":["龍頌織夢者","每回合我方首次祈望時，召喚1隻幼龍。","","「我能感覺到……龍族就在我身旁。即使是現在，他們也在我的夢中遨遊。」","單位",[],["巨石峰"],"史詩"],"09NX025":["競技場王者","I-II：本回合給予1個友軍單位+2|+0。\nIII：本回合給予1個敵軍單位無法進行格擋。","","競技場擁有超高人氣的部分原因，是因為任何人都能在這裡成名。這位粉絲看了達瑞文的每場比賽，他相信如果自己得到相同的機會，也能登上冠軍寶座。","地標",["故事"],["諾克薩斯"],"史詩"],"09NX032":["雪怪馴獸師","棄置1張牌即可出此牌。\n召喚此牌時，召喚1隻暴怒雪怪。","","諾克薩斯戰爭機器之所以能夠成功，有一部分得歸功於它的靈活性。面對險惡地形或棘手狀況時，就得隨機應變，而這支軍隊就懂得如何利用令人意想不到的當地資源。","單位",[],["諾克薩斯"],"稀有"],"09NX033":["腐敗戰斧","回合結束：若此牌的裝備者本回合沒有進行攻擊，則賦予其無望。","","膽怯的代價非常大。","裝備",[],["諾克薩斯"],"稀有"]};
